          "የከፍተኛው ብርሃን (ኦር ማኪፍ) መውረድ፣ የሰውየውን ውስጣዊ ተፈጥሮ ከመቀበል ወደ መስጠት የሚቀይር፣ ሰላምን እና አንድነትን የሚያመጣ።",
          "ሰውዬው ወዲያውኑ አካላዊ አካሉን እንደሚለቅ።",
