window.lessonDB[18].flashcards = {
    hu: [
    { f: "Mi az ima kabbalisztikus definíciója?", b: "A 'szív munkája' (Avoda shebaLev), a belső vágyak, szándékok és hiányosságok mély tisztázása a Teremtő előtt." },
    { f: "Mit jelent a spirituális 'szív' a Kabbalában?", b: "A szív az ember megszerzési vágyainak és összes érzelmi-akarati törekvésének az összessége." },
    { f: "Hogyan viszonyulnak egymáshoz a száj szavai és a szív vágya?", b: "A Teremtő kizárólag a szív mélyén rejlő valódi hiányra (Hisaron) válaszol, nem pedig a száj által kiejtett külsőséges szavakra." },
    { f: "Mi a 'Hisaron' fogalma az imában?", b: "Valódi belső hiányérzet, az edény (Kli) üressége, amely a betöltésre és a spirituális korrekcióra vágyik." },
    { f: "Miért nem tekinthető igazi imának a szavak pusztán mechanikus elmondása?", b: "Mert ha a szív nem vágyik arra, amit a száj mond, a szavak üres formák maradnak belső spirituális erő nélkül." },
    { f: "Melyik az ima meghallgatásának első feltétele?", b: "A sziklaszilárd hit abban, hogy a Teremtő képes megszabadítani az embert az egoizmus fogságából." },
    { f: "Melyik az ima meghallgatásának második feltétele?", b: "Annak felismerése, hogy nincs más választás: az ember minden saját ereje csődöt mondott, egyedül a Teremtő segíthet." },
    { f: "Melyik az ima meghallgatásának harmadik feltétele?", b: "Hogy a kérés valóban élet-halál kérdése legyen, anélkül a lélek elpusztul a megszerzési vágyban." },
    { f: "Hogyan működik az ima mint 'médium' a spirituális fejlődésben?", b: "Nem a Teremtő megváltoztatását célozza, hanem az embert alakítja át, felkészítve a Klit az adakozás fényének befogadására." },
    { f: "Mit kér a kabbalista a valódi imában mint médiumban?", b: "Kizárólag az adakozási hiányt (az adakozni akarás vágyát) és a Teremtővel való formaegyezést kéri." },
    { f: "Mi a Shamati 20. cikkely központi üzenete a Lishma eléréséről?", b: "A Lishma (az Ő Nevéért / önzetlen adakozás) fentről jövő ajándék, amelyet emberi elme önmagában képtelen megszerezni." },
    { f: "Ha a Lishma fentről kapott ajándék, miért van szükség emberi erőfeszítésre?", b: "Az erőfeszítések és gyógymódok hozzák létre az emberben a korrigált edényeket (Kelim), amelyek valóban vágynak a Lishmára." },
    { f: "Milyen szerepet játszik a kudarc az imában a Shamati 20 szerint?", b: "Amikor az ember látja, hogy minden erőfeszítése hiábavaló volt, eléri a teljes tehetetlenséget, és csak ekkor tud tiszta szívből imádkozni." },
    { f: "Mikor képes az ember szívének legmélyéről igazán őszinte imát mondani?", b: "Miután minden emberi eszközt kipróbált, és belátta, hogy saját erejéből semmit sem tud elérni a Teremtő nélkül." },
    { f: "Mit jelent a 'MAN' (Mayin Nukvin) fogalma?", b: "Női vizek; az alsó edényből felszálló hiány, ima és felébredés, amely fentről fényt és bőséget vonz le." },
    { f: "Mi a 'lentről jövő ébredés' szerepe a spirituális rendszerben?", b: "A lenti ébredés (a teremtett lény imája) indítja be a felső fények áradását (MAD - Mayin Dehrin)." },
    { f: "Mit jelent az az elv, hogy 'Aki megtisztulni jön, segítséget kap'?", b: "Aki valóban az adakozás és a tisztaság felé törekszik, annak a Teremtő felülről megadja a korrekció és a felemelkedés erejét." },
    { f: "Hogyan segíti a Teremtő azt, aki megtisztulni jön?", b: "Megajándékozza a Lishma állapotával, felébreszti a szívét, és megadja neki a természetét felülmúló erőt." },
    { f: "Mi a 'szív munkája' a mindennapi belső tisztázás során?", b: "Megkülönböztetni a saját önző vágyakat az adakozás vágyától, és kérni a Teremtőt a vágyak átalakítására." },
    { f: "Miért nem változtatható meg a Teremtő az ima által?", b: "Mert a Teremtő Abszolút Jó és Változatlan; az ima a befogadó edényt változtatja meg, hogy alkalmassá váljon a fényre." },
    { f: "Mi a különbség a vallásos ima és a kabbalisztikus ima között?", b: "A vallásos ima anyagi javakat vagy egoista megkönnyebbülést kér, a kabbalisztikus ima az önzésből való megváltást kéri." },
    { f: "Hogyan születik meg a valódi Hisaron a spirituális úton?", b: "A csoportban és a források tanulmányozásában végzett kitartó munka során, amikor a hiány a fény hiányaként tisztázódik." },
    { f: "Mit jelent az, hogy a test 'nem ért egyet a Mennyek Országának terhével'?", b: "A fizikai megszerzési vágy ösztönösen ellenáll annak, hogy kizárólag a Teremtő kedvére, haszon nélkül dolgozzon." },
    { f: "Mi a teendő, amikor az ember látja, hogy a szervei ellenállnak az adakozásnak?", b: "Ki kell öntenie a szívét a Teremtőnek, kérve, hogy segítsen a testet az Ő szolgálatába állítani." },
    { f: "Hogyan pusztítja el a Lishma elérése a gonosz hajlamot?", b: "Lenullázza az önszeretetet; a megszerzés edényei funkciójukat vesztik, és spirituális értelemben 'halottnak' minősülnek." },
    { f: "Miért fontos, hogy az ember tudja: ima nélkül lehetetlen elérni a Lishmát?", b: "Mert csak e tudat révén válik az ima abszolút szükségletté, elkerülve az önelégültséget és a hamis biztonságérzetet." },
    { f: "Mi a kapcsolat a MAN felemelése és a lélek edénye között?", b: "A MAN maga az edény hiányossága; minél tisztább és mélyebb a hiány, annál nagyobb fényt képes befogadni." },
    { f: "Mit jelent az, hogy az ima az egoizmus beismerése?", b: "A szív feltárja teljes rászorultságát és azt, hogy a saját egoja egy leküzdhetetlen börtön a Teremtő segítsége nélkül." },
    { f: "Hogyan kapcsolódik a csoport munkája a személyes imához?", b: "A csoporttársak közötti szeretet megkísérlése hozza felszínre a valódi képtelenséget az önzetlenségre, ami valódi imát szül." },
    { f: "Miért mondják, hogy az ima az edény megteremtése?", b: "Mert a betöltés csak a hiány mértékében létezhet; az ima tisztázza és kitágítja ezt a spirituális vákuumot." },
    { f: "Mit jelent az, hogy 'a Teremtő meghallgatja az imát'?", b: "A kérés és a felső adakozási törvény rezonanciába lép, és a fény azonnal belép a megnyílt edénybe." },
    { f: "Milyen szerepe van a kétségbeesésnek a spirituális imában?", b: "A spirituális kétségbeesés az egoista erők teljes kimerülését jelzi, ami közvetlenül megelőzi a fény áradását." },
    { f: "Mit jelent az 'ébredés fentről' (Itaruta de-Leila)?", b: "A felső fény megnyilvánulása, amely válaszul érkezik a lentről jövő felkészült, tiszta hiányra (MAN)." },
    { f: "Miért nevezik a megszerzési vágyat 'tolvajnak' a Shamati 20-ban?", b: "Mert minden energiát és fényt azonnal a saját önző élvezetére akar ellopni és kisajátítani." },
    { f: "Miért nem kap az ember azonnal örömet az adakozásért végzett munkában kezdetben?", b: "Hogy a kapni akarás ne érezze meg az ízét; ha érezné, az ember soha nem tudna felemelkedni a tiszta Lishmába." },
    { f: "Mikor válik a munka önmagában örömmé?", b: "Amikor az ember hozzászokott az adakozáshoz, és a Teremtőben való gyönyörködés jutalmává válik maga a szolgálat." },
    { f: "Hogyan válik a panasz jogosulttá vagy jogtalanná a spirituális munkában?", b: "Csak annak panaszkodhatunk, akinek dolgozunk; ha idegen célokért gürcölünk, nincs jogunk a Teremtőtől életerőt kérni." },
    { f: "Mit jelent a belső tisztázás (Berur) az imában?", b: "A szándékok szétválasztása: mi szól a saját önző élvezetemért, és mi szolgálja a Teremtő örömét." },
    { f: "Mi a 'tökéletes teljesség' az adakozás terhének vállalásakor?", b: "Kizárólag adakozni akarni, és teljesen lemondani a saját célú megszerzésről." },
    { f: "Miért nem elegendő az intellektuális megértés a szív imájához?", b: "Mert a szellem érvei nem mozdítják meg az edényt; csak a szívben megélt valós hiány vonzza a fényt." },
    { f: "Hogyan működik a MAN a spirituális világok fokozatain keresztül?", b: "Az alsóbb fokozat feladja hiányát a felsőbbnek, amely felemeli azt a forrásig, lehozva a választ." },
    { f: "Mit jelent az, hogy az ima az egyetlen fegyver a megszerzési vágy ellen?", b: "Az ember természete a vágy; a természetét nem tudja megváltoztatni, egyedül a Teremtőhöz kiálthat új természetért." },
    { f: "Miért mondják, hogy az ima egy folyamat, nem egy pillanat műve?", b: "Mert az erőfeszítések és kudarcok sorozata csiszolja és érleli a hiányt, amíg az eléri a teljes őszinteséget." },
    { f: "Hogyan nyilvánul meg a hit a szabadításban a legsötétebb állapotban?", b: "Bár a test semmi esélyt nem lát a megváltásra, a pont a szívben bizonyos abban, hogy a Teremtő meg tudja menteni." },
    { f: "Mit jelent az, hogy a Teremtő 'várja az igazak imáját'?", b: "A Teremtő várja a felkészült, adakozásra vágyó edényt, mert szeretetének természete a betöltés és adás." },
    { f: "Milyen kapcsolat van a bűnbánat és a kabbalisztikus ima között?", b: "A bűnbánat az egoizmus természetének fájdalmas felismerése, az ima pedig a belőle való szabadulás kérése." },
    { f: "Hogyan védi meg az ima az embert a spirituális gőgtől?", b: "Felismeri, hogy minden elért spirituális szint kizárólag a felülről kapott segítség és kegyelem eredménye." },
    { f: "Mi az oka annak, ha egy imára látszólag nem érkezik válasz?", b: "A hiány még nem érte el a szükséges mélységet vagy tisztaságot; az edény még nem alkalmas a fény megtartására." },
    { f: "Mit jelent a 'szív kiöntése a Teremtő elé'?", b: "Minden rejtett vágy, félelem és tehetetlenség gátlások nélküli átadása a Teremtő irányításának." },
    { f: "Hogyan segít az imakönyv (Siddur) a kabbalista belső munkájában?", b: "A bölcsek által megfogalmazott spirituális állapotok és korrekciós folyamatok belső térképeként szolgál." },
    { f: "Miért tekintik a Lishmát csodának?", b: "Mert a teremtett természet (önszeretet) teljes megfordítása a természetfeletti adakozásba csak a Fény erejével lehetséges." },
    { f: "Hogyan válik az ima a Teremtővel való beszélgetéssé?", b: "Amikor a szív rezdülései pontosan tükrözik a Teremtőhöz való közeledés vágyát, közvetlen belső párbeszéd nyílik." },
    { f: "Mit jelent az, hogy az ember 'nem mentheti fel magát' az erőfeszítés alól?", b: "Bár a cél fentről adatik, a munka és a vágy felépítése a teremtett lény kizárólagos kötelezettsége." },
    { f: "Milyen kapcsolat van az ima és a barátok szeretete között?", b: "A barátok felé tett adakozási erőfeszítések során derül ki, mennyire hiányzik az adakozás ereje, ami közös imát szül." },
    { f: "Hogyan tisztítja meg a szándékot az ima előtti belső számvetés?", b: "Felfedi az önös érdekeket, segít elvetni a hamis célokat, és egyetlen pontra fókuszálja a kérést." },
    { f: "Mi a különbség a passzív várakozás és a spirituális ima között?", b: "A passzivitás feladja a harcot, míg az ima a végsőkig küzdő ember végső, koncentrált kiáltása a segítségért." },
    { f: "Hogyan tükröződik a Tóra fénye az imában?", b: "A tanulás során vonzott Reformáló Fény megvilágítja a szív sötétségét, felkeltve a mély imát a javulásért." },
    { f: "Mit jelent az, hogy az igazi ima 'a mélységekből kiált'?", b: "A megszerzési vágy legaljáról, az egoizmus börtönének legsötétebb mélységéből feltörő segélykiáltás." },
    { f: "Hogyan vezet az ima a Teremtővel való Dvekuthoz (összetapadáshoz)?", b: "Az adakozási vágy elnyerésével az ember tulajdonságai megegyeznek a Teremtőével, ami a végső egyesülés." },
    { f: "Mi a 18. lecke legfőbb tanítása az ima gyakorlatáról?", b: "Ne elégedj meg a szavak ismétlésével; építs valódi hiányt a szívedben, mert a Teremtő csak a szív igazságára válaszol." }
  ],
  en: [
    { f: "What is the Kabbalistic definition of prayer?", b: "The 'work in the heart' (Avoda shebaLev), the deep internal clarification of desires, intentions, and deficiencies before the Creator." },
    { f: "What does the spiritual 'heart' signify in Kabbalah?", b: "The heart represents the sum total of all a person's desires to receive and emotional-volitional inclinations." },
    { f: "How do the words of the mouth relate to the desire of the heart?", b: "The Creator answers exclusively to the true lack (Hisaron) within the depths of the heart, never to external mechanical words." },
    { f: "What is the concept of 'Hisaron' in prayer?", b: "A genuine internal deficiency, the emptiness of the vessel (Kli) yearning for spiritual fulfillment and correction." },
    { f: "Why is the mechanical repetition of spoken words not considered authentic prayer?", b: "Because if the heart does not yearn for what the lips utter, the words remain lifeless forms devoid of spiritual vitality." },
    { f: "What is the first condition for prayer to be answered?", b: "Unshakable faith that the Creator is truly capable of delivering man from the imprisonment of egoism." },
    { f: "What is the second condition for prayer to be answered?", b: "Recognizing that there is no other choice: all human efforts have failed, and only the Creator can help." },
    { f: "What is the third condition for prayer to be answered?", b: "That the petition is truly a matter of life and death, without which the soul perishes in the desire to receive." },
    { f: "How does prayer act as a 'medium' in spiritual evolution?", b: "It does not seek to change the Creator, but transforms the human being, preparing the Kli to receive the light of bestowal." },
    { f: "What does a Kabbalist ask for through prayer as a medium?", b: "Exclusively the deficiency for bestowal (the desire to bestow) and equivalence of form with the Creator." },
    { f: "What is the central message of Shamati Article 20 regarding attaining Lishma?", b: "Lishma (for Her sake / altruistic bestowal) is an illumination and gift from Above that the human mind cannot grasp alone." },
    { f: "If Lishma is a gift from Above, why is human effort necessary?", b: "Because human efforts and remedies construct the corrected vessels (Kelim) that genuinely want to receive Lishma." },
    { f: "What role does failure play in prayer according to Shamati 20?", b: "When a person sees that all their actions were completely futile, they reach total helplessness, enabling a prayer from the bottom of the heart." },
    { f: "When can a person offer a truly honest prayer from the depths of their heart?", b: "Only after exhausting all human remedies and recognizing that they can accomplish nothing on their own without the Creator." },
    { f: "What is the concept of 'MAN' (Mayin Nukvin)?", b: "Female waters; the deficiency, prayer, and awakening ascending from the lower vessel that draws down abundance and light from Above." },
    { f: "What is the role of the 'awakening from below' in the spiritual system?", b: "The awakening from below (the prayer of the created being) initiates the flow of Upper Lights (MAD - Mayin Dehrin)." },
    { f: "What does the principle 'He who comes to purify is aided' mean?", b: "Whoever genuinely strives toward bestowal and purity receives strength, correction, and elevation from the Creator from Above." },
    { f: "How does the Creator assist one who comes to purify?", b: "By bestowing the gift of Lishma, awakening their heart, and granting them supernatural strength that transcends their nature." },
    { f: "What is the 'work in the heart' during daily internal clarification?", b: "Distinguishing between self-serving desires and the desire to bestow, praying for the transformation of one's nature." },
    { f: "Why is the Creator unchanged by human prayer?", b: "Because the Creator is Absolute Good and Immutable; prayer alters the receiving vessel so it becomes compatible with the Light." },
    { f: "What is the difference between conventional prayer and Kabbalistic prayer?", b: "Conventional prayer asks for corporeal benefits or egoistic relief, whereas Kabbalistic prayer pleads for redemption from egoism." },
    { f: "How is a genuine Hisaron born on the spiritual path?", b: "Through persistent work in the group and the study of authentic sources, clarifying the lack as an absence of the Light of bestowal." },
    { f: "What does it mean that the body 'does not agree with the burden of the Kingdom of Heaven'?", b: "The innate desire to receive instinctively recoils from laboring purely for the contentment of the Creator without personal reward." },
    { f: "What should one do upon seeing that their organs resist bestowal?", b: "One has no choice but prayer: to pour out their heart to the Creator to help make their body consent to bestowal." },
    { f: "How does obtaining Lishma put the evil inclination to death?", b: "It nullifies self-love; the vessels of reception lose their self-serving function and are considered spiritually 'dead'." },
    { f: "Why is it vital to know that without prayer Lishma cannot be attained?", b: "Because this realization makes prayer an absolute necessity, dispelling complacency and false self-reliance." },
    { f: "What is the connection between raising MAN and the vessel of the soul?", b: "MAN is the deficiency itself; the purer and deeper the lack, the greater the Light the vessel can receive." },
    { f: "What does it mean that prayer is an admission of egoistic helplessness?", b: "The heart reveals its absolute dependence, acknowledging that its own ego is an inescapable prison without divine aid." },
    { f: "How does group work integrate with personal prayer?", b: "Attempting to love the companions exposes one's utter inability to bestow selflessly, generating a true prayer for help." },
    { f: "Why is prayer considered the actual creation of the spiritual vessel?", b: "Because fulfillment can only enter where there is a corresponding deficiency; prayer clarifies and expands this spiritual vacuum." },
    { f: "What does it mean that 'the Creator hears the prayer'?", b: "The petition resonates in perfect harmony with the Upper law of bestowal, allowing the Light to instantly fill the open vessel." },
    { f: "What role does spiritual despair play in prayer?", b: "Spiritual despair marks the complete exhaustion of egoistic forces, directly preceding the influx of Upper assistance." },
    { f: "What is the 'awakening from Above' (Itaruta de-Leila)?", b: "The manifestation of the Upper Light that arrives in direct response to a mature, purified deficiency from below (MAN)." },
    { f: "Why is the desire to receive compared to a 'thief' in Shamati 20?", b: "Because it seeks to hijack and steal every bit of energy and pleasure exclusively for its own self-serving enjoyment." },
    { f: "Why does a person initially feel no vitality in laboring for the sake of bestowal?", b: "So that the desire to receive does not taste pleasure in it; if it did, man would never transcend into pure Lishma." },
    { f: "When does spiritual labor become an intrinsic joy?", b: "When one becomes accustomed to bestowal, and finding delight in the Creator becomes the reward of the work itself." },
    { f: "When is complaining in spiritual work justified or unjustified?", b: "One can only complain to the master one actually works for; working for selfish goals gives no right to demand vitality from the Creator." },
    { f: "What is internal clarification (Berur) within prayer?", b: "Sorting out intentions: discerning what serves one's own egoistic pleasure versus what brings contentment to the Creator." },
    { f: "What is 'utter completeness' when assuming the burden of the Kingdom of Heaven?", b: "Desiring only to bestow, completely renouncing self-serving reception." },
    { f: "Why is intellectual comprehension insufficient for the prayer of the heart?", b: "Because mental arguments cannot move the spiritual vessel; only an authentic deficiency experienced in the heart draws the Light." },
    { f: "How does MAN operate through the degrees of the spiritual worlds?", b: "The lower degree elevates its deficiency to the higher degree, which carries it to the Source, drawing down the answer." },
    { f: "Why is prayer called the only weapon against the desire to receive?", b: "Because man cannot alter his own created nature; he can only cry out to the Creator to grant him a new nature of bestowal." },
    { f: "Why is prayer described as a continuous process rather than a single moment?", b: "Because a series of efforts and failures polishes and matures the deficiency until it reaches absolute sincerity." },
    { f: "How is faith in deliverance expressed in the darkest spiritual states?", b: "Even when the body sees no escape, the point in the heart remains confident that the Creator can redeem it in a split second." },
    { f: "What does it mean that the Creator 'longs for the prayer of the righteous'?", b: "The Creator yearns for a prepared vessel capable of bestowal, as the nature of divine love is to bestow fulfillment." },
    { f: "What is the relationship between repentance and Kabbalistic prayer?", b: "Repentance is the painful recognition of one's egoistic nature, and prayer is the plea for liberation from it." },
    { f: "How does prayer protect a person from spiritual pride?", b: "It instills the constant realization that every spiritual achievement is solely a gift and mercy from Above." },
    { f: "What does it mean when a prayer seemingly goes unanswered?", b: "The deficiency has not yet reached sufficient depth or purity; the vessel is not yet ready to retain the Light." },
    { f: "What does 'pouring out the heart before the Creator' mean?", b: "Surrendering all hidden desires, fears, and vulnerabilities unconditionally to the governance of the Creator." },
    { f: "How does the prayer book (Siddur) assist the Kabbalist's internal work?", b: "It serves as a precise spiritual map of inner states and correction processes formulated by attained sages." },
    { f: "Why is the transition to Lishma considered a supernatural miracle?", b: "Because inverting created nature (self-love) into pure altruism can only be accomplished by the transformative power of the Light." },
    { f: "How does prayer turn into a living dialogue with the Creator?", b: "When the vibrations of the heart perfectly mirror the desire to draw closer, a direct internal communion opens." },
    { f: "What does it mean that one 'is not free to rid oneself of the effort'?", b: "Although the final achievement is a gift from Above, the labor of building the desire is man's absolute responsibility." },
    { f: "What is the connection between prayer and love of companions?", b: "Laboring to bestow upon friends reveals one's complete lack of love, generating an authentic shared prayer for correction." },
    { f: "How does internal accounting before prayer purify one's intention?", b: "It exposes ulterior selfish motives, helps discard false goals, and focuses the petition on a single point of truth." },
    { f: "What is the difference between passive waiting and spiritual prayer?", b: "Passivity surrenders the battle, whereas authentic prayer is the focused cry of a warrior fighting to the absolute limit." },
    { f: "How does the Light of Torah reflect in prayer?", b: "The Reforming Light drawn during study illuminates the heart's darkness, evoking a profound plea for spiritual correction." },
    { f: "What does it mean that true prayer 'cries from the depths'?", b: "An outcry bursting from the very bottom of the desire to receive, from the darkest depths of the ego's prison." },
    { f: "How does prayer lead to Dvekut (adhesion) with the Creator?", b: "By acquiring the desire to bestow, man achieves equivalence of form with the Creator, culminating in complete oneness." },
    { f: "What is the paramount practical lesson of Lesson 18 on prayer?", b: "Do not settle for reciting words; cultivate a genuine deficiency in your heart, for the Creator responds only to the heart's truth." }
  ],
  he: [
    { f: "מהי ההגדרה הקבלית של תפילה?", b: "'עבודה שבלב', בירור פנימי עמוק של הרצונות, הכוונות והחסרונות של האדם מול הבורא." },
    { f: "מהי המשמעות של 'לב' מבחינה רוחנית בחכמת הקבלה?", b: "הלב מייצג את כלל הרצונות לקבל של האדם ואת מכלול נטיותיו הרגשיות והרצוניות." },
    { f: "כיצד מתייחסים זה לזה דברי הפה ורצון הלב?", b: "הבורא שומע ועונה אך ורק לחיסרון האמיתי השוכן בעומק הלב, ולא למילים המכניות שמוציא הפה." },
    { f: "מהו מושג ה'חיסרון' בתפילה?", b: "הרגשת ריקנות וצורך פנימי אמיתי, חלל הכלי (רצון) המשתוקק למילוי ולתיקון רוחני." },
    { f: "מדוע חזרה מכנית על מילים אינה נחשבת לתפילה אמיתית?", b: "משום שאם הלב אינו משתוקק למה שהשפתיים מביעות, המילים נותרות צורות מתות ללא חיות רוחנית." },
    { f: "מהו התנאי הראשון לקבלת התפילה?", b: "אמונה איתנה בכך שהבורא מסוגל ויכול להושיע את האדם ממאסר האגואיזם." },
    { f: "מהו התנאי השני לקבלת התפילה?", b: "ההכרה שאין ברירה אחרת: כל המאמצים העצמיים נכשלו, ורק הבורא לבדו יכול לעזור." },
    { f: "מהו התנאי השלישי לקבלת התפילה?", b: "שהבקשה תהיה בבחינת עניין של חיים ומוות, שבלעדיה הנפש אובדת בתוך הרצון לקבל." },
    { f: "כיצד פועלת התפילה כ'מדיום' (אמצעי) בהתפתחות הרוחנית?", b: "היא אינה משנה את הבורא, אלא משנה ומכשירה את האדם ואת הכלי לקבלת אור ההשפעה." },
    { f: "מה מבקש המקובל בתפילה אמיתית המשמשת כמדיום?", b: "אך ורק את החיסרון להשפעה (את הרצון להשפיע) ואת השתוות הצורה עם הבורא." },
    { f: "מהו המסר המרכזי במאמר 'שמעתי כ' (עניין לtarget לשמה)?", b: "השגת 'לשמה' (למען שמה / השפעה טהורה) היא מתנה והארה מלמעלה שאין ביכולת שכל האדם להשיגה לבדו." },
    { f: "אם 'לשמה' היא מתנה מלמעלה, מדוע נדרש מאמץ האדם?", b: "המאמצים והסגולות בונים באדם את הכלים המתוקנים שבאמת משתוקקים לקבל את מתנת ה'לשמה'." },
    { f: "איזה תפקיד ממלא הכישלון בתפילה לפי 'שמעתי כ'?", b: "כאשר אדם רואה שכל פעולותיו עלו בתוהו, הוא מגיע לחוסר אונים מוחלט ורק אז יכול לצעוק מעומק הלב." },
    { f: "מתי מסוגל האדם להתפלל תפילה אמיתית וכנה מעומק לבו?", b: "רק לאחר שניסה את כל התחבולות האנושיות והכיר בכך שאינו יכול להועיל לעצמו במאומה ללא הבורא." },
    { f: "מהו המושג 'מ\"ן' (ניין נוקבין)?", b: "מים נוקבים; החיסרון, התפילה וההתעוררות העולים מהכלי התחתון והמושכים שפע ואורות מלמעלה." },
    { f: "מהו תפקידה של 'התעוררות דלתתא' (מלמטה) במערכת הרוחנית?", b: "התעוררות התחתון (תפילת הנברא) היא זו שמפעילה וממשיכה את זרימת האורות העליונים (מ\"ד - מים דכורין)." },
    { f: "מהי המשמעות של הכלל 'הבא ליטהר מסייעין אותו'?", b: "מי שמשתוקק באמת להגיע להשפעה ולטהרה מקבל מלמעלה כוח, תיקון ועזרה מן הבורא להתעלות מעל טבעו." },
    { f: "כיצד מסייע הבורא לאדם הבא ליטהר?", b: "הוא מעניק לו את מדרגת ה'לשמה', מעורר את לבו ונותן לו כוחות על-טבעיים המתעלים מעל הטבע האגואיסטי." },
    { f: "מהי 'עבודה שבלב' במהלך הבירור הפנימי היומיומי?", b: "הבחנה והפרדה בין הרצונות האגואיסטיים לבין הרצון להשפיע, ובקשת עזרה מהבורא לתיקון הטבע." },
    { f: "מדוע אין התפילה משנה את הבורא כלל?", b: "משום שהבורא הוא טוב ומיטיב ובלתי משתנה; התפילה פועלת על הכלי המקבל ומכשירה אותו לאור." },
    { f: "מהו ההבדל בין תפילה דתית-חיצונית לתפילה קבלית?", b: "תפילה רגילה מבקשת מילויים גשמיים או הקלה לאגו, בעוד שתפילה קבלית דורשת גאולה מן האגואיזם עצמו." },
    { f: "כיצד נולד חיסרון רוחני אמיתי בדרך הקבלה?", b: "מתוך יגיעה מתמדת בקבוצה ובלימוד המקורות, המבררת את החיסרון כהיעדר תכונת ההשפעה." },
    { f: "מה פירוש הדבר שהגוף 'אינו מסכים לעול מלכות שמיים'?", b: "הרצון לקבל הטבעי מתנגד באופן אינסטינקטיבי לעבודה שהיא כולה להשפיע נחת רוח לבורא ללא שכר." },
    { f: "מה עושה אדם כשהוא מגלה שכל איבריו מתנגדים להשפעה?", b: "אין לו עצה אלא תפילה: לשפוך לבו לבורא שירחם עליו ויכניע את גופו לקבל עול מלכות שמיים." },
    { f: "כיצד השגת 'לשמה' ממיתה את היצר הרע?", b: "היא מבטלת את האהבה העצמית; כלי הקבלה מאבדים את תפקידם האנוכי ונחשבים ברוחניות כ'מתים'." },
    { f: "מדוע חשוב לדעת שאי אפשר לזכות ל'לשמה' ללא תפילה?", b: "משום שידיעה זו הופכת את התפילה לצורך מוחלט ונואש, ומונעת שאננות ואשליה של כוחי ועוצם ידי." },
    { f: "מהו הקשר בין העלאת מ\"ן לבין כלי הנשמה?", b: "המ\"ן הוא עצם החיסרון של הכלי; ככל שהחיסרון מזוכך ועמוק יותר, כך הוא יכול לקבל אור עליון גדול יותר." },
    { f: "מה המשמעות של ההגדרה שהתפילה היא הודאה באפסות האגו?", b: "הלב חושף את תלותו המוחלטת ומכיר בכך שהאגו שלו הוא כלא שאי אפשר להימלט ממנו לבד." },
    { f: "כיצד משתלבת עבודת הקבוצה עם התפילה האישית?", b: "הניסיון לאהוב את החברים חושף את חוסר היכולת להשפיע באמת, ומוליד זעקה אמיתית לעזרה מלמעלה." },
    { f: "מדוע נחשבת התפילה ליצירת הכלי הרוחני עצמו?", b: "מפני שאין מילוי ללא חיסרון מקדים; התפילה מבררת, מעמיקה ומרחיבה את החלל הרוחני." },
    { f: "מהי המשמעות של הביטוי 'הבורא שומע תפילה'?", b: "הבקשה מגיעה לתהודה מלאה עם חוק ההשפעה העליון, והאור נכנס מיד לתוך הכלי הפתוח." },
    { f: "איזה תפקיד ממלא הייאוש הרוחני בתפילה?", b: "הייאוש מן הכוחות האגואיסטיים מסמל את סוף המאמץ העצמי, ומקדים ישירות את ישועת הבורא." },
    { f: "מהי 'התעוררות דלעילא' (מלמעלה)?", b: "הופעת האור העליון והשפע בתגובה ישירה לחיסרון בשל ומתוקן שעלה מלמטה (מ\"ן)." },
    { f: "מדוע הרצון לקבל מכונה 'גנב' במאמר שמעתי כ'?", b: "מפני שהוא מבקש לגנוב ולנכס כל אנרגיה, שמחה והארה לטובת הנאתו האנוכית הפרטית בלבד." },
    { f: "מדוע אין האדם מרגיש חיות בעבודה של השפעה בתחילת הדרך?", b: "כדי שהרצון לקבל לא יטעם בה טעם; אילו היה טועם תענוג, לעולם לא היה האדם מגיע להשפעה טהורה." },
    { f: "מתי הופכת העבודה הרוחנית לשמחה בפני עצמה?", b: "כאשר האדם מתרגל להשפיע, ועצם האפשרות להשפיע נחת רוח לבורא הופכת לשכר הגדול ביותר." },
    { f: "מתי תרעומת בעבודה רוחנית היא מוצדקת או בלתי מוצדקת?", b: "אדם יכול להתרעם רק על מי שהוא באמת עובד עבורו; אם עבד למען עצמו, אין לו זכות לדרוש חיות מהבורא." },
    { f: "מהו בירור פנימי בתפילה?", b: "הפרדת הכוונות בלב: זיהוי מה נעשה לתועלת האגו ומה באמת מכוון לנחת רוח לבורא." },
    { f: "מהי 'שלמות גמורה' בקבלת עול מלכות שמיים?", b: "לרצות אך ורק להשפיע, ולהתנתק לחלוטין מכל רצון לקבל לתועלת עצמית." },
    { f: "מדוע הבנה שכלית אינה מספיקה לתפילת הלב?", b: "משום שטענות שכליות אינן מזיזות את הרצון; רק חיסרון ממשי שנחווה בלב ממשיך את האור." },
    { f: "כיצד פועל המ\"ן דרך מדרגות העולמות הרוחניים?", b: "המדרגה התחתונה מעלה את חסרונה לעליון, והעליון מעלה זאת למקור ומוריד את התשובה." },
    { f: "מדוע התפילה נקראת 'הנשק היחיד' נגד הרצון לקבל?", b: "משום שאין אדם יכול לשנות את טבעו בעצמו; הוא יכול רק לזעוק לבורא שייתן לו טבע שני של השפעה." },
    { f: "מדוע התפילה היא תהליך מתמשך ולא פעולה רגעית?", b: "משום שסדרה של מאמצים ונפילות מלטשת ומבשילה את החיסרון עד שהוא מגיע לשיא הכנות." },
    { f: "כיצד מתבטאת האמונה בישועה במצבים החשוכים ביותר?", b: "אף כשהגוף אינו רואה שום מוצא, הנקודה שבלב בטוחה שהבורא יכול להושיעו כהרף עין." },
    { f: "מה פירוש הדבר שהבורא 'מתאווה לתפילתם של צדיקים'?", b: "הבורא משתוקק לכלי מוכן שמסוגל לקבל על מנת להשפיע, שכן טבע אהבתו הוא להעניק מילוי." },
    { f: "מהו הקשר בין תשובה לבין תפילה קבלית?", b: "תשובה היא ההכרה הכואבת בטבע האגואיזם, והתפילה היא הבקשה להשתחרר ממנו ולשוב לבורא." },
    { f: "כיצד מגנה התפילה על האדם מגאווה רוחנית?", b: "היא מטמיעה בו את ההכרה שכל השגה רוחנית היא אך ורק מתנת חינם ורחמים מלמעלה." },
    { f: "מהי הסיבה לכך שתפילה נראית כאילו אינה נענית?", b: "החיסרון טרם הגיע למידת העומק או הטוהר הנדרשת; הכלי עדיין אינו מוכשר להחזיק באור." },
    { f: "מהי המשמעות של 'שפיכת הלב לפני הבורא'?", b: "מסירת כל הרצונות הנסתרים, הפחדים וחוסר האונים ללא עכבות לשליטתו של הבורא." },
    { f: "כיצד מסייע הסידור בעבודתו הפנימית של המקובל?", b: "הוא משמש כמפה רוחנית מדויקת של מצבים פנימיים ותהליכי תיקון שניסחו בעלי השגה." },
    { f: "מדוע המעבר ל'לשמה' נחשב לנס עליון?", b: "מפני שהפיכת הטבע הנברא (אהבה עצמית) להשפעה טהורה תיתכן אך ורק בכוח האור האלוקי." },
    { f: "כיצד הופכת התפילה לשיחה חיה עם הבורא?", b: "כאשר רחשי הלב משקפים במדויק את הרצון להידבק בו, נפתח דו-שיח פנימי ישיר." },
    { f: "מהי המשמעות של 'אין אתה בן חורין להיפטר ממנה' בנוגע למאמץ?", b: "אף שהמטרה ניתנת מלמעלה, עמל בניית הרצון והחיסרון מוטל במלואו על כתפי הנברא." },
    { f: "מהו הקשר בין תפילה לבין אהבת חברים?", b: "במאמץ להשפיע לחברים מתגלה חוסר היכולת המוחלט לאהוב, ומתוכו נולדת תפילה אמיתית לתיקון." },
    { f: "כיצד חשבון נפש לפני התפילה מטהר את הכוונה?", b: "הוא חושף את האינטרסים האנוכיים הזרים, מנפה מטרות שווא וממקד את הזעקה בנקודת האמת." },
    { f: "מה ההבדל בין המתנה פסיבית לבין תפילה רוחנית?", b: "פסיביות היא ויתור על המערכה, ואילו תפילה אמיתית היא צעקת הלוחם הנאבק עד קצה גבול יכולתו." },
    { f: "כיצד משתקף אור התורה בתוך התפילה?", b: "המאור המחזיר למוטב שנמשך בלימוד מאיר את חשכת הלב ומעורר תפילה עמוקה לגאולה." },
    { f: "מהי המשמעות של תפילה 'ממעמקים קראתיך'?", b: "זעקה הבוקעת מתחתית הרצון לקבל, מעומק תהום המאסר של האגו הצר." },
    { f: "כיצד מביאה התפילה לדבקות בבורא?", b: "על ידי השגת הרצון להשפיע זוכה האדם להשתוות הצורה עם הבורא, שהיא שיא הדבקות והאחדות." },
    { f: "מהו הלקח המעשי המרכזי של שיעור 18 על התפילה?", b: "אל תסתפק באמירת מילים; בנה חיסרון אמיתי בלבך, שכן הבורא שומע רק את זעקת האמת שבלב." }
  ],
  ru: [
    { f: "Каково каббалистическое определение молитвы?", b: "'Работа в сердце' (Авода шеба-Лев) — глубокое внутреннее выяснение желаний, намерений и истинной нехватки перед Творцом." },
    { f: "Что в науке Каббала означает понятие духовного 'сердца'?", b: "Сердце — это совокупность всех желаний получать, всех чувственных и волевых устремлений человека." },
    { f: "Как соотносятся между собой слова уст и желание сердца?", b: "Творец отвечает исключительно на подлинную внутреннюю нехватку (Хисарон) в глубине сердца, а не на механические слова." },
    { f: "Что такое 'Хисарон' в контексте молитвы?", b: "Подлинное внутреннее ощущение пустоты и дефицита духовного свойства, потребность сосуда (Кли) в исправлении и наполнении." },
    { f: "Почему механическое произнесение слов не считается истинной молитвой?", b: "Если сердце не жаждет того, о чем говорят уста, слова остаются мертвой внешней оболочкой без духовной силы." },
    { f: "Каково первое условие для ответа на молитву?", b: "Непоколебимая вера в то, что Творец действительно способен избавить человека из плена эгоизма." },
    { f: "Каково второе условие для ответа на молитву?", b: "Осознание отсутствия иного выбора: все собственные силы человека исчерпаны, и помочь может только Творец." },
    { f: "Каково третье условие для ответа на молитву?", b: "Просьба должна быть вопросом жизни и смерти, без решения которого душа погибает в эгоистическом желании получать." },
    { f: "Как молитва действует в качестве 'медиума' (средства связи)?", b: "Она не меняет Творца, но трансформирует самого человека, подготавливая его Кли к принятию Высшего Света отдачи." },
    { f: "О чем просит каббалист в истинной молитве как медиуме?", b: "Исключительно о нехватке к отдаче (желании отдавать) и о достижении подобия свойств с Творцом." },
    { f: "В чем главный посыл статьи 'Шамати 20' относительно постижения Лишма?", b: "Состояние Лишма (ради Творца / бескорыстная отдача) — это дар и озарение свыше, недостижимое силами одного человеческого разума." },
    { f: "Если Лишма — это дар свыше, зачем нужны усилия человека?", b: "Усилия и применение средств строят исправленные сосуды (Келим), которые по-настоящему жаждут получить альтруистический дар Лишма." },
    { f: "Какова роль неудач и бессилия в молитве согласно 'Шамати 20'?", b: "Убедившись в тщетности всех своих действий, человек приходит к полному бессилию, и только тогда рождается молитва из глубины сердца." },
    { f: "Когда человек становится способен на истинную и искреннюю молитву?", b: "После того как он испробовал все человеческие способы и осознал, что сам по себе ничего не может достичь без Творца." },
    { f: "Что означает понятие 'МА\"Н' (Маин Нуквин)?", b: "Женские воды — молитва, нехватка и пробуждение, поднимающиеся от нижнего творения и притягивающие Свет и изобилие свыше." },
    { f: "Какова роль 'пробуждения снизу' в духовной системе?", b: "Пробуждение снизу (молитва творения) запускает излияние Высшего Света и нисхождение Высших вод (МА\"Д)." },
    { f: "Что означает принцип 'Приходящему очиститься помогают'?", b: "Тому, кто искренне устремлен к отдаче и чистоте намерений, Творец посылает свыше силы для исправления и духовного подъема." },
    { f: "Как именно Творец помогает приходящему очиститься?", b: "Дарует ступень Лишма, пробуждает сердце и наделяет силой, превосходящей природный эгоизм человека." },
    { f: "В чем заключается 'работа в сердце' во время ежедневного выяснения?", b: "В разделении эгоистических желаний и стремления к отдаче, с непрестанной молитвой об исправлении своей природы." },
    { f: "Почему молитва никоим образом не меняет Самого Творца?", b: "Творец абсолютно добр и неизменен; молитва меняет воспринимающий сосуд, делая его способным удержать Свет." },
    { f: "В чем разница между религиозной и каббалистической молитвой?", b: "Обычная молитва просит о материальных благах или облегчении для эго, а каббалистическая молитва требует избавления от эгоизма." },
    { f: "Как на духовном пути рождается истинный Хисарон?", b: "Через постоянную работу в группе и учебу по первоисточникам, когда нехватка осознается как отсутствие Света отдачи." },
    { f: "Что означает, что тело 'не согласно с бременем Царства Небесного'?", b: "Эгоистическое желание получать инстинктивно противится бескорыстному труду ради Творца без личной выгоды." },
    { f: "Что делать человеку, если все органы его тела сопротивляются отдаче?", b: "У него нет иного выхода, кроме молитвы: излить сердце перед Творцом, моля склонить тело к отдаче." },
    { f: "Как достижение Лишма умерщвляет дурное начало (эгоизм)?", b: "Оно аннулирует самолюбие; эгоистические сосуды теряют свои функции и в духовном смысле считаются 'мертвыми'." },
    { f: "Почему важно знать, что без молитвы невозможно достичь Лишма?", b: "Это знание превращает молитву в абсолютную и насущную необходимость, разрушая самоуверенность и самодовольство." },
    { f: "Какова связь между подъемом МА\"Н и сосудом души?", b: "МА\"Н — это сама нехватка Кли; чем глубже и чище этот дефицит, тем больший Высший Свет способен наполнить сосуд." },
    { f: "Почему молитва определяется как признание бессилия эгоизма?", b: "Сердце открывает свою абсолютную зависимость от Творца, осознавая, что эго — это тюрьма, из которой невозможно выбраться в одиночку." },
    { f: "Как работа в группе связана с личной молитвой человека?", b: "Попытка искренне полюбить товарищей обнажает неспособность к отдаче, что рождает истинный крик о помощи." },
    { f: "Почему молитва считается непосредственным созиданием сосуда (Кли)?", b: "Наполнение может войти только туда, где есть соответствующая пустота; молитва проясняет и расширяет этот духовный вакуум." },
    { f: "Что значит выражение 'Творец слышит молитву'?", b: "Просьба входит в совершенный резонанс с Высшим законом отдачи, и Свет мгновенно заполняет открывшийся сосуд." },
    { f: "Какова роль духовного отчаяния в рождении молитвы?", b: "Духовное отчаяние означает полное истощение эгоистических ресурсов, что напрямую предшествует раскрытию Света." },
    { f: "Что такое 'пробуждение свыше' (Итарута де-Лэила)?", b: "Проявление и раскрытие Высшего Света в ответ на созревший, чистый подъем нехватки снизу (МА\"Н)." },
    { f: "Почему в статье 'Шамати 20' желание получать сравнивается с 'вором'?", b: "Потому что оно пытается украсть любую крупицу энергии и радости исключительно для собственного услаждения." },
    { f: "Почему в начале работы ради отдачи человек не чувствует вкуса и радости?", b: "Чтобы эгоизм не ощутил наслаждения; если бы он почувствовал выгоду, человек никогда не вышел бы в чистое Лишма." },
    { f: "Когда духовная работа становится радостью сама по себе?", b: "Когда человек привыкает отдавать, и возможность доставить радость Творцу становится высшей наградой." },
    { f: "В каком случае претензии и ропот в духовной работе обоснованы?", b: "Человек может роптать только на того хозяина, на которого действительно работает; работая на себя, нельзя требовать сил у Творца." },
    { f: "Что представляет собой внутреннее выяснение (Берур) в молитве?", b: "Анализ намерений: отделение того, что делается ради собственного эго, от того, что направлено на отдачу Творцу." },
    { f: "Что такое 'полное совершенство' в принятии бремени Царства Небесного?", b: "Желание только отдавать и полный отказ от использования желания получать ради себя." },
    { f: "Почему интеллектуального понимания недостаточно для молитвы сердца?", b: "Доводы ума не могут сдвинуть духовный сосуд; только реальная боль и нехватка в сердце притягивают Свет." },
    { f: "Как действует МА\"Н через ступени духовных миров?", b: "Нижняя ступень поднимает свой запрос к высшей, а высшая возносит его к Источнику, низводя ответный Свет." },
    { f: "Почему молитва названа единственным оружием против желания получать?", b: "Человек не в силах изменить свою природу; он может только взывать к Творцу о даровании второй природы отдачи." },
    { f: "Почему молитва — это длительный процесс, а не секундное действие?", b: "Цепь усилий и неудач шлифует и кристаллизует внутреннюю потребность, пока она не достигнет абсолютной правдивости." },
    { f: "Как проявляется вера в избавление в самых темных духовных состояниях?", b: "Даже когда эго не видит никакого выхода, точка в сердце уверена, что Творец способен спасти в мгновение ока." },
    { f: "Что означает утверждение: 'Творец жаждет молитвы праведников'?", b: "Творец ждет подготовленного сосуда, способного к отдаче, поскольку природа Его любви — наполнять и отдавать." },
    { f: "Какова связь между раскаянием (Тшува) и каббалистической молитвой?", b: "Раскаяние — это болезненное осознание зла своей природы, а молитва — мольба об избавлении от нее и слиянии с Творцом." },
    { f: "Как искренняя молитва защищает человека от духовной гордыни?", b: "Она укрепляет понимание того, что любое духовное достижение — это исключительно милость и незаслуженный подарок свыше." },
    { f: "В чем причина того, что на молитву долго нет видимого ответа?", b: "Хисарон еще не достиг нужной глубины и чистоты; Кли еще не готово удержать и не расплескать Высший Свет." },
    { f: "Что означает 'излить сердце перед Творцом'?", b: "Полная и безоговорочная передача всех тайных мыслей, страхов и своего бессилия под управление Творца." },
    { f: "Как молитвенник (Сидур) помогает внутренней работе каббалиста?", b: "Он служит точнейшей картой внутренних состояний и ступеней исправления, составленной постигшими мудрецами." },
    { f: "Почему переход к альтруизму (Лишма) считается чудом?", b: "Потому что перевернуть врожденную природу эгоизма в чистое бескорыстие возможно только преображающей силой Света." },
    { f: "Как молитва перерастает в живой диалог с Творцом?", b: "Когда движения сердца в точности соответствуют стремлению к Нему, раскрывается прямое внутреннее общение." },
    { f: "Что означает изречение: 'Не ты волен освободиться от этой работы'?", b: "Хотя результат дается свыше, вся работа по созданию истинного желания возложена исключительно на человека." },
    { f: "Какова связь между молитвой и любовью к товарищам?", b: "В усилиях отдавать товарищам раскрывается полное бессилие любить, что порождает подлинную молитву о помощи." },
    { f: "Как самоотчет перед молитвой очищает намерение человека?", b: "Он срывает маски с эгоистических целей, отсеивает ложь и фокусирует весь крик сердца в единую точку истины." },
    { f: "В чем отличие пассивного ожидания от духовной молитвы?", b: "Пассивность сдается без боя, тогда как молитва — это отчаянный крик воина, сражающегося до последнего предела сил." },
    { f: "Как Свет Торы отражается и раскрывается в молитве?", b: "Свет, привлекаемый при учебе, освещает тьму сердца, порождая глубокую мольбу о духовном исправлении." },
    { f: "Что значит фраза: 'Из глубин воззвал я к Тебе'?", b: "Крик, вырывающийся со дна эгоистического желания получать, из самой беспросветной тьмы тюрьмы эго." },
    { f: "Как молитва приводит к слиянию (Двекут) с Творцом?", b: "Обретая свойство отдачи через молитву, человек достигает подобия свойств с Творцом, что и есть слияние." },
    { f: "Каков главный практический вывод Урока 18 о молитве?", b: "Не ограничивайся словами уст; взращивай истинную нехватку в сердце, ибо Творец внимает только правде сердца." }
  ],
  de: [
    { f: "Was ist die kabbalistische Definition des Gebets?", b: "Die 'Arbeit im Herzen' (Awoda schebaLew), die tiefe innere Klärung von Wünschen, Absichten und Mängeln vor dem Schöpfer." },
    { f: "Was bedeutet das spirituelle 'Herz' in der Kabbala?", b: "Das Herz repräsentiert die Gesamtheit aller Wünsche zu empfangen sowie aller emotionalen und willentlichen Regungen des Menschen." },
    { f: "Wie verhalten sich die Worte des Mundes zum Verlangen des Herzens?", b: "Der Schöpfer antwortet ausschließlich auf den wahren Mangel (Chissaron) in den Tiefen des Herzens, niemals auf mechanische Lippenbekenntnisse." },
    { f: "Was bedeutet das Konzept 'Chissaron' beim Gebet?", b: "Ein echter innerer Mangel, die spirituelle Leere des Gefäßes (Kli), das sich nach Erfüllung und Korrektur sehnt." },
    { f: "Warum gilt das bloße mechanische Aufsagen von Worten nicht als Gebet?", b: "Weil Worte ohne das Verlangen des Herzens leblose Hüllen ohne spirituelle Kraft bleiben." },
    { f: "Was ist die erste Bedingung für die Erhörung eines Gebets?", b: "Felsenfestes Vertrauen, dass der Schöpfer wirklich fähig ist, den Menschen aus dem Gefängnis des Egoismus zu befreien." },
    { f: "Was ist die zweite Bedingung für die Erhörung eines Gebets?", b: "Die Einsicht, dass es keine andere Wahl gibt: Alle eigenen Kräfte haben versagt, und nur der Schöpfer allein kann helfen." },
    { f: "Was ist die dritte Bedingung für die Erhörung eines Gebets?", b: "Dass die Bitte eine Frage von Leben und Tod ist, ohne deren Erfüllung die Seele im Egoismus zugrunde geht." },
    { f: "Wie fungiert das Gebet als 'Medium' in der spirituellen Entwicklung?", b: "Es verändert nicht den Schöpfer, sondern transformiert den Menschen und bereitet das Kli auf das Licht des Gebens vor." },
    { f: "Worum bittet der Kabbalist im wahren Gebet als Medium?", b: "Ausschließlich um den Mangel an Geben (den Wunsch zu geben) und um Formgleichheit mit dem Schöpfer." },
    { f: "Was ist die Hauptaussage von Shamati Artikel 20 bezüglich Lischma?", b: "Lischma (um Seinetwillen / reines Geben) ist ein Geschenk von Oben, das der menschliche Verstand allein nicht erlangen kann." },
    { f: "Wenn Lischma ein Geschenk von Oben ist, warum sind eigene Anstrengungen nötig?", b: "Eigene Anstrengungen und Mittel erbauen im Menschen die korrigierten Gefäße (Kelim), die sich wahrhaft nach Lischma sehnen." },
    { f: "Welche Rolle spielt das Scheitern im Gebet nach Shamati 20?", b: "Wenn der Mensch sieht, dass all sein Tun vergeblich war, erreicht er völlige Hilflosigkeit und kann erst dann aus tiefstem Herzen beten." },
    { f: "Wann kann ein Mensch ein wahrhaft aufrichtiges Gebet sprechen?", b: "Erst nachdem er alle menschlichen Mittel ausgeschöpft hat und erkennt, dass er ohne den Schöpfer absolut nichts vermag." },
    { f: "Was bedeutet das Konzept 'MAN' (Majin Nukwin)?", b: "Weibliche Wasser; der Mangel, das Gebet und das Erwachen aus dem unteren Gefäß, das Fülle und Licht von Oben herabzieht." },
    { f: "Welche Rolle spielt das 'Erwachen von Unten' im spirituellen System?", b: "Das Erwachen von Unten (das Gebet des Geschöpfs) setzt das Fließen der Oberen Lichter (MAD) in Gang." },
    { f: "Was bedeutet das Prinzip 'Wer kommt, um sich zu reinigen, dem wird geholfen'?", b: "Wer aufrichtig nach Geben und Reinheit strebt, dem schenkt der Schöpfer von Oben die Kraft zur Korrektur und Erhebung." },
    { f: "Wie hilft der Schöpfer demjenigen, der kommt, um sich zu reinigen?", b: "Indem Er ihm den Zustand Lischma schenkt, sein Herz erweckt und ihm übernatürliche Kraft über seine Natur hinaus verleiht." },
    { f: "Was bedeutet die 'Arbeit im Herzen' bei der täglichen Klärung?", b: "Egoistische Wünsche vom Verlangen zu geben zu unterscheiden und um die Verwandlung der eigenen Natur zu beten." },
    { f: "Warum kann der Schöpfer durch ein Gebet nicht verändert werden?", b: "Weil der Schöpfer absolut gut und unveränderlich ist; das Gebet verändert nur das empfangende Gefäß für das Licht." },
    { f: "Was ist der Unterschied zwischen einem religiösen und einem kabbalistischen Gebet?", b: "Das religiöse Gebet erbittet materielle Güter oder Erleichterung fürs Ego, das kabbalistische Gebet bittet um Erlösung vom Egoismus." },
    { f: "Wie entsteht ein echter Chissaron auf dem spirituellen Weg?", b: "Durch beharrliche Arbeit in der Gruppe und das Studium der Quellen, wodurch der Mangel als Fehlen des Lichts des Gebens bewusst wird." },
    { f: "Was bedeutet es, dass der Körper 'mit dem Joch des Himmelreichs nicht einverstanden' ist?", b: "Das egoistische Verlangen sträubt sich instinktiv dagegen, ohne eigenen Lohn rein zur Freude des Schöpfers zu arbeiten." },
    { f: "Was soll man tun, wenn alle Organe des Körpers sich gegen das Geben wehren?", b: "Man muss sein Herz vor dem Schöpfer ausschütten und Ihn anflehen, dem Körper die Kraft zur Hingabe zu schenken." },
    { f: "Wie überwindet das Erreichen von Lischma den bösen Trieb?", b: "Es annulliert die Eigenliebe; die egoistischen Empfangsgefäße verlieren ihren Zweck und gelten spirituell als 'tot'." },
    { f: "Warum muss man wissen, dass Lischma ohne Gebet unerreichbar ist?", b: "Weil dieses Wissen das Gebet zu einer absoluten Notwendigkeit macht und jede trügerische Selbstzufriedenheit zerstört." },
    { f: "Wie hängen das Erheben von MAN und das Gefäß der Seele zusammen?", b: "MAN ist der Mangel des Kli selbst; je reiner und tiefer dieser Mangel ist, desto größeres Licht kann empfangen werden." },
    { f: "Inwiefern ist das Gebet ein Eingeständnis egoistischer Hilflosigkeit?", b: "Das Herz offenbart seine völlige Abhängigkeit und erkennt, dass das eigene Ego ohne göttliche Hilfe ein unentrinnbares Gefängnis ist." },
    { f: "Wie verbindet sich die Gruppenarbeit mit dem persönlichen Gebet?", b: "Der Versuch, die Freunde zu lieben, offenbart die eigene Unfähigkeit zum selbstlosen Geben und gebiert das wahre Gebet um Hilfe." },
    { f: "Warum gilt das Gebet als Erschaffung des spirituellen Gefäßes?", b: "Weil Erfüllung nur dort eintreten kann, wo ein Mangel existiert; das Gebet klärt und erweitert dieses spirituelle Vakuum." },
    { f: "Was bedeutet es, dass 'der Schöpfer das Gebet erhört'?", b: "Die Bitte schwingt in vollkommener Resonanz mit dem Gesetz des Gebens, und das Licht füllt augenblicklich das offene Gefäß." },
    { f: "Welche Rolle spielt spirituelle Verzweiflung beim Gebet?", b: "Sie markiert die völlige Erschöpfung aller egoistischen Kräfte und geht dem Einströmen des Lichts direkt voraus." },
    { f: "Was ist das 'Erwachen von Oben' (Itaruta de-Leila)?", b: "Die Offenbarung des Oberen Lichts, die als Antwort auf einen reifen, von unten erhobenen Mangel (MAN) herabfließt." },
    { f: "Warum wird das Verlangen zu empfangen in Shamati 20 mit einem 'Dieb' verglichen?", b: "Weil es versucht, jede Energie und Freude heimlich für den eigenen egoistischen Genuss zu stehlen." },
    { f: "Warum spürt der Mensch zu Beginn keine Freude bei der Arbeit des Gebens?", b: "Damit das Verlangen zu empfangen keinen Geschmack daran findet; fände es Geschmack, könnte man Lischma nie erreichen." },
    { f: "Wann wird die spirituelle Arbeit aus sich selbst heraus zur Freude?", b: "Wenn man sich an das Geben gewöhnt hat und die Freude des Schöpfers zum eigentlichen Lohn der Arbeit wird." },
    { f: "Wann ist Klagen in der spirituellen Arbeit berechtigt oder unberechtigt?", b: "Man kann nur bei dem Herrn klagen, für den man arbeitet; wer fürs Ego schuftet, hat kein Recht, vom Schöpfer Kraft zu fordern." },
    { f: "Was ist die innere Klärung (Berur) im Gebet?", b: "Die Trennung der Absichten: Erkennen, was der eigenen Befriedigung dient und was rein zur Freude des Schöpfers geschieht." },
    { f: "Was ist 'völlige Vollkommenheit' bei der Annahme des Himmelreichs?", b: "Ausschließlich geben zu wollen und vollständig auf den egoistischen Empfang zu verzichten." },
    { f: "Warum genügt intellektuelles Verstehen nicht für das Gebet des Herzens?", b: "Weil Argumente des Verstandes das Kli nicht bewegen können; nur ein im Herzen erlebter Mangel zieht das Licht an." },
    { f: "Wie wirkt MAN durch die Stufen der spirituellen Welten?", b: "Die untere Stufe hebt ihren Mangel zur höheren Stufe empor, welche ihn zur Quelle bringt und die Antwort herabzieht." },
    { f: "Warum ist das Gebet die einzige Waffe gegen das Verlangen zu empfangen?", b: "Weil der Mensch seine Natur nicht selbst ändern kann; er kann nur zum Schöpfer um eine neue Natur des Gebens rufen." },
    { f: "Warum ist das Gebet ein Prozess und kein einmaliger Akt?", b: "Weil eine Kette von Mühen und Rückschlägen den Mangel schleift und reifen lässt, bis er vollkommene Aufrichtigkeit erreicht." },
    { f: "Wie äußert sich der Glaube an Erlösung in den dunkelsten Zuständen?", b: "Selbst wenn der Verstand keinen Ausweg sieht, vertraut der Punkt im Herzen darauf, dass der Schöpfer im Nu retten kann." },
    { f: "Was bedeutet es, dass der Schöpfer 'sich nach dem Gebet der Gerechten sehnt'?", b: "Der Schöpfer sehnt sich nach einem bereiteten Kli des Gebens, da das Wesen Seiner Liebe im Schenken und Erfüllen liegt." },
    { f: "Welche Verbindung besteht zwischen Umkehr (Teschuwa) und Gebet?", b: "Umkehr ist das schmerzhafte Erkennen der eigenen egoistischen Natur, und das Gebet ist das Flehen um Befreiung daraus." },
    { f: "Wie schützt das Gebet vor spirituellem Hochmut?", b: "Es verankert das Bewusstsein, dass jede spirituelle Stufe ausschließlich ein unverdientes Geschenk und Gnade von Oben ist." },
    { f: "Warum bleibt ein Gebet scheinbar oft unbeantwortet?", b: "Weil der Mangel noch nicht die nötige Tiefe oder Reinheit erreicht hat und das Kli das Licht noch nicht halten könnte." },
    { f: "Was bedeutet es, 'sein Herz vor dem Schöpfer auszuschütten'?", b: "Alle verborgenen Wünsche, Ängste und Hilflosigkeiten rückhaltlos der Führung des Schöpfers zu übergeben." },
    { f: "Wie unterstützt das Gebetbuch (Siddur) die innere Arbeit des Kabbalisten?", b: "Es dient als präzise spirituelle Landkarte innerer Zustände und Korrekturen, verfasst von erleuchteten Weisen." },
    { f: "Warum gilt der Übergang zu Lischma als Wunder?", b: "Weil die Umkehrung der angeborenen Natur (Selbstliebe) in reine Hingabe nur durch die Kraft des Lichts möglich ist." },
    { f: "Wie wird das Gebet zu einem lebendigen Dialog mit dem Schöpfer?", b: "Wenn die Regungen des Herzens den Wunsch nach Annäherung an Ihn genau widerspiegeln, öffnet sich ein inneres Zwiegespräch." },
    { f: "Was bedeutet: 'Es steht dir nicht frei, dich der Mühe zu entziehen'?", b: "Obwohl das Ziel ein Geschenk von Oben ist, liegt der Aufbau des Mangels und des Verlangens vollkommen beim Menschen." },
    { f: "Was ist die Verbindung zwischen Gebet und Freundenliebe?", b: "Im Bemühen, den Freunden zu geben, wird die eigene Unfähigkeit zu wahrer Liebe offenbar, was ein echtes Gebet erzeugt." },
    { f: "Wie reinigt die innere Rechenschaft vor dem Gebet die Absicht?", b: "Sie deckt egoistische Hintergedanken auf, sondert falsche Ziele aus und bündelt den Schrei auf den Punkt der Wahrheit." },
    { f: "Was unterscheidet passives Warten von spirituellem Gebet?", b: "Passivität gibt den Kampf auf, während das Gebet der äußerste Hilferuf eines bis an die Grenze kämpfenden Menschen ist." },
    { f: "Wie spiegelt sich das Licht der Tora im Gebet wider?", b: "Das beim Lernen angezogene Reformierende Licht erhellt das dunkle Herz und weckt ein tiefes Flehen um Korrektur." },
    { f: "Was bedeutet es, dass das wahre Gebet 'aus der Tiefe ruft'?", b: "Ein Schrei, der vom tiefsten Grund des egoistischen Empfangens, aus dem finstersten Gefängnis des Ego aufsteigt." },
    { f: "Wie führt das Gebet zu Dwekut (Anhaftung) an den Schöpfer?", b: "Durch die Erlangung der Eigenschaft des Gebens erreicht der Mensch Formgleichheit mit dem Schöpfer und höchste Einheit." },
    { f: "Was ist die wichtigste praktische Lehre aus Lektion 18 über das Gebet?", b: "Begnüge dich nicht mit Lippenbekenntnissen; baue einen echten Mangel im Herzen auf, denn der Schöpfer hört nur das Herz." }
  ],
  es: [
    { f: "¿Cuál es la definición cabalística de la plegaria?", b: "El 'trabajo en el corazón' (Avodá shebaLev), una profunda clarificación interna de los deseos, intenciones y carencias ante el Creador." },
    { f: "¿Qué representa el 'corazón' espiritual en la Cabalá?", b: "El corazón representa la suma total de los deseos de recibir del hombre y todas sus inclinaciones emocionales y de la voluntad." },
    { f: "¿Cómo se relacionan las palabras de la boca con el deseo del corazón?", b: "El Creador responde exclusivamente a la verdadera carencia (Jisaron) en lo profundo del corazón, nunca a las palabras mecánicas de la boca." },
    { f: "¿Qué es el concepto de 'Jisaron' en la plegaria?", b: "Una genuina carencia interna, el vacío del recipiente (Kli) que anhela con fervor la plenitud y la corrección espiritual." },
    { f: "¿Por qué la repetición mecánica de palabras no se considera una plegaria auténtica?", b: "Porque si el corazón no anhela lo que pronuncian los labios, las palabras quedan como formas muertas sin vitalidad espiritual." },
    { f: "¿Cuál es la primera condición para que la plegaria sea escuchada?", b: "Tener una fe inquebrantable de que el Creador es verdaderamente capaz de liberar al hombre de la prisión del egoísmo." },
    { f: "¿Cuál es la segunda condición para que la plegaria sea escuchada?", b: "Reconocer que no hay otra opción: todas las fuerzas humanas han fracasado y solo el Creador puede ayudar." },
    { f: "¿Cuál es la tercera condición para que la plegaria sea escuchada?", b: "Que la petición sea verdaderamente una cuestión de vida o muerte, sin la cual el alma perece en el deseo de recibir." },
    { f: "¿Cómo actúa la plegaria como un 'médium' en la evolución espiritual?", b: "No busca cambiar al Creador, sino que transforma al ser humano, preparando el Kli para recibir la luz del otorgamiento." },
    { f: "¿Qué pide el cabalista en la verdadera plegaria como médium?", b: "Únicamente la carencia de otorgamiento (el deseo de otorgar) y la equivalencia de forma con el Creador." },
    { f: "¿Cuál es el mensaje central del artículo 20 de Shamati sobre alcanzar Lishmá?", b: "Lishmá (por Su Nombre / otorgamiento altruista) es un regalo y una iluminación de lo Alto que la mente humana no puede lograr por sí misma." },
    { f: "Si Lishmá es un regalo de lo Alto, ¿por qué es necesario el esfuerzo humano?", b: "Porque los esfuerzos y remedios construyen en el ser humano las vasijas corregidas (Kelim) que genuinamente anhelan Lishmá." },
    { f: "¿Qué papel juega el fracaso en la plegaria según Shamati 20?", b: "Cuando el hombre ve que todas sus acciones han sido inútiles, alcanza una impotencia total y solo entonces puede orar desde el fondo del corazón." },
    { f: "¿Cuándo es capaz una persona de emitir una plegaria sincera desde lo profundo del corazón?", b: "Solo después de haber agotado todos los recursos humanos y reconocer que por sí misma nada puede lograr sin el Creador." },
    { f: "¿Qué significa el concepto de 'MAN' (Mayin Nukvin)?", b: "Aguas femeninas; la carencia, plegaria y despertar que ascienden desde el recipiente inferior y atraen la abundancia y la luz de lo Alto." },
    { f: "¿Cuál es el papel del 'despertar desde abajo' en el sistema espiritual?", b: "El despertar desde abajo (la plegaria de la criatura) activa el flujo de las Luces Superiores (MAD - Mayin Dejrin)." },
    { f: "¿Qué significa el principio 'Aquel que viene a purificarse recibe ayuda'?", b: "A quien verdaderamente se esfuerza por el otorgamiento y la pureza, el Creador le otorga desde lo Alto fuerza, corrección y elevación." },
    { f: "¿Cómo ayuda el Creador a quien viene a purificarse?", b: "Concediéndole el estado de Lishmá, despertando su corazón y otorgándole una fuerza que trasciende su naturaleza egoísta." },
    { f: "¿Qué es el 'trabajo en el corazón' durante la clarificación interna diaria?", b: "Distinguir entre los deseos egoístas y el deseo de otorgar, rezando pidiendo la transformación de la propia naturaleza." },
    { f: "¿Por qué el Creador no cambia mediante la plegaria?", b: "Porque el Creador es el Bien Absoluto e Inmutable; la plegaria transforma la vasija receptora para hacerla apta para la luz." },
    { f: "¿Cuál es la diferencia entre la plegaria religiosa convencional y la cabalística?", b: "La plegaria convencional pide bienes materiales o alivio egoísta, mientras que la cabalística ruega por la redención del egoísmo." },
    { f: "¿Cómo nace un auténtico Jisaron en el camino espiritual?", b: "Mediante el trabajo constante en el grupo y el estudio de las fuentes, clarificando la carencia como la ausencia de la luz de otorgamiento." },
    { f: "¿Qué significa que el cuerpo 'no está de acuerdo con el yugo del Reino de los Cielos'?", b: "El deseo de recibir natural se resiste por instinto a trabajar exclusivamente por el contento del Creador sin obtener beneficio personal." },
    { f: "¿Qué debe hacer la persona cuando ve que todos sus órganos se oponen al otorgamiento?", b: "No tiene más remedio que la plegaria: derramar su corazón ante el Creador para que someta su cuerpo al otorgamiento." },
    { f: "¿Cómo destruye el logro de Lishmá a la inclinación al mal?", b: "Anula el amor propio; las vasijas de recepción pierden su función egoísta y se consideran espiritualmente 'muertas'." },
    { f: "¿Por qué es crucial saber que sin plegaria es imposible alcanzar Lishmá?", b: "Porque esta certeza convierte la plegaria en una necesidad absoluta y urgente, disipando la autosuficiencia y la complacencia." },
    { f: "¿Cuál es la conexión entre elevar MAN y la vasija del alma?", b: "El MAN es la carencia misma; cuanto más pura y profunda sea la falta, mayor será la Luz que el Kli puede albergar." },
    { f: "¿Por qué la plegaria es una confesión de la impotencia del egoísmo?", b: "Porque el corazón revela su dependencia absoluta y reconoce que su propio ego es una prisión ineludible sin el auxilio divino." },
    { f: "¿Cómo se integra el trabajo en el grupo con la plegaria personal?", b: "El esfuerzo por amar a los compañeros revela la total incapacidad de otorgar, haciendo brotar un auténtico clamor de ayuda." },
    { f: "¿Por qué se considera que la plegaria crea la vasija espiritual misma?", b: "Porque el llenado solo puede entrar donde existe una carencia correspondiente; la plegaria define y ensancha este vacío espiritual." },
    { f: "¿Qué significa que 'el Creador escucha la plegaria'?", b: "Que la petición entra en perfecta resonancia con la ley superior del otorgamiento y la Luz llena de inmediato el Kli abierto." },
    { f: "¿Qué papel desempeña la desesperación espiritual en la plegaria?", b: "Marca el agotamiento total de las fuerzas egoístas, precediendo de forma inmediata a la irrupción del socorro de lo Alto." },
    { f: "¿Qué es el 'despertar de lo Alto' (Itaruta de-Leila)?", b: "La manifestación de la Luz Superior que desciende en respuesta directa a una carencia madura y purificada desde abajo (MAN)." },
    { f: "¿Por qué el deseo de recibir se compara con un 'ladrón' en Shamati 20?", b: "Porque intenta hurtar y apropiarse de cada partícula de energía y placer únicamente para su propio deleite egoísta." },
    { f: "¿Por qué al principio la persona no siente vitalidad en el trabajo por otorgar?", b: "Para que el deseo de recibir no le encuentre gusto; si sintiera placer egoísta, el hombre jamás se elevaría al puro Lishmá." },
    { f: "¿Cuándo se convierte el trabajo espiritual en una alegría intrínseca?", b: "Cuando uno se acostumbra al otorgamiento, y brindar placer al Creador se convierte en la recompensa misma del esfuerzo." },
    { f: "¿Cuándo es justificada o injustificada una queja en el trabajo espiritual?", b: "Uno solo puede quejarse ante el amo para el que realmente trabaja; trabajar para el ego no da derecho a exigir fuerzas al Creador." },
    { f: "¿Qué es la clarificación interna (Berur) en la plegaria?", b: "Discernir intenciones: separar lo que se hace por propio deleite egoísta de lo que realmente busca agradar al Creador." },
    { f: "¿Qué es la 'perfección absoluta' al asumir el yugo del Reino de los Cielos?", b: "Desear únicamente otorgar y renunciar por completo a la recepción para beneficio propio." },
    { f: "¿Por qué no basta la comprensión intelectual para la plegaria del corazón?", b: "Porque los argumentos mentales no conmueven la vasija; solo una carencia real experimentada en el corazón atrae la Luz." },
    { f: "¿Cómo opera el MAN a través de los grados de los mundos espirituales?", b: "El grado inferior eleva su carencia al superior, y este la eleva hasta la Fuente, atrayendo la respuesta hacia abajo." },
    { f: "¿Por qué se define la plegaria como la única arma contra el deseo de recibir?", b: "Porque el hombre no puede cambiar su naturaleza creada; solo puede clamar al Creador para que le conceda una nueva naturaleza." },
    { f: "¿Por qué la plegaria es un proceso continuo y no un acto momentáneo?", b: "Porque una serie de esfuerzos y caídas pule y madura la carencia interior hasta que alcanza una sinceridad absoluta." },
    { f: "¿Cómo se manifiesta la fe en la liberación en los estados más oscuros?", b: "Aunque el cuerpo no vea salida, el punto en el corazón tiene la certeza de que el Creador puede salvarlo en un parpadeo." },
    { f: "¿Qué significa que el Creador 'anhela la plegaria de los justos'?", b: "El Creador anhela una vasija preparada capaz de otorgar, pues la naturaleza de Su amor es colmar y dar plenitud." },
    { f: "¿Qué relación existe entre el arrepentimiento y la plegaria cabalística?", b: "El arrepentimiento es el doloroso reconocimiento de la naturaleza egoísta, y la plegaria es la súplica para ser liberado de ella." },
    { f: "¿Cómo protege la plegaria a la persona del orgullo espiritual?", b: "Inculca la certeza constante de que todo logro espiritual es pura gracia y un regalo inmerecido de lo Alto." },
    { f: "¿Por qué a menudo parece que una plegaria no recibe respuesta?", b: "Porque la carencia aún no ha alcanzado la profundidad o pureza requeridas; el Kli aún no es apto para retener la Luz." },
    { f: "¿Qué significa 'derramar el corazón ante el Creador'?", b: "Entregarle sin reservas todos los anhelos ocultos, temores e impotencias al gobierno absoluto del Creador." },
    { f: "¿Cómo ayuda el libro de rezos (Sidur) al trabajo interior del cabalista?", b: "Sirve como un mapa espiritual exacto de estados internos y procesos de corrección trazado por sabios que alcanzaron la meta." },
    { f: "¿Por qué el paso a Lishmá es considerado un milagro supremo?", b: "Porque transformar la naturaleza creada (amor propio) en puro altruismo solo es posible mediante el poder transformador de la Luz." },
    { f: "¿Cómo se convierte la plegaria en un diálogo vivo con el Creador?", b: "Cuando los latidos del corazón reflejan con exactitud el anhelo de adhesión, se abre una comunicación interior directa." },
    { f: "¿Qué significa que 'uno no es libre de eximirse del esfuerzo'?", b: "Aunque la meta se otorga desde lo Alto, el arduo trabajo de forjar el deseo y la carencia es responsabilidad exclusiva del hombre." },
    { f: "¿Cuál es el nexo entre la plegaria y el amor a los compañeros?", b: "El esfuerzo por otorgar a los amigos revela la total incapacidad de amar desinteresadamente, gestando un verdadero clamor de ayuda." },
    { f: "¿Cómo purifica la intención el balance interior previo a la plegaria?", b: "Desnuda los motivos egoístas ocultos, descarta objetivos falsos y enfoca el clamor en un único punto de verdad." },
    { f: "¿Cuál es la diferencia entre la espera pasiva y la plegaria espiritual?", b: "La pasividad se rinde sin luchar, mientras que la plegaria es el grito supremo de quien combate hasta el límite de sus fuerzas." },
    { f: "¿Cómo se refleja la Luz de la Torá en la plegaria?", b: "La Luz que Reforma atraída en el estudio ilumina la oscuridad del corazón, despertando una profunda súplica de corrección." },
    { f: "¿Qué significa que la verdadera plegaria 'clama desde las profundidades'?", b: "Un grito que brota desde el fondo del deseo de recibir, desde el abismo más sombrío de la prisión del ego." },
    { f: "¿Cómo conduce la plegaria a la adhesión (Dvekut) con el Creador?", b: "Al adquirir la cualidad de otorgamiento, el hombre alcanza la equivalencia de forma con el Creador, logrando la unión total." },
    { f: "¿Cuál es la máxima enseñanza práctica de la Lección 18 sobre la plegaria?", b: "No te conformes con pronunciar palabras; construye una carencia real en tu corazón, pues el Creador solo atiende a la verdad del corazón." }
  ],
  fr: [
    { f: "¿Quelle est la définition kabbalistique de la prière ?", b: "Le 'travail dans le cœur' (Avoda shebaLev), une profonde clarification intérieure des désirs, intentions et manques devant le Créateur." },
    { f: "¿Que représente le 'cœur' spirituel dans la Kabbale ?", b: "Le cœur incarne la somme totale des désirs de recevoir de l'homme ainsi que l'ensemble de ses penchants émotionnels et volontaires." },
    { f: "¿Comment les paroles de la bouche se rapportent-elles au désir du cœur ?", b: "Le Créateur répond exclusivement au manque réel (Hissaron) tapi au fond du cœur, jamais aux paroles mécaniques prononcées par les lèvres." },
    { f: "¿Qu'est-ce que le concept de 'Hissaron' dans la prière ?", b: "Un manque intérieur authentique, le vide du récipient (Kli) aspirant ardemment à la plénitude et à la correction spirituelle." },
    { f: "¿Pourquoi la récitation mécanique de mots ne constitue-t-elle pas une prière authentique ?", b: "Parce que si le cœur n'aspire pas à ce que les lèvres expriment, les mots demeurent des coquilles mortes sans force spirituelle." },
    { f: "¿Quelle est la première condition pour que la prière soit exaucée ?", b: "Une foi inébranlable dans le fait que le Créateur a le pouvoir absolu de délivrer l'homme de la prison de l'égoïsme." },
    { f: "¿Quelle est la deuxième condition pour que la prière soit exaucée ?", b: "Reconnaître qu'il n'y a pas d'autre issue : toutes les forces humaines ont échoué et seul le Créateur peut apporter le salut." },
    { f: "¿Quelle est la troisième condition pour que la prière soit exaucée ?", b: "Que la demande soit une question de vie ou de mort, sans laquelle l'âme périt engloutie dans le désir de recevoir." },
    { f: "¿Comment la prière agit-elle comme un 'médium' dans l'évolution spirituelle ?", b: "Elle ne vise pas à modifier le Créateur, mais transforme l'être humain en préparant le Kli à recevoir la lumière du don." },
    { f: "¿Que demande le kabbaliste dans la prière authentique en tant que médium ?", b: "Exclusivement le manque de don (le désir de donner) et l'équivalence de forme avec le Créateur." },
    { f: "¿Quel est le message fondamental de l'article 20 de Shamati concernant l'atteinte de Lishma ?", b: "Lishma (en Son Nom / don désintéressé) est un don et une illumination d'en Haut que l'esprit humain ne peut atteindre seul." },
    { f: "Si Lishma est un don d'en Haut, pourquoi l'effort humain est-il indispensable ?", b: "Parce que les efforts et les remèdes construisent chez l'homme les récipients corrigés (Kelim) qui désirent véritablement Lishma." },
    { f: "¿Quel rôle joue l'échec dans la prière selon Shamati 20 ?", b: "En constatant l'échec de toutes ses tentatives, l'homme sombre dans une totale impuissance et peut enfin prier du fond du cœur." },
    { f: "¿Quand l'homme devient-il apte à formuler une prière sincère du fond du cœur ?", b: "Seulement après avoir épuisé toutes les ressources humaines et compris que par lui-même, il ne peut rien accomplir sans le Créateur." },
    { f: "¿Que signifie le concept de 'MAN' (Mayin Noukvin) ?", b: "Eaux féminines ; le manque, la prière et l'éveil qui montent du récipient inférieur pour attirer l'abondance et les lumières d'en Haut." },
    { f: "¿Quel est le rôle de 'l'éveil d'en bas' dans le système spirituel ?", b: "L'éveil d'en bas (la prière de la créature) déclenche l'épanchement des Lumières Supérieures (MAD - Mayin Dehrin)." },
    { f: "¿Que signifie le principe 'Celui qui vient pour se purifier est aidé' ?", b: "Celui qui aspire sincèrement au don et à la pureté reçoit d'en Haut la force, la correction et l'élévation accordées par le Créateur." },
    { f: "¿Comment le Créateur aide-t-il celui qui vient pour se purifier ?", b: "En lui conférant l'état de Lishma, en éveillant son cœur et en lui octroyant une force qui transcende sa nature égoïste." },
    { f: "¿En quoi consiste le 'travail dans le cœur' lors de la clarification intérieure quotidienne ?", b: "Distinguer les désirs égoïstes du désir de donner, en priant constamment pour la transformation de sa propre nature." },
    { f: "¿Pourquoi le Créateur demeure-t-il inchangé par la prière ?", b: "Parce que le Créateur est le Bien Absolu et Immuable ; la prière modifie le récipient récepteur afin de l'accorder à la lumière." },
    { f: "¿Quelle est la différence entre la prière religieuse ordinaire et la prière kabbalistique ?", b: "La prière ordinaire sollicite des biens temporels ou un répit pour l'ego, tandis que la prière kabbalistique réclame d'être racheté de l'égoïsme." },
    { f: "¿Comment naît un véritable Hissaron sur le chemin spirituel ?", b: "Par un labeur constant au sein du groupe et l'étude des sources, révélant le manque comme étant l'absence de la lumière du don." },
    { f: "¿Que signifie le fait que le corps 'ne consente pas au joug du Royaume des Cieux' ?", b: "Le désir de recevoir inné refuse instinctivement de peiner sans récompense personnelle, uniquement pour satisfaire le Créateur." },
    { f: "¿Que doit faire l'homme lorsqu'il s'aperçoit que ses organes résistent au don ?", b: "Il n'a d'autre recours que la prière : épancher son cœur devant le Créateur afin qu'Il soumette son corps au don." },
    { f: "¿Comment l'accession à Lishma terrasse-t-elle le mauvais penchant ?", b: "Elle anéantit l'amour-propre ; les récipients de réception perdent leur fonction égoïste et sont tenus pour 'morts' au sens spirituel." },
    { f: "¿Pourquoi est-il capital de savoir que Lishma est inaccessible sans la prière ?", b: "Parce que cette prise de conscience fait de la prière une nécessité vitale et absolue, dissipant toute illusion de suffisance." },
    { f: "¿Quel est le lien entre l'élévation de MAN et le récipient de l'âme ?", b: "Le MAN est le manque même du Kli ; plus ce manque est pur et profond, plus grande est la Lumière que le récipient peut accueillir." },
    { f: "¿En quoi la prière constitue-t-elle l'aveu de l'impuissance de l'ego ?", b: "Le cœur dévoile sa dépendance absolue, reconnaissant que son propre ego forme une geôle inviolable sans l'intervention divine." },
    { f: "¿Comment le travail de groupe s'articule-t-il avec la prière personnelle ?", b: "L'effort pour aimer les compagnons met à nu l'incapacité d'aimer gratuitement, faisant jaillir un cri d'appel au secours véritable." },
    { f: "¿Pourquoi la prière est-elle considérée comme la création même du récipient spirituel ?", b: "Parce que le remplissage ne peut survenir que là où réside un manque ; la prière circonscrit et dilate ce vide spirituel." },
    { f: "¿Que signifie l'expression 'le Créateur écoute la prière' ?", b: "La requête entre en résonance parfaite avec la loi suprême du don, et la Lumière vient aussitôt combler le récipient ouvert." },
    { f: "¿Quel rôle le désespoir spirituel joue-t-il dans la prière ?", b: "Il signale l'épuisement total des forces de l'ego, prélude immédiat à l'intervention et à la délivrance accordées par la Lumière." },
    { f: "¿Qu'est-ce que 'l'éveil d'en Haut' (Itarouta de-Leïla) ?", b: "Le dévoilement de la Lumière Supérieure survenant en réponse directe à un manque mature et purifié élevé d'en bas (MAN)." },
    { f: "¿Pourquoi le désir de recevoir est-il assimilé à un 'voleur' dans Shamati 20 ?", b: "Parce qu'il cherche à dérober et monopoliser chaque parcelle d'énergie et de plaisir pour sa seule jouissance personnelle." },
    { f: "¿Pourquoi l'homme ne ressent-il au début aucune saveur à œuvrer pour le don ?", b: "Afin que le désir de recevoir n'y goûte aucun plaisir ; s'il en tirait jouissance, l'homme ne pourrait jamais s'élever au pur Lishma." },
    { f: "¿Quand le travail spirituel devient-il une joie en lui-même ?", b: "Lorsque l'homme s'accoutume au don, et que procurer du contentement au Créateur devient la récompense suprême de son labeur." },
    { f: "¿Quand une récrimination est-elle légitime ou illégitime dans le travail spirituel ?", b: "On ne peut réclamer qu'auprès du maître pour lequel on travaille ; peiner pour son ego ne donne aucun droit d'exiger des forces du Créateur." },
    { f: "¿Qu'est-ce que la clarification intérieure (Berour) dans la prière ?", b: "Trier les intentions : distinguer ce qui sert sa propre satisfaction égoïste de ce qui est voué à réjouir le Créateur." },
    { f: "¿Qu'est-ce que la 'perfection absolue' dans l'acceptation du joug divin ?", b: "Ne désirer rien d'autre que donner, en renonçant intégralement à recevoir pour soi-même." },
    { f: "¿Pourquoi la compréhension intellectuelle est-elle insuffisante pour la prière du cœur ?", b: "Parce que les arguments de l'esprit n'émeuvent pas le Kli ; seul un manque réel éprouvé dans le cœur attire la Lumière." },
    { f: "¿Comment le MAN agit-il à travers les degrés des mondes spirituels ?", b: "Le degré inférieur transmet son manque au degré supérieur, qui l'élève jusqu'à la Source, faisant redescendre la réponse." },
    { f: "¿Pourquoi la prière est-elle désignée comme la seule arme contre le désir de recevoir ?", b: "Parce que l'homme ne peut altérer sa propre nature ; il ne peut que supplier le Créateur de lui accorder une nouvelle nature de don." },
    { f: "¿Pourquoi la prière est-elle un cheminement continu plutôt qu'un acte ponctuel ?", b: "Parce qu'une succession d'efforts et de chutes façonne et fait mûrir le manque jusqu'à ce qu'il atteigne une sincérité absolue." },
    { f: "¿Comment la foi en la délivrance s'exprime-t-elle dans les états les plus sombres ?", b: "Même quand le corps ne voit aucune issue, le point dans le cœur demeure certain que le Créateur peut le sauver en un instant." },
    { f: "¿Que signifie la parole selon laquelle le Créateur 'désire la prière des justes' ?", b: "Le Créateur languit après un Kli prêt et apte au don, car la nature même de Son amour est d'accorder la plénitude." },
    { f: "¿Quel lien unit le repentir à la prière kabbalistique ?", b: "Le repentir est la prise de conscience cuisante de la noirceur de l'ego, et la prière est la supplication pour en être arraché." },
    { f: "¿Comment la prière préserve-t-elle l'homme de l'orgueil spirituel ?", b: "Elle ancre la conviction inébranlable que chaque degré spirituel atteint est uniquement un don immérité et une grâce d'en Haut." },
    { f: "¿Pourquoi une prière semble-t-elle parfois demeurer sans réponse ?", b: "Parce que le manque n'a pas encore atteint la profondeur ou la pureté requises ; le récipient ne saurait encore contenir la Lumière." },
    { f: "¿Que signifie 'épancher son cœur devant le Créateur' ?", b: "Lui remettre sans feinte ni réserve l'ensemble de ses désirs secrets, de ses craintes et de son impuissance." },
    { f: "¿Comment le livre de prières (Siddour) soutient-il le travail intérieur du kabbaliste ?", b: "Il fait office de carte spirituelle des états intérieurs et des étapes de correction dressée par des sages accomplis." },
    { f: "¿Pourquoi le passage à Lishma est-il considéré comme un miracle surnaturel ?", b: "Parce que métamorphoser la nature créée (amour-propre) en altruisme pur n'est possible que par l'action transformatrice de la Lumière." },
    { f: "¿Comment la prière s'érige-t-elle en dialogue vivant avec le Créateur ?", b: "Dès lors que les battements du cœur reflètent fidèlement l'ardeur de s'unir à Lui, une communion intime s'ouvre spontanément." },
    { f: "¿Que signifie l'adage 'Tu n'es pas libre de te soustraire au labeur' ?", b: "Bien que l'accomplissement soit un don d'en Haut, l'effort pour forger le désir incombe tout entier à l'homme." },
    { f: "¿Quelle est la relation entre la prière et l'amour des compagnons ?", b: "C'est en s'efforçant de donner aux amis que l'on prend la mesure de son incapacité d'aimer, engendrant un appel au secours sincère." },
    { f: "¿Comment l'introspection préalable purifie-t-elle l'intention de la prière ?", b: "Elle démasque les arrière-pensées égoïstes, élague les desseins illusoires et rassemble le cri vers l'unique vérité." },
    { f: "¿En quoi l'attente passive diffère-t-elle de la prière spirituelle ?", b: "La passivité capitule sans combattre, tandis que la prière est l'ultime clameur du soldat luttant jusqu'à l'extrême limite de ses forces." },
    { f: "¿Comment la Lumière de la Torah s'illustre-t-elle dans la prière ?", b: "La Lumière qui Ramène au Bien attirée par l'étude dévoile les ténèbres du cœur, provoquant un appel vibrant à la délivrance." },
    { f: "¿Que signifie l'injonction selon laquelle la vraie prière 'crie du fond des abîmes' ?", b: "C'est un cri montant des profondeurs du désir de recevoir, du fond le plus obscur de la geôle du moi égoïste." },
    { f: "¿Comment la prière conduit-elle au Dvekout (adhésion) avec le Créateur ?", b: "En acquérant le désir de donner, l'homme parvient à l'équivalence de forme avec le Créateur, ce qui scelle l'union suprême." },
    { f: "¿Quelle est la leçon pratique essentielle de la Leçon 18 au sujet de la prière ?", b: "Ne te contente pas de réciter des formules ; bâtis un manque véritable en ton cœur, car le Créateur n'exauce que la vérité du cœur." }
  ],
  it: [
    { f: "Qual è la definizione cabalistica della preghiera?", b: "Il 'lavoro nel cuore' (Avoda shebaLev), un profondo chiarimento interiore dei desideri, delle intenzioni e delle mancanze dinanzi al Creatore." },
    { f: "Cosa rappresenta il 'cuore' spirituale nella Kabbalah?", b: "Il cuore rappresenta la totalità dei desideri di ricevere dell'uomo e l'insieme delle sue inclinazioni emotive e volitive." },
    { f: "In che rapporto stanno le parole della bocca con il desiderio del cuore?", b: "Il Creatore risponde esclusivamente alla vera mancanza (Hisaron) nel profondo del cuore, mai alle parole meccaniche pronunciate dalle labbra." },
    { f: "Che cos'è il concetto di 'Hisaron' nella preghiera?", b: "Un'autentica carenza interiore, il vuoto del vaso (Kli) che anela con forza al riempimento e alla correzione spirituale." },
    { f: "Perché la recitazione meccanica delle parole non è considerata una preghiera autentica?", b: "Perché se il cuore non brama ciò che le labbra esprimono, le parole restano forme spente prive di vitalità spirituale." },
    { f: "Qual è la prima condizione affinché la preghiera sia esaudita?", b: "Una fede incrollabile nel fatto che il Creatore sia realmente in grado di liberare l'uomo dalla prigione dell'egoismo." },
    { f: "Qual è la seconda condizione affinché la preghiera sia esaudita?", b: "Riconoscere che non vi è altra scelta: tutte le forze umane hanno fallito e solo il Creatore può recare aiuto." },
    { f: "Qual è la terza condizione affinché la preghiera sia esaudita?", b: "Che la richiesta sia realmente una questione di vita o di morte, senza la quale l'anima perisce nel desiderio di ricevere." },
    { f: "Come agisce la preghiera in qualità di 'medium' nell'evoluzione interiore?", b: "Non mira a mutare il Creatore, bensì trasforma l'essere umano, preparando il Kli ad accogliere la luce della dazione." },
    { f: "Cosa domanda il cabalista nella vera preghiera come medium?", b: "Esclusivamente la mancanza di dazione (il desiderio di donare) e l'equivalenza di forma con il Creatore." },
    { f: "Qual è il messaggio cardine dell'articolo 20 di Shamati sul raggiungimento di Lishma?", b: "Lishma (per il Suo Nome / dazione altruistica) è un dono e un'illuminazione dall'Alto che la mente umana non può conquistare da sola." },
    { f: "Se Lishma è un dono dall'Alto, perché l'impegno umano è indispensabile?", b: "Perché gli sforzi e i rimedi costruiscono nell'uomo i vasi corretti (Kelim) che anelano sinceramente a ricevere Lishma." },
    { f: "Quale ruolo ricopre il fallimento nella preghiera secondo Shamati 20?", b: "Quando l'uomo constata che ogni sua azione è stata vana, giunge a una totale impotenza e solo allora può pregare dal profondo del cuore." },
    { f: "Quando una persona è capace di innalzare una preghiera sincera dal profondo del cuore?", b: "Solo dopo aver tentato ogni rimedio umano e aver riconosciuto che da sola non può compiere nulla senza il Creatore." },
    { f: "Cosa esprime il concetto di 'MAN' (Mayin Nukvin)?", b: "Acque femminili; la mancanza, la preghiera e il risveglio che salgono dal vaso inferiore attirando abbondanza e luce dall'Alto." },
    { f: "Qual è il ruolo del 'risveglio dal basso' nel sistema spirituale?", b: "Il risveglio dal basso (la preghiera del creato) innesca l'effusione delle Luci Superiori (MAD - Mayin Dehrin)." },
    { f: "Cosa significa il principio 'Chi viene per purificarsi riceve aiuto'?", b: "Chiunque tenda con sincerità alla dazione e alla purezza riceve dall'Alto la forza, la correzione e l'elevazione concesse dal Creatore." },
    { f: "In che modo il Creatore aiuta chi viene per purificarsi?", b: "Concedendogli lo stato di Lishma, risvegliando il suo cuore e donandogli una forza che trascende la sua natura egoistica." },
    { f: "Cos'è il 'lavoro nel cuore' durante il quotidiano chiarimento interiore?", b: "Distinguere i desideri egoistici dal desiderio di donare, pregando costantemente per la trasformazione della propria natura." },
    { f: "Perché il Creatore non viene mutato dalla preghiera?", b: "Perché il Creatore è il Bene Assoluto e Immutabile; la preghiera trasforma il vaso ricevente rendendolo idoneo ad accogliere la luce." },
    { f: "Qual è la differenza tra la preghiera convenzionale e quella cabalistica?", b: "La preghiera ordinaria chiede vantaggi materiali o sollievo per l'ego, mentre quella cabalistica implora il riscatto dall'egoismo." },
    { f: "Come nasce un autentico Hisaron lungo il cammino spirituale?", b: "Attraverso il lavoro assiduo nel gruppo e lo studio delle fonti, chiarendo la mancanza come assenza della luce di dazione." },
    { f: "Cosa significa che il corpo 'non concorda con il giogo del Regno dei Cieli'?", b: "Il naturale desiderio di ricevere rifiuta istintivamente di faticare solo per compiacere il Creatore senza ricompensa personale." },
    { f: "Cosa deve compiere l'uomo quando vede che le sue membra resistono alla dazione?", b: "Non ha altro scampo se non la preghiera: effondere il cuore al Creatore affinché assoggetti il corpo alla dazione." },
    { f: "In che modo l'acquisizione di Lishma abbatte l'inclinazione al male?", b: "Annulla l'amor proprio; i vasi di ricezione perdono la loro funzione egoistica e sono considerati spiritualmente 'morti'." },
    { f: "Perché è essenziale comprendere che senza preghiera è impossibile raggiungere Lishma?", b: "Perché tale consapevolezza rende la preghiera un bisogno assoluto e improrogabile, dissipando ogni compiacimento illusorio." },
    { f: "Qual è il legame tra l'elevazione di MAN e il vaso dell'anima?", b: "Il MAN è la mancanza stessa del Kli; quanto più pura e profonda è tale carenza, tanto più grande è la Luce che il vaso può contenere." },
    { f: "In che senso la preghiera è la confessione dell'impotenza dell'ego?", b: "Il cuore palesa la sua assoluta dipendenza, riconoscendo che il proprio ego è un carcere inespugnabile senza il soccorso divino." },
    { f: "In che modo il lavoro di gruppo si fonde con la preghiera personale?", b: "Lo sforzo di amare i compagni smaschera la totale incapacità di donare, facendo scaturire un vero grido di aiuto." },
    { f: "Perché la preghiera è considerata la vera creazione del vaso spirituale?", b: "Perché il riempimento può aver luogo unicamente dove sussiste una carenza; la preghiera definisce e dilata questo vuoto." },
    { f: "Cosa significa che 'il Creatore ascolta la preghiera'?", b: "Che la richiesta entra in perfetta risonanza con la legge superiore di dazione e la Luce riempie all'istante il Kli aperto." },
    { f: "Quale ruolo svolge la disperazione spirituale nella preghiera?", b: "Segna il completo esaurimento delle forze dell'ego, precedendo immediatamente l'irruzione della salvezza dall'Alto." },
    { f: "Cos'è il 'risveglio dall'Alto' (Itaruta de-Leila)?", b: "La rivelazione della Luce Superiore che scende in risposta diretta a una mancanza matura e purificata dal basso (MAN)." },
    { f: "Perché il desiderio di ricevere è paragonato a un 'ladro' in Shamati 20?", b: "Perché cerca di sottrarre e usurpare ogni frammento di energia e piacere unicamente per il proprio godimento egoistico." },
    { f: "Perché all'inizio l'uomo non avverte vitalità nel lavoro di dazione?", b: "Affinché il desiderio di ricevere non vi trovi gusto; se ne traesse diletto, l'uomo non potrebbe mai elevarsi al puro Lishma." },
    { f: "Quando il lavoro spirituale diventa una gioia in sé?", b: "Quando ci si abitua a donare, e recare appagamento al Creatore diviene la ricompensa stessa dello sforzo compiuto." },
    { f: "Quando una rimostranza nel lavoro spirituale è legittima o illegittima?", b: "Ci si può lamentare solo con il padrone per cui si lavora; faticare per l'ego non dà alcun diritto di pretendere forze dal Creatore." },
    { f: "Cos'è il chiarimento interiore (Berur) nella preghiera?", b: "Il vaglio delle intenzioni: separare ciò che è volto al proprio godimento egoistico da ciò che mira ad allietare il Creatore." },
    { f: "Cos'è la 'perfezione assoluta' nell'accogliere il giogo del Regno dei Cieli?", b: "Desiderare esclusivamente di donare e rinunciare integralmente alla ricezione per il proprio tornaconto." },
    { f: "Perché la comprensione intellettuale non è sufficiente per la preghiera del cuore?", b: "Perché le tesi mentali non scuotono il vaso; solo una mancanza reale vissuta nel cuore attira la Luce." },
    { f: "Come agisce il MAN attraverso i gradi dei mondi spirituali?", b: "Il grado inferiore affida la sua carenza al grado superiore, che la eleva fino alla Sorgente facendo scendere la risposta." },
    { f: "Perché la preghiera è definita l'unica arma contro il desiderio di ricevere?", b: "Perché l'uomo non può mutare la propria natura creata; può solo gridare al Creatore per ricevere una nuova natura di dazione." },
    { f: "Perché la preghiera è un cammino continuo e non un gesto istantaneo?", b: "Perché una sequenza di sforzi e cadute affina e matura la carenza finché non tocca una sincerità assoluta." },
    { f: "Come si manifesta la fede nella redenzione negli stati più oscuri?", b: "Anche quando il corpo non scorge alcuna via d'uscita, il punto nel cuore è certo che il Creatore possa salvarlo in un battito di ciglia." },
    { f: "Cosa significa che il Creatore 'brama la preghiera dei giusti'?", b: "Il Creatore anela a un Kli pronto e idoneo alla dazione, poiché la natura del Suo amore è elargire riempimento." },
    { f: "Quale legame unisce il pentimento alla preghiera cabalistica?", b: "Il pentimento è la dolorosa presa di coscienza della propria natura egoistica, e la preghiera è la supplica per esserne strappati." },
    { f: "In che modo la preghiera preserva l'uomo dall'orgoglio spirituale?", b: "Radica la certezza costante che ogni conquista spirituale è unicamente una grazia e un dono immeritato dall'Alto." },
    { f: "Per quale motivo una preghiera pare talvolta restare inascoltata?", b: "Perché la mancanza non ha ancora raggiunto la profondità o purezza necessaria; il vaso non è ancora pronto a trattenere la Luce." },
    { f: "Cosa significa 'effondere il proprio cuore dinanzi al Creatore'?", b: "Rimettere senza riserve tutti i desideri reconditi, i timori e le debolezze al governo sovrano del Creatore." },
    { f: "In che modo il libro delle preghiere (Siddur) sostiene il lavoro interiore del cabalista?", b: "Funge da mappa spirituale esatta degli stati interiori e dei processi di correzione tracciata da saggi che hanno conseguito la meta." },
    { f: "Perché il passaggio a Lishma è considerato un prodigio supremo?", b: "Perché capovolgere la natura creata (amor proprio) in puro altruismo è possibile unicamente per virtù trasformatrice della Luce." },
    { f: "Come fa la preghiera a tramutarsi in un dialogo vivente con il Creatore?", b: "Quando i moti del cuore rispecchiano con precisione l'ardore di unirsi a Lui, si spalanca un colloquio interiore diretto." },
    { f: "Cosa denota il detto 'Non sei libero di sottrarti alla fatica'?", b: "Sebbene il traguardo sia un dono dall'Alto, il gravoso lavoro di forgiare il desiderio e la mancanza compete tutto all'uomo." },
    { f: "Qual è la relazione tra la preghiera e l'amore per i compagni?", b: "Nello sforzo di donare agli amici emerge la completa incapacità di amare disinteressatamente, generando un vero grido di soccorso." },
    { f: "In che modo l'esame di coscienza prima della preghiera depura l'intenzione?", b: "Smaschera i secondi fini egoistici, sfronda i traguardi illusori e concentra il richiamo su un unico punto di verità." },
    { f: "Qual è la differenza tra l'attesa passiva e la preghiera spirituale?", b: "La passività abbandona la lotta, mentre la preghiera è il grido estremo di chi combatte sino all'ultimo limite delle forze." },
    { f: "Come risplende la Luce della Torà nella preghiera?", b: "La Luce che Riforma attirata nello studio rischiara le tenebre del cuore, ridestando una vibrante supplica di correzione." },
    { f: "Cosa significa che la vera preghiera 'grida dal profondo'?", b: "Un urlo che si leva dal fondo del desiderio di ricevere, dall'abisso più cupo della prigione dell'ego." },
    { f: "In che modo la preghiera conduce al Dvekut (adesione) con il Creatore?", b: "Acquisendo il desiderio di donare, l'uomo consegue l'equivalenza di forma con il Creatore, suggellando l'unione suprema." },
    { f: "Qual è l'insegnamento pratico fondamentale della Lezione 18 sulla preghiera?", b: "Non appagarti di recitare formule; edifica una vera mancanza nel tuo cuore, poiché il Creatore esaudisce solo la verità del cuore." }
  ],
  pt: [
    { f: "Qual é a definição cabalística da oração?", b: "O 'trabalho no coração' (Avoda shebaLev), um profundo esclarecimento interior dos desejos, intenções e carências perante o Criador." },
    { f: "O que representa o 'coração' espiritual na Cabala?", b: "O coração representa a soma de todos os desejos de receber do ser humano e a totalidade das suas inclinações emotivas e volitivas." },
    { f: "Como se relacionam as palavras da boca com o anseio do coração?", b: "O Criador atende exclusivamente à verdadeira carência (Hisaron) no íntimo do coração, jamais às palavras mecânicas proferidas pelos lábios." },
    { f: "O que encerra o conceito de 'Hisaron' na oração?", b: "Uma genuína carência interior, o vazio do vaso (Kli) que anseia com vigor pelo preenchimento e pela correção espiritual." },
    { f: "Por que a repetição mecânica de palavras não é tida como uma oração autêntica?", b: "Porque, se o coração não suspira por aquilo que os lábios balbuciam, as palavras permanecem invólucros mortos sem vitalidade espiritual." },
    { f: "Qual é a primeira condição para que a oração seja acolhida?", b: "Uma fé inabalável de que o Criador é verdadeiramente capaz de resgatar o ser humano do cativeiro do egoísmo." },
    { f: "Qual é a segunda condição para que a oração seja acolhida?", b: "Reconhecer que não há outra saída: todas as forças humanas fracassaram e somente o Criador pode prestar socorro." },
    { f: "Qual é a terceira condição para que a oração seja acolhida?", b: "Que a súplica seja genuinamente uma questão de vida ou de morte, sem a qual a alma perece asfixiada no desejo de receber." },
    { f: "Como a oração atua na condição de 'médium' na evolução espiritual?", b: "Não pretende alterar o Criador, mas transforma o ser humano, preparando o Kli para acolher a luz da doação." },
    { f: "O que roga o cabalista na verdadeira oração como médium?", b: "Exclusivamente a carência de doação (o anseio de doar) e a equivalência de forma com o Criador." },
    { f: "Qual é a mensagem central do artigo 20 de Shamati sobre alcançar Lishmá?", b: "Lishmá (por Seu Nome / doação altruísta) é uma dádiva e uma iluminação do Alto que a mente humana não consegue atingir por si só." },
    { f: "Se Lishmá é uma dádiva do Alto, por que o esforço humano se faz necessário?", b: "Porque os esforços e os remédios erigem no ser humano os vasos corrigidos (Kelim) que verdadeiramente anseiam por Lishmá." },
    { f: "Que papel desempenha o fracasso na oração segundo Shamati 20?", b: "Quando o homem constata a total inutilidade de seus atos, atinge o desamparo absoluto e só então pode orar do fundo do coração." },
    { f: "Quando a criatura se torna capaz de proferir uma oração sincera do fundo do coração?", b: "Apenas após esgotar todos os ardis humanos e reconhecer que por si mesma nada pode consumar sem o Criador." },
    { f: "O que denota o conceito de 'MAN' (Mayin Nukvin)?", b: "Águas femininas; a carência, a prece e o despertar que sobem do vaso inferior, atraindo abundância e luz do Alto." },
    { f: "Qual é a função do 'despertar de baixo' na engrenagem espiritual?", b: "O despertar de baixo (a oração do ser criado) desencadeia o jorro das Luzes Superiores (MAD - Mayin Dehrin)." },
    { f: "O que expressa a máxima 'Aquele que vem para se purificar recebe ajuda'?", b: "A quem sinceramente aspira à doação e à pureza, o Criador concede do Alto vigor, correção e elevação sobre sua natureza." },
    { f: "De que modo o Criador socorre quem vem para se purificar?", b: "Agraciando-o com o grau de Lishmá, despertando-lhe o coração e concedendo-lhe uma força sobrenatural que subjuga o egoísmo." },
    { f: "Em que consiste o 'trabalho no coração' durante o escrutínio interior diário?", b: "Distinguir as volições egoístas da aspiração à doação, rogando continuamente pela transmutação da própria índole." },
    { f: "Por que o Criador não se altera por força da oração?", b: "Porque o Criador é o Bem Absoluto e Imutável; a oração molda o vaso receptor tornando-o afim com a Luz." },
    { f: "Qual é o abismo entre a prece religiosa formal e a oração cabalística?", b: "A prece comum demanda bens terrenos ou alívio para o ego, ao passo que a cabalística clama por redenção do próprio egoísmo." },
    { f: "Como brota um autêntico Hisaron no caminho espiritual?", b: "Por meio do labor infatigável no grupo e do exame das fontes, clarificando a carência como a ausência da luz de doação." },
    { f: "O que significa o corpo 'não consentir com o jugo do Reino dos Céus'?", b: "O desejo de receber inato repele instintivamente trabalhar em prol do agrado do Criador sem auferir recompensa pessoal." },
    { f: "O que deve fazer o indivíduo ao notar que seus membros rechaçam a doação?", b: "Resta-lhe apenas a oração: derramar a alma perante o Criador para que este dobre o corpo ao serviço da doação." },
    { f: "De que modo o alcance de Lishmá aniquila a inclinação ao mal?", b: "Extingue o amor-próprio; os vasos de recepção perdem seu ofício egoísta e são reputados espiritualmente como 'mortos'." },
    { f: "Por que é basilar saber que sem oração é impossível granjear Lishmá?", b: "Porque tal certeza converte a oração numa carência premente e incontornável, banindo a presunção e a falsa segurança." },
    { f: "Qual é o nexo entre a elevação de MAN e o vaso da alma?", b: "O MAN é a própria deficiência do Kli; quanto mais límpida e funda for a falta, maior será a Luz que o vaso poderá reter." },
    { f: "Em que sentido a oração é a confissão da falência do egoísmo?", b: "O coração escancara a sua dependência absoluta, anuindo que o próprio ego é uma masmorra inviolável sem o influxo divino." },
    { f: "Como o labor no grupo se articula com a oração individual?", b: "O empenho em amar os companheiros expõe a incapacidade de doar, parindo um clamor genuíno por intervenção e amparo." },
    { f: "Por que se assevera que a oração é a própria gênese do vaso espiritual?", b: "Porque o preenchimento só pode penetrar onde há vazio correspondente; a prece define e dilata esse vácuo espiritual." },
    { f: "O que significa 'o Criador ouve a oração'?", b: "Que a súplica entra em ressonância exata com a lei superior de doação e a Luz preenche sem demora o Kli receptivo." },
    { f: "Que serventia tem o desespero espiritual na dinâmica da oração?", b: "Atesta o esgotamento cabal das forças do ego, antecedendo de forma imediata o descer do socorro do Alto." },
    { f: "O que é o 'despertar do Alto' (Itaruta de-Leila)?", b: "A efusão da Luz Superior que brota em resposta direta a uma carência amadurecida e depurada vinda de baixo (MAN)." },
    { f: "Por que o desejo de receber é alcunhado de 'ladrão' em Shamati 20?", b: "Porque intenta saquear e açambarcar cada centelha de energia e deleite tão-só para o seu proveito ensimesmado." },
    { f: "Por que no início o homem não experimenta vigor ao trabalhar para doar?", b: "Para que o desejo de receber não lhe sinta o sabor; se experimentasse gozo, jamais alçaria voo ao Lishmá imaculado." },
    { f: "Quando a faina espiritual se converte em regozijo por si mesma?", b: "Quando o ser se afeiçoa à doação, e proporcionar contentamento ao Criador passa a ser a própria paga do labor." },
    { f: "Quando uma queixa na senda espiritual é julgada legítima ou espúria?", b: "Só é lícito queixar-se ao senhor para quem de fato se trabalha; labutar para o ego não dá o direito de exigir alento do Criador." },
    { f: "O que consubstancia o discernimento interior (Berur) na oração?", b: "A triagem das intenções: cindir aquilo que mira o gozo egoísta do que verdadeiramente anseia alegrar o Criador." },
    { f: "O que é a 'perfeição consumada' ao assumir o jugo do Reino dos Céus?", b: "Anelar unicamente a doar, renunciando de ponta a ponta à recepção em causa própria." },
    { f: "Por que o mero juízo intelectual é insuficiente para a oração do coração?", b: "Porque arrazoados lógicos não comovem o vaso; só a carência vívida sentida no peito drena a Luz." },
    { f: "Como atua o MAN através dos degraus dos mundos espirituais?", b: "O degrau inferior remete sua indigência ao superior, que a guinda à Fonte, fazendo descer a devolutiva divina." },
    { f: "Por que a prece é designada a única arma contra o desejo de receber?", b: "Porque o homem é impotente para alterar sua feitura natural; resta-lhe clamar ao Criador por uma nova natureza de doação." },
    { f: "Por que a oração é um processo contínuo e não um ato fugaz?", b: "Porque uma fiada de lidas e reveses lapida e amadurece a carência até que esta resplandeça em inteira veracidade." },
    { f: "Como se estampa a fé no livramento sob as trevas mais espessas?", b: "Ainda que o corpo não vislumbre saída, o ponto no coração confia que o Criador pode salvá-lo num piscar de olhos." },
    { f: "O que significa 'o Criador anela pela oração dos justos'?", b: "O Criador suspira por um Kli preparado e apto à doação, pois a natureza do Seu amor radica em cumular e outorgar plenitude." },
    { f: "Qual é o elo entre o arrependimento e a oração cabalística?", b: "O arrependimento é a pungente constatação da hediondez do ego, e a oração é a súplica pelo desvencilhar de suas amarras." },
    { f: "De que modo a oração blinda o caminhante contra a vaidade espiritual?", b: "Inculca a certeza perene de que todo patamar atingido é unicamente graça e esmola imerecida do Alto." },
    { f: "Por qual razão uma prece aparenta amiúde jazer sem resposta?", b: "Porque a carência não atingiu ainda a profundeza ou o despojamento mister; o vaso não se acha pronto para sustentar a Luz." },
    { f: "O que denota 'derramar o coração diante do Criador'?", b: "Entregar-Lhe sem peias nem reservas todos os anseios secretos, pavores e debilidades à Sua soberana regência." },
    { f: "Como o livro de preces (Sidur) subsidia a lida interior do cabalista?", b: "Funciona como um mapa espiritual milimétrico de paragens interiores e retificações lavrado por sábios ungidos." },
    { f: "Por que a travessia para Lishmá é vista como um milagre supremo?", b: "Porque transmutar a índole forjada (o amor a si) em puro altruísmo só se opera mediante o influxo transfigurador da Luz." },
    { f: "Como a oração se erige em diálogo vivente com o Criador?", b: "Quando o palpitar do íntimo mimetiza à risca a ânsia de achegamento, descortina-se um colóquio interior franco." },
    { f: "O que encerra o adágio 'Não és livre para te eximires da lida'?", b: "Conquanto o laurel venha do Alto, a árdua tarefa de forjar o anseio e a falta recai inteira nos ombros do ser criado." },
    { f: "Qual é o liame entre a oração e o amor aos companheiros?", b: "No afã de doar aos pares patenteia-se a inaptidão para amar sem interesse, deflagrando um brado de socorro genuíno." },
    { f: "Como o balanço íntimo prévio à oração escoima a intenção?", b: "Desmascara as segundas intenções egoístas, depura as metas fictícias e afunila o rogo num único vértice de verdade." },
    { f: "Qual é o divisor de águas entre a espera passiva e a oração espiritual?", b: "A apatia depõe as armas sem pelejar, ao passo que a oração é o bramido derradeiro do guerreiro que combate até o extremo." },
    { f: "Como a Luz da Torá se reflete no bojo da oração?", b: "A Luz que Corrige haurida no estudo alumia as trevas do coração, acordando uma súplica veemente de retificação." },
    { f: "O que quer dizer a sentença de que a oração fidedigna 'clama das profundezas'?", b: "Um brado que irrompe do chão do desejo de receber, do fosso mais lúgubre das masmorras do ego." },
    { f: "Como a oração conduz ao Dvekut (fusão) com o Criador?", b: "Ao apossar-se da têmpera da doação, o ser humano alcança a equivalência de forma com o Criador, selando a união consumada." },
    { f: "Qual é a exortação prática basilar da Lição 18 acerca da oração?", b: "Não te contentes em balbuciar palavras; ergue uma falta genuína em teu peito, pois o Criador atende somente à verdade do coração." }
  ],
  uk: [
    { f: "Яке кабалістичне визначення молитви?", b: "'Праця в серці' (Авода шеба-Лев) — глибоке внутрішнє з'ясування бажань, намірів і справжньої нестачі перед Творцем." },
    { f: "Що в науці Кабала означає поняття духовного 'серця'?", b: "Серце — це сукупність усіх бажань отримувати, усіх почуттєвих і вольових прагнень людини." },
    { f: "Як співвідносяться між собою слова уст і бажання серця?", b: "Творець відповідає виключно на справжню нестачу (Хісарон) у глибині серця, а не на механічні слова уст." },
    { f: "Що таке 'Хісарон' у контексті молитви?", b: "Справжнє внутрішнє відчуття порожнечі й нестачі, потреба посудини (Клі) у духовному виправленні та наповненні." },
    { f: "Чому механічне промовляння слів не вважається справжньою молитвою?", b: "Якщо серце не прагне того, що промовляють вуста, слова залишаються мертвою формою без духовної сили." },
    { f: "Яка перша умова для того, щоб молитва була почута?", b: "Непохитна віра в те, що Творець дійсно здатний визволити людину з ув'язнення егоїзмом." },
    { f: "Яка друга умова для того, щоб молитва була почута?", b: "Усвідомлення, що іншого вибору немає: усі власні людські сили зазнали краху, і допомогти може тільки Творець." },
    { f: "Яка третя умова для того, щоб молитва була почута?", b: "Прохання має бути питанням життя і смерті, без вирішення якого душа гине в бажанні отримувати." },
    { f: "Як молитва діє як 'медіум' (засіб) у духовному розвитку?", b: "Вона не змінює Творця, але трансформує людину, готуючи Клі до прийняття світла віддачі." },
    { f: "Про що просить кабаліст у справжній молитві як медіумі?", b: "Виключно про нестачу до віддачі (бажання віддавати) та про набуття подоби форми з Творцем." },
    { f: "У чому головний зміст статті 20 книги 'Шаматі' щодо досягнення Лішма?", b: "Лішма (заради Творця / чиста віддача) — це дарунок і осяяння згори, яке людський розум не здатний осягнути самостійно." },
    { f: "Якщо Лішма — це подарунок згори, навіщо потрібні зусилля людини?", b: "Зусилля та засоби вибудовують у людині виправлені судини (Келім), які по-справжньому прагнуть отримати Лішма." },
    { f: "Яка роль невдач і безсилля у молитві згідно з 'Шаматі' 20?", b: "Коли людина бачить марність усіх своїх дій, вона приходить до цілковитого безсилля, і лише тоді може щиро молитися від щирого серця." },
    { f: "Коли людина стає здатною на щиру молитву з глибини серця?", b: "Лише після того, як випробувала всі людські засоби й усвідомила, що сама без Творця нічого не здатна досягти." },
    { f: "Що означає поняття 'МА\"Н' (Маїн Нуквін)?", b: "Жіночі води; нестача, молитва і пробудження, що піднімаються від нижньої судини й притягують світло та достаток згори." },
    { f: "Яка роль 'пробудження знизу' в духовній системі?", b: "Пробудження знизу (молитва створіння) запускає виливання Вищого Світла (МА\"Д — Маїн Дехрін)." },
    { f: "Що означає принцип 'Тому, хто приходить очиститися, допомагають'?", b: "Тому, хто щиро прагне до віддачі й чистоти, Творець посилає згори силу, виправлення та духовне піднесення." },
    { f: "Як саме Творець допомагає тому, хто приходить очиститися?", b: "Дарує ступінь Лішма, пробуджує його серце й наділяє силою, що перевершує його егоїстичну природу." },
    { f: "У чому полягає 'праця в серці' під час щоденного внутрішнього з'ясування?", b: "У розрізненні егоїстичних бажань і прагнення до віддачі з молитвою про перетворення власної природи." },
    { f: "Чому Творець не змінюється під дією молитви?", b: "Тому що Творець є Абсолютним Добром і Незмінним; молитва змінює посудину сприйняття, роблячи її придатною для світла." },
    { f: "У чому різниця між звичайною релігійною та кабалістичною молитвою?", b: "Звичайна молитва просить про матеріальні блага чи полегшення для его, а кабалістична благає про порятунок від егоїзму." },
    { f: "Як на духовному шляху народжується справжній Хісарон?", b: "Через наполегливу працю в групі та навчання за першоджерелами, коли нестача усвідомлюється як відсутність світла віддачі." },
    { f: "Що означає, що тіло 'не згодне з тягарем Царства Небесного'?", b: "Природне бажання отримувати інстинктивно опирається праці заради задоволення Творця без особистої винагороди." },
    { f: "Що робити людині, коли всі її органи чинять опір віддачі?", b: "У неї немає іншого виходу, окрім молитви: вилити своє серце перед Творцем, щоб Він схилив тіло до віддачі." },
    { f: "Як досягнення Лішма умертвляє зле начало?", b: "Воно анулює самолюбство; егоїстичні судини втрачають свою функцію і вважаються духовно 'мертвими'." },
    { f: "Чому важливо знати, що без молитви неможливо досягти Лішма?", b: "Бо це знання перетворює молитву на абсолютну й нагальну необхідність, розсіюючи ілюзію самозаспокоєння." },
    { f: "Який зв'язок між підйомом МА\"Н і судиною душі?", b: "МА\"Н — це сама нестача Клі; чим чистіша й глибша ця нестача, тим більше світло здатна вмістити судина." },
    { f: "У якому сенсі молитва є визнанням безсилля егоїзму?", b: "Серце відкриває свою цілковиту залежність, визнаючи, що власне его — це в'язниця, з якої не вибратися без Творця." },
    { f: "Як праця в групі поєднується з особистою молитвою?", b: "Спроба полюбити товаришів оголює абсолютну нездатність віддавати, породжуючи справжній крик про допомогу." },
    { f: "Чому молитва вважається безпосереднім створенням духовної судини?", b: "Наповнення може увійти лише туди, де є відповідна нестача; молитва окреслює і розширює цей духовний вакуум." },
    { f: "Що означає вираз 'Творець чує молитву'?", b: "Прохання входить у цілковитий резонанс із вищим законом віддачі, і світло миттєво наповнює відкрите Клі." },
    { f: "Яку роль відіграє духовний відчай у молитві?", b: "Він знаменує повне вичерпання егоїстичних сил, що безпосередньо передує виливанню вищої допомоги." },
    { f: "Що таке 'пробудження згори' (Ітарута де-Леїла)?", b: "Розкриття Вищого Світла, яке приходить у відповідь на зрілу, очищену нестачу знизу (МА\"Н)." },
    { f: "Чому бажання отримувати порівнюють із 'злодієм' у 'Шаматі' 20?", b: "Тому що воно намагається викрасти і присвоїти кожну крихту енергії та радості виключно для власної вигоди." },
    { f: "Чому людина спочатку не відчуває радості від праці заради віддачі?", b: "Щоб бажання отримувати не відчуло в цьому смаку; якби відчуло, людина ніколи не піднялася б до чистого Лішма." },
    { f: "Коли духовна праця стає радістю сама по собі?", b: "Коли людина звикає віддавати, і можливість принести радість Творцеві стає найвищою нагородою за працю." },
    { f: "Коли нарікання в духовній праці є виправданим чи невиправданим?", b: "Нарікати можна лише на того господаря, на якого дійсно працюєш; працюючи на себе, не можна вимагати сил у Творця." },
    { f: "Що таке внутрішнє з'ясування (Беру́р) у молитві?", b: "Аналіз намірів: відокремлення того, що робиться заради власного задоволення, від того, що приносить радість Творцеві." },
    { f: "Що таке 'цілковита досконалість' у прийнятті тягаря Царства Небесного?", b: "Бажати виключно віддавати і повністю відмовитися від отримання заради власної вигоди." },
    { f: "Чому інтелектуального розуміння недостатньо для молитви серця?", b: "Аргументи розуму не рухають духовну судину; лише реальна нестача, пережита в серці, притягує світло." },
    { f: "Як діє МА\"Н крізь ступені духовних світів?", b: "Нижчий ступінь передає свою нестачу вищому, а вищий підносить її до Джерела, зводячи відповідь униз." },
    { f: "Чому молитву називають єдиною зброєю проти бажання отримувати?", b: "Людина не здатна сама змінити власну природу; вона може лише волати до Творця про дарування нової природи віддачі." },
    { f: "Чому молитва — це тривалий процес, а не миттєва дія?", b: "Низка зусиль і падінь шліфує і дозріває внутрішню нестачу, доки вона не досягне абсолютної щирості." },
    { f: "Як виражається віра у визволення в найтемніших духовних станах?", b: "Навіть коли тіло не бачить виходу, точка в серці впевнена, що Творець може врятувати за одну мить." },
    { f: "Що означає вислів 'Творець прагне молитви праведників'?", b: "Творець чекає на підготовлене Клі, здатне до віддачі, оскільки природа Його любові — наповнювати й віддавати." },
    { f: "Який зв'язок між каяттям (Тшува) і кабалістичною молитвою?", b: "Каяття — це болісне усвідомлення егоїстичної природи, а молитва — прохання про визволення з неї." },
    { f: "Як молитва захищає людину від духовної гордині?", b: "Вона утверджує усвідомлення того, що будь-який духовний здобуток є виключно незаслуженим даром і милістю згори." },
    { f: "Чому молитва інколи здається безвідповідною?", b: "Нестача ще не досягла потрібної глибини чи чистоти; посудина ще не здатна утримати світло." },
    { f: "Що означає 'вилити серце перед Творцем'?", b: "Беззастережно віддати всі потаємні бажання, страхи та своє безсилля під керівництво Творця." },
    { f: "Як молитовник (Сідур) допомагає внутрішній праці кабаліста?", b: "Він слугує точною духовною картою внутрішніх станів і процесів виправлення, складеною мудрецями." },
    { f: "Чому перехід до Лішма вважається дивом?", b: "Бо перевернути вроджену природу (самолюбство) на чистий альтруїзм можливо лише перетворювальною силою Світла." },
    { f: "Як молитва перетворюється на живий діалог із Творцем?", b: "Коли рухи серця точно відображають прагнення наблизитися до Нього, відкривається пряме внутрішнє спілкування." },
    { f: "Що означає вислів 'Ти не вільний звільнитися від праці'?", b: "Хоча мета дається згори, уся праця зі створення бажання й нестачі покладена виключно на людину." },
    { f: "Який зв'язок між молитвою та любов'ю до товаришів?", b: "У зусиллях віддавати товаришам викривається повна нездатність любити, що породжує справжню спільну молитву." },
    { f: "Як самозвіт перед молитвою очищує намір?", b: "Він зриває маски з егоїстичних мотивів, відкидає хибні цілі й фокусує поклик в одну точку правди." },
    { f: "У чому різниця між пасивним очікуванням і духовною молитвою?", b: "Пасивність здається без бою, тоді як молитва — це граничний зойк воїна, який бореться до останньої межі сил." },
    { f: "Як Світло Тори відображається в молитві?", b: "Світло, що повертає до Джерела, освічує темряву серця, викликаючи глибоке благання про виправлення." },
    { f: "Що означає, що справжня молитва 'кличе з глибин'?", b: "Крик, що виривається з самого дна бажання отримувати, з найтемнішої безодні в'язниці его." },
    { f: "Як молитва приводить до злиття (Двекут) із Творцем?", b: "Здобуваючи бажання віддавати, людина набуває подоби форми з Творцем, що є найвищим єднанням." },
    { f: "Який головний практичний урок 18-го уроку про молитву?", b: "Не задовольняйся механічними словами; вибудовуй справжній Хісарон у серці, бо Творець чує лише правду серця." }
  ],
  pl: [
    { f: "Jaka jest kabalistyczna definicja modlitwy?", b: "'Praca w sercu' (Awoda szebaLew) — głębokie wewnętrzne wyjaśnienie pragnień, intencji i braków przed Stwórcą." },
    { f: "Co w Kabale oznacza pojęcie duchowego 'serca'?", b: "Serce reprezentuje sumę wszystkich pragnień otrzymywania człowieka oraz ogół jego emocjonalnych i wolicjonalnych dążeń." },
    { f: "Jak słowa ust mają się do pragnienia serca?", b: "Stwórca odpowiada wyłącznie na prawdziwy brak (Chisaron) w głębi serca, a nie na mechaniczne słowa wypowiadane ustami." },
    { f: "Czym jest pojęcie 'Chisaron' w modlitwie?", b: "Autentycznym wewnętrznym brakiem, pustką naczynia (Kli), które tęskni za duchowym napełnieniem i naprawą." },
    { f: "Dlaczego mechaniczne powtarzanie słów nie jest uważane za prawdziwą modlitwę?", b: "Ponieważ jeśli serce nie pragnie tego, co wypowiadają usta, słowa pozostają martwą formą bez duchowej siły." },
    { f: "Jaki jest pierwszy warunek wysłuchania modlitwy?", b: "Niezłomna wiara w to, że Stwórca naprawdę jest w stanie wyzwolić człowieka z więzienia egoizmu." },
    { f: "Jaki jest drugi warunek wysłuchania modlitwy?", b: "Uświadomienie sobie braku innego wyboru: wszystkie ludzkie siły zawiodły i tylko Stwórca może pomóc." },
    { f: "Jaki jest trzeci warunek wysłuchania modlitwy?", b: "Prośba musi być kwestią życia i śmierci, bez rozwiązania której dusza ginie w pragnieniu otrzymywania." },
    { f: "Jak modlitwa działa jako 'medium' w rozwoju duchowym?", b: "Nie zmienia Stwórcy, lecz przekształca człowieka, przygotowując Kli na przyjęcie światła obdarzania." },
    { f: "O co prosi kabalista w prawdziwej modlitwie jako medium?", b: "Wyłącznie o brak do obdarzania (pragnienie obdarzania) oraz o zrównanie formy ze Stwórcą." },
    { f: "Jakie jest główne przesłanie artykułu 20 'Szamati' dotyczącego osiągnięcia Liszma?", b: "Liszma (dla Jej Imienia / bezinteresowne obdarzanie) to dar i oświecenie z Góry, którego ludzki rozum nie jest w stanie osiągnąć sam." },
    { f: "Skoro Liszma jest darem z Góry, dlaczego ludzki wysiłek jest konieczny?", b: "Wysiłki i środki budują w człowieku naprawione naczynia (Kelim), które prawdziwie pragną otrzymać Liszma." },
    { f: "Jaką rolę odgrywa porażka i bezsilność w modlitwie według 'Szamati' 20?", b: "Gdy człowiek widzi bezcelowość wszystkich swoich działań, osiąga całkowitą bezradność i dopiero wtedy może modlić się z głębi serca." },
    { f: "Kiedy człowiek jest zdolny do szczerej modlitwy z głębi serca?", b: "Dopiero po wyczerpaniu wszystkich ludzkich środków i uznaniu, że sam bez Stwórcy nie może niczego osiągnąć." },
    { f: "Co oznacza pojęcie 'MAN' (Majin Nukwin)?", b: "Żeńskie wody; brak, modlitwa i przebudzenie wznoszące się z niższego naczynia, które przyciągają światło i obfitość z Góry." },
    { f: "Jaka jest rola 'przebudzenia z dołu' w systemie duchowym?", b: "Przebudzenie z dołu (modlitwa stworzenia) uruchamia przepływ Wyższych Świateł (MAD — Majin Dechrin)." },
    { f: "Co oznacza zasada 'Temu, kto przychodzi się oczyścić, pomagają'?", b: "Temu, kto szczerze dąży do obdarzania i czystości, Stwórca z Góry zsyła siłę, naprawę i duchowe wzniesienie." },
    { f: "Jak dokładnie Stwórca pomaga temu, kto przychodzi się oczyścić?", b: "Obdarza go stanem Liszma, budzi jego serce i daje mu siłę przewyższającą jego egoistyczną naturę." },
    { f: "Na czym polega 'praca w sercu' podczas codziennego wewnętrznego wyjaśniania?", b: "Na rozróżnianiu pragnień egoistycznych od pragnienia obdarzania i modlitwie o przekształcenie własnej natury." },
    { f: "Dlaczego Stwórca nie zmienia się pod wpływem modlitwy?", b: "Ponieważ Stwórca jest Dobrem Absolutnym i Niezmiennym; modlitwa przekształca naczynie odbiorcze, by mogło utrzymać światło." },
    { f: "Jaka jest różnica między tradycyjną modlitwą a modlitwą kabalistyczną?", b: "Zwykła modlitwa prosi o dobra materialne lub ulgę dla ego, podczas gdy modlitwa kabalistyczna błaga o wybawienie z egoizmu." },
    { f: "Jak na duchowej ścieżce rodzi się prawdziwy Chisaron?", b: "Poprzez wytrwałą pracę w grupie i studiowanie źródeł, kiedy brak jest uświadamiany jako brak światła obdarzania." },
    { f: "Co oznacza, że ciało 'nie zgadza się z jarzmem Królestwa Niebios'?", b: "Wrodzone pragnienie otrzymywania instynktownie opiera się pracy wyłącznie dla zadowolenia Stwórcy bez własnej nagrody." },
    { f: "Co powinien zrobić człowiek, gdy widzi, że wszystkie jego członki opierają się obdarzaniu?", b: "Nie ma innego wyjścia, jak tylko modlić się: wylać serce przed Stwórcą, aby nakłonił ciało do obdarzania." },
    { f: "W jaki sposób osiągnięcie Liszma uśmierca złe nachylenie?", b: "Unicestwia miłość własną; naczynia otrzymywania tracą swoją egoistyczną funkcję i są duchowo uważane za 'martwe'." },
    { f: "Dlaczego wiedza o tym, że bez modlitwy nie da się osiągnąć Liszma, jest kluczowa?", b: "Ponieważ przekształca modlitwę w absolutną i naglącą konieczność, rozpraszając złudzenie samowystarczalności." },
    { f: "Jaki jest związek między wznoszeniem MAN a naczyniem duszy?", b: "MAN to sam brak w Kli; im czystszy i głębszy jest ten brak, tym większe Światło naczynie może przyjąć." },
    { f: "W jakim sensie modlitwa jest wyznaniem bezsilności egoizmu?", b: "Serce ujawnia swoją całkowitą zależność, uznając, że własne ego to więzienie nie do zdobycia bez boskiej pomocy." },
    { f: "Jak praca w grupie łączy się z osobistą modlitwą?", b: "Wysiłek ukochania przyjaciół obnaża całkowitą niezdolność do bezinteresowności, rodząc prawdziwe wołanie o pomoc." },
    { f: "Dlaczego modlitwa uważana jest za bezpośrednie stworzenie naczynia duchowego?", b: "Napełnienie może wejść tylko tam, gdzie istnieje odpowiedni brak; modlitwa określa i poszerza tę duchową próżnię." },
    { f: "Co oznacza wyrażenie 'Stwórca słucha modlitwy'?", b: "Prośba wchodzi w doskonały rezonans z wyższym prawem obdarzania, a Światło natychmiast napełnia otwarte Kli." },
    { f: "Jaką rolę odgrywa duchowa rozpacz w modlitwie?", b: "Oznacza całkowite wyczerpanie sił egoistycznych, bezpośrednio poprzedzając nadejście Wyższego ratunku." },
    { f: "Czym jest 'przebudzenie z Góry' (Itaruta de-Leila)?", b: "Objawieniem Wyższego Światła, które spływa w odpowiedzi na dojrzały, oczyszczony brak z dołu (MAN)." },
    { f: "Dlaczego pragnienie otrzymywania jest przyrównane do 'złodzieja' w 'Szamati' 20?", b: "Ponieważ próbuje ukraść i zawłaszczyć każdą cząstkę energii i radości wyłącznie dla własnej przyjemności." },
    { f: "Dlaczego na początku człowiek nie czuje radości w pracy na rzecz obdarzania?", b: "Aby pragnienie otrzymywania nie poczuło w tym smaku; gdyby poczuło przyjemność, człowiek nigdy nie wzniósłby się do czystego Liszma." },
    { f: "Kiedy praca duchowa staje się radością samą w sobie?", b: "Kiedy człowiek przyzwyczaja się do obdarzania, a sprawianie radości Stwórcy staje się najwyższą nagrodą za trud." },
    { f: "Kiedy pretensje w pracy duchowej są uzasadnione lub nieuzasadnione?", b: "Można narzekać tylko na tego pana, dla którego się rzeczywiście pracuje; pracując dla ego, nie ma się prawa żądać sił od Stwórcy." },
    { f: "Czym jest wewnętrzne wyjaśnienie (Berur) w modlitwie?", b: "Rozróżnieniem intencji: oddzieleniem tego, co służy własnemu egoizmowi, od tego, co służy uciesze Stwórcy." },
    { f: "Czym jest 'całkowita doskonałość' w przyjmowaniu jarzma Królestwa Niebios?", b: "Pragnieniem wyłącznie obdarzania i całkowitym zrzeczeniem się otrzymywania dla własnej korzyści." },
    { f: "Dlaczego intelektualne zrozumienie nie wystarcza do modlitwy serca?", b: "Argumenty umysłu nie poruszają naczynia duchowego; tylko rzeczywisty brak przeżyty w sercu przyciąga Światło." },
    { f: "Jak działa MAN poprzez stopnie światów duchowych?", b: "Niższy stopień przekazuje swój brak wyższemu, a wyższy wznosi go do Źródła, sprowadzając odpowiedź w dół." },
    { f: "Dlaczego modlitwa jest nazywana jedyną bronią przeciwko pragnieniu otrzymywania?", b: "Człowiek nie może zmienić własnej natury; może jedynie wołać do Stwórcy o obdarowanie go nową naturą obdarzania." },
    { f: "Dlaczego modlitwa to ciągły proces, a nie jednorazowy akt?", b: "Szereg wysiłków i upadków szlifuje i dojrzewa brak, aż osiągnie on absolutną szczerość." },
    { f: "Jak przejawia się wiara w wybawienie w najciemniejszych stanach?", b: "Nawet gdy ciało nie widzi ratunku, punkt w sercu ufa, że Stwórca może ocalić w mgnieniu oka." },
    { f: "Co oznacza stwierdzenie, że 'Stwórca pragnie modlitwy sprawiedliwych'?", b: "Stwórca czeka na przygotowane Kli zdolne do obdarzania, ponieważ naturą Jego miłości jest napełnianie i dawanie." },
    { f: "Jaki jest związek między skruchą (Tszuwa) a modlitwą kabalistyczną?", b: "Skrucha to bolesne uświadomienie sobie egoistycznej natury, a modlitwa to błaganie o wyzwolenie z niej." },
    { f: "Jak modlitwa chroni człowieka przed duchową pychą?", b: "Utrwala świadomość, że każde osiągnięcie duchowe jest wyłącznie darem i niezasłużonym miłosierdziem z Góry." },
    { f: "Dlaczego modlitwa pozornie pozostaje czasem bez odpowiedzi?", b: "Brak nie osiągnął jeszcze wymaganej głębokości ani czystości; naczynie nie jest jeszcze gotowe na zatrzymanie Światła." },
    { f: "Co oznacza 'wylanie serca przed Stwórcą'?", b: "Bezwarunkowe oddanie wszystkich ukrytych pragnień, lęków i bezsilności pod rządy Stwórcy." },
    { f: "Jak modlitewnik (Siddur) wspiera wewnętrzną pracę kabalisty?", b: "Służy jako precyzyjna mapa duchowa wewnętrznych stanów i procesów naprawy opracowana przez mędrców." },
    { f: "Dlaczego przejście do Liszma uważane jest za cud?", b: "Ponieważ odwrócenie wrodzonej natury (miłości własnej) w czysty altruizm jest możliwe tylko dzięki przemieniającej sile Światła." },
    { f: "Jak modlitwa staje się żywym dialogiem ze Stwórcą?", b: "Gdy poruszenia serca dokładnie odzwierciedlają pragnienie zbliżenia się do Niego, otwiera się bezpośrednia wewnętrzna rozmowa." },
    { f: "Co oznacza przysłowie: 'Nie do ciebie należy ukończenie pracy, lecz nie jesteś wolny od trudu'?", b: "Chociaż cel jest darem z Góry, cały wysiłek budowania pragnienia i braku spoczywa wyłącznie na człowieku." },
    { f: "Jaki jest związek między modlitwą a miłością przyjaciół?", b: "W wysiłku obdarzania przyjaciół ujawnia się całkowita niezdolność do miłości, rodząc autentyczną wspólną modlitwę." },
    { f: "Jak rachunek sumienia przed modlitwą oczyszcza intencję?", b: "Ujawnia ukryte motywy egoistyczne, odrzuca fałszywe cele i skupia wołanie w jednym punkcie prawdy." },
    { f: "Jaka jest różnica między biernym czekaniem a modlitwą duchową?", b: "Bierność poddaje się bez walki, podczas gdy modlitwa jest krańcowym krzykiem wojownika walczącego do ostatka sił." },
    { f: "Jak Światło Tory odzwierciedla się w modlitwie?", b: "Światło Reformujące przyciągane podczas nauki rozświetla mrok serca, wywołując głębokie błaganie o naprawę." },
    { f: "Co oznacza, że prawdziwa modlitwa 'woła z głębokości'?", b: "Krzyk wydobywający się z samego dna pragnienia otrzymywania, z najciemniejszych czeluści więzienia ego." },
    { f: "Jak modlitwa prowadzi do Dwekut (przylgnięcia) ze Stwórcą?", b: "Poprzez nabycie pragnienia obdarzania człowiek osiąga zrównanie formy ze Stwórcą, co stanowi szczyt jedności." },
    { f: "Jaka jest najważniejsza praktyczna nauka Lekcji 18 o modlitwie?", b: "Nie zadowalaj się mechanicznym powtarzaniem słów; buduj prawdziwy brak w sercu, bo Stwórca odpowiada tylko na prawdę serca." }
  ],
  ro: [
    { f: "Care este definiția cabalistică a rugăciunii?", b: "'Munca în inimă' (Avoda shebaLev), o profundă clarificare interioară a dorințelor, intențiilor și lipsurilor în fața Creatorului." },
    { f: "Ce reprezintă 'inima' spirituală în Cabala?", b: "Inima întruchipează suma tuturor dorințelor de a primi ale omului și ansamblul înclinațiilor sale emoționale și volitive." },
    { f: "Cum se raportează cuvintele gurii la dorința inimii?", b: "Creatorul răspunde exclusiv lipsei reale (Hisaron) din adâncul inimii, niciodată cuvintelor mecanice rostite de buze." },
    { f: "Ce este conceptul de 'Hisaron' în rugăciune?", b: "O veritabilă carență interioară, golul din vas (Kli) care tânjește după împlinire și corectare spirituală." },
    { f: "De ce repetarea mecanică a cuvintelor nu este considerată o rugăciune autentică?", b: "Pentru că, dacă inima nu tânjește după ceea ce rostesc buzele, cuvintele rămân forme moarte, lipsite de vitalitate spirituală." },
    { f: "Care este prima condiție pentru ca rugăciunea să fie ascultată?", b: "O credință de neclintit în faptul că doar Creatorul este capabil să-l elibereze pe om din temnița egoismului." },
    { f: "Care este a doua condiție pentru ca rugăciunea să fie ascultată?", b: "Conștientizarea faptului că nu există altă cale: toate puterile umane au eșuat și numai Creatorul poate aduce ajutor." },
    { f: "Care este a treia condiție pentru ca rugăciunea să fie ascultată?", b: "Cererea să fie cu adevărat o chestiune de viață și de moarte, fără de care sufletul piere în dorința de a primi." },
    { f: "Cum funcționează rugăciunea ca 'mediu' în evoluția spirituală?", b: "Ea nu urmărește să-L schimbe pe Creator, ci îl transformă pe om, pregătind Kli-ul pentru a primi lumina dăruirii." },
    { f: "Ce cere cabalistul în adevărata rugăciune ca mediu?", b: "Exclusiv lipsa pentru dăruire (dorința de a dărui) și echivalența de formă cu Creatorul." },
    { f: "Care este mesajul central al articolului 20 din Shamati privind atingerea stării de Lishma?", b: "Lishma (de dragul Numelui Său / dăruire altruistă) este un dar și o iluminare de Sus pe care mintea umană nu o poate atinge singură." },
    { f: "Dacă Lishma este un dar de Sus, de ce sunt necesare eforturile omului?", b: "Deoarece eforturile și remediile construiesc în om vasele corectate (Kelim) care tânjesc sincer să primească Lishma." },
    { f: "Ce rol joacă eșecul și neputința în rugăciune conform Shamati 20?", b: "Când omul vede că toate acțiunile sale au fost zadarnice, ajunge la o neputință totală și abia atunci poate striga din străfundul inimii." },
    { f: "Când este capabil un om să înalțe o rugăciune sinceră din adâncul inimii?", b: "Abia după ce a epuizat toate remediile umane și a recunoscut că prin el însuși nu poate realiza nimic fără Creator." },
    { f: "Ce semnifică conceptul de 'MAN' (Mayin Nukvin)?", b: "Ape feminine; lipsa, rugăciunea și trezirea care se înalță din vasul inferior și atrag abundența și Lumina de Sus." },
    { f: "Care este rolul 'trezirii de jos' în sistemul spiritual?", b: "Trezirea de jos (rugăciunea creației) declanșează revărsarea Luminilor Superioare (MAD - Mayin Dehrin)." },
    { f: "Ce înseamnă principiul 'Celui ce vine să se purifice i se dă ajutor'?", b: "Celui ce aspiră cu sinceritate la dăruire și puritate, Creatorul îi trimite de Sus tărie, corectare și înălțare peste natura sa." },
    { f: "Cum îl ajută Creatorul pe cel care vine să se purifice?", b: "Dăruindu-i starea de Lishma, trezindu-i inima și oferindu-i o putere supranaturală care îi transcende egoismul." },
    { f: "Ce este 'munca în inimă' în timpul clarificării interioare zilnice?", b: "Distincția între dorințele egoiste și dorința de a dărui, cu rugăciunea neîncetată de transformare a propriei naturi." },
    { f: "De ce Creatorul nu se schimbă prin rugăciune?", b: "Deoarece Creatorul este Binele Absolut și Imuabil; rugăciunea schimbă vasul primitor, făcându-l capabil să primească Lumina." },
    { f: "Care este diferența între rugăciunea convențională și cea cabalistică?", b: "Rugăciunea obișnuită cere bunuri materiale sau alinare pentru ego, în timp ce rugăciunea cabalistică imploră izbăvirea din egoism." },
    { f: "Cum se naște un adevărat Hisaron pe calea spirituală?", b: "Prin muncă susținută în grup și studiul surselor, clarificând lipsa ca absență a luminii dăruirii." },
    { f: "Ce înseamnă că trupul 'nu este de acord cu povara Regatului Cerurilor'?", b: "Dorința înnăscută de a primi se împotrivește instinctiv muncii depuse exclusiv pentru bucuria Creatorului, fără răsplată personală." },
    { f: "Ce trebuie să facă omul când vede că toate organele sale se împotrivesc dăruirii?", b: "Nu are altă soluție decât rugăciunea: să-și verse inima înaintea Creatorului pentru a-și supune trupul dăruirii." },
    { f: "Cum nimicește atingerea stării de Lishma înclinația spre rău?", b: "Anulează iubirea de sine; vasele de primire își pierd funcția egoistă și sunt considerate spiritual 'moarte'." },
    { f: "De ce este esențial să știm că fără rugăciune Lishma este de neatins?", b: "Pentru că această conștientizare transformă rugăciunea într-o necesitate absolută și urgentă, risipind iluzia autosuficienței." },
    { f: "Care este legătura între înălțarea MAN și vasul sufletului?", b: "MAN este lipsa însăși a Kli-ului; cu cât lipsa este mai pură și mai profundă, cu atât mai mare este Lumina pe care o poate primi vasul." },
    { f: "În ce sens este rugăciunea o mărturisire a neputinței egoismului?", b: "Inima își dezvăluie dependența totală, recunoscând că propriul ego este o temniță de neînvins fără ajutorul divin." },
    { f: "Cum se împletește munca în grup cu rugăciunea personală?", b: "Efortul de a-i iubi pe prieteni scoate la iveală incapacitatea totală de a dărui, dând naștere unui veritabil strigăt de ajutor." },
    { f: "De ce este considerată rugăciunea crearea însăși a vasului spiritual?", b: "Deoarece umplerea poate pătrunde doar acolo unde există o lipsă corespunzătoare; rugăciunea lărgește acest vid spiritual." },
    { f: "Ce înseamnă că 'Creatorul ascultă rugăciunea'?", b: "Cererea intră în rezonanță deplină cu legea superioară a dăruirii, iar Lumina umple pe loc Kli-ul deschis." },
    { f: "Ce rol are deznădejdea spirituală în nașterea rugăciunii?", b: "Semnalează epuizarea completă a forțelor egoiste, precedând în mod direct revărsarea ajutorului de Sus." },
    { f: "Ce este 'trezirea de Sus' (Itaruta de-Leila)?", b: "Manifestarea Luminii Superioare care coboară ca răspuns direct la o lipsă coaptă și purificată înălțată de jos (MAN)." },
    { f: "De ce este dorința de a primi comparată cu un 'hoț' în Shamati 20?", b: "Pentru că încearcă să fure și să-și însușească orice fărâmă de energie și bucurie exclusiv pentru propria plăcere egoistă." },
    { f: "De ce la început omul nu simte nicio bucurie în munca dăruirii?", b: "Pentru ca dorința de a primi să nu simtă niciun gust; dacă ar simți plăcere, omul nu s-ar putea ridica niciodată la Lishma curată." },
    { f: "Când devine munca spirituală o bucurie în sine?", b: "Când omul se obișnuiește cu dăruirea, iar bucuria oferită Creatorului devine răsplata însăși a muncii." },
    { f: "Când este o nemulțumire justificată sau nejustificată în munca spirituală?", b: "Te poți plânge doar stăpânului pentru care lucrezi cu adevărat; muncind pentru ego, nu ai dreptul să ceri forțe de la Creator." },
    { f: "Ce este clarificarea interioară (Berur) în rugăciune?", b: "Sortarea intențiilor: separarea a ceea ce se face pentru propriul ego de ceea ce este orientat spre dăruirea către Creator." },
    { f: "Ce este 'desăvârșirea absolută' la asumarea jugului Regatului Cerurilor?", b: "A dori exclusiv să dăruiești și a renunța complet la primirea în scop propriu." },
    { f: "De ce nu este suficientă înțelegerea intelectuală pentru rugăciunea inimii?", b: "Argumentele rațiunii nu mișcă vasul; doar o lipsă reală trăită în inimă atrage Lumina." },
    { f: "Cum funcționează MAN prin treptele lumilor spirituale?", b: "Treapta inferioară își înalță lipsa către cea superioară, care o ridică la Sursă, coborând răspunsul." },
    { f: "De ce este rugăciunea numită singura armă împotriva dorinței de a primi?", b: "Omul nu-și poate schimba singur natura creată; poate doar să strige către Creator pentru a primi o nouă natură a dăruirii." },
    { f: "De ce este rugăciunea un proces continuu și nu un act de moment?", b: "Un șir de eforturi și căderi șlefuiește și coace lipsa până când aceasta atinge o sinceritate deplină." },
    { f: "Cum se manifestă credința în izbăvire în stările cele mai întunecate?", b: "Chiar dacă trupul nu vede nicio scăpare, punctul din inimă este sigur că Creatorul îl poate salva într-o clipită." },
    { f: "Ce înseamnă că 'Creatorul tânjește după rugăciunea drepților'?", b: "Creatorul așteaptă un Kli pregătit și capabil de dăruire, deoarece natura iubirii Sale este de a revărsa plinătate." },
    { f: "Care este legătura între căință (Tshuva) și rugăciunea cabalistică?", b: "Căința este conștientizarea dureroasă a naturii egoiste, iar rugăciunea este cererea de eliberare din ea." },
    { f: "Cum protejează rugăciunea omul de mândria spirituală?", b: "Înrădăcinează certitudinea că orice nivel atins este exclusiv un dar nemeritat și o milă de Sus." },
    { f: "De ce pare uneori că o rugăciune rămâne fără răspuns?", b: "Lipsa nu a atins încă profunzimea sau puritatea necesară; vasul nu este încă pregătit să rețină Lumina." },
    { f: "Ce înseamnă 'vărsarea inimii înaintea Creatorului'?", b: "Predarea necondiționată a tuturor dorințelor ascunse, a temerilor și a neputințelor sub călăuzirea Creatorului." },
    { f: "Cum ajută cartea de rugăciuni (Sidur) munca interioară a cabalistului?", b: "Servește drept hartă spirituală precisă a stărilor interioare și a proceselor de corectare trasată de înțelepți atinși." },
    { f: "De ce este trecerea la Lishma considerată un miracol suprem?", b: "Pentru că transformarea naturii create (iubirea de sine) în altruism pur este posibilă doar prin puterea transformatoare a Luminii." },
    { f: "Cum devine rugăciunea un dialog viu cu Creatorul?", b: "Când vibrațiile inimii oglindesc fidel dorința de alipire, se deschide o comunicare interioară directă." },
    { f: "Ce înseamnă maxima 'Nu ești liber să te sustragi de la această muncă'?", b: "Deși scopul este un dar de Sus, travaliul de a clădi dorința și lipsa revine în totalitate omului." },
    { f: "Care este legătura între rugăciune și iubirea de prieteni?", b: "În efortul de a dărui prietenilor se dezvăluie incapacitatea de a iubi dezinteresat, dând naștere unui strigăt autentic de ajutor." },
    { f: "Cum curăță bilanțul interior intenția înainte de rugăciune?", b: "Demască motivele egoiste ascunse, înlătură țelurile false și focalizează strigătul într-un singur punct de adevăr." },
    { f: "Care este diferența între așteptarea pasivă și rugăciunea spirituală?", b: "Pasivitatea renunță la luptă, în timp ce rugăciunea este strigătul suprem al ostașului care luptă până la capătul forțelor." },
    { f: "Cum se reflectă Lumina Torei în rugăciune?", b: "Lumina Reformatoare atrasă în studiu luminează întunericul inimii, trezind o profundă rugă pentru corectare." },
    { f: "Ce înseamnă că rugăciunea adevărată 'strigă din adâncuri'?", b: "Un strigăt care izbucnește din adâncul dorinței de a primi, din cel mai întunecat abis al temniței ego-ului." },
    { f: "Cum conduce rugăciunea la Dvekut (contopire) cu Creatorul?", b: "Prin dobândirea dorinței de a dărui, omul atinge echivalența de formă cu Creatorul, realizând unirea supremă." },
    { f: "Care este învățătura practică esențială a Lecției 18 despre rugăciune?", b: "Nu te mulțumi cu repetarea cuvintelor; construiește un Hisaron adevărat în inimă, căci Creatorul ascultă doar adevărul inimii." }
  ],
  bg: [
    { f: "Какво е кабалистичното определение за молитва?", b: "'Работа в сърцето' (Авода шебаЛев) — дълбоко вътрешно изясняване на желанията, намеренията и дефицита пред Твореца." },
    { f: "Какво представлява духовното 'сърце' в Кабала?", b: "Сърцето олицетворява сбора от всички желания за получаване на човека и целостта на неговите емоционални и волеви стремежи." },
    { f: "Как се отнасят думите на устата към желанието на сърцето?", b: "Творецът отговаря единствено на истинския недостиг (Хисарон) в дълбините на сърцето, а не на механичните думи на устните." },
    { f: "Какво представлява понятието 'Хисарон' в молитвата?", b: "Истински вътрешен дефицит, празнотата на съсъда (Кли), копнеещ за духовно напълване и поправяне." },
    { f: "Защо механичното произнасяне на думи не се смята за автентична молитва?", b: "Защото ако сърцето не копнее за онова, което устните изричат, думите остават мъртви форми без духовна сила." },
    { f: "Кое е първото условие за чуване на молитвата?", b: "Непоколебима вяра, че Творецът действително е способен да избави човека от затвора на егоизма." },
    { f: "Кое е второто условие за чуване на молитвата?", b: "Осъзнаването, че няма друг изход: всички човешки сили са се провалили и само Творецът може да помогне." },
    { f: "Кое е третото условие за чуване на молитвата?", b: "Молбата да бъде наистина въпрос на живот и смърт, без която душата загива в желанието за получаване." },
    { f: "Как молитвата действа като 'медиум' (средство) в духовното развитие?", b: "Тя не цели промяна на Твореца, а трансформира човека, подготвяйки Кли за приемане на светлината на отдаването." },
    { f: "За какво моли кабалистът в истинската молитва като медиум?", b: "Единствено за дефицит за отдаване (желание за отдаване) и за подобие по форма с Твореца." },
    { f: "Какво е главното послание на статия 20 от 'Шамати' относно постигането на Лишма?", b: "Лишма (в името на Твореца / безкористно отдаване) е дар и озарение свише, което човешкият разум не може да постигне сам." },
    { f: "Ако Лишма е дар свише, защо са нужни човешките усилия?", b: "Усилията и средствата изграждат в човека поправените съсъди (Келим), които искрено желаят да получат Лишма." },
    { f: "Каква е ролята на неуспеха и безсилието в молитвата според 'Шамати' 20?", b: "Когато види безполезността на всички свои действия, човек стига до пълно безсилие и едва тогава може да се помоли от дъното на сърцето си." },
    { f: "Кога човек е способен на искрена молитва от дълбините на сърцето?", b: "Едва след като е изчерпал всички човешки средства и е осъзнал, че сам по себе си нищо не може да постигне без Твореца." },
    { f: "Какво означава понятието 'МА\"Н' (Маин Нуквин)?", b: "Женски води; недостигът, молитвата и пробуждането, издигащи се от долния съсъд, които привличат изобилие и светлина свише." },
    { f: "Каква е ролята на 'пробуждането отдолу' в духовната система?", b: "Пробуждането отдолу (молитвата на творението) задейства изливането на Висшите Светлини (МА\"Д — Маин Дехрин)." },
    { f: "Какво означава принципът 'На идващия да се пречисти помагат'?", b: "На онзи, който искрено се стреми към отдаване и чистота, Творецът дава свише сила, поправяне и издигане над егоизма." },
    { f: "Как точно Творецът помага на идващия да се пречисти?", b: "Дарява му състоянието Лишма, пробужда сърцето му и му дава сила, превъзхождаща неговата егоистична природа." },
    { f: "В какво се състои 'работата в сърцето' по време на ежедневното изясняване?", b: "В разграничаването на егоистичните желания от стремежа към отдаване и молитва за трансформация на собствената природа." },
    { f: "Защо Творецът не се променя чрез молитвата?", b: "Защото Творецът е Абсолютното Добро и Неизменен; молитвата променя приемащия съсъд, правейки го способен за Светлината." },
    { f: "Каква е разликата между конвенционалната религиозна и кабалистичната молитва?", b: "Обикновената молитва проси материални блага или облекчение за егото, докато кабалистичната молитва моли за избавление от егоизма." },
    { f: "Как се ражда истинският Хисарон по духовния път?", b: "Чрез постоянна работа в групата и изучаване на източниците, когато недостигът се осъзнава като отсъствие на светлината на отдаването." },
    { f: "Какво означава, че тялото 'не е съгласно с бремето на Небесното Царство'?", b: "Егоистичното желание за получаване инстинктивно се противи на труда единствено за радост на Твореца без лична изгода." },
    { f: "Какво трябва да направи човек, когато вижда, че всичките му органи се съпротивляват на отдаването?", b: "Няма друг изход освен молитвата: да излее сърцето си пред Твореца, умолявайки Го да склони тялото към отдаване." },
    { f: "Как постигането на Лишма умъртвява злото начало?", b: "То анулира себелюбието; съсъдите за получаване губят егоистичната си функция и духовно се считат за 'мъртви'." },
    { f: "Защо е важно да знаем, че без молитва Лишма е недостижима?", b: "Защото това знание превръща молитвата в абсолютна и неотложна необходимост, разсейвайки заблудата за самодостатъчност." },
    { f: "Каква е връзката между издигането на МА\"Н и съсъда на душата?", b: "МА\"Н е самият дефицит на Кли; колкото по-чист и дълбок е той, толкова по-голяма Светлина може да приеме съсъдът." },
    { f: "В какъв смисъл молитвата е признание за безсилието на егоизма?", b: "Сърцето разкрива пълната си зависимост, признавайки, че собственото му его е непревземаем затвор без божествената помощ." },
    { f: "Как работата в групата се съчетава с личната молитва?", b: "Усилието да обикнеш приятелите разкрива пълната неспособност за отдаване, раждайки истински вик за помощ." },
    { f: "Защо молитвата се счита за същинското създаване на духовния съсъд?", b: "Защото напълването може да влезе само там, където съществува празнота; молитвата очертава и разширява този вакуум." },
    { f: "Какво означава изразът 'Творецът чува молитвата'?", b: "Молбата влиза в съвършен резонанс с висшия закон на отдаването и Светлината мигновено изпълва отвореното Кли." },
    { f: "Каква роля играе духовното отчаяние в молитвата?", b: "То бележи пълното изтощение на егоистичните сили, което непосредствено предшества изливането на спасението свише." },
    { f: "Какво е 'пробуждане свише' (Итарута де-Леила)?", b: "Проявлението на Висшата Светлина, която се спуска в пряк отговор на зрял и пречистен недостиг отдолу (МА\"Н)." },
    { f: "Защо желанието за получаване е сравнено с 'крадец' в 'Шамати' 20?", b: "Защото се опитва да открадне и присвои всяка частица енергия и радост единствено за свое егоистично удоволствие." },
    { f: "Защо първоначално човек не усеща радост в работата по отдаване?", b: "За да не намери желанието за получаване вкус в нея; ако изпитваше егоистично удоволствие, никога не би се издигнал до Лишма." },
    { f: "Кога духовната работа става радост сама по себе си?", b: "Когато човек свикне с отдаването и доставянето на радост на Твореца се превърне в самата награда за труда." },
    { f: "Кога недоволството в духовната работа е оправдано или неоправдано?", b: "Човек може да роптае само срещу онзи господар, за когото реално работи; трудейки се за егото, няма право да иска сили от Твореца." },
    { f: "Какво представлява вътрешното изясняване (Беру́р) в молитвата?", b: "Анализ на намеренията: отделяне на онова, което се прави за егото, от онова, което е насочено към радост за Твореца." },
    { f: "Какво е 'пълно съвършенство' при приемането на бремето на Небесното Царство?", b: "Да желаеш единствено да отдаваш и напълно да се откажеш от получаване заради себе си." },
    { f: "Защо интелектуалното разбиране не е достатъчно за молитвата на сърцето?", b: "Доводите на ума не раздвижват съсъда; само реалният дефицит, изживян в сърцето, привлича Светлината." },
    { f: "Как действа МА\"Н през степените на духовните светове?", b: "По-долната степен издига своя дефицит към по-висшата, а тя го издига до Източника, спускайки отговора надолу." },
    { f: "Защо молитвата е наречена единственото оръжие срещу желанието за получаване?", b: "Човек не може сам да промени природата си; той може само да вика към Твореца за даряване на нова природа на отдаване." },
    { f: "Защо молитвата е продължителен процес, а не моментно действие?", b: "Поредица от усилия и падения шлифова и прави вътрешния дефицит зрял, докато достигне абсолютна искреност." },
    { f: "Как се проявява вярата в спасението в най-тъмните състояния?", b: "Дори когато тялото не вижда никакъв изход, точката в сърцето е сигурна, че Творецът може да спаси за миг." },
    { f: "Какво означава твърдението, че 'Творецът копнее за молитвата на праведниците'?", b: "Творецът очаква подготвен съсъд, способен на отдаване, тъй като природата на Неговата любов е да дава напълване." },
    { f: "Каква е връзката между разкаянието (Тшува) и кабалистичната молитва?", b: "Разкаянието е болезнено осъзнаване на егоистичната природа, а молитвата е молба за избавление от нея." },
    { f: "Как молитвата предпазва човека от духовна горделивост?", b: "Тя утвърждава съзнанието, че всяко духовно постижение е единствено незаслужен дар и милосърдие свише." },
    { f: "Защо понякога изглежда, че на молитвата няма отговор?", b: "Недостигът все още не е достигнал нужната дълбочина или чистота; съсъдът все още не е готов да задържи Светлината." },
    { f: "Какво означава 'да излееш сърцето си пред Твореца'?", b: "Безусловно предаване на всички тайни желания, страхове и безсилие под управлението на Твореца." },
    { f: "Как молитвеникът (Сидур) подпомага вътрешната работа на кабалиста?", b: "Служи като точна духовна карта на вътрешните състояния и процеси на поправяне, съставена от мъдреци." },
    { f: "Защо преходът към Лишма се счита за върховно чудо?", b: "Защото преобръщането на вродената природа (себелюбието) в чист алтруизъм е възможно само чрез силата на Светлината." },
    { f: "Как молитвата се превръща в жив диалог с Твореца?", b: "Когато трептенията на сърцето отразяват точно копнежа за сливане с Него, се открива пряко вътрешно общуване." },
    { f: "Какво означава изречението 'Не си длъжен да завършиш делото, но не си свободен да се откажеш'?", b: "Въпреки че целта е дар свише, трудът по изграждането на желанието и дефицита пада изцяло върху човека." },
    { f: "Каква е връзката между молитвата и любовта към приятелите?", b: "В усилието да се отдава на приятелите се разкрива пълната неспособност за любов, раждайки автентичен вик за помощ." },
    { f: "Как равносметката преди молитва пречиства намерението?", b: "Тя разобличава егоистичните подбуди, премахва фалшивите цели и фокусира вика в една точка на истината." },
    { f: "Каква е разликата между пасивното чакане и духовната молитва?", b: "Пасивността се предава без бой, докато молитвата е пределният вик на воина, борещ се до крайния предел на силите си." },
    { f: "Как Светлината на Тора се отразява в молитвата?", b: "Светлината, възвръщаща към Източника, привлечена в ученето, осветява мрака на сърцето, събуждайки дълбока молба за поправяне." },
    { f: "Какво означава, че истинската молитва 'вика от дълбините'?", b: "Вик, изригващ от самото дъно на желанието за получаване, от най-мрачната бездна на затвора на егото." },
    { f: "Как молитвата води до Двекут (сливане) с Твореца?", b: "Чрез придобиване на свойството отдаване човек постига подобие по форма с Твореца, което е пълно единство." },
    { f: "Кой е най-важният практически урок на Урок 18 относно молитвата?", b: "Не се задоволявай с механично повтаряне на думи; изгради истински Хисарон в сърцето си, защото Творецът откликва само на истината на сърцето." }
  ],
  cs: [
    { f: "Jaká je kabalistická definice modlitby?", b: "'Práce v srdci' (Avoda shebaLev), hluboké vnitřní vyjasnění tužeb, záměrů a nedostatků před Stvořitelem." },
    { f: "Co v Kabale představuje duchovní 'srdce'?", b: "Srdce ztělesňuje souhrn všech tužeb přijímat a veškerých emocionálních i volních sklonů člověka." },
    { f: "Jak se vztahují slova úst k touze srdce?", b: "Stvořitel odpovídá výhradně na skutečný nedostatek (Chisaron) v hloubi srdce, nikoli na mechanická slova vyřčená rty." },
    { f: "Co je to koncept 'Chisaron' v modlitbě?", b: "Opravdový vnitřní nedostatek, prázdnota nádoby (Kli), která horoucně touží po naplnění a duchovní nápravě." },
    { f: "Proč se mechanické opakování slov nepovažuje za autentickou modlitbu?", b: "Protože pokud srdce netouží po tom, co rty vyslovují, slova zůstávají mrtvými formami bez duchovní síly." },
    { f: "Jaká je první podmínka pro vyslyšení modlitby?", b: "Neotřesitelná víra v to, že Stvořitel je skutečně schopen vysvobodit člověka z vězení egoismu." },
    { f: "Jaká je druhá podmínka pro vyslyšení modlitby?", b: "Uvědomění si, že není jiné volby: všechny lidské síly selhaly a pomoci může jedině Stvořitel." },
    { f: "Jaká je třetí podmínka pro vyslyšení modlitby?", b: "Že prosba je vskutku otázkou života a smrti, bez jejíhož vyřešení duše hyne v touze přijímat." },
    { f: "Jak funguje modlitba jako 'médium' v duchovním vývoji?", b: "Nesnaží se změnit Stvořitele, nýbrž proměňuje člověka a připravuje Kli k přijetí světla odevzdání." },
    { f: "O co prosí kabalista v pravé modlitbě jako médiu?", b: "Výhradně o nedostatek k odevzdání (touhu odevzdávat) a o rovnocennost formy se Stvořitelem." },
    { f: "Jaké je hlavní poselství 20. článku Shamati ohledně dosažení Lišma?", b: "Lišma (pro Její Jméno / nezištné odevzdání) je dar a osvícení shůry, jehož lidská mysl nemůže dosáhnout sama o sobě." },
    { f: "Je-li Lišma darem shůry, proč je nutné lidské úsilí?", b: "Protože úsilí a nápravné prostředky budují v člověku napravené nádoby (Kelim), které si Lišma upřímně přejí přijmout." },
    { f: "Jakou roli hraje selhání a bezmoc v modlitbě podle Shamati 20?", b: "Když člověk vidí marnost všech svých činů, dospěje k naprosté bezmoci a teprve pak může volat z hloubi srdce." },
    { f: "Kdy je člověk schopen vyslat upřímnou modlitbu z hloubi svého srdce?", b: "Teprve poté, co vyčerpal všechny lidské prostředky a uznal, že sám ze sebe bez Stvořitele nezmůže vůbec nic." },
    { f: "Co znamená pojem 'MAN' (Majin Nukvin)?", b: "Ženské vody; nedostatek, modlitba a probuzení stoupající ze spodní nádoby, které přitahují hojnost a Světlo shůry." },
    { f: "Jaká je role 'probuzení zdola' v duchovním systému?", b: "Probuzení zdola (modlitba stvoření) spouští proudění Vyšších Světel (MAD – Majin Dechrin)." },
    { f: "Co znamená princip 'Kdo se přichází očistit, tomu pomáhají'?", b: "Tomu, kdo upřímně usiluje o odevzdání a čistotu, dává Stvořitel shůry sílu, nápravu a pozvednutí nad jeho přirozenost." },
    { f: "Jak konkrétně pomáhá Stvořitel tomu, kdo se přichází očistit?", b: "Obdaruje ho stavem Lišma, probudí jeho srdce a udělí mu sílu přesahující jeho egoistickou přirozenost." },
    { f: "Co je to 'práce v srdci' během každodenního vnitřního vyjasňování?", b: "Rozlišování egoistických tužeb od touhy odevzdávat s neustálou prosbou o proměnu vlastní přirozenosti." },
    { f: "Proč se Stvořitel modlitbou nemění?", b: "Protože Stvořitel je Absolutní Dobro a Neměnný; modlitba mění přijímající nádobu, aby byla schopna pojmout Světlo." },
    { f: "Jaký je rozdíl mezi konvenční náboženskou a kabalistickou modlitbou?", b: "Běžná modlitba žádá hmotné statky či úlevu pro ego, zatímco kabalistická modlitba prosí o vykoupení z egoismu." },
    { f: "Jak se na duchovní cestě rodí opravdový Chisaron?", b: "Vytrvalou prací ve skupině a studiem pramenů, kdy se nedostatek vyjasňuje jako absence světla odevzdání." },
    { f: "Co znamená, že tělo 'nesouhlasí s břemenem Království Nebes'?", b: "Vrozená touha přijímat instinktivně odmítá pracovat výhradně pro potěšení Stvořitele bez osobního zisku." },
    { f: "Co má člověk dělat, když vidí, že se všechny jeho orgány vzpírají odevzdání?", b: "Nezbývá mu než modlitba: vylít své srdce před Stvořitelem, aby přiměl tělo sklonit se k odevzdání." },
    { f: "Jak dosažení Lišma usmrcuje zlý sklon?", b: "Anuluje sebelásku; nádoby přijímání ztrácejí svou sobeckou funkci a jsou v duchovním smyslu považovány za 'mrtvé'." },
    { f: "Proč je zásadní vědět, že bez modlitby nelze dosáhnout Lišma?", b: "Protože toto vědomí činí z modlitby absolutní a naléhavou nutnost a rozptyluje iluzi soběstačnosti." },
    { f: "Jaká je souvislost mezi pozvednutím MAN a nádobou duše?", b: "MAN je samotný nedostatek Kli; čím čistší a hlubší je tento nedostatek, tím větší Světlo může nádoba pojmout." },
    { f: "V jakém smyslu je modlitba přiznáním bezmoci egoismu?", b: "Srdce odhaluje svou naprostou závislost a uznává, že jeho vlastní ego je vězením, ze kterého bez Stvořitele nelze uniknout." },
    { f: "Jak se práce ve skupině propojuje s osobní modlitbou?", b: "Úsilí milovat přátele odhaluje naprostou neschopnost nezištně odevzdávat, což plodí skutečné volání o pomoc." },
    { f: "Proč je modlitba považována za samotné vytvoření duchovní nádoby?", b: "Protože naplnění může vstoupit pouze tam, kde existuje odpovídající prázdnota; modlitba tento duchovní prostor rozšiřuje." },
    { f: "Co znamená výrok 'Stvořitel slyší modlitbu'?", b: "Prosba vstoupí do dokonalé rezonance s vyšším zákonem odevzdání a Světlo okamžitě naplní otevřené Kli." },
    { f: "Jakou roli hraje duchovní zoufalství při zrodu modlitby?", b: "Značí úplné vyčerpání egoistických sil, což bezprostředně předchází vstupu pomoci shůry." },
    { f: "Co je to 'probuzení shůry' (Itaruta de-Leila)?", b: "Zjevení Vyššího Světla, které přichází jako přímá odpověď na zralý a očištěný nedostatek zdola (MAN)." },
    { f: "Proč je touha přijímat v Shamati 20 přirovnávána ke 'zloději'?", b: "Protože se snaží ukrást a přivlastnit si každou jiskru energie a radosti výhradně pro své sobecké potěšení." },
    { f: "Proč člověk zpočátku necítí žádnou radost z práce pro odevzdání?", b: "Aby v tom touha přijímat nenašla zalíbení; kdyby v tom měla sobecký požitek, člověk by se nikdy nepozdvihl k čistému Lišma." },
    { f: "Kdy se duchovní práce stává radostí sama o sobě?", b: "Když si člověk zvykne odevzdávat a možnost působit potěšení Stvořiteli se stane samotnou odměnou za práci." },
    { f: "Kdy je stížnost v duchovní práci oprávněná či neoprávněná?", b: "Stěžovat si lze pouze tomu pánovi, pro kterého člověk skutečně pracuje; práce pro ego nedává právo žádat síly od Stvořitele." },
    { f: "Co je to vnitřní vyjasnění (Berur) v modlitbě?", b: "Třídění záměrů: oddělení toho, co slouží vlastnímu egu, od toho, co směřuje k potěšení Stvořitele." },
    { f: "Co je 'naprostá dokonalost' při přijetí břemene Království Nebes?", b: "Toužit výhradně odevzdávat a zcela se zříci přijímání pro vlastní prospěch." },
    { f: "Proč intelektuální porozumění nestačí pro modlitbu srdce?", b: "Důvody rozumu nepohnou duchovní nádobou; pouze skutečný nedostatek prožitý v srdci přitahuje Světlo." },
    { f: "Jak působí MAN skrze stupně duchovních světů?", b: "Nižší stupeň pozvedá svůj nedostatek k vyššímu, a ten jej vynáší ke Zdroji, odkud snáší odpověď." },
    { f: "Proč je modlitba nazývána jedinou zbraní proti touze přijímat?", b: "Člověk nedokáže sám změnit svou přirozenost; může pouze volat ke Stvořiteli, aby mu udělil novou přirozenost odevzdání." },
    { f: "Proč je modlitba nepřetržitým procesem, a nikoli chvilkovým aktem?", b: "Řetězec úsilí a pádů brousí a zceluje vnitřní nedostatek, dokud nedosáhne absolutní upřímnosti." },
    { f: "Jak se projevuje víra ve vysvobození v těch nejtemnějších stavech?", b: "I když tělo nevidí žádné východisko, bod v srdci si je jist, že Stvořitel dokáže zachránit v mžiku oka." },
    { f: "Co znamená, že 'Stvořitel touží po modlitbě spravedlivých'?", b: "Stvořitel čeká na připravené Kli schopné odevzdávat, neboť podstatou Jeho lásky je udělovat naplnění." },
    { f: "Jaká je souvislost mezi pokáním (Tshuva) a kabalistickou modlitbou?", b: "Pokání je bolestné rozpoznání zla vlastní egoistické přirozenosti a modlitba je prosbou o vysvobození z ní." },
    { f: "Jak modlitba chrání člověka před duchovní pýchou?", b: "Upevňuje vědomí, že jakýkoli dosažený duchovní stupeň je výhradně nezaslouženým darem a milosrdenstvím shůry." },
    { f: "Proč se někdy zdá, že modlitba zůstává bez odpovědi?", b: "Nedostatek ještě nedosáhl potřebné hloubky a čistoty; Kli ještě není připraveno udržet Světlo." },
    { f: "Co znamená 'vylít své srdce před Stvořitelem'?", b: "Bezvýhradné odevzdání všech skrytých tužeb, obav a bezmoci pod vedení Stvořitele." },
    { f: "Jak modlitební kniha (Sidur) pomáhá vnitřní práci kabalisty?", b: "Slouží jako přesná duchovní mapa vnitřních stavů a procesů nápravy sepsaná moudrými, kteří dosáhli cíle." },
    { f: "Proč je přechod k Lišma považován za zázrak?", b: "Protože převrátit vrozenou přirozenost (sebelásku) v čistý altruismus je možné pouze proměňující silou Světla." },
    { f: "Jak se modlitba mění v živý dialog se Stvořitelem?", b: "Když záchvěvy srdce přesně zrcadlí touhu přimknout se k Němu, otevírá se přímá vnitřní komunikace." },
    { f: "Co znamená rčení 'Nejsi povinen dílo dokončit, ale nejsi volen se mu vyhnout'?", b: "Ačkoli cíl je darem shůry, veškeré břemeno budování touhy a nedostatku leží plně na člověku." },
    { f: "Jaká je vazba mezi modlitbou a láskou k přátelům?", b: "V úsilí odevzdávat přátelům se odhaluje naprostá neschopnost nezištně milovat, což rodí pravé volání o pomoc." },
    { f: "Jak vnitřní účtování před modlitbou očišťuje záměr?", b: "Odhaluje skryté sobecké motivy, odstraňuje falešné cíle a soustředí volání do jediného bodu pravdy." },
    { f: "Jaký je rozdíl mezi pasivním čekáním a duchovní modlitbou?", b: "Pasivita se vzdává bez boje, zatímco modlitba je mezním křikem bojovníka zápasícího na samé hranici sil." },
    { f: "Jak se Světlo Tóry odráží v modlitbě?", b: "Reformující Světlo přitahované při studiu osvětluje temnotu srdce a probouzí hlubokou prosbu o nápravu." },
    { f: "Co znamená, že pravá modlitba 'volá z hlubin'?", b: "Křik vyrážející ze samotného dna touhy přijímat, z nejtemnější propasti vězení ega." },
    { f: "Jak modlitba vede k Dvekut (přilnutí) se Stvořitelem?", b: "Získáním vlastnosti odevzdání dosahuje člověk rovnocennosti formy se Stvořitelem, což je dokonalé sjednocení." },
    { f: "Jaké je hlavní praktické ponaučení 18. lekce o modlitbě?", b: "Nespokojuj se s opakováním slov; vybuduj v srdci opravdový Chisaron, neboť Stvořitel naslouchá pouze pravdě srdce." }
  ],
  hr: [
    { f: "Koja je kabalistička definicija molitve?", b: "'Rad u srcu' (Avoda shebaLev), duboko unutarnje razjašnjenje želja, namjera i nedostataka pred Stvoriteljem." },
    { f: "Što u Kabali predstavlja duhovno 'srce'?", b: "Srce utjelovljuje zbroj svih čovjekovih želja za primanjem te cjelokupnost njegovih emocionalnih i voljnih težnji." },
    { f: "Kako se riječi usana odnose prema želji srca?", b: "Stvoritelj odgovara isključivo na istinski nedostatak (Hisaron) u dubini srca, a nikada na mehaničke riječi izrečene usnama." },
    { f: "Što je pojam 'Hisaron' u molitvi?", b: "Istinski unutarnji nedostatak, praznina posude (Kli) koja žudno čezne za ispunjenjem i duhovnim ispravljanjem." },
    { f: "Zašto se mehaničko ponavljanje riječi ne smatra autentičnom molitvom?", b: "Zato što ako srce ne žudi za onim što usne izgovaraju, riječi ostaju mrtve forme bez duhovne snage." },
    { f: "Koji je prvi uvjet da bi molitva bila uslišana?", b: "Nepokolebljiva vjera u to da je Stvoritelj doista sposoban izbaviti čovjeka iz zatočeništva egoizma." },
    { f: "Koji je drugi uvjet da bi molitva bila uslišana?", b: "Spoznaja da nema drugog izbora: sve su ljudske snage zakazale i jedino Stvoritelj može pomoći." },
    { f: "Koji je treći uvjet da bi molitva bila uslišana?", b: "Da molba doista bude pitanje života i smrti, bez čijeg rješenja duša propada u želji za primanjem." },
    { f: "Kako molitva djeluje kao 'medij' u duhovnom razvoju?", b: "Ona ne nastoji promijeniti Stvoritelja, već preobražava čovjeka, pripremajući Kli za primanje svjetla davanja." },
    { f: "Što kabalist traži u pravoj molitvi kao mediju?", b: "Isključivo nedostatak za davanje (želju za davanjem) i istovjetnost oblika sa Stvoriteljem." },
    { f: "Koja je središnja poruka 20. članka Shamati o postizanju Lishma?", b: "Lishma (radi Njezina Imena / nesebično davanje) dar je i prosvjetljenje odozgo koje ljudski razum ne može postići sam." },
    { f: "Ako je Lishma dar odozgo, zašto je potreban ljudski trud?", b: "Zato što napori i sredstva grade u čovjeku ispravljene posude (Kelim) koje istinski čeznu primiti Lishma." },
    { f: "Kakvu ulogu igra neuspjeh i nemoć u molitvi prema Shamati 20?", b: "Kada čovjek vidi uzaludnost svih svojih djela, dospijeva u potpunu nemoć i tek tada može zavapiti iz dubine srca." },
    { f: "Kada je čovjek sposoban uputiti iskrenu molitvu iz dubine svoga srca?", b: "Tek nakon što je iscrpio sva ljudska sredstva i uvidio da sam bez Stvoritelja ne može postići ništa." },
    { f: "Što označava pojam 'MAN' (Mayin Nukvin)?", b: "Ženske vode; nedostatak, molitva i buđenje koji se uzdižu iz donje posude i privlače obilje i Svjetlo odozgo." },
    { f: "Koja je uloga 'buđenja odozdo' u duhovnom sustavu?", b: "Buđenje odozdo (molitva stvorenja) pokreće izlijevanje Viših Svjetala (MAD – Mayin Dehrin)." },
    { f: "Što znači načelo 'Onome tko se dolazi očistiti pomaže se'?", b: "Onome tko iskreno teži davanju i čistoći, Stvoritelj odozgo daje snagu, ispravljanje i uzdizanje iznad njegove prirode." },
    { f: "Kako točno Stvoritelj pomaže onome tko se dolazi očistiti?", b: "Daruje mu stanje Lishma, budi njegovo srce i daje mu nadnaravnu snagu koja nadilazi njegov egoizam." },
    { f: "Što je 'rad u srcu' tijekom svakodnevnog unutarnjeg razjašnjenja?", b: "Razlikovanje egoističnih želja od želje za davanjem, uz neprestanu molitvu za preobrazbu vlastite prirode." },
    { f: "Zašto se Stvoritelj ne mijenja molitvom?", b: "Zato što je Stvoritelj Apsolutno Dobro i Nepromjenjiv; molitva mijenja posudu primateljicu čineći je sposobnom zadržati Svjetlo." },
    { f: "Koja je razlika između konvencionalne religijske i kabalističke molitve?", b: "Obična molitva traži materijalna dobra ili olakšanje za ego, dok kabalistička molitva vapi za izbavljenjem iz egoizma." },
    { f: "Kako se na duhovnom putu rađa pravi Hisaron?", b: "Ustrajnim radom u grupi i proučavanjem izvora, pri čemu se nedostatak razjašnjava kao odsutnost svjetla davanja." },
    { f: "Što znači da se tijelo 'ne slaže s jarmom Kraljevstva Nebeskog'?", b: "Urođena želja za primanjem instinktivno se protivi radu isključivo za radost Stvoritelja bez osobne nagrade." },
    { f: "Što čovjek treba učiniti kad vidi da se svi njegovi organi opiru davanju?", b: "Nema drugog izbora osim molitve: izliti svoje srce pred Stvoriteljem da privoli tijelo na davanje." },
    { f: "Kako postizanje Lishma usmrćuje zli nagon?", b: "Poništava samoljublje; posude primanja gube svoju sebičnu funkciju i duhovno se smatraju 'mrtvima'." },
    { f: "Zašto je ključno znati da je bez molitve nemoguće postići Lishma?", b: "Jer to znanje pretvara molitvu u apsolutnu i hitnu potrebu, raspršujući iluziju samodostatnosti." },
    { f: "Kakva je veza između uzdizanja MAN i posude duše?", b: "MAN je sam nedostatak u Kli; što je taj nedostatak čišći i dublji, to veće Svjetlo posuda može primiti." },
    { f: "U kojem je smislu molitva priznanje nemoći egoizma?", b: "Srce otkriva svoju potpunu ovisnost, priznajući da je vlastiti ego tamnica iz koje se ne može izaći bez Stvoritelja." },
    { f: "Kako se rad u grupi povezuje s osobnom molitvom?", b: "Napor da se zavole prijatelji razotkriva potpunu nesposobnost nesebičnog davanja, rađajući istinski vapaj za pomoć." },
    { f: "Zašto se molitva smatra samim stvaranjem duhovne posude?", b: "Zato što ispunjenje može ući samo ondje gdje postoji odgovarajući nedostatak; molitva širi taj duhovni vakuum." },
    { f: "Što znači izraz 'Stvoritelj čuje molitvu'?", b: "Molba ulazi u savršenu rezonanciju s višim zakonom davanja i Svjetlo trenutačno ispunjava otvoreni Kli." },
    { f: "Kakvu ulogu igra duhovni očaj u rađanju molitve?", b: "Označava potpuno iscrpljenje egoističnih snaga, što izravno prethodi spuštanju pomoći odozgo." },
    { f: "Što je to 'buđenje odozgo' (Itaruta de-Leila)?", b: "Očitovanje Višeg Svjetla koje silazi kao izravan odgovor na zreo i pročišćen nedostatak odozdo (MAN)." },
    { f: "Zašto se želja za primanjem uspoređuje s 'lopovom' u Shamati 20?", b: "Zato što pokušava ukrasti i prisvojiti svaku česticu energije i radosti isključivo za svoj sebični užitak." },
    { f: "Zašto čovjek u početku ne osjeća radost u radu za davanje?", b: "Kako želja za primanjem u tome ne bi osjetila okus; da je osjetila slast, čovjek se nikada ne bi uzdigao do čistog Lishma." },
    { f: "Kada duhovni rad postaje radost sam po sebi?", b: "Kada se čovjek navikne na davanje, a donošenje radosti Stvoritelju postane sama nagrada za trud." },
    { f: "Kada je prigovor u duhovnom radu opravdan ili neopravdan?", b: "Prigovarati se može samo onom gospodaru za kojeg se doista radi; rad za ego ne daje pravo tražiti snagu od Stvoritelja." },
    { f: "Što je unutarnje razjašnjenje (Berur) u molitvi?", b: "Analiza namjera: odvajanje onoga što služi vlastitom egu od onoga što donosi radost Stvoritelju." },
    { f: "Što je 'potpuno savršenstvo' u prihvaćanju jarma Kraljevstva Nebeskog?", b: "Željeti isključivo davati i potpuno se odreći primanja za vlastitu korist." },
    { f: "Zašto intelektualno razumijevanje nije dovoljno za molitvu srca?", b: "Razumski argumenti ne pokreću duhovnu posudu; samo stvarni nedostatak proživljen u srcu privlači Svjetlo." },
    { f: "Kako djeluje MAN kroz stupnjeve duhovnih svjetova?", b: "Niži stupanj uzdiže svoj nedostatak višem, a viši ga uznosi do Izvora, spuštajući odgovor dolje." },
    { f: "Zašto se molitva naziva jedinim oružjem protiv želje za primanjem?", b: "Čovjek ne može sam promijeniti svoju stvorenu prirodu; može samo vapiti Stvoritelju da mu podari novu prirodu davanja." },
    { f: "Zašto je molitva trajan proces, a ne trenutan čin?", b: "Niz napora i padova brusi i sazrijeva unutarnji nedostatak dok ne dosegne apsolutnu iskrenost." },
    { f: "Kako se očituje vjera u izbavljenje u najmračnijim stanjima?", b: "Čak i kada tijelo ne vidi izlaz, točka u srcu sigurna je da Stvoritelj može spasiti u tren oka." },
    { f: "Što znači da 'Stvoritelj čezne za molitvom pravednika'?", b: "Stvoritelj čeka pripremljeni Kli sposoban za davanje, jer je priroda Njegove ljubavi pružati ispunjenje." },
    { f: "Kakva je veza između pokajanja (Tshuva) i kabalističke molitve?", b: "Pokajanje je bolna spoznaja egoistične prirode, a molitva je molba za izbavljenje iz nje." },
    { f: "Kako molitva štiti čovjeka od duhovne oholosti?", b: "Učvršćuje svijest da je svako duhovno postignuće isključivo nezasluženi dar i milosrđe odozgo." },
    { f: "Zašto se ponekad čini da molitva ostaje bez odgovora?", b: "Nedostatak još nije dosegnuo potrebnu dubinu ili čistoću; Kli još nije spreman zadržati Svjetlo." },
    { f: "Što znači 'izliti srce pred Stvoriteljem'?", b: "Bezuvjetna predaja svih skrivenih želja, strahova i nemoći pod vodstvo Stvoritelja." },
    { f: "Kako molitvenik (Siddur) pomaže unutarnjem radu kabalista?", b: "Služi kao točna duhovna karta unutarnjih stanja i procesa ispravljanja koju su sastavili mudraci." },
    { f: "Zašto se prijelaz u Lishma smatra vrhunskim čudom?", b: "Jer je preokretanje stvorene prirode (samoljublja) u čisti altruizam moguće samo preobražavajućom snagom Svjetla." },
    { f: "Kako molitva prerasta u živi dijalog sa Stvoriteljem?", b: "Kada titraji srca točno zrcale čežnju za prianjanjem uz Njega, otvara se izravna unutarnja komunikacija." },
    { f: "Što znači izreka 'Nisi dužan dovršiti posao, ali nisi slobodan odustati'?", b: "Iako je cilj dar odozgo, sav trud oko izgradnje želje i nedostatka počiva u potpunosti na čovjeku." },
    { f: "Kakva je veza između molitve i ljubavi prema prijateljima?", b: "U naporu da se daje prijateljima razotkriva se potpuna nesposobnost nesebične ljubavi, rađajući autentičan vapaj za pomoć." },
    { f: "Kako preispitivanje prije molitve pročišćava namjeru?", b: "Razotkriva skrivene sebične motive, odbacuje lažne ciljeve i usmjerava vapaj u jednu točku istine." },
    { f: "Koja je razlika između pasivnog čekanja i duhovne molitve?", b: "Pasivnost se predaje bez borbe, dok je molitva krajnji krik ratnika koji se bori do posljednje kapi snage." },
    { f: "Kako se Svjetlo Tore odražava u molitvi?", b: "Svjetlo koje Reformira privučeno učenjem osvjetljava tminu srca, budeći duboku molbu za ispravljanjem." },
    { f: "Što znači da prava molitva 'vapi iz dubine'?", b: "Krik koji izbija s dna želje za primanjem, iz najmračnijeg ponora tamnice ega." },
    { f: "Kako molitva vodi do Dvekut (prianjanja) uz Stvoritelja?", b: "Stjecanjem svojstva davanja čovjek postiže istovjetnost oblika sa Stvoriteljem, što je potpuno jedinstvo." },
    { f: "Koja je najvažnija praktična pouka 18. lekcije o molitvi?", b: "Ne zadovoljavaj se ponavljanjem riječi; izgradi pravi Hisaron u srcu, jer Stvoritelj uslišava samo istinu srca." }
  ],
  sr: [
    { f: "Која је кабалистичка дефиниција молитве?", b: "'Рад у срцу' (Авода шебаЛев), дубоко унутрашње разјашњење жеља, намера и недостатака пред Створитељем." },
    { f: "Шта у Кабали представља духовно 'срце'?", b: "Срце представља збир свих човекових жеља за примањем и целину његових емоционалних и вољних тежњи." },
    { f: "Како се речи уста односе према жељи срца?", b: "Створитељ одговара искључиво на истински недостатак (Хисарон) у дубини срца, а никада на механичке речи изречене уснама." },
    { f: "Шта је појам 'Хисарон' у молитви?", b: "Истински унутрашњи недостатак, празнина посуде (Кли) која чезне за испуњењем и духовним исправљањем." },
    { f: "Зашто се механичко понављање речи не сматра аутентичном молитвом?", b: "Зато што ако срце не жуди за оним што усне изговарају, речи остају мртве форме без духовне снаге." },
    { f: "Који је први услов да би молитва била услишена?", b: "Непоколебљива вера у то да је Створитељ заиста способан да избави човека из затвора егоизма." },
    { f: "Који је други услов да би молитва била услишена?", b: "Свест да нема другог избора: све људске снаге су пропале и само Створитељ може помоћи." },
    { f: "Који је трећи услов да би молитва била услишена?", b: "Да молба заиста буде питање живота и смрти, без чијег решења душа пропада у жељи за примањем." },
    { f: "Како молитва делује као 'медијум' у духовном развоју?", b: "Она не мења Створитеља, већ преображава човека, припремајући Кли да прими светлост давања." },
    { f: "Шта кабалиста тражи у правој молитви као медијуму?", b: "Искључиво недостатак за давање (жељу за давањем) и једнакост облика са Створитељем." },
    { f: "Која је централна порука 20. чланка Шамати о постизању Лишма?", b: "Лишма (ради Њеног Имена / несебично давање) је дар и просветљење одозго које људски разум не може сам да постигне." },
    { f: "Ако је Лишма дар одозго, зашто је потребан људски труд?", b: "Зато што напори и средства граде у човеку исправљене посуде (Келим) које истински желе да приме Лишма." },
    { f: "Какву улогу играју неуспех и немоћ у молитви према Шамати 20?", b: "Када човек види узалудност свих својих поступака, долази до потпуне немоћи и тек тада може завапити из дубине срца." },
    { f: "Када је човек способан да упути искрену молитву из дубине свог срца?", b: "Тек након што је испробао сва људска средства и увидео да сам без Створитеља не може постићи ништа." },
    { f: "Шта означава појам 'МАН' (Мајин Нуквин)?", b: "Женске воде; недостатак, молитва и буђење који се уздижу из доње посуде и привлаче обиље и Светлост одозго." },
    { f: "Која је улога 'буђења одоздо' у духовном систему?", b: "Буђење одоздо (молитва створења) покреће изливање Виших Светлости (МАД – Мајин Дехрин)." },
    { f: "Шта значи начело 'Ономе ко долази да се очисти помаже се'?", b: "Ономе ко искрено тежи давању и чистоти, Створитељ одозго даје снагу, исправљање и уздизање изнад његове природе." },
    { f: "Како тачно Створитељ помаже ономе ко долази да се очисти?", b: "Дарује му стање Лишма, буди његово срце и даје му натприродну снагу која превазилази његов егоизам." },
    { f: "Шта је 'рад у срцу' током свакодневног унутрашњег разјашњења?", b: "Разликовање егоистичних жеља од жеље за давањем, уз непрестану молитву за преображај сопствене природе." },
    { f: "Зашто се Створитељ не мења молитвом?", b: "Зато што је Створитељ Апсолутно Добро и Непроменљив; молитва мења посуду примаоца чинећи је способном да задржи Светлост." },
    { f: "Која је разлика између конвенционалне религијске и кабалистичке молитве?", b: "Обична молитва тражи материјална добра или олакшање за его, док кабалистичка молитва вапи за избављењем из егоизма." },
    { f: "Како се на духовном путу рађа прави Хисарон?", b: "Истрајним радом у групи и проучавањем извора, при чему се недостатак разјашњава као одсуство светлости давања." },
    { f: "Шта значи да се тело 'не слаже са јармом Царства Небеског'?", b: "Урођена жеља за примањем инстинктивно се противи раду искључиво ради радости Створитеља без личне награде." },
    { f: "Шта човек треба да уради кад види да се сви његови органи опиру давању?", b: "Нема другог избора осим молитве: излити своје срце пред Створитељем да приволи тело на давање." },
    { f: "Како постизање Лишма усмрћује зли нагон?", b: "Поништава самољубље; посуде примања губе своју себичну функцију и духовно се сматрају 'мртвима'." },
    { f: "Зашто је важно знати да је без молитве немогуће постићи Лишма?", b: "Јер то знање претвара молитву у апсолутну и хитну потребу, распршујући илузију самодовољности." },
    { f: "Каква је веза између уздизања МАН и посуде душе?", b: "МАН је сам недостатак у Кли; што је тај недостатак чистији и дубљи, то већу Светлост посуда може примити." },
    { f: "У ком смислу је молитва признање немоћи егоизма?", b: "Срце открива своју потпуну зависност, признајући да је сопствени его тамница из које се не може изаћи без Створитеља." },
    { f: "Како се рад у групи спаја са личном молитвом?", b: "Напор да се воле пријатељи разоткрива потпуну неспособност несебичног давања, рађајући истински вапај за помоћ." },
    { f: "Зашто се молитва сматра самим стварањем духовне посуде?", b: "Зато што испуњење може ући само тамо где постоји одговарајући недостатак; молитва шири тај духовни вакуум." },
    { f: "Шта значи израз 'Створитељ чује молитву'?", b: "Молба улази у савршену резонанцу са вишим законом давања и Светлост тренутно испуњава отворени Кли." },
    { f: "Какву улогу игра духовни очај у молитви?", b: "Означава потпуно исцрпљивање егоистичних снага, што непосредно претходи изливању спасења одозго." },
    { f: "Шта је то 'буђење одозго' (Итарута де-Леила)?", b: "Очитовање Више Светлости која силази као директан одговор на зрео и прочишћен недостатак одоздо (МАН)." },
    { f: "Зашто се жеља за примањем пореди са 'лоповом' у Шамати 20?", b: "Зато што покушава да украде и присвоји сваку честицу енергије и радости искључиво за своје себично уживање." },
    { f: "Зашто човек у почетку не осећа радост у раду за давање?", b: "Како жеља за примањем у томе не би осетила укус; да је осетила сласт, човек се никада не би уздигао до чистог Лишма." },
    { f: "Када духовни рад постаје радост сам по себи?", b: "Када се човек навикне на давање, а доношење радости Створитељу постане сама награда за труд." },
    { f: "Када је приговор у духовном раду оправдан или неоправдан?", b: "Човек се може жалити само оном господару за кога стварно ради; рад за его не даје право тражити снагу од Створитеља." },
    { f: "Шта је унутрашње разјашњење (Берур) у молитви?", b: "Анализа намера: одвајање онога што служи сопственом егу од онога што доноси радост Створитељу." },
    { f: "Шта је 'потпуно савршенство' у прихватању јарма Царства Небеског?", b: "Желети искључиво давати и потпуно се одрећи примања за сопствену корист." },
    { f: "Зашто интелектуално разумевање није довољно за молитву срца?", b: "Разлози ума не покрећу духовну посуду; само стварни недостатак доживљен у срцу привлачи Светлост." },
    { f: "Како делује МАН кроз ступњеве духовних светова?", b: "Нижи ступањ уздиже свој недостатак вишем, а виши га узноси до Извора, спуштајући одговор доле." },
    { f: "Зашто се молитва назива јединим оружјем против жеље за примањем?", b: "Човек не може сам променити своју створену природу; може само вапити Створитељу да му подари нову природу давања." },
    { f: "Зашто је молитва трајан процес, а не тренутан чин?", b: "Низ напора и падова бруси и чини унутрашњи недостатак зрелим док не достигне апсолутну искреност." },
    { f: "Како се очитује вера у избављење у најмрачнијим стањима?", b: "Чак и када тело не види излаз, тачка у срцу је сигурна да Створитељ може спасити у трен ока." },
    { f: "Шта значи да 'Створитељ жуди за молитвом праведника'?", b: "Створитељ чека припремљени Кли способан за давање, јер је природа Његове љубави пружање испуњења." },
    { f: "Каква је веза између покајања (Тшува) и кабалистичке молитве?", b: "Покајање је болна спознаја егоистичне природе, а молитва је молба за избављење из ње." },
    { f: "Како молитва штити човека од духовне охолости?", b: "Учвршћује свест да је свако духовно постигнуће искључиво незаслужени дар и милосрђе одозго." },
    { f: "Зашто понекад изгледа да молитва остаје без одговора?", b: "Недостатак још није достигао потребну дубину или чистоту; Кли још није спреман да задржи Светлост." },
    { f: "Шта значи 'излити срце пред Створитељем'?", b: "Безусловна предаја свих скривених жеља, страхова и немоћи под вођство Створитеља." },
    { f: "Како молитвеник (Сидур) помаже унутрашњем раду кабалисте?", b: "Служи као тачна духовна карта унутрашњих стања и процеса исправљања коју су саставили мудраци." },
    { f: "Зашто се прелазак у Лишма сматра врхунским чудом?", b: "Јер је преокретање створене природе (самољубља) у чисти алтруизам могуће само преображавајућом снагом Светлости." },
    { f: "Како молитва прераста у живи дијалог са Створитељем?", b: "Када трептаји срца тачно осликавају чежњу за сједињењем са Њим, отвара се директна унутрашња комуникација." },
    { f: "Шта значи изрека 'Ниси дужан да завршиш посао, али ниси слободан да одустанеш'?", b: "Иако је циљ дар одозго, сав труд око изградње жеље и недостатка лежи у потпуности на човеку." },
    { f: "Каква је веза између молитве и љубави према пријатељима?", b: "У напору да се даје пријатељима разоткрива се потпуна неспособност несебичне љубави, рађајући аутентичан вапај за помоћ." },
    { f: "Како преиспитивање пре молитве прочишћава намеру?", b: "Разоткрива скривене себичне мотиве, одбацује лажне циљеве и усмерава вапај у једну тачку истине." },
    { f: "Која је разлика између пасивног чекања и духовне молитве?", b: "Пасивност се предаје без борбе, док је молитва крајњи крик ратника који се бори до последње капи снаге." },
    { f: "Како се Светлост Торе одражава у молитви?", b: "Светлост која Реформише привучена учењем осветљава тмину срца, будећи дубоку молбу за исправљањем." },
    { f: "Шта значи да права молитва 'вапи из дубине'?", b: "Крик који избија са дна жеље за примањем, из најмрачнијег понора тамнице ега." },
    { f: "Како молитва води до Двекут (пријањања) уз Створитеља?", b: "Стицањем својства давања човек постиже једнакост облика са Створитељем, што је потпуно јединство." },
    { f: "Која је најважнија практична поука 18. лекције о молитви?", b: "Не задовољавај се понављањем речи; изгради прави Хисарон у срцу, јер Створитељ услишава само истину срца." }
  ],
  tr: [
    { f: "Duanın Kabalistik tanımı nedir?", b: "'Kalpteki çalışma' (Avoda shebaLev), kişinin Yaratan'ın huzurunda arzularını, niyetlerini ve eksikliklerini derinlemesine içsel olarak netleştirmesidir." },
    { f: "Kabala'da manevi 'kalp' neyi temsil eder?", b: "Kalp, insanın tüm alma arzularının ve duygusal-iradesel yönelimlerinin toplamını temsil eder." },
    { f: "Ağzın sözleri ile kalbin arzusu birbiriyle nasıl ilişkilidir?", b: "Yaratan ağzın mekanik sözlerine değil, yalnızca kalbin derinliklerinde yatan gerçek eksikliğe (Hisaron) cevap verir." },
    { f: "Duada 'Hisaron' kavramı ne anlama gelir?", b: "Doyuma ve manevi ıslaha özlem duyan kabın (Kli) içsel boşluğu, samimi bir eksiklik hissidir." },
    { f: "Sözcüklerin mekanik olarak tekrarlanması neden otantik bir dua sayılmaz?", b: "Çünkü dudakların söylediğini kalp arzulamıyorsa, sözler manevi canlılıktan yoksun ölü formlar olarak kalır." },
    { f: "Duanın kabul olmasının birinci koşulu nedir?", b: "Yaratan'ın insanı bencillik zindanından kurtarmaya gerçekten muktedir olduğuna dair sarsılmaz bir inanç." },
    { f: "Duanın kabul olmasının ikinci koşulu nedir?", b: "Başka hiçbir seçeneğin kalmadığının farkına varmak: tüm insani güçler tükenmiştir ve yalnızca Yaratan yardım edebilir." },
    { f: "Duanın kabul olmasının üçüncü koşulu nedir?", b: "Talebin gerçekten bir ölüm kalım meselesi olması; bu olmadan ruh alma arzusunda helak olur." },
    { f: "Dua manevi gelişimde bir 'araç' (medyum) olarak nasıl işlev görür?", b: "Yaratan'ı değiştirmeyi amaçlamaz, aksine insanı dönüştürür ve Kli'yi ihsan etme ışığını almaya hazırlar." },
    { f: "Kabalist bir araç olan gerçek duada ne ister?", b: "Yalnızca ihsan etme eksikliğini (ihsan etme arzusunu) ve Yaratan ile form eşitliğini ister." },
    { f: "Şamati 20. makalesinin Lişma'ya ulaşma konusundaki temel mesajı nedir?", b: "Lişma (O'nun Adına / özgecil ihsan etme), insan aklının tek başına kavrayamayacağı, Yukarıdan gelen bir hediye ve aydınlanmadır." },
    { f: "Lişma Yukarıdan gelen bir lütufsa, insanın çabası neden gereklidir?", b: "Çünkü çabalar ve ıslah araçları, insanda Lişma'yı gerçekten arzulayan ıslah edilmiş kapları (Kelim) inşa eder." },
    { f: "Şamati 20'ye göre başarısızlığın ve çaresizliğin duadaki rolü nedir?", b: "İnsan tüm eylemlerinin nafile olduğunu gördüğünde tam bir çaresizliğe ulaşır ve ancak o zaman kalbinin derinliklerinden feryat edebilir." },
    { f: "İnsan ne zaman kalbinin derinliklerinden samimi bir dua edebilir?", b: "Ancak tüm insani çareleri tükettikten ve Yaratan olmadan tek başına hiçbir şey yapamayacağını anladıktan sonra." },
    { f: "'MAN' (Mayin Nukvin) kavramı neyi ifade eder?", b: "Dişil sular; alt kaptan yükselen ve Yukarıdan bereketi ve Işığı çeken eksiklik, dua ve uyanıştır." },
    { f: "Manevi sistemde 'aşağıdan gelen uyanışın' rolü nedir?", b: "Aşağıdan gelen uyanış (yaratılanın duası), Üst Işıkların (MAD - Mayin Dehrin) akışını başlatır." },
    { f: "'Arınmaya gelene yardım edilir' ilkesi ne anlama gelir?", b: "İhsan etmeye ve arınmaya samimiyetle çabalayana Yaratan Yukarıdan güç, ıslah ve doğasının üzerine yükselme imkanı bahşeder." },
    { f: "Yaratan arınmaya gelen kişiye tam olarak nasıl yardım eder?", b: "Ona Lişma derecesini bahşeder, kalbini uyandırır ve bencil doğasını aşan doğaüstü bir güç verir." },
    { f: "Günlük içsel netleşmede 'kalpteki çalışma' nedir?", b: "Bencil arzuları ihsan etme arzusundan ayırt etmek ve kişinin kendi doğasını dönüştürmesi için dua etmesidir." },
    { f: "Yaratan dua yoluyla neden değişmez?", b: "Çünkü Yaratan Mutlak İyidir ve Değişmezdir; dua alıcı kabı dönüştürerek onu Işığı almaya uygun hale getirir." },
    { f: "Geleneksel dini dua ile Kabalistik dua arasındaki fark nedir?", b: "Geleneksel dua maddi kazançlar veya ego için rahatlama dilerken, Kabalistik dua bencillikten kurtuluş için yalvarır." },
    { f: "Manevi yolda gerçek bir Hisaron nasıl doğar?", b: "Gruptaki ısrarlı çalışma ve kaynakların incelenmesi yoluyla; bu süreçte eksiklik, ihsan etme ışığının yokluğu olarak netleşir." },
    { f: "Bedenin 'Göklerin Krallığının boyunduruğunu kabul etmemesi' ne anlama gelir?", b: "Doğuştan gelen alma arzusu, kişisel çıkar olmaksızın sırf Yaratan'ı memnun etmek için çalışmaya içgüdüsel olarak direnir." },
    { f: "Tüm organlarının ihsan etmeye direndiğini gören insan ne yapmalıdır?", b: "Duadan başka çaresi yoktur: bedenini ihsan etmeye boyun eğdirmesi için kalbini Yaratan'a dökmelidir." },
    { f: "Lişma'ya ulaşmak kötü eğilimi nasıl ortadan kaldırır?", b: "Kişisel sevgiyi sıfırlar; alma kapları bencil işlevlerini kaybeder ve manevi anlamda 'ölü' sayılır." },
    { f: "Dua olmadan Lişma'ya ulaşılamayacağını bilmek neden hayati önem taşır?", b: "Çünkü bu bilinç duayı mutlak ve acil bir ihtiyaç haline getirir, rehaveti ve sahte özgüveni dağıtır." },
    { f: "MAN yükseltmek ile ruhun kabı arasındaki bağlantı nedir?", b: "MAN, Kli'nin eksikliğinin ta kendisidir; eksiklik ne kadar saf ve derinse, kap o kadar büyük bir Işık alabilir." },
    { f: "Dua hangi anlamda bencilliğin çaresizliğinin bir itirafıdır?", b: "Kalp mutlak bağımlılığını açığa vurur ve kendi egosunun ilahi yardım olmadan aşılamaz bir zindan olduğunu kabul eder." },
    { f: "Grup çalışması kişisel dua ile nasıl bütünleşir?", b: "Dostları sevme çabası, karşılıksız verme konusundaki tam yetersizliği ortaya çıkarır ve gerçek bir yardım çığlığı doğurur." },
    { f: "Dua neden manevi kabın bizzat yaratılması olarak kabul edilir?", b: "Çünkü doyum yalnızca karşılık gelen bir boşluğun olduğu yere girebilir; dua bu manevi vakumu genişletir." },
    { f: "'Yaratan duayı duyar' ifadesi ne anlama gelir?", b: "Talep, üst ihsan etme yasasıyla tam bir rezonansa girer ve Işık açılan Kli'yi anında doldurur." },
    { f: "Manevi umutsuzluğun duadaki rolü nedir?", b: "Egoist güçlerin tamamen tükendiğini gösterir ve bu durum doğrudan Yukarıdan gelen yardımın habercisidir." },
    { f: "'Yukarıdan uyanış' (İtaruta de-Leila) nedir?", b: "Aşağıdan yükselen olgun ve arınmış bir eksikliğe (MAN) doğrudan yanıt olarak inen Üst Işığın tecellisidir." },
    { f: "Şamati 20'de alma arzusu neden bir 'hırsıza' benzetilir?", b: "Çünkü her enerji ve sevinç kırıntısını yalnızca kendi bencil hazzı için çalmaya ve sahiplenmeye çalışır." },
    { f: "İnsan ihsan etmek için çalışırken başlangıçta neden hiç sevinç hissetmez?", b: "Alma arzusunun bundan tat almaması için; eğer bencilce zevk alsaydı, insan asla saf Lişma'ya yükselemezdi." },
    { f: "Manevi çalışma ne zaman kendi başına bir sevinç haline gelir?", b: "Kişi ihsan etmeye alıştığında ve Yaratan'a memnuniyet vermek emeğin kendi ödülü haline geldiğinde." },
    { f: "Manevi çalışmada şikayet ne zaman haklı veya haksızdır?", b: "Kişi sadece gerçekten çalıştığı efendiye şikayet edebilir; ego için çalışıp Yaratan'dan güç talep etme hakkı yoktur." },
    { f: "Duada içsel netleşme (Berur) nedir?", b: "Niyetlerin ayrıştırılması: Kendi egosu için yapılanlar ile Yaratan'ı hoşnut etmeye yönelik olanların ayırt edilmesidir." },
    { f: "Göklerin Krallığının boyunduruğunu almada 'tam kusursuzluk' nedir?", b: "Sadece ihsan etmeyi istemek ve kendi çıkarı için almaktan tamamen vazgeçmektir." },
    { f: "Entelektüel kavrayış kalbin duası için neden yetersizdir?", b: "Zihnin argümanları manevi kabı harekete geçiremez; Işığı yalnızca kalpte yaşanan gerçek bir eksiklik çeker." },
    { f: "MAN manevi dünyaların basamakları boyunca nasıl çalışır?", b: "Alt derece eksikliğini üst dereceye yükseltir, üst derece de bunu Kaynağa taşır ve cevabı aşağı indirir." },
    { f: "Dua neden alma arzusuna karşı tek silah olarak adlandırılır?", b: "İnsan kendi yaratılmış doğasını değiştiremez; yalnızca yeni bir ihsan etme doğası bahşetmesi için Yaratan'a yakarabilir." },
    { f: "Dua neden anlık bir eylem değil de sürekli bir süreçtir?", b: "Çabalar ve düşüşler zinciri, eksikliği mutlak bir samimiyete ulaşana kadar törpüler ve olgunlaştırır." },
    { f: "En karanlık durumlarda kurtuluşa olan inanç nasıl tezahür eder?", b: "Beden hiçbir çıkış yolu görmese bile, kalpteki nokta Yaratan'ın bir göz açıp kapayıncaya kadar kurtarabileceğinden emindir." },
    { f: "'Yaratan doğruların duasını arzular' sözü ne anlama gelir?", b: "Yaratan ihsan edebilecek hazır bir Kli'yi özler, çünkü sevgisinin doğası doyum vermek ve doldurmaktır." },
    { f: "Tövbe (Tşuva) ile Kabalistik dua arasındaki bağlantı nedir?", b: "Tövbe, bencil doğanın acı verici bir şekilde farkına varılmasıdır; dua ise ondan kurtulma talebidir." },
    { f: "Dua insanı manevi kibirden nasıl korur?", b: "Ulaşılan her manevi derecenin yalnızca hak edilmemiş bir lütuf ve Yukarıdan gelen bir merhamet olduğu bilincini yerleştirir." },
    { f: "Bir duanın cevapsız kalmış gibi görünmesinin sebebi nedir?", b: "Eksiklik henüz gerekli derinliğe veya saflığa ulaşmamıştır; kap henüz Işığı tutmaya hazır değildir." },
    { f: "'Kalbi Yaratan'ın önüne dökmek' ne anlama gelir?", b: "Tüm gizli arzuları, korkuları ve çaresizliği çekinmeden Yaratan'ın yönetimine teslim etmektir." },
    { f: "Dua kitabı (Siddur) Kabalist'in içsel çalışmasına nasıl yardımcı olur?", b: "Ulaşmış bilgeler tarafından yazılmış, içsel durumların ve ıslah süreçlerinin kesin bir manevi haritası olarak hizmet eder." },
    { f: "Lişma'ya geçiş neden mucize olarak kabul edilir?", b: "Çünkü yaratılan doğayı (öz sevgiyi) saf özgeciliğe dönüştürmek ancak Işığın dönüştürücü gücüyle mümkündür." },
    { f: "Dua Yaratan'la yaşayan bir diyaloğa nasıl dönüşür?", b: "Kalbin titreşimleri O'na yakınlaşma arzusunu tam olarak yansıttığında, doğrudan bir içsel diyalog açılır." },
    { f: "'İşi tamamlamak sana düşmez, ama ondan el çekmekte de özgür değilsin' ne anlama gelir?", b: "Hedef Yukarıdan verilse de, arzu ve eksikliği inşa etme emeği tamamen insanın sorumluluğundadır." },
    { f: "Dua ile dost sevgisi arasındaki bağlantı nedir?", b: "Dostlara ihsan etme çabasında bencilce sevmeme konusundaki tam yetersizlik açığa çıkar ve bu durum gerçek bir yardım çığlığı doğurur." },
    { f: "Duadan önceki içsel muhasebe niyeti nasıl arındırır?", b: "Gizli bencil saikleri ortaya çıkarır, sahte hedefleri eler ve feryadı tek bir hakikat noktasına odaklar." },
    { f: "Pasif bekleyiş ile manevi dua arasındaki fark nedir?", b: "Pasiflik savaşmadan teslim olur, oysa dua gücünün son sınırına kadar savaşan savaşçının nihai çığlığıdır." },
    { f: "Tora'nın Işığı duaya nasıl yansır?", b: "Çalışma sırasında çekilen Islah Eden Işık kalbin karanlığını aydınlatır ve ıslah için derin bir yakarış uyandırır." },
    { f: "Gerçek duanın 'derinliklerden seslenmesi' ne anlama gelir?", b: "Alma arzusunun en dibinden, egonun zindanının en karanlık uçurumundan kopup gelen bir çığlıktır." },
    { f: "Dua Yaratan'la Dvekut'a (bağlanmaya) nasıl götürür?", b: "İhsan etme niteliğini kazanarak insan Yaratan'la form eşitliğine ulaşır ve bu da nihai birliktir." },
    { f: "18. Dersin dua konusundaki en önemli pratik dersi nedir?", b: "Sözleri tekrarlamakla yetinme; kalbinde gerçek bir Hisaron inşa et, çünkü Yaratan yalnızca kalbin gerçeğini duyar." }
  ],
  el: [
    { f: "Ποιος είναι ο καμπαλιστικός ορισμός της προσευχής;", b: "Η 'εργασία στην καρδιά' (Αβοντά σεμπαΛέβ), μια βαθιά εσωτερική διευκρίνιση των επιθυμιών, των προθέσεων και των ελλείψεων ενώπιον του Δημιουργού." },
    { f: "Τι αντιπροσωπεύει η πνευματική 'καρδιά' στην Καμπαλά;", b: "Η καρδιά αντιπροσωπεύει το σύνολο όλων των επιθυμιών λήψης του ανθρώπου και όλων των συναισθηματικών και βουλητικών του τάσεων." },
    { f: "Πώς σχετίζονται τα λόγια του στόματος με την επιθυμία της καρδιάς;", b: "Ο Δημιουργός απαντά αποκλειστικά στην αληθινή έλλειψη (Χισαρόν) στα βάθη της καρδιάς, ποτέ στα μηχανικά λόγια των χειλιών." },
    { f: "Τι είναι η έννοια του 'Χισαρόν' στην προσευχή;", b: "Μια γνήσια εσωτερική ανεπάρκεια, το κενό του δοχείου (Κλι) που λαχταρά πνευματική πλήρωση και διόρθωση." },
    { f: "Γιατί η μηχανική επανάληψη λέξεων δεν θεωρείται αυθεντική προσευχή;", b: "Επειδή εάν η καρδιά δεν λαχταρά αυτό που προφέρουν τα χείλη, οι λέξεις παραμένουν νεκρές μορφές χωρίς πνευματική ζωτικότητα." },
    { f: "Ποια είναι η πρώτη προϋπόθεση για να εισακουστεί η προσευχή;", b: "Ακλόνητη πίστη ότι ο Δημιουργός είναι πράγματι ικανός να ελευθερώσει τον άνθρωπο από τη φυλακή του εγωισμού." },
    { f: "Ποια είναι η δεύτερη προϋπόθεση για να εισακουστεί η προσευχή;", b: "Η συνειδητοποίηση ότι δεν υπάρχει άλλη επιλογή: όλες οι ανθρώπινες δυνάμεις έχουν αποτύχει και μόνο ο Δημιουργός μπορεί να βοηθήσει." },
    { f: "Ποια είναι η τρίτη προϋπόθεση για να εισακουστεί η προσευχή;", b: "Το αίτημα να είναι πράγματι ζήτημα ζωής και θανάτου, χωρίς το οποίο η ψυχή χάνεται μέσα στην επιθυμία λήψης." },
    { f: "Πώς λειτουργεί η προσευχή ως 'μέσο' στην πνευματική εξέλιξη;", b: "Δεν αποσκοπεί στην αλλαγή του Δημιουργού, αλλά μεταμορφώνει τον άνθρωπο, προετοιμάζοντας το Κλι να δεχθεί το φως της προσφοράς." },
    { f: "Τι ζητά ο καμπαλιστής στην αληθινή προσευχή ως μέσο;", b: "Αποκλειστικά την έλλειψη για προσφορά (την επιθυμία να προσφέρει) και την εξίσωση μορφής με τον Δημιουργό." },
    { f: "Ποιο είναι το κεντρικό μήνυμα του άρθρου 20 του Σαμάτι σχετικά με την επίτευξη του Λισμά;", b: "Το Λισμά (για το Όνομά Της / ανιδιοτελής προσφορά) είναι ένα δώρο και ένας φωτισμός από Πάνω που το ανθρώπινο μυαλό δεν μπορεί να κατακτήσει μόνο του." },
    { f: "Εάν το Λισμά είναι δώρο από Πάνω, γιατί είναι απαραίτητη η ανθρώπινη προσπάθεια;", b: "Επειδή οι προσπάθειες και τα μέσα οικοδομούν στον άνθρωπο τα διορθωμένα δοχεία (Κελήμ) που επιθυμούν ειλικρινά να λάβουν το Λισμά." },
    { f: "Ποιος είναι ο ρόλος της αποτυχίας και της αδυναμίας στην προσευχή κατά το Σαμάτι 20;", b: "Όταν ο άνθρωπος διαπιστώνει ότι όλες οι πράξεις του απέβησαν μάταιες, φτάνει σε απόλυτη αδυναμία και μόνο τότε μπορεί να προσευχηθεί από τα βάθη της καρδιάς του." },
    { f: "Πότε είναι ο άνθρωπος ικανός για μια ειλικρινή προσευχή από τα βάθη της καρδιάς του;", b: "Μόνο αφού εξαντλήσει όλα τα ανθρώπινα μέσα και αναγνωρίσει ότι από μόνος του δεν μπορεί να πετύχει τίποτα χωρίς τον Δημιουργό." },
    { f: "Τι σημαίνει η έννοια 'ΜΑΝ' (Μαγίν Νουκβίν);", b: "Θηλυκά ύδατα· η έλλειψη, η προσευχή και το ξύπνημα που αναδύονται από το κατώτερο δοχείο και έλκουν αφθονία και Φως από Πάνω." },
    { f: "Ποιος είναι ο ρόλος του 'ξυπνήματος από κάτω' στο πνευματικό σύστημα;", b: "Το ξύπνημα από κάτω (η προσευχή του δημιουργήματος) ενεργοποιεί τη ροή των Ανώτερων Φώτων (ΜΑΔ – Μαγίν Ντεχρίν)." },
    { f: "Τι σημαίνει η αρχή 'Αυτός που έρχεται να εξαγνιστεί βοηθείται';", b: "Σε όποιον ειλικρινά επιδιώκει την προσφορά και την καθαρότητα, ο Δημιουργός δίνει από Πάνω δύναμη, διόρθωση και ανύψωση πάνω από τη φύση του." },
    { f: "Πώς ακριβώς βοηθά ο Δημιουργός αυτόν που έρχεται να εξαγνιστεί;", b: "Του χαρίζει την κατάσταση Λισμά, αφυπνίζει την καρδιά του και του δίνει μια υπερφυσική δύναμη που υπερβαίνει τον εγωισμό του." },
    { f: "Τι είναι η 'εργασία στην καρδιά' κατά την καθημερινή εσωτερική διευκρίνιση;", b: "Η διάκριση ανάμεσα στις εγωιστικές επιθυμίες και την επιθυμία για προσφορά, με συνεχή προσευχή για τη μεταμόρφωση της φύσης κάποιου." },
    { f: "Γιατί ο Δημιουργός δεν αλλάζει μέσω της προσευχής;", b: "Επειδή ο Δημιουργός είναι το Απόλυτο Αγαθό και Αμετάβλητος· η προσευχή αλλάζει το δοχείο υποδοχής κάνοντάς το ικανό να κρατήσει το Φως." },
    { f: "Ποια είναι η διαφορά μεταξύ της συμβατικής θρησκευτικής και της καμπαλιστικής προσευχής;", b: "Η συνήθης προσευχή ζητά υλικά αγαθά ή ανακούφιση για το εγώ, ενώ η καμπαλιστική προσευχή ικετεύει για λύτρωση από τον εγωισμό." },
    { f: "Πώς γεννιέται ένα αυθεντικό Χισαρόν στο πνευματικό μονοπάτι;", b: "Μέσα από επίμονη εργασία στην ομάδα και μελέτη των πηγών, διευκρινίζοντας την έλλειψη ως απουσία του φωτός της προσφοράς." },
    { f: "Τι σημαίνει ότι το σώμα 'δεν συμφωνεί με τον ζυγό της Βασιλείας των Ουρανών';", b: "Η έμφυτη επιθυμία λήψης αντιστέκεται ενστικτωδώς στην εργασία αποκλειστικά για την ευχαρίστηση του Δημιουργού χωρίς προσωπική ανταμοιβή." },
    { f: "Τι πρέπει να κάνει ο άνθρωπος όταν βλέπει ότι όλα τα μέλη του αντιστέκονται στην προσφορά;", b: "Δεν έχει άλλη επιλογή παρά την προσευχή: να ξεχειλίσει την καρδιά του μπροστά στον Δημιουργό για να υποτάξει το σώμα στην προσφορά." },
    { f: "Πώς η επίτευξη του Λισμά θανατώνει την κακή κλίση;", b: "Εκμηδενίζει τη φιλαυτία· τα δοχεία λήψης χάνουν την εγωιστική τους λειτουργία και θεωρούνται πνευματικά 'νεκρά'." },
    { f: "Γιατί είναι ζωτικής σημασίας να γνωρίζει κανείς ότι χωρίς προσευχή είναι αδύνατο να φτάσει στο Λισμά;", b: "Επειδή αυτή η γνώση καθιστά την προσευχή απόλυτη και επείγουσα ανάγκη, διαλύοντας την ψευδαίσθηση της αυτάρκειας." },
    { f: "Ποια είναι η σύνδεση ανάμεσα στην ανύψωση του ΜΑΝ και το δοχείο της ψυχής;", b: "Το ΜΑΝ είναι η ίδια η έλλειψη του Κλι· όσο πιο καθαρή και βαθιά είναι η έλλειψη, τόσο μεγαλύτερο Φως μπορεί να δεχθεί το δοχείο." },
    { f: "Με ποια έννοια η προσευχή είναι ομολογία της αδυναμίας του εγωισμού;", b: "Η καρδιά αποκαλύπτει την απόλυτη εξάρτησή της, αναγνωρίζοντας ότι το εγώ είναι μια φυλακή από την οποία δεν μπορεί να δραπετεύσει χωρίς τον Δημιουργό." },
    { f: "Πώς συνδέεται η ομαδική εργασία με την προσωπική προσευχή;", b: "Η προσπάθεια να αγαπήσει κανείς τους φίλους αποκαλύπτει την πλήρη ανικανότητα για ανιδιοτέλεια, γεννώντας μια πραγματική κραυγή για βοήθεια." },
    { f: "Γιατί η προσευχή θεωρείται η ίδια η δημιουργία του πνευματικού δοχείου;", b: "Επειδή η πλήρωση μπορεί να εισέλθει μόνο εκεί όπου υπάρχει αντίστοιχο κενό· η προσευχή ορίζει και διευρύνει αυτό το πνευματικό κενό." },
    { f: "Τι σημαίνει η φράση 'ο Δημιουργός ακούει την προσευχή';", b: "Το αίτημα εισέρχεται σε τέλειο συντονισμό με τον ανώτερο νόμο της προσφοράς και το Φως γεμίζει αμέσως το ανοιχτό Κλι." },
    { f: "Ποιον ρόλο παίζει η πνευματική απόγνωση στη γέννηση της προσευχής;", b: "Σηματοδοτεί την πλήρη εξάντληση των εγωιστικών δυνάμεων, προηγούμενη άμεσα από την κάθοδο της βοήθειας από Πάνω." },
    { f: "Τι είναι το 'ξύπνημα από Πάνω' (Ιταρούτα ντε-Λέιλα);", b: "Η εκδήλωση του Ανώτερου Φωτός που κατέρχεται ως άμεση απάντηση σε μια ώριμη και εξαγνισμένη έλλειψη από κάτω (ΜΑΝ)." },
    { f: "Γιατί η επιθυμία λήψης παρομοιάζεται με 'κλέφτη' στο Σαμάτι 20;", b: "Επειδή προσπαθεί να κλέψει και να οικειοποιηθεί κάθε ίχνος ενέργειας και χαράς αποκλειστικά για τη δική της εγωιστική απόλαυση." },
    { f: "Γιατί αρχικά ο άνθρωπος δεν αισθάνεται καμία χαρά στην εργασία για προσφορά;", b: "Για να μην νιώσει γεύση η επιθυμία λήψης· αν ένιωθε απόλαυση, ο άνθρωπος δεν θα ανέβαινε ποτέ στο αγνό Λισμά." },
    { f: "Πότε η πνευματική εργασία γίνεται χαρά από μόνη της;", b: "Όταν ο άνθρωπος συνηθίσει στην προσφορά, και το να δίνει χαρά στον Δημιουργό γίνεται η ίδια η ανταμοιβή του κόπου του." },
    { f: "Πότε είναι δικαιολογημένο ή αδικαιολόγητο ένα παράπονο στην πνευματική εργασία;", b: "Μπορεί κανείς να παραπονεθεί μόνο στον κύριο για τον οποίο πραγματικά εργάζεται· δουλεύοντας για το εγώ, δεν έχει δικαίωμα να απαιτεί δυνάμεις από τον Δημιουργό." },
    { f: "Τι είναι η εσωτερική διευκρίνιση (Μπερούρ) στην προσευχή;", b: "Ο διαχωρισμός των προθέσεων: να διακρίνει κανείς τι γίνεται για το δικό του εγώ από αυτό που αποσκοπεί στην ευχαρίστηση του Δημιουργού." },
    { f: "Τι είναι η 'πλήρης τελειότητα' στην αποδοχή του ζυγού της Βασιλείας των Ουρανών;", b: "Το να επιθυμεί κανείς αποκλειστικά να προσφέρει και να παραιτηθεί εντελώς από τη λήψη για ίδιον όφελος." },
    { f: "Γιατί η διανοητική κατανόηση δεν επαρκεί για την προσευχή της καρδιάς;", b: "Τα επιχειρήματα του νου δεν κινούν το πνευματικό δοχείο· μόνο μια πραγματική έλλειψη που βιώνεται στην καρδιά προσελκύει το Φως." },
    { f: "Πώς λειτουργεί το ΜΑΝ μέσα από τους βαθμούς των πνευματικών κόσμων;", b: "Ο κατώτερος βαθμός ανυψώνει την έλλειψή του στον ανώτερο, και αυτός την υψώνει στην Πηγή, κατεβάζοντας την απάντηση κάτω." },
    { f: "Γιατί η προσευχή ονομάζεται το μόνο όπλο ενάντια στην επιθυμία λήψης;", b: "Ο άνθρωπος δεν μπορεί να αλλάξει τη δημιουργημένη φύση του· μπορεί μόνο να κραυγάσει στον Δημιουργό για να του δώσει μια νέα φύση προσφοράς." },
    { f: "Γιατί η προσευχή είναι μια συνεχής διαδικασία και όχι μια στιγμιαία πράξη;", b: "Μια σειρά από προσπάθειες και πτώσεις λειαίνει και ωριμάζει την εσωτερική έλλειψη μέχρι να φτάσει σε απόλυτη ειλικρίνεια." },
    { f: "Πώς εκδηλώνεται η πίστη στη λύτρωση στις πιο σκοτεινές καταστάσεις;", b: "Ακόμη και όταν το σώμα δεν βλέπει καμία διέξοδο, το σημείο στην καρδιά είναι βέβαιο ότι ο Δημιουργός μπορεί να σώσει σε μια στιγμή." },
    { f: "Τι σημαίνει ότι 'ο Δημιουργός λαχταρά την προσευχή των δικαίων';", b: "Ο Δημιουργός περιμένει ένα προετοιμασμένο Κλι ικανό να προσφέρει, καθώς η φύση της αγάπης Του είναι να δίνει πλήρωση." },
    { f: "Ποια είναι η σχέση ανάμεσα στη μετάνοια (Τσουβά) και την καμπαλιστική προσευχή;", b: "Η μετάνοια είναι η οδυνηρή συνειδητοποίηση της εγωιστικής φύσης, και η προσευχή είναι η έκκληση για απελευθέρωση από αυτήν." },
    { f: "Πώς προστατεύει η προσευχή τον άνθρωπο από την πνευματική υπερηφάνεια;", b: "Εδραιώνει τη συνείδηση ότι κάθε πνευματικό επίτευγμα είναι αποκλειστικά ένα αναπάντεχο δώρο και έλεος από Πάνω." },
    { f: "Γιατί φαίνεται μερικές φορές ότι μια προσευχή μένει αναπάντητη;", b: "Η έλλειψη δεν έχει φτάσει ακόμη στο απαιτούμενο βάθος ή καθαρότητα· το δοχείο δεν είναι ακόμη έτοιμο να συγκρατήσει το Φως." },
    { f: "Τι σημαίνει 'να ξεχειλίζεις την καρδιά σου μπροστά στον Δημιουργό';", b: "Η άνευ όρων παράδοση όλων των κρυφών επιθυμιών, των φόβων και της αδυναμίας υπό την καθοδήγηση του Δημιουργού." },
    { f: "Πώς βοηθά το προσευχητάρι (Σιντούρ) την εσωτερική εργασία του καμπαλιστή;", b: "Χρησιμεύει ως ακριβής πνευματικός χάρτης εσωτερικών καταστάσεων και διαδικασιών διόρθωσης σχεδιασμένος από σοφούς." },
    { f: "Γιατί η μετάβαση στο Λισμά θεωρείται ύψιστο θαύμα;", b: "Επειδή η ανατροπή της δημιουργημένης φύσης (φιλαυτία) σε αγνό αλτρουισμό είναι δυνατή μόνο μέσω της μεταμορφωτικής δύναμης του Φωτός." },
    { f: "Πώς η προσευχή μετατρέπεται σε ζωντανό διάλογο με τον Δημιουργό;", b: "Όταν οι παλμοί της καρδιάς αντικατοπτρίζουν με ακρίβεια τη λαχτάρα για προσκόλληση σε Αυτόν, ανοίγει μια άμεση εσωτερική επικοινωνία." },
    { f: "Τι σημαίνει το ρητό 'Δεν είσαι υποχρεωμένος να ολοκληρώσεις το έργο, αλλά δεν είσαι ελεύθερος να το εγκαταλείψεις';", b: "Αν και ο στόχος είναι δώρο από Πάνω, ο μόχθος για την οικοδόμηση της επιθυμίας και της έλλειψης βαρύνει εξ ολοκλήρου τον άνθρωπο." },
    { f: "Ποια είναι η σχέση ανάμεσα στην προσευχή και την αγάπη των φίλων;", b: "Στην προσπάθεια να προσφέρει κανείς στους φίλους αποκαλύπτεται η πλήρης ανικανότητα για αγνή αγάπη, γεννώντας μια αυθεντική κραυγή για βοήθεια." },
    { f: "Πώς ο εσωτερικός απολογισμός πριν από την προσευχή καθαρίζει την πρόθεση;", b: "Ξεσκεπάζει τα κρυφά εγωιστικά κίνητρα, εξαλείφει τους ψευδείς στόχους και εστιάζει την κραυγή σε ένα μόνο σημείο αλήθειας." },
    { f: "Ποια είναι η διαφορά μεταξύ της παθητικής αναμονής και της πνευματικής προσευχής;", b: "Η παθητικότητα παραδίνεται αμαχητί, ενώ η προσευχή είναι η έσχατη κραυγή του πολεμιστή που παλεύει μέχρι το απώτατο όριο των δυνάμεών του." },
    { f: "Πώς αντικατοπτρίζεται το Φως της Τορά στην προσευχή;", b: "Το Μεταμορφωτικό Φως που έλκεται κατά τη μελέτη φωτίζει το σκοτάδι της καρδιάς, ξυπνώντας μια βαθιά παράκληση για διόρθωση." },
    { f: "Τι σημαίνει ότι η αληθινή προσευχή 'κραυγάζει από τα βάθη';", b: "Μια κραυγή που ξεσπά από τον πάτο της επιθυμίας λήψης, από τη σκοτεινότερη άβυσσο της φυλακής του εγώ." },
    { f: "Πώς οδηγεί η προσευχή στο Ντβεκούτ (προσκόλληση) με τον Δημιουργό;", b: "Αποκτώντας την ιδιότητα της προσφοράς, ο άνθρωπος επιτυγχάνει εξίσωση μορφής με τον Δημιουργό, επισφραγίζοντας την απόλυτη ενότητα." },
    { f: "Ποιο είναι το πιο σημαντικό πρακτικό δίδαγμα του Μαθήματος 18 για την προσευχή;", b: "Μην αρκείσαι στην επανάληψη λέξεων· χτίσε ένα πραγματικό Χισαρόν στην καρδιά σου, γιατί ο Δημιουργός ακούει μόνο την αλήθεια της καρδιάς." }
  ],
  nl: [
    { f: "Wat is de kabbalistische definitie van gebed?", b: "Het 'werk in het hart' (Avoda shebaLev), een diepgaande innerlijke verduidelijking van verlangens, intenties en tekorten voor het aangezicht van de Schepper." },
    { f: "Wat vertegenwoordigt het spirituele 'hart' in de Kabbala?", b: "Het hart staat voor de som van alle verlangens om te ontvangen en de totaliteit van iemands emotionele en wilsmatige neigingen." },
    { f: "Hoe verhouden de woorden van de mond zich tot het verlangen van het hart?", b: "De Schepper antwoordt uitsluitend op het ware tekort (Chissaron) in de diepten van het hart, nooit op mechanische woorden van de lippen." },
    { f: "Wat behelst het concept 'Chissaron' in het gebed?", b: "Een oprecht innerlijk gebrek, de leegte van het vat (Kli) dat vurig smacht naar vervulling en spirituele correctie." },
    { f: "Waarom geldt het louter mechanisch herhalen van woorden niet als een echt gebed?", b: "Omdat wanneer het hart niet verlangt naar wat de lippen uitspreken, de woorden levenloze vormen blijven zonder spirituele levenskracht." },
    { f: "Wat is de eerste voorwaarde voor het verhoren van het gebed?", b: "Rotsvast geloof dat de Schepper werkelijk in staat is de mens te verlossen uit de kerker van het egoïsme." },
    { f: "Wat is de tweede voorwaarde voor het verhoren van het gebed?", b: "Het besef dat er geen andere uitweg is: alle menselijke krachten hebben gefaald en alleen de Schepper kan helpen." },
    { f: "Wat is de derde voorwaarde voor het verhoren van het gebed?", b: "Dat het verzoek waarlijk een kwestie van leven en dood is, zonder welks vervulling de ziel omkomt in het verlangen om te ontvangen." },
    { f: "Hoe fungeert het gebed als een 'medium' in de spirituele evolutie?", b: "Het tracht niet de Schepper te veranderen, maar transformeert de mens en bereidt het Kli voor op het ontvangen van het licht van schenking." },
    { f: "Wat vraagt de kabbalist in het ware gebed als medium?", b: "Uitsluitend het tekort aan schenking (het verlangen om te schenken) en vormgelijkheid met de Schepper." },
    { f: "Wat is de kernboodschap van Shamati artikel 20 over het bereiken van Lishma?", b: "Lishma (omwille van Haar Naam / onbaatzuchtig schenken) is een geschenk en een verlichting van Boven die het menselijk verstand op eigen kracht niet kan bevatten." },
    { f: "Als Lishma een geschenk van Boven is, waarom is menselijke inspanning dan nodig?", b: "Omdat inspanningen en middelen in de mens de gecorrigeerde vaten (Kelim) opbouwen die oprecht verlangen naar Lishma." },
    { f: "Welke rol spelen mislukking en onmacht in het gebed volgens Shamati 20?", b: "Wanneer de mens de vergeefsheid van al zijn handelingen inziet, raakt hij in totale hulpeloosheid en kan pas dan uit het diepst van zijn hart bidden." },
    { f: "Wanneer is een mens in staat een oprecht gebed vanuit de grond van zijn hart op te zenden?", b: "Pas nadat hij alle menselijke middelen heeft uitgeput en erkent dat hij uit eigen kracht niets kan bereiken zonder de Schepper." },
    { f: "Wat betekent het concept 'MAN' (Mayin Nukvin)?", b: "Vrouwelijke wateren; het tekort, het gebed en het ontwaken die opstijgen uit het lagere vat en overvloed en Licht van Boven aantrekken." },
    { f: "Wat is de rol van het 'ontwaken van beneden' in het spirituele systeem?", b: "Het ontwaken van beneden (het gebed van het geschapene) zet de stroom van de Hogere Lichten (MAD - Mayin Dehrin) in gang." },
    { f: "Wat betekent het principe 'Wie komt om zich te reinigen, wordt geholpen'?", b: "Wie oprecht streeft naar schenking en zuiverheid, ontvangt van Boven kracht, correctie en verheffing boven zijn egoïstische natuur." },
    { f: "Hoe helpt de Schepper degene die komt om zich te reinigen?", b: "Door hem de staat van Lishma te schenken, zijn hart te wekken en hem bovennatuurlijke kracht te geven die zijn aard overstijgt." },
    { f: "Wat houdt het 'werk in het hart' in tijdens de dagelijkse innerlijke verduidelijking?", b: "Het onderscheiden van egoïstische verlangens van het verlangen om te schenken, met aanhoudend gebed om transformatie van de eigen natuur." },
    { f: "Waarom verandert de Schepper niet door het gebed?", b: "Omdat de Schepper het Absolute Goede en Onveranderlijke is; het gebed verandert het ontvangende vat zodat het geschikt wordt voor het Licht." },
    { f: "Wat is het verschil tussen het conventionele en het kabbalistische gebed?", b: "Het gewone gebed vraagt om materiële goederen of verlichting voor het ego, terwijl het kabbalistische gebed smeekt om verlossing uit het egoïsme." },
    { f: "Hoe ontstaat een authentieke Chissaron op het spirituele pad?", b: "Door volhardend werk in de groep en studie van de bronnen, waardoor het tekort verhelderd wordt als de afwezigheid van het licht van schenking." },
    { f: "Wat betekent het dat het lichaam 'niet instemt met het juk van het Koninkrijk der Hemelen'?", b: "Het aangeboren verlangen om te ontvangen verzet zich instinctief tegen arbeid die puur voor het welbehagen van de Schepper is zonder eigenbelang." },
    { f: "Wat moet iemand doen als hij ziet dat al zijn geledingen zich verzetten tegen schenking?", b: "Hij heeft geen andere uitweg dan het gebed: zijn hart uitstorten voor de Schepper om het lichaam te dwingen zich over te geven aan schenking." },
    { f: "Hoe doodt het bereiken van Lishma de kwade neiging?", b: "Het vernietigt de eigenliefde; de vaten van ontvangst verliezen hun zelfzuchtige functie en gelden spiritueel als 'dood'." },
    { f: "Waarom is het cruciaal te weten dat Lishma zonder gebed onbereikbaar is?", b: "Omdat dit inzicht het gebed tot een absolute en dringende noodzaak maakt, waarmee zelfgenoegzaamheid wordt verdreven." },
    { f: "Wat is het verband tussen het verheffen van MAN en het vat van de ziel?", b: "MAN is het tekort zelf van het Kli; hoe zuiverder en dieper dat gebrek is, des te groter het Licht is dat het vat kan bevatten." },
    { f: "In welke zin is het gebed een bekentenis van de onmacht van het ego?", b: "Het hart onthult zijn totale afhankelijkheid en erkent dat het eigen ego een ondoordringbare gevangenis is zonder goddelijke bijstand." },
    { f: "Hoe integreert groepswerk met het persoonlijke gebed?", b: "De poging om van de vrienden te houden legt het totale onvermogen tot belangeloze liefde bloot, wat een waarachtige noodkreet baart." },
    { f: "Waarom wordt het gebed beschouwd als het eigenlijke scheppen van het spirituele vat?", b: "Omdat vervulling alleen kan binnentreden waar een overeenkomstig tekort is; het gebed bakent dit spirituele vacuüm af en vergroot het." },
    { f: "Wat betekent het dat 'de Schepper het gebed hoort'?", b: "Het verzoek resoneert volmaakt met de hogere wet van schenking en het Licht vult ogenblikkelijk het geopende Kli." },
    { f: "Welke rol speelt spirituele wanhoop bij het ontstaan van het gebed?", b: "Het markeert de volkomen uitputting van egoïstische krachten, wat direct voorafgaat aan het neerdalen van hulp van Boven." },
    { f: "Wat is het 'ontwaken van Boven' (Itaruta de-Leila)?", b: "De openbaring van het Hogere Licht dat neerdaalt als direct antwoord op een gerijpt en gezuiverd tekort van beneden (MAN)." },
    { f: "Waarom wordt het verlangen om te ontvangen vergeleken met een 'dief' in Shamati 20?", b: "Omdat het ieder greintje energie en vreugde probeert te stelen en toe te eigenen voor puur zelfzuchtig genot." },
    { f: "Waarom voelt de mens aanvankelijk geen vreugde in de arbeid voor schenking?", b: "Opdat het verlangen om te ontvangen er geen smaak in vindt; vond het er eigenbelang in, dan zou de mens nooit opstijgen naar zuiver Lishma." },
    { f: "Wanneer wordt de spirituele arbeid een vreugde op zichzelf?", b: "Wanneer men gewend raakt aan schenken en vreugde schenken aan de Schepper de beloning van de inspanning zelve wordt." },
    { f: "Wanneer is klagen in de spirituele arbeid gerechtvaardigd of ongerechtvaardigd?", b: "Men kan alleen klagen bij de meester voor wie men daadwerkelijk werkt; wie voor het ego zwoegt, heeft geen recht kracht van de Schepper te eisen." },
    { f: "Wat behelst de innerlijke verduidelijking (Beroer) in het gebed?", b: "Het schiften van intenties: scheiden wat dient voor het eigen ego van wat waarlijk gericht is op vreugde voor de Schepper." },
    { f: "Wat is 'volledige volmaaktheid' bij het aanvaarden van het hemelse juk?", b: "Uitsluitend willen schenken en volkomen afzien van ontvangen voor eigen gewin." },
    { f: "Waarom volstaat intellectueel begrip niet voor het gebed van het hart?", b: "Verstandelijke argumenten bewegen het vat niet; alleen een werkelijk tekort dat in het hart wordt doorleefd, trekt het Licht aan." },
    { f: "Hoe werkt MAN door de treden van de spirituele werelden?", b: "De lagere trede verheft haar tekort naar de hogere, die het opvoert naar de Bron en het antwoord naar beneden brengt." },
    { f: "Waarom wordt het gebed het enige wapen tegen het verlangen om te ontvangen genoemd?", b: "De mens kan zijn geschapen aard niet zelf wijzigen; hij kan slechts tot de Schepper roepen om een nieuwe natuur van schenking te ontvangen." },
    { f: "Waarom is het gebed een continu proces en geen momentopname?", b: "Een aaneenschakeling van inspanningen en vallen polijst en rijpt het tekort totdat het absolute oprechtheid bereikt." },
    { f: "Hoe openbaart het geloof in verlossing zich in de donkerste toestanden?", b: "Zelfs wanneer het lichaam geen uitweg ziet, is het punt in het hart er zeker van dat de Schepper in een oogwenk kan redden." },
    { f: "Wat betekent het dat de Schepper 'smacht naar het gebed van de rechtvaardigen'?", b: "De Schepper wacht op een toebereid Kli dat in staat is tot schenking, want de aard van Zijn liefde is overvloed te geven." },
    { f: "Wat is het verband tussen inkeer (Tesjoewa) en het kabbalistische gebed?", b: "Inkeer is het smartelijke besef van de egoïstische natuur, en het gebed is de smeking om daaruit verlost te worden." },
    { f: "Hoe beschermt het gebed de mens tegen spirituele hoogmoed?", b: "Het verankert het besef dat elk behaald spiritueel niveau uitsluitend een onverdiend geschenk en genade van Boven is." },
    { f: "Waarom lijkt een gebed soms onbeantwoord te blijven?", b: "Het tekort heeft nog niet de vereiste diepte of zuiverheid bereikt; het vat is nog niet gereed om het Licht vast te houden." },
    { f: "Wat betekent 'het hart uitstorten voor de Schepper'?", b: "Het onvoorwaardelijk overgeven van alle verborgen verlangens, angsten en onmacht aan de leiding van de Schepper." },
    { f: "Hoe helpt het gebedenboek (Siddur) het innerlijke werk van de kabbalist?", b: "Het fungeert als een exacte spirituele landkaart van innerlijke staten en correctieprocessen, opgesteld door ingewijden." },
    { f: "Waarom geldt de overgang naar Lishma als een wonder?", b: "Omdat het omkeren van de geschapen natuur (eigenliefde) in zuiver altruïsme alleen mogelijk is door de transformerende kracht van het Licht." },
    { f: "Hoe verandert het gebed in een levende dialoog met de Schepper?", b: "Wanneer de bewegingen van het hart zuiver het verlangen weerspiegelen om aan Hem te hechten, opent zich een direct innerlijk gesprek." },
    { f: "Wat betekent het gezegde 'Het staat je niet vrij je aan de arbeid te onttrekken'?", b: "Hoewel het doel een geschenk van Boven is, rust het zware werk van het bouwen van het verlangen geheel op de mens." },
    { f: "Wat is het verband tussen gebed en liefde voor de vrienden?", b: "In de poging aan vrienden te schenken wordt het onvermogen tot liefhebben zichtbaar, wat een authentieke noodkreet baart." },
    { f: "Hoe zuivert zelfonderzoek vóór het gebed de intentie?", b: "Het ontmaskert verborgen egoïstische motieven, snoeit valse doelen weg en focust de roep op één enkel punt van waarheid." },
    { f: "Wat is het verschil tussen passief wachten en spiritueel gebed?", b: "Passiviteit geeft de strijd zonder slag of stoot op, terwijl het gebed de uiterste noodkreet is van een strijder die vecht tot de grens van zijn krachten." },
    { f: "Hoe weerspiegelt het Licht van de Tora zich in het gebed?", b: "Het Hervormende Licht dat bij de studie wordt aangetrokken verlicht de duisternis van het hart en wekt een diep smeken om correctie." },
    { f: "Wat betekent het dat een waarachtig gebed 'uit de diepten roept'?", b: "Een kreet die opwelt uit de bodem van het verlangen om te ontvangen, uit de donkerste afgrond van de kerker van het ego." },
    { f: "Hoe leidt het gebed tot Dwekoet (aanhechting) met de Schepper?", b: "Door de eigenschap van schenking te verwerven bereikt de mens vormgelijkheid met de Schepper, wat volkomen eenheid is." },
    { f: "Wat is de belangrijkste praktische les van Les 18 over gebed?", b: "Neem geen genoegen met het herhalen van woorden; bouw een waar tekort in je hart, want de Schepper luistert alleen naar de waarheid van het hart." }
  ],
  da: [
    { f: "Hvad er den kabbalistiske definition på bøn?", b: "'Arbejdet i hjertet' (Avoda shebaLev), en dyb indre afklaring af ønsker, intentioner og mangler foran Skaberen." },
    { f: "Hvad repræsenterer det spirituelle 'hjerte' i Kabbala?", b: "Hjertet repræsenterer summen af alle menneskets ønsker om at modtage og helheden af dets følelsesmæssige og viljesmæssige tilbøjeligheder." },
    { f: "Hvordan forholder mundens ord sig til hjertets ønske?", b: "Skaberen svarer udelukkende på den sande mangel (Chissaron) i hjertets dyb, aldrig på læbernes mekaniske ord." },
    { f: "Hvad indebærer begrebet 'Chissaron' i bønnen?", b: "En ægte indre mangel, tomheden i karret (Kli), der længes inderligt efter opfyldelse og spirituel korrektion." },
    { f: "Hvorfor regnes mekanisk gentagelse af ord ikke for sand bøn?", b: "Fordi hvis hjertet ikke længes efter det, læberne udtaler, forbliver ordene livløse former uden spirituel kraft." },
    { f: "Hvad er den første betingelse for, at bønnen bliver hørt?", b: "Klippefast tro på, at Skaberen virkelig er i stand til at udfri mennesket fra egoismens fængsel." },
    { f: "Hvad er den anden betingelse for, at bønnen bliver hørt?", b: "Erkendelsen af, at der ikke er andet valg: alle menneskelige kræfter har fejlet, og kun Skaberen kan hjælpe." },
    { f: "Hvad er den tredje betingelse for, at bønnen bliver hørt?", b: "At bønnen vitterlig er et spørgsmål om liv og død, uden hvis løsning sjælen fortabes i ønsket om at modtage." },
    { f: "Hvordan fungerer bønnen som et 'medium' i den spirituelle udvikling?", b: "Den søger ikke at ændre Skaberen, men forvandler mennesket og forbereder Kli'et til at modtage overgivelsernes lys." },
    { f: "Hvad beder kabbalisten om i den sande bøn som medium?", b: "Udelukkende om manglen på at give (ønsket om at give) og om formlighed med Skaberen." },
    { f: "Hvad er hovedbudskabet i Shamati artikel 20 om at nå Lishma?", b: "Lishma (for Hendes Navns skyld / uselvisk hengivenhed) er en gave og en belysning fra Oven, som det menneskelige sind ikke kan opnå alene." },
    { f: "Når Lishma er en gave fra Oven, hvorfor er menneskelig anstrengelse så nødvendig?", b: "Fordi anstrengelser og midler opbygger de korrigerede kar (Kelim) i mennesket, som oprigtigt ønsker at modtage Lishma." },
    { f: "Hvilken rolle spiller fiasko og afmagt i bønnen ifølge Shamati 20?", b: "Når mennesket ser forgævesheden i alle sine handlinger, når det en total afmagt, og først da kan det råbe fra bunden af sit hjerte." },
    { f: "Hvornår er et menneske i stand til at bede en oprigtig bøn fra hjertets dyb?", b: "Først efter at have udtømt alle menneskelige midler og erkendt, at det intet formår af sig selv uden Skaberen." },
    { f: "Hvad betyder begrebet 'MAN' (Mayin Nukvin)?", b: "Kvindelige vande; manglen, bønnen og opvågningen, der stiger op fra det nedre kar og tiltrækker overflod og Lys fra Oven." },
    { f: "Hvad er rollen for 'opvågningen nedefra' i det spirituelle system?", b: "Opvågningen nedefra (skabningens bøn) igangsætter strømmen af de Øvre Lys (MAD - Mayin Dehrin)." },
    { f: "Hvad betyder princippet 'Den, der kommer for at rense sig, hjælpes'?", b: "Den, der oprigtigt stræber mod hengivenhed og renhed, skænker Skaberen styrke, korrektion og opløftelse over sin natur fra Oven." },
    { f: "Hvordan hjælper Skaberen den, der kommer for at rense sig?", b: "Ved at skænke ham tilstanden Lishma, vække hans hjerte og give ham overnaturlig styrke over hans egoistiske natur." },
    { f: "Hvad er 'arbejdet i hjertet' under den daglige indre afklaring?", b: "At skelne egoistiske ønsker fra ønsket om at give, med uophørlig bøn om forvandling af egen natur." },
    { f: "Hvorfor ændres Skaberen ikke gennem bøn?", b: "Fordi Skaberen er det Absolut Gode og Uforanderlige; bønnen forandrer modtagerkarret, så det bliver egnet til Lyset." },
    { f: "Hvad er forskellen på konventionel og kabbalistisk bøn?", b: "Den almindelige bøn beder om materielle goder eller lindring for egoet, mens den kabbalistiske bøn bønfalder om frelse fra egoismen." },
    { f: "Hvordan fødes en sand Chissaron på den spirituelle vej?", b: "Gennem vedholdende arbejde i gruppen og studiet af kilderne, hvor manglen afklares som fraværet af overgivelsens lys." },
    { f: "Hvad betyder det, at kroppen 'ikke er enig med Himmerigets åg'?", b: "Det medfødte ønske om at modtage modsætter sig instinktivt at arbejde udelukkende til Skaberens behag uden personlig vinding." },
    { f: "Hvad skal man gøre, når man ser, at alle kroppens organer modarbejder hengivenhed?", b: "Man har ingen anden udvej end bøn: at udgyde sit hjerte for Skaberen, så Han tvinger kroppen til at give efter for hengivenhed." },
    { f: "Hvordan tilintetgør opnåelsen af Lishma den onde tilbøjelighed?", b: "Den udsletter egenkærligheden; modtagekarrene mister deres selviske funktion og betragtes spirituelt som 'døde'." },
    { f: "Hvorfor er det afgørende at vide, at Lishma er uopnåelig uden bøn?", b: "Fordi denne bevidsthed gør bønnen til en absolut og uopsættelig nødvendighed og spreder enhver illusion om selvtilstrækkelighed." },
    { f: "Hvad er forbindelsen mellem at hæve MAN og sjælens kar?", b: "MAN er selve manglen i Kli'et; jo renere og dybere manglen er, desto større Lys kan karret rumme." },
    { f: "I hvilken forstand er bønnen en tilståelse af egoismens magtesløshed?", b: "Hjertet afslører sin totale afhængighed og erkender, at dets eget ego er et uindtageligt fængsel uden guddommelig hjælp." },
    { f: "Hvordan forener gruppearbejdet sig med den personlige bøn?", b: "Bestræbelsen på at elske vennerne blotlægger den totale mangel på evne til at give, hvilket afføder et sandt råb om hjælp." },
    { f: "Hvorfor betragtes bønnen som selve skabelsen af det spirituelle kar?", b: "Fordi opfyldelse kun kan indtræde, hvor der findes et tilsvarende tomrum; bønnen afgrænser og udvider dette spirituelle vakuum." },
    { f: "Hvad vil det sige, at 'Skaberen hører bønnen'?", b: "Bønnen kommer i fuldkommen resonans med den øvre lov om hengivenhed, og Lyset fylder øjeblikkeligt det åbnede Kli." },
    { f: "Hvilken rolle spiller spirituel fortvivlelse ved bønnens fødsel?", b: "Den markerer den totale udmattelse af egoistiske kræfter, hvilket umiddelbart går forud for hjælpens indtrængen fra Oven." },
    { f: "Hvad er 'opvågningen fra Oven' (Itaruta de-Leila)?", b: "Åbenbaringen af det Øvre Lys, der strømmer ned som et direkte svar på en moden og renset mangel nedefra (MAN)." },
    { f: "Hvorfor sammenlignes ønsket om at modtage med en 'tyv' i Shamati 20?", b: "Fordi det forsøger at stjæle og tilrane sig enhver gnist af energi og glæde udelukkende til sin egen selviske nydelse." },
    { f: "Hvorfor mærker mennesket i begyndelsen ingen glæde ved at arbejde for at give?", b: "For at ønsket om at modtage ikke skal finde smag deri; fandt det nydelse, ville mennesket aldrig hæve sig til ren Lishma." },
    { f: "Hvornår bliver det spirituelle arbejde en glæde i sig selv?", b: "Når man vænner sig til at give, og det at glæde Skaberen bliver selve belønningen for anstrengelsen." },
    { f: "Hvornår er utilfredshed i det spirituelle arbejde berettiget eller uberettiget?", b: "Man kan kun klage til den herre, man rent faktisk arbejder for; arbejder man for egoet, har man ingen ret til at kræve kræfter af Skaberen." },
    { f: "Hvad indebærer den indre afklaring (Berur) i bønnen?", b: "Sondering af hensigter: at adskille det, der tjener ens eget ego, fra det, der sigter mod at glæde Skaberen." },
    { f: "Hvad er 'fuldkommen fuldstændighed' ved påtagelsen af Himmerigets åg?", b: "Udelukkende at ville give og fuldstændigt give afkald på modtagelse til egen fordel." },
    { f: "Hvorfor er intellektuel forståelse utilstrækkelig for hjertets bøn?", b: "Sindets ræsonnementer bevæger ikke det spirituelle kar; kun en virkelig mangel oplevet i hjertet tiltrækker Lyset." },
    { f: "Hvordan virker MAN gennem de spirituelle verdners trin?", b: "Det lavere trin hæver sin mangel til det højere, som bringer det op til Kilden og trækker svaret ned." },
    { f: "Hvorfor kaldes bønnen for det eneste våben mod ønsket om at modtage?", b: "Mennesket kan ikke selv ændre sin skabte natur; det kan kun råbe til Skaberen om at modtage en ny natur af hengivenhed." },
    { f: "Hvorfor er bønnen en kontinuerlig proces og ikke en isoleret handling?", b: "En kæde af anstrengelser og fald sliber og modner den indre mangel, indtil den opnår absolut oprigtighed." },
    { f: "Hvordan viser troen på frelse sig i de mørkeste tilstande?", b: "Selv når kroppen ikke øjner nogen udvej, er punktet i hjertet forvisset om, at Skaberen kan frelse på et splitsekund." },
    { f: "Hvad vil det sige, at 'Skaberen længes efter de retfærdiges bøn'?", b: "Skaberen venter på et forberedt Kli, der formår at give, da Hans kærligheds natur er at skænke fylde." },
    { f: "Hvad er forbindelsen mellem omvendelse (Tshuva) og kabbalistisk bøn?", b: "Omvendelse er den smertelige erkendelse af den egoistiske natur, og bønnen er bønfaldesen om at blive udfriet fra den." },
    { f: "Hvordan beskytter bønnen mod spirituelt hovmod?", b: "Den forankrer bevidstheden om, at enhver opnået spirituel grad udelukkende er en ufortjent gave og nåde fra Oven." },
    { f: "Hvorfor forekommer det undertiden, at en bøn ikke besvares?", b: "Manglen har endnu ikke nået den påkrævede dybde eller renhed; karret er endnu ikke klar til at rumme Lyset." },
    { f: "Hvad vil det sige 'at udgyde sit hjerte for Skaberen'?", b: "Uforbeholdent at overgive alle skjulte ønsker, frygt og afmagt til Skaberens styrelse." },
    { f: "Hvordan bistår bønnebogen (Siddur) kabbalistens indre arbejde?", b: "Den tjener som et præcist spirituelt kort over indre tilstande og korrektionsprocesser forfattet af oplyste vise." },
    { f: "Hvorfor betragtes overgangen til Lishma som et mirakel?", b: "Fordi det at vende den skabte natur (egenkærlighed) til ren altruisme kun er muligt ved Lysets forvandlende kraft." },
    { f: "Hvordan bliver bønnen til en levende dialog med Skaberen?", b: "Når hjertets bevægelser trofast afspejler længslen efter at binde sig til Ham, åbnes en direkte indre samtale." },
    { f: "Hvad indebærer ordsproget 'Det tilkommer ikke dig at fuldføre værket, men du er ej heller fri til at unddrage dig det'?", b: "Selvom målet er en gave fra Oven, påhviler hele arbejdet med at opbygge ønsket og manglen mennesket alene." },
    { f: "Hvad er forbindelsen mellem bøn og kærlighed til vennerne?", b: "I anstrengelsen for at give til vennerne afsløres den totale mangel på evne til at elske, hvilket afføder et sandt råb om hjælp." },
    { f: "Hvordan renser selvransagelse forud for bønnen intentionen?", b: "Den afdækker skjulte egoistiske motiver, fjerner falske mål og fokuserer råbet mod et enkelt sandhedens punkt." },
    { f: "Hvad er forskellen på passiv venten og spirituel bøn?", b: "Passivitet opgiver kampen, mens bønnen er krigerens yderste råb, når han kæmper til det allersidste af sine kræfter." },
    { f: "Hvordan genspejles Toraens Lys i bønnen?", b: "Det Reformerende Lys, der tiltrækkes under studiet, oplyser hjertets mørke og vækker en dyb bøn om korrektion." },
    { f: "Hvad vil det sige, at den sande bøn 'råber fra dybet'?", b: "Et råb, der bryder frem fra selve bunden af ønsket om at modtage, fra den mørkeste afgrund i egoets fængsel." },
    { f: "Hvordan fører bønnen til Dvekut (vedhæftning) med Skaberen?", b: "Ved at tilegne sig egenskaben at give opnår mennesket formlighed med Skaberen, hvilket er fuldkommen enhed." },
    { f: "Hvad er den vigtigste praktiske lære i Lektion 18 om bøn?", b: "Nøj dig ikke med at gentage ord; opbyg en sand Chissaron i dit hjerte, for Skaberen hører kun hjertets sandhed." }
  ],
  sv: [
    { f: "Vad är den kabbalistiska definitionen av bön?", b: "'Arbetet i hjärtat' (Avoda shebaLev), en djupgående inre klargöring av begär, avsikter och brister inför Skaparen." },
    { f: "Vad representerar det andliga 'hjärtat' inom Kabbala?", b: "Hjärtat representerar summan av människans alla begär att ta emot och helheten av hennes känslomässiga och viljemässiga böjelser." },
    { f: "Hur förhåller sig munnens ord till hjärtats begär?", b: "Skaparen svarar uteslutande på den sanna bristen (Chisaron) i hjärtats djup, aldrig på läpparnas mekaniska ord." },
    { f: "Vad innebär begreppet 'Chisaron' i bönen?", b: "En äkta inre brist, tomheten i kärlet (Kli) som intensivt längtar efter uppfyllelse och andlig korrigering." },
    { f: "Varför räknas inte mekaniskt upprepande av ord som en sann bön?", b: "För om hjärtat inte längtar efter det läpparna uttalar, förblir orden döda former utan andlig livskraft." },
    { f: "Vilket är det första villkoret för att bönen ska bli hörd?", b: "Orubblig tro på att Skaparen verkligen är förmögen att befria människan ur egoismens fängelse." },
    { f: "Vilket är det andra villkoret för att bönen ska bli hörd?", b: "Insikten att det inte finns något annat val: alla mänskliga krafter har misslyckats och endast Skaparen kan hjälpa." },
    { f: "Vilket är det tredje villkoret för att bönen ska bli hörd?", b: "Att bönen sannerligen är en fråga om liv och död, utan vars uppfyllelse själen förgås i begäret att ta emot." },
    { f: "Hur fungerar bönen som ett 'medium' i den andliga utvecklingen?", b: "Den söker inte förändra Skaparen, utan transformerar människan och förbereder kärlet (Kli) för att ta emot givandets ljus." },
    { f: "Vad ber kabbalisten om i den sanna bönen som medium?", b: "Uteslutande om bristen på givande (önskan att ge) och om formlikhet med Skaparen." },
    { f: "Vad är det centrala budskapet i Shamati artikel 20 om att nå Lishma?", b: "Lishma (för Hennes Namns skull / osjälviskt givande) är en gåva och en upplysning från Ovan som det mänskliga förståndet inte kan uppnå på egen hand." },
    { f: "Om Lishma är en gåva från Ovan, varför behövs då mänsklig ansträngning?", b: "För att ansträngningar och medel bygger upp de korrigerade kärlen (Kelim) i människan som uppriktigt längtar efter att ta emot Lishma." },
    { f: "Vilken roll spelar misslyckande och maktlöshet i bönen enligt Shamati 20?", b: "När människan ser det meningslösa i alla sina handlingar når hon total hjälplöshet, och först då kan hon ropa från djupet av sitt hjärta." },
    { f: "När förmår en människa be en uppriktig bön från botten av sitt hjärta?", b: "Först efter att ha uttömt alla mänskliga medel och insett att hon inte förmår någonting alls på egen hand utan Skaparen." },
    { f: "Vad innebär begreppet 'MAN' (Mayin Nukvin)?", b: "Kvinnliga vatten; bristen, bönen och uppvaknandet som stiger upp från det lägre kärlet och attraherar överflöd och Ljus från Ovan." },
    { f: "Vilken roll spelar 'uppvaknandet nerifrån' i det andliga systemet?", b: "Uppvaknandet nerifrån (skapelsens bön) utlöser utgjutandet av de Övre Ljusen (MAD – Mayin Dehrin)." },
    { f: "Vad innebär principen 'Den som kommer för att rena sig får hjälp'?", b: "Den som uppriktigt strävar efter givande och renhet skänker Skaparen styrka, korrigering och upplyftelse över sin egoistiska natur från Ovan." },
    { f: "Hur hjälper Skaparen den som kommer för att rena sig?", b: "Genom att förläna tillståndet Lishma, väcka hjärtat och ge en övernaturlig kraft som överskrider den egoistiska naturen." },
    { f: "Vad innebär 'arbetet i hjärtat' under det dagliga inre klargörandet?", b: "Att skilja egoistiska begär från önskan att ge, med ständig bön om att transformera den egna naturen." },
    { f: "Varför förändras inte Skaparen genom bönen?", b: "Eftersom Skaparen är det Absoluta Goda och Oföränderliga; bönen förändrar det mottagande kärlet så att det blir förmöget att hålla Ljuset." },
    { f: "Vad är skillnaden mellan traditionell och kabbalistisk bön?", b: "Konventionell bön ber om materiella fördelar eller lindring för egot, medan kabbalistisk bön bönfaller om frälsning från själva egoismen." },
    { f: "Hur föds en äkta Chisaron på den andliga vägen?", b: "Genom ihärdigt arbete i gruppen och studier av källorna, varvid bristen klargörs som frånvaron av givandets ljus." },
    { f: "Vad betyder det att kroppen 'inte samtycker till Himmelrikets ok'?", b: "Det medfödda begäret att ta emot motsätter sig instinktivt att arbeta uteslutande till Skaparens behag utan personlig vinning." },
    { f: "Vad ska människan göra när hon märker att kroppens alla organ gör motstånd mot givande?", b: "Hon har ingen annan utväg än bön: att utgjuta sitt hjärta inför Skaparen så att Han förmår kroppen att böja sig för givande." },
    { f: "Hur tillintetgör uppnåendet av Lishma den onda böjelsen?", b: "Det upphäver egenkärleken; mottagandets kärl förlorar sin själviska funktion och räknas andligt som 'döda'." },
    { f: "Varför är det avgörande att veta att Lishma är ouppnåeligt utan bön?", b: "Eftersom denna insikt gör bönen till ett absolut och akut behov och raserar varje illusion av självgodhet." },
    { f: "Vad är kopplingen mellan att höja MAN och själens kärl?", b: "MAN är själva bristen i Kli; ju renare och djupare bristen är, desto större Ljus kan kärlet ta emot." },
    { f: "I vilken mening är bönen en bekännelse av egoismens maktlöshet?", b: "Hjärtat blottar sitt fullständiga beroende och erkänner att det egna egot är ett ointagligt fängelse utan gudomlig hjälp." },
    { f: "Hur samverkar grupparbetet med den personliga bönen?", b: "Ansträngningen att älska vännerna avslöjar den totala oförmågan till osjälviskt givande, vilket föder ett sant rop på hjälp." },
    { f: "Varför betraktas bönen som själva skapandet av det andliga kärlet?", b: "Eftersom uppfyllande endast kan inträda där det finns en motsvarande brist; bönen definierar och expanderar detta andliga vakuum." },
    { f: "Vad innebär uttrycket 'Skaparen hör bönen'?", b: "Begäran hamnar i fullständig resonans med den övre lagen om givande, och Ljuset fyller omedelbart det öppnade Kli." },
    { f: "Vilken roll spelar andlig förtvivlan vid bönens födelse?", b: "Den markerar den totala utmattningen av egoistiska krafter, vilket omedelbart föregår hjälpen från Ovan." },
    { f: "Vad är 'uppvaknandet från Ovan' (Itaruta de-Leila)?", b: "Uppenbarelsen av det Övre Ljuset som sänker sig som ett direkt svar på en mogen och renad brist nedifrån (MAN)." },
    { f: "Varför liknas begäret att ta emot vid en 'tjuv' i Shamati 20?", b: "Eftersom det försöker stjäla och lägga beslag på varje uns av energi och glädje uteslutande för sin egen själviska njutning." },
    { f: "Varför känner människan i början ingen glädje i arbetet för givande?", b: "För att begäret att ta emot inte ska finna smak i det; om det fann självisk njutning, skulle människan aldrig kunna lyfta sig till rent Lishma." },
    { f: "När blir det andliga arbetet en glädje i sig självt?", b: "När människan vänjer sig vid att ge, och glädjen som skänks Skaparen blir själva belöningen för ansträngningen." },
    { f: "När är klagan i det andliga arbetet berättigad eller oberättigad?", b: "Man kan bara klaga hos den herre man faktiskt arbetar för; att arbeta för egot ger ingen rätt att kräva krafter av Skaparen." },
    { f: "Vad innebär inre klargörande (Berur) i bönen?", b: "Att sålla avsikter: särskilja det som tjänar det egna egot från det som syftar till att glädja Skaparen." },
    { f: "Vad är 'fullständig fullkomlighet' i att ta på sig Himmelrikets ok?", b: "Att uteslutande vilja ge och helt avstå från mottagande för egen vinning." },
    { f: "Varför är intellektuell förståelse otillräcklig för hjärtats bön?", b: "Förståndets argument rör inte det andliga kärlet; endast en verklig brist som upplevs i hjärtat attraherar Ljuset." },
    { f: "Hur verkar MAN genom de andliga världarnas grader?", b: "Den lägre graden höjer sin brist till den högre, som lyfter den till Källan och för svaret nedåt." },
    { f: "Varför kallas bönen för det enda vapnet mot begäret att ta emot?", b: "Människan kan inte ändra sin skapade natur på egen hand; hon kan endast ropa till Skaparen om att få en ny natur av givande." },
    { f: "Varför är bönen en kontinuerlig process och inte en engångshandling?", b: "En kedja av ansträngningar och fall slipar och mognar bristen tills den når absolut uppriktighet." },
    { f: "Hur tar sig tron på befrielse uttryck i de mörkaste tillstånden?", b: "Även när kroppen inte ser någon utväg, är punkten i hjärtat förvissad om att Skaparen kan frälsa på ett ögonblick." },
    { f: "Vad innebär det att 'Skaparen längtar efter de rättfärdigas bön'?", b: "Skaparen väntar på ett förberett Kli som förmår ge, eftersom naturen i Hans kärlek är att överösa med uppfyllelse." },
    { f: "Vad är kopplingen mellan ånger (Tshuva) och kabbalistisk bön?", b: "Ånger är det smärtsamma erkännandet av den egoistiska naturen, och bönen är vädjan om att befrias från den." },
    { f: "Hur skyddar bönen människan mot andligt högmod?", b: "Den förankrar medvetenheten om att varje uppnådd andlig nivå uteslutande är en oförtjänt gåva och nåd från Ovan." },
    { f: "Varför verkar en bön ibland förbli obesvarad?", b: "Bristen har ännu inte nått det nödvändiga djupet eller renheten; kärlet är ännu inte redo att hålla Ljuset." },
    { f: "Vad innebär det att 'utgjuta sitt hjärta inför Skaparen'?", b: "Att förbehållslöst överlämna alla dolda begär, rädslor och maktlöshet under Skaparens ledning." },
    { f: "Hur bistår böneboken (Siddur) kabbalistens inre arbete?", b: "Den fungerar som en exakt andlig karta över inre tillstånd och korrigeringsprocesser formulerad av upplysta vise." },
    { f: "Varför betraktas övergången till Lishma som ett mirakel?", b: "För att omvandlingen av den skapade naturen (egenkärlek) till ren altruism endast är möjlig genom Ljusets transformerande kraft." },
    { f: "Hur blir bönen till en levande dialog med Skaparen?", b: "När hjärtats rörelser exakt återspeglar längtan efter att förenas med Honom öppnas en direkt inre samtalston." },
    { f: "Vad innebär ordspråket 'Det åligger inte dig att fullborda verket, men du är inte fri att avstå från det'?", b: "Även om målet är en gåva från Ovan, vilar hela mödan med att bygga begäret och bristen på människan." },
    { f: "Vad är kopplingen mellan bön och kärlek till vännerna?", b: "I ansträngningen att ge till vännerna blottas den totala oförmågan att älska osjälviskt, vilket föder ett genuint rop på hjälp." },
    { f: "Hur renar rannsakning före bönen avsikten?", b: "Den avslöjar dolda själviska motiv, rensar bort falska mål och fokuserar ropet till en enda punkt av sanning." },
    { f: "Vad är skillnaden mellan passiv väntan och andlig bön?", b: "Passivitet ger upp kampen, medan bön är det yttersta ropet från krigaren som kämpar till gränsen av sin förmåga." },
    { f: "Hur återspeglas Torans Ljus i bönen?", b: "Det Reformerande Ljuset som attraheras under studierna upplyser hjärtats mörker och väcker en djup vädjan om korrigering." },
    { f: "Vad innebär det att den sanna bönen 'ropar ur djupen'?", b: "Ett rop som bryter fram från botten av begäret att ta emot, från den mörkaste avgrunden i egot fängelse." },
    { f: "Hur leder bönen till Dvekut (vidhäftning) vid Skaparen?", b: "Genom att förvärva egenskapen att ge uppnår människan formlikhet med Skaparen, vilket är fullständig enhet." },
    { f: "Vilken är den viktigaste praktiska lärdomen i Lektion 18 om bön?", b: "Nöj dig inte med att upprepa ord; bygg upp en sann Chisaron i ditt hjärta, för Skaparen hör endast hjärtats sanning." }
  ],
  no: [
    { f: "Hva er den kabbalistiske definisjonen på bønn?", b: "'Arbeidet i hjertet' (Avoda shebaLev), en dyp indre avklaring av begjær, intensjoner og mangler foran Skaperen." },
    { f: "Hva representerer det åndelige 'hjertet' i Kabbala?", b: "Hjertet representerer summen av menneskets begjær etter å motta og helheten av dets emosjonelle og viljemessige tilbøyeligheter." },
    { f: "Hvordan forholder munnens ord seg til hjertets begjær?", b: "Skaperen svarer utelukkende på den sanne mangelen (Chisaron) i hjertets dyp, aldri på leppenes mekaniske ord." },
    { f: "Hva innebærer begrepet 'Chisaron' i bønnen?", b: "En ekte indre mangel, tomheten i karet (Kli) som intenst lengter etter oppfyllelse og åndelig korreksjon." },
    { f: "Hvorfor regnes ikke mekanisk repetisjon av ord som en sann bønn?", b: "Fordi hvis hjertet ikke lengter etter det leppene uttaler, forblir ordene livløse former uten åndelig kraft." },
    { f: "Hva er den første betingelsen for at bønnen skal bli hørt?", b: "Urokkelig tro på at Skaperen virkelig er i stand til å befri mennesket fra egoismens fengsel." },
    { f: "Hva er den andre betingelsen for at bønnen skal bli hørt?", b: "Erkjennelsen av at det ikke finnes noe annet valg: alle menneskelige krefter har slått feil og bare Skaperen kan hjelpe." },
    { f: "Hva er den tredje betingelsen for at bønnen skal bli hørt?", b: "At bønnen sannelig er et spørsmål om liv og død, uten hvis oppfyllelse sjelen går til grunne i begjæret etter å motta." },
    { f: "Hvordan fungerer bønnen som et 'medium' i den åndelige utviklingen?", b: "Den søker ikke å forandre Skaperen, men transformerer mennesket og forbereder Kli-et til å motta overgivelsens lys." },
    { f: "Hva ber kabbalisten om i den sanne bønnen som medium?", b: "Utelukkende om mangelen på å gi (ønsket om å gi) og om formlikhet med Skaperen." },
    { f: "Hva er hovedbudskapet i Shamati artikkel 20 om å nå Lishma?", b: "Lishma (for Hennes Navns skyld / uselvisk hengivenhet) er en gave og en opplysning ovenfra som det menneskelige sinnet ikke kan fatte på egen hånd." },
    { f: "Dersom Lishma er en gave ovenfra, hvorfor er menneskelig anstrengelse nødvendig?", b: "Fordi anstrengelser og midler bygger opp de korrigerte karene (Kelim) i mennesket som oppriktig lengter etter å motta Lishma." },
    { f: "Hvilken rolle spiller fiasko og maktesløshet i bønnen ifølge Shamati 20?", b: "Når mennesket ser det fåfengte i alle sine handlinger, når det en total hjelpeløshet, og først da kan det rope fra bunnen av sitt hjerte." },
    { f: "Når er et menneske i stand til å be en oppriktig bønn fra dypet av sitt hjerte?", b: "Først etter å ha uttømt alle menneskelige midler og innsett at det ikke makter noe som helst på egen hånd uten Skaperen." },
    { f: "Hva betyr begrepet 'MAN' (Mayin Nukvin)?", b: "Kvinnelige vann; mangelen, bønnen og oppvåkningen som stiger opp fra det lavere karet og tiltrekker overflod og Lys ovenfra." },
    { f: "Hva er rollen til 'oppvåkningen nedenfra' i det åndelige systemet?", b: "Oppvåkningen nedenfra (skaperverkets bønn) utløser strømmen av de Øvre Lysene (MAD – Mayin Dehrin)." },
    { f: "Hva betyr prinsippet 'Den som kommer for å rense seg, blir hjulpet'?", b: "Den som oppriktig streber etter overgivelse og renhet, skjenker Skaperen styrke, korreksjon og opphøyelse over sin egoistiske natur ovenfra." },
    { f: "Hvordan hjelper Skaperen den som kommer for å rense seg?", b: "Ved å skjenke ham tilstanden Lishma, vekke hans hjerte og gi ham en overnaturlig kraft som overskrider den egoistiske naturen." },
    { f: "Hva innebærer 'arbeidet i hjertet' under den daglige indre avklaringen?", b: "Å skille egoistiske begjær fra ønsket om å gi, med uopphørlig bønn om transformasjon av ens egen natur." },
    { f: "Hvorfor forandres ikke Skaperen gjennom bønnen?", b: "Fordi Skaperen er det Absolutt Gode og Uforanderlige; bønnen forandrer mottakerkaret slik at det blir skikket til å holde Lyset." },
    { f: "Hva er forskjellen mellom tradisjonell og kabbalistisk bønn?", b: "Konvensjonell bønn ber om materielle fordeler eller lindring for egoet, mens kabbalistisk bønn ber om frelse fra selve egoismen." },
    { f: "Hvordan fødes en ekte Chisaron på den åndelige veien?", b: "Gjennom iherdig arbeid i gruppen og studier av kildene, hvor mangelen avklares som fraværet av overgivelsens lys." },
    { f: "Hva betyr det at kroppen 'ikke samtykker til Himmelrikets åk'?", b: "Det medfødte begjæret etter å motta motsetter seg instinktivt å arbeide utelukkende for Skaperens behag uten personlig vinning." },
    { f: "Hva skal mennesket gjøre når det oppdager at kroppens organer kjemper imot overgivelse?", b: "Det har ingen annen utvei enn bønn: å utøse sitt hjerte for Skaperen slik at Han bøyer kroppen til overgivelse." },
    { f: "Hvordan tilintetgjør oppnåelsen av Lishma den onde tilbøyeligheten?", b: "Den opphever egenkjærligheten; mottakskarene mister sin selviske funksjon og regnes åndelig som 'døde'." },
    { f: "Hvorfor er det avgjørende å vite at Lishma er uoppnåelig uten bønn?", b: "Fordi denne innsikten gjør bønnen til et absolutt og prekært behov, og feier bort enhver illusjon om selvgodhet." },
    { f: "Hva er sammenhengen mellom å heve MAN og sjelens kar?", b: "MAN er selve mangelen i Kli; jo renere og dypere mangelen er, desto større Lys kan karet motta." },
    { f: "På hvilken måte er bønnen en tilståelse av egoismens maktesløshet?", b: "Hjertet avdekker sin totale avhengighet og erkjenner at dets eget ego er et uinntagelig fengsel uten guddommelig bistand." },
    { f: "Hvordan samvirker gruppearbeidet med den personlige bønnen?", b: "Anstrengelsen for å elske vennene avdekker den totale mangelen på evne til å gi uselvisk, noe som føder et ekte rop om hjelp." },
    { f: "Hvorfor betraktes bønnen som selve skapelsen av det åndelige karet?", b: "Fordi oppfyllelse kun kan komme inn der det finnes et tilsvarende tomrom; bønnen definerer og utvider dette åndelige vakuumet." },
    { f: "Hva betyr uttrykket 'Skaperen hører bønnen'?", b: "Bønnen kommer i fullkommen resonans med den øvre loven om overgivelse, og Lyset fyller umiddelbart det åpnede Kli." },
    { f: "Hvilken rolle spiller åndelig fortvilelse ved bønnens fødsel?", b: "Den markerer den totale utmattelsen av egoistiske krefter, noe som umiddelbart går forut for hjelpen ovenfra." },
    { f: "Hva er 'oppvåkningen ovenfra' (Itaruta de-Leila)?", b: "Åpenbaringen av det Øvre Lyset som senker seg som et direkte svar på en moden og renset mangel nedenfra (MAN)." },
    { f: "Hvorfor sammenlignes begjæret etter å motta med en 'tyv' i Shamati 20?", b: "Fordi det forsøker å stjele og tilrive seg hver minste partikkel av energi og glede utelukkende for sin egen selviske nytelse." },
    { f: "Hvorfor kjenner mennesket i begynnelsen ingen glede i arbeidet for overgivelse?", b: "For at begjæret etter å motta ikke skal finne smak i det; fant det selvisk nytelse, ville mennesket aldri heve seg til ren Lishma." },
    { f: "Når blir det åndelige arbeidet en glede i seg selv?", b: "Når mennesket venner seg til å gi, og gleden man gir Skaperen blir selve lønnen for anstrengelsen." },
    { f: "Når er klage i det åndelige arbeidet berettiget eller uberettiget?", b: "Man kan bare klage til den herren man faktisk arbeider for; å arbeide for egoet gir ingen rett til å kreve krefter fra Skaperen." },
    { f: "Hva innebærer indre avklaring (Berur) i bønnen?", b: "Å sortere intensjoner: skille det som tjener det egne egoet fra det som virkelig tar sikte på å glede Skaperen." },
    { f: "Hva er 'fullstendig fullkommenhet' i å påta seg Himmelrikets åk?", b: "Å utelukkende ønske å gi og fullstendig gi avkall på mottakelse til egen fordel." },
    { f: "Hvorfor er intellektuell forståelse utilstrekkelig for hjertets bønn?", b: "Forstandens argumenter beveger ikke det åndelige karet; kun en virkelig mangel opplevd i hjertet tiltrekker Lyset." },
    { f: "Hvordan virker MAN gjennom de åndelige verdenenes grader?", b: "Den lavere graden hever sin mangel til den høyere, som løfter den til Kilden og bringer svaret nedover." },
    { f: "Hvorfor kalles bønnen for det eneste våpenet mot begjæret etter å motta?", b: "Mennesket kan ikke endre sin skapte natur på egen hånd; det kan bare rope til Skaperen om å få en ny natur av overgivelse." },
    { f: "Hvorfor er bønnen en kontinuerlig prosess og ikke en isolert handling?", b: "En kjede av anstrengelser og fall sliper og modner mangelen inntil den oppnår absolutt oppriktighet." },
    { f: "Hvordan viser troen på frelse seg i de mørkeste tilstandene?", b: "Selv når kroppen ikke ser noen utvei, er punktet i hjertet forvisset om at Skaperen kan frelse på et øyeblikk." },
    { f: "Hva innebærer det at 'Skaperen lengter etter de rettferdiges bønn'?", b: "Skaperen venter på et forberedt Kli som makter å gi, ettersom naturen i Hans kjærlighet er å overøse med oppfyllelse." },
    { f: "Hva er forbindelsen mellom anger (Tshuva) og kabbalistisk bønn?", b: "Anger er den smertefulle erkjennelsen av den egoistiske naturen, og bønnen er ropet om å bli fridd fra den." },
    { f: "Hvordan beskytter bønnen mot åndelig hovmod?", b: "Den forankrer bevisstheten om at ethvert oppnådd åndelig nivå utelukkende er en ufortjent gave og nåde ovenfra." },
    { f: "Hvorfor virker en bønn noen ganger ubesvart?", b: "Mangelen har ennå ikke nådd den nødvendige dybden eller renheten; karet er ennå ikke klart til å holde Lyset." },
    { f: "Hva betyr det 'å utøse sitt hjerte for Skaperen'?", b: "Betingelsesløst å overgi alle skjulte begjær, frykt og maktesløshet under Skaperens ledelse." },
    { f: "Hvordan bistår bønneboken (Siddur) kabbalistens indre arbeid?", b: "Den fungerer som et nøyaktig åndelig kart over indre tilstander og korreksjonsprosesser utformet av opplyste vise." },
    { f: "Hvorfor betraktes overgangen til Lishma som et mirakel?", b: "Fordi omvandlingen av den skapte naturen (egenkjærlighet) til ren altruisme bare er mulig gjennom Lysets transformerende kraft." },
    { f: "Hvordan blir bønnen en levende dialog med Skaperen?", b: "Når hjertets bevegelser nøyaktig gjenspeiler lengselen etter å forenes med Ham, åpnes en direkte indre samtale." },
    { f: "Hva innebærer ordspråket 'Det påligger ikke deg å fullføre verket, men du er ikke fri til å avstå fra det'?", b: "Selv om målet er en gave ovenfra, hviler hele strevet med å bygge begjæret og mangelen på mennesket." },
    { f: "Hva er forbindelsen mellom bønn og kjærlighet til vennene?", b: "I anstrengelsen for å gi til vennene avdekkes den totale mangelen på evne til å elske uselvisk, noe som føder et sant rop om hjelp." },
    { f: "Hvordan renser selvransakelse forut for bønnen intensjonen?", b: "Den avdekker skjulte egoistiske motiver, fjerner falske mål og fokuserer ropet mot ett enkelt sannhetens punkt." },
    { f: "Hva er forskjellen mellom passiv venting og åndelig bønn?", b: "Passivitet gir opp kampen, mens bønn er det ytterste ropet fra krigeren som kjemper til grensen av sine krefter." },
    { f: "Hvordan gjenspeiles Toraens Lys i bønnen?", b: "Det Reformerende Lyset som tiltrekkes under studiene opplyser hjertets mørke og vekker en dyp bønn om korreksjon." },
    { f: "Hva innebærer det at den sanne bønnen 'roper fra dypet'?", b: "Et rop som bryter fram fra bunnen av begjæret etter å motta, fra den mørkeste avgrunnen i egoets fengsel." },
    { f: "Hvordan fører bønnen til Dvekut (vedhefting) med Skaperen?", b: "Ved å tilegne seg egenskapen til å gi oppnår mennesket formlikhet med Skaperen, som er fullkommen enhet." },
    { f: "Hva er den viktigste praktiske lærdommen i Leksjon 18 om bønn?", b: "Slå deg ikke til ro med å gjenta ord; bygg opp en sann Chisaron i ditt hjerte, for Skaperen hører kun hjertets sannhet." }
  ],
  fi: [
    { f: "Mikä on rukouksen kabbalistinen määritelmä?", b: "'Sydämen työ' (Avoda shebaLev), halujen, aikomusten ja puutteiden syvällinen sisäinen selvittäminen Luojan edessä." },
    { f: "Mitä henkinen 'sydän' edustaa Kabbalassa?", b: "Sydän edustaa ihmisen kaikkien vastaanottamisen halujen summaa sekä hänen emotionaalisten ja tahdonalaisten pyrkimystensä kokonaisuutta." },
    { f: "Miten suun sanat liittyvät sydämen haluun?", b: "Luoja vastaa yksinomaan sydämen syvyyksissä olevaan todelliseen puutteeseen (Hisaron), ei koskaan huulten mekaanisiin sanoihin." },
    { f: "Mitä tarkoittaa 'Hisaron'-käsite rukouksessa?", b: "Aitoa sisäistä puutetta, astian (Kli) tyhjyyttä, joka kaipaa kiihkeästi täyttymystä ja henkistä korjausta." },
    { f: "Miksi sanojen mekaanista toistamista ei pidetä aitona rukouksena?", b: "Koska jos sydän ei kaipaa sitä, mitä huulet lausuvat, sanat jäävät elottomiksi muodoiksi ilman henkistä elinvoimaa." },
    { f: "Mikä on rukouksen kuulemisen ensimmäinen ehto?", b: "Horjumaton usko siihen, että Luoja todella kykenee vapauttamaan ihmisen egoismin vankilasta." },
    { f: "Mikä on rukouksen kuulemisen toinen ehto?", b: "Sen oivaltaminen, ettei muuta vaihtoehtoa ole: kaikki inhimilliset voimat ovat pettäneet, ja vain Luoja voi auttaa." },
    { f: "Mikä on rukouksen kuulemisen kolmas ehto?", b: "Että pyyntö on todellakin elämän ja kuoleman kysymys, jota ilman sielu menehtyy vastaanottamisen haluun." },
    { f: "Miten rukous toimii 'välineenä' (medium) henkisessä kehityksessä?", b: "Se ei pyri muuttamaan Luojaa, vaan muuntaa ihmistä ja valmistaa Kliä vastaanottamaan antamisen valoa." },
    { f: "Mitä kabbalisti pyytää todellisessa rukouksessa välineenä?", b: "Ainoastaan antamisen puutetta (halua antaa) ja muodon vastaavuutta Luojan kanssa." },
    { f: "Mikä on Shamati-artikkelin 20 pääsanoma Lishman saavuttamisesta?", b: "Lishma (Hänen nimensä tähden / pyyteetön antaminen) on Ylhäältä tuleva lahja ja valaistus, jota ihmismieli ei kykene saavuttamaan yksin." },
    { f: "Jos Lishma on lahja Ylhäältä, miksi ihmisen ponnistelu on välttämätöntä?", b: "Koska ponnistelut ja korjauskeinot rakentavat ihmiseen ne korjatut astiat (Kelim), jotka vilpittömästi haluavat vastaanottaa Lishman." },
    { f: "Mikä rooli epäonnistumisella ja voimattomuudella on rukouksessa Shamatin 20 mukaan?", b: "Kun ihminen näkee kaikkien tekojensa turhuuden, hän saavuttaa täydellisen avuttomuuden ja voi vasta silloin huutaa sydämensä pohjasta." },
    { f: "Milloin ihminen kykenee lausumaan vilpittömän rukouksen sydämensä pohjasta?", b: "Vasta kokeiltuaan kaikkia inhimillisiä keinoja ja tunnustettuaan, ettei voi itse saavuttaa mitään ilman Luojaa." },
    { f: "Mitä tarkoittaa käsite 'MAN' (Mayin Nukvin)?", b: "Feminiinisiä vesiä; alemmasta astiasta nousevaa puutetta, rukousta ja heräämistä, joka vetää puoleensa runsautta ja Valoa Ylhäältä." },
    { f: "Mikä rooli 'alhaalta tulevalla heräämisellä' on henkisessä järjestelmässä?", b: "Alhaalta tuleva herääminen (luodun rukous) käynnistää Ylempien Valojen (MAD – Mayin Dehrin) vuodatuksen." },
    { f: "Mitä tarkoittaa periaate 'Joka tulee puhdistautumaan, sitä autetaan'?", b: "Sille, joka vilpittömästi pyrkii antamiseen ja puhtauteen, Luoja antaa Ylhäältä voimaa, korjausta ja kohotusta egoistisen luontonsa yläpuolelle." },
    { f: "Miten Luoja auttaa sitä, joka tulee puhdistautumaan?", b: "Suomalla hänelle Lishman asteen, herättämällä hänen sydämensä ja antamalla yliluonnollista voimaa, joka ylittää hänen luontonsa." },
    { f: "Mitä on 'sydämen työ' päivittäisen sisäisen selvittelyn aikana?", b: "Egoististen halujen erottamista antamisen halusta ja jatkuvaa rukousta oman luonnon muuntamiseksi." },
    { f: "Miksi Luoja ei muutu rukouksen kautta?", b: "Koska Luoja on Absoluuttinen Hyvä ja Muuttumaton; rukous muuttaa vastaanottavaa astiaa tehden siitä kykenevän pitämään Valon." },
    { f: "Mikä on ero tavanomaisen uskonnollisen ja kabbalistisen rukouksen välillä?", b: "Tavanomainen rukous pyytää aineellisia hyödykkeitä tai helpotusta egolle, kun taas kabbalistinen rukous anelee vapahdusta egoismista." },
    { f: "Miten aito Hisaron syntyy henkisellä tiellä?", b: "Sinnikkäällä työllä ryhmässä ja lähteiden tutkimisella, jolloin puute selkiytyy antamisen valon puuttumiseksi." },
    { f: "Mitä tarkoittaa, että keho 'ei suostu Taivaan Valtakunnan ikeeseen'?", b: "Synnynnäinen vastaanottamisen halu vastustaa vaistomaisesti työntekoa puhtaasti Luojan iloksi ilman henkilökohtaista hyötyä." },
    { f: "Mitä ihmisen tulee tehdä nähdessään kaikkien elimiensä vastustavan antamista?", b: "Hänellä ei ole muuta keinoa kuin rukous: vuodattaa sydämensä Luojalle, jotta Hän taivuttaisi kehon antamiseen." },
    { f: "Miten Lishman saavuttaminen surmaa pahan taipumuksen?", b: "Se mitätöi itserakkauden; vastaanottamisen astiat menettävät itsekkään tehtävänsä ja niitä pidetään henkisesti 'kuolleina'." },
    { f: "Miksi on ratkaisevaa tietää, että ilman rukousta Lishmaan ei voi päästä?", b: "Koska tämä tieto tekee rukouksesta ehdottoman ja kiireellisen tarpeen haihduttaen omahyväisyyden illuusion." },
    { f: "Mikä yhteys on MANin kohottamisella ja sielun astialla?", b: "MAN on itse Klin puute; mitä puhtaampi ja syvempi puute on, sitä suuremman Valon astia kykenee ottamaan vastaan." },
    { f: "Missä mielessä rukous on egoismin voimattomuuden tunnustamista?", b: "Sydän paljastaa täydellisen riippuvuutensa myöntäen oman egonsa olevan vankila, josta ei voi paeta ilman jumalallista apua." },
    { f: "Miten ryhmätyö yhdistyy henkilökohtaiseen rukoukseen?", b: "Ponnistelu ystävien rakastamiseksi paljastaa täydellisen kyvyttömyyden pyyteettömään antamiseen synnyttäen aidon avunhuudon." },
    { f: "Miksi rukousta pidetään itse henkisen astian luomisena?", b: "Koska täyttymys voi saapua vain sinne, missä on vastaava puute; rukous selkeyttää ja laajentaa tätä henkistä tyhjiötä." },
    { f: "Mitä tarkoittaa ilmaus 'Luoja kuulee rukouksen'?", b: "Pyyntö asettuu täydelliseen resonanssiin ylemmän antamisen lain kanssa, ja Valo täyttää avatun Klin välittömästi." },
    { f: "Mikä rooli henkisellä epätoivolla on rukouksen syntymisessä?", b: "Se merkitsee egoististen voimien täydellistä uupumista, mikä edeltää välittömästi Ylhäältä tulevan avun saapumista." },
    { f: "Mitä on 'herääminen Ylhäältä' (Itaruta de-Leila)?", b: "Ylemmän Valon ilmestyminen, joka laskeutuu suorana vastauksena kypsyneeseen ja puhdistuneeseen puutteeseen alhaalta (MAN)." },
    { f: "Miksi vastaanottamisen halua verrataan 'varkaaseen' Shamatin 20:ssä?", b: "Koska se yrittää varastaa ja omia jokaisen energian ja ilon murusen yksinomaan omaan itsekkääseen nautintoonsa." },
    { f: "Miksi ihminen ei aluksi tunne iloa antamisen työssä?", b: "Jotta vastaanottamisen halu ei löytäisi siitä makua; jos se saisi siitä mielihyvää, ihminen ei voisi koskaan nousta puhtaaseen Lishmaan." },
    { f: "Milloin henkisestä työstä tulee ilo itsessään?", b: "Kun ihminen tottuu antamaan, ja Luojan miellyttämisestä tulee itsessään ponnistelun suurin palkkio." },
    { f: "Milloin valitus henkisessä työssä on oikeutettua tai perusteetonta?", b: "Ihminen voi valittaa vain sille herralle, jolle todella tekee työtä; egolle ahertaminen ei anna oikeutta vaatia voimia Luojalta." },
    { f: "Mitä on sisäinen selvittely (Berur) rukouksessa?", b: "Aikomusten lajittelua: sen erottamista, mikä tehdään oman egon hyväksi, siitä, mikä tähtää Luojan ilahduttamiseen." },
    { f: "Mitä on 'täydellinen täydellisyys' Taivaan Valtakunnan ikeen vastaanottamisessa?", b: "Haluta ainoastaan antaa ja luopua täydellisesti vastaanottamisesta omaan lukuunsa." },
    { f: "Miksi älyllinen ymmärrys ei riitä sydämen rukoukseen?", b: "Järjen perustelut eivät liikuta henkistä astiaa; vain sydämessä koettu todellinen puute vetää Valoa puoleensa." },
    { f: "Miten MAN toimii henkisten maailmojen asteiden läpi?", b: "Alempi aste kohottaa puutteensa ylemmälle, joka vie sen Lähteelle ja laskee vastauksen alas." },
    { f: "Miksi rukousta kutsutaan ainoaksi aseeksi vastaanottamisen halua vastaan?", b: "Ihminen ei kykene muuttamaan luotua luontoaan omin voimin; hän voi ainoastaan huutaa Luojalle uuden antamisen luonnon saamiseksi." },
    { f: "Miksi rukous on jatkuva prosessi eikä hetkellinen teko?", b: "Ponnistelujen ja lankeamisten ketju hioo ja kypsyttää sisäistä puutetta, kunnes se saavuttaa absoluuttisen vilpittömyyden." },
    { f: "Miten usko pelastukseen ilmenee pimeimmissä tiloissa?", b: "Vaikka keho ei näe mitään ulospääsyä, sydämessä oleva piste on varma siitä, että Luoja voi pelastaa silmänräpäyksessä." },
    { f: "Mitä tarkoittaa, että 'Luoja kaipaa vanhurskaiden rukousta'?", b: "Luoja odottaa valmistettua Kliä, joka kykenee antamiseen, sillä Hänen rakkautensa luonne on täyttymyksen jakaminen." },
    { f: "Mikä yhteys on parannuksen (Tshuva) ja kabbalistisen rukouksen välillä?", b: "Parannus on egoistisen luonnon tuskallista havaitsemista, ja rukous on anomus siitä vapautumiseksi." },
    { f: "Miten rukous suojaa ihmistä henkiseltä ylpeydeltä?", b: "Se juurruttaa tietoisuuden siitä, että jokainen saavutettu henkinen taso on yksinomaan ansaitsematon lahja ja armo Ylhäältä." },
    { f: "Miksi rukous vaikuttaa toisinaan jäävän vaille vastausta?", b: "Puute ei ole vielä saavuttanut vaadittua syvyyttä tai puhtautta; astia ei ole vielä valmis pitämään Valoa." },
    { f: "Mitä tarkoittaa 'sydämen vuodattaminen Luojan eteen'?", b: "Kaikkien salaisten halujen, pelkojen ja voimattomuuden ehdotonta jättämistä Luojan ohjaukseen." },
    { f: "Miten rukouskirja (Siddur) tukee kabbalistin sisäistä työtä?", b: "Se toimii viisaiden laatimana tarkkana henkisenä karttana sisäisistä tiloista ja korjausprosesseista." },
    { f: "Miksi siirtymistä Lishmaan pidetään ihmeenä?", b: "Koska luodun luonnon (itserakkauden) kääntäminen puhtaaksi altruismiksi on mahdollista vain Valon muuntavan voiman avulla." },
    { f: "Miten rukous muuttuu eläväksi vuoropuheluksi Luojan kanssa?", b: "Kun sydämen liikkeet heijastavat tarkasti halua kiintyä Häneen, avautuu suora sisäinen yhteys." },
    { f: "Mitä tarkoittaa lausahdus 'Et ole vapaa vetäytymään työstä'?", b: "Vaikka päämäärä on lahja Ylhäältä, vaivannäkö halun ja puutteen rakentamiseksi kuuluu täysin ihmiselle." },
    { f: "Mikä yhteys on rukouksen ja ystävien rakastamisen välillä?", b: "Pyrkimys antaa ystäville paljastaa täydellisen kyvyttömyyden pyyteettömään rakkauteen synnyttäen aidon avunhuudon." },
    { f: "Miten itsetutkistelu ennen rukousta puhdistaa aikomuksen?", b: "Se riisuu naamiot itsekkäiltä vaikuttimilta, karsii väärät päämäärät ja keskittää huudon yhteen totuuden pisteeseen." },
    { f: "Mikä on passiivisen odottelun ja henkisen rukouksen ero?", b: "Passiivisuus luovuttaa taistelutta, kun taas rukous on äärirajoilleen taistelevan soturin viimeinen huuto." },
    { f: "Miten Tooran Valo heijastuu rukouksessa?", b: "Opiskelun aikana puoleensa vedetty Korjaava Valo valaisee sydämen pimeyden herättäen syvän anomuksen korjauksesta." },
    { f: "Mitä tarkoittaa, että todellinen rukous 'huutaa syvyyksistä'?", b: "Huutoa, joka purkautuu vastaanottamisen halun pohjalta, egon vankilan pimeimmästä kuilusta." },
    { f: "Miten rukous johtaa Dvekutiin (liittymiseen) Luojan kanssa?", b: "Saavuttamalla antamisen ominaisuuden ihminen saavuttaa muodon vastaavuuden Luojan kanssa, mikä on täydellistä ykseyttä." },
    { f: "Mikä on oppitunnin 18 tärkein käytännön opetus rukouksesta?", b: "Älä tyydy sanojen toistamiseen; rakenna aito Hisaron sydämeesi, sillä Luoja kuulee vain sydämen totuuden." }
  ],
  et: [
    { f: "Mis on palve kabalistlik määratlus?", b: "'Töö südames' (Avoda shebaLev) — soovide, kavatsuste ja puuduste sügav sisemine selgitamine Looja ees." },
    { f: "Mida tähistab vaimne 'süda' Kabalas?", b: "Süda esindab inimese kõigi saamissoovide summat ning tema emotsionaalsete ja tahteliste püüdluste tervikut." },
    { f: "Kuidas suhestuvad suu sõnad südame sooviga?", b: "Looja vastab eranditult südame sügavustes olevale tõelisele puudusele (Hisaron), mitte huulte mehaanilistele sõnadele." },
    { f: "Mida tähendab 'Hisaron'-mõiste palves?", b: "Ehtsat sisemist puudust, anuma (Kli) tühjust, mis igatseb kirglikult täitumust ja vaimset parandamist." },
    { f: "Miks ei peeta sõnade mehaanilist kordamist tõeliseks palveks?", b: "Sest kui süda ei igatse seda, mida huuled lausuvad, jäävad sõnad elututeks vormideks ilma vaimse väeta." },
    { f: "Mis on palve kuuldavõtmise esimene tingimus?", b: "Kõikumatu usk sellesse, et Looja on tõepoolest võimeline inimest egoismi vanglast vabastama." },
    { f: "Mis on palve kuuldavõtmise teine tingimus?", b: "Teadmine, et muud valikut pole: kõik inimlikud jõud on luhtunud ja aidata saab üksnes Looja." },
    { f: "Mis on palve kuuldavõtmise kolmas tingimus?", b: "Et palve oleks tõepoolest elu ja surma küsimus, ilma milleta hing hukkub saamissoovis." },
    { f: "Kuidas toimib palve 'meediumina' (vahendina) vaimses arengus?", b: "See ei püüa muuta Loojat, vaid muundab inimest, valmistades Kli ette andmise valguse vastuvõtmiseks." },
    { f: "Mida palub kabalist tõelises palves kui meediumis?", b: "Eranditult andmise puudust (soovi anda) ja vormi samasust Loojaga." },
    { f: "Mis on Shamati artikli 20 põhisõnum Lishma saavutamise kohta?", b: "Lishma (Tema nime nimel / omakasupüüdmatu andmine) on Ülevalt tulev kingitus ja valgustus, mida inimmõistus ei suuda üksinda saavutada." },
    { f: "Kui Lishma on kingitus Ülevalt, miks on vajalik inimese pingutus?", b: "Sest pingutused ja abinõud ehitavad inimeses üles parandatud anumad (Kelim), mis tõeliselt igatsevad Lishmat vastu võtta." },
    { f: "Millist rolli mängivad ebaõnnestumine ja abitus palves Shamati 20 järgi?", b: "Kui inimene näeb kõigi oma tegude tühisust, jõuab ta täieliku jõuetuseni ja alles siis suudab hüüda südamest." },
    { f: "Millal on inimene võimeline lausuma siirast palvet oma südamepõhjast?", b: "Alles pärast seda, kui ta on proovinud kõiki inimlikke abinõusid ja mõistnud, et ei suuda ise ilma Loojata midagi saavutada." },
    { f: "Mida tähendab mõiste 'MAN' (Mayin Nukvin)?", b: "Naiselikud veed; puudus, palve ja ärkamine, mis tõusevad madalamast anumast ning tõmbavad Ülevalt ligi küllust ja Valgust." },
    { f: "Milline on 'altpoolt tuleva ärkamise' roll vaimses süsteemis?", b: "Altpoolt tulev ärkamine (loodu palve) käivitab Ülemiste Valguste (MAD – Mayin Dehrin) voolamise." },
    { f: "Mida tähendab põhimõte 'Seda, kes tuleb end puhastama, aidatakse'?", b: "Sellele, kes siiralt püüdleb andmise ja puhtuse poole, annab Looja Ülevalt jõudu, parandust ja ülendust üle tema egoistliku loomuse." },
    { f: "Kuidas Looja aitab seda, kes tuleb end puhastama?", b: "Kingib talle Lishma astme, äratab tema südame ja annab talle üleloomuliku jõu, mis ületab tema loomuse." },
    { f: "Mis on 'töö südames' igapäevase sisemise selgitamise ajal?", b: "Egoistlike soovide eristamine andmissoovist ja pidev palve oma loomuse muundamiseks." },
    { f: "Miks Looja ei muutu palve kaudu?", b: "Kuna Looja on Absoluutne Headus ja Muutumatu; palve muudab vastuvõtvat anumat, tehes selle võimeliseks Valgust hoidma." },
    { f: "Mis vahe on tavapärasel religioossel ja kabalistlikul palvel?", b: "Tavapärane palve küsib materiaalseid hüvesid või kergendust egole, samas kui kabalistlik palve anub päästmist egoismist." },
    { f: "Kuidas sünnib vaimsel teel ehtne Hisaron?", b: "Pideva töö kaudu grupis ja allikate uurimisel, kusjuures puudus selgineb andmise valguse puudumisena." },
    { f: "Mida tähendab, et keha 'ei nõustu Taevariigi ikkega'?", b: "Kaasasündinud saamissoov seisab instinktiivselt vastu töötegemisele puhtalt Looja rõõmuks ilma isikliku tasuta." },
    { f: "Mida peab inimene tegema, kui ta näeb, et kõik tema liikmed seisavad andmisele vastu?", b: "Tal pole muud pääsu kui palve: valada oma süda Looja ette, et Ta painutaks keha andmisele." },
    { f: "Kuidas Lishma saavutamine surmavalt hävitab kurja kalduvuse?", b: "See nullib enesearmastuse; vastuvõtuanumad kaotavad oma iseka funktsiooni ja neid peetakse vaimselt 'surnuteks'." },
    { f: "Miks on oluline teada, et ilma palveta on Lishmat võimatu saavutada?", b: "Sest see teadmine muudab palve absoluutseks ja vältimatuks vajaduseks, hajutades enesega rahulolu illusiooni." },
    { f: "Milline on seos MANi tõstmise ja hinge anuma vahel?", b: "MAN on Kli enda puudus; mida puhtam ja sügavam on see puudus, seda suuremat Valgust suudab anum vastu võtta." },
    { f: "Mis mõttes on palve egoismi jõuetuse ülestunnistus?", b: "Süda paljastab oma täieliku sõltuvuse, tunnistades oma ego vanglaks, millest pole võimalik ilma jumaliku abita põgeneda." },
    { f: "Kuidas põimub rühmatöö isikliku palvega?", b: "Püüd armastada sõpru paljastab täieliku võimetuse omakasupüüdmatuks andmiseks, sünnitades tõelise appikarje." },
    { f: "Miks peetakse palvet vaimse anuma enese loomiseks?", b: "Sest täitumus saab siseneda vaid sinna, kus on vastav puudus; palve määratleb ja laiendab seda vaimset vaakumit." },
    { f: "Mida tähendab väljend 'Looja kuuleb palvet'?", b: "Päring satub täielikku resonantsi ülima andmisseadusega ja Valgus täidab avatud Kli silmapilkselt." },
    { f: "Millist rolli mängib vaimne meeleheide palve sünnis?", b: "See tähistab egoistlike jõudude täielikku kurnatust, mis eelneb otseselt Ülevalt tuleva abi saabumisele." },
    { f: "Mis on 'ärkamine Ülevalt' (Itaruta de-Leila)?", b: "Ülemise Valguse ilmnemine, mis laskub otsese vastusena altpoolt tõusnud küpsele ja puhastatud puudusele (MAN)." },
    { f: "Miks võrreldakse saamissoovi Shamati 20-s 'vargaga'?", b: "Sest see püüab varastada ja omastada iga energia- ja rõõmupuru üksnes oma isekaks naudinguks." },
    { f: "Miks ei tunne inimene alguses mingit rõõmu andmise nimel tehtavas töös?", b: "Selleks, et saamissoov ei leiaks sellest maitset; kui ta tunneks sellest naudingut, ei tõuseks inimene iial puhta Lishmani." },
    { f: "Millal saab vaimsest tööst rõõm iseeneses?", b: "Kui inimene harjub andmisega ja Loojale heameele valmistamisest saab pingutuse enese suurim tasu." },
    { f: "Millal on vaimses töös kaebamine õigustatud või õigustamatu?", b: "Kaevata saab vaid sellele isandale, kelle heaks tegelikult töötatakse; ego heaks rügades pole õigust nõuda jõudu Loojalt." },
    { f: "Mis on sisemine selgitamine (Berur) palves?", b: "Kavatsuste eritlemine: oma ego heaks tehtava eraldamine sellest, mis on suunatud Looja rõõmustamisele." },
    { f: "Mis on 'täielik täiuslikkus' Taevariigi ikke vastuvõtmisel?", b: "Tahta üksnes anda ja loobuda täielikult enda tarbeks saamisest." },
    { f: "Miks ei piisa intellektuaalsest arusaamisest südame palveks?", b: "Mõistuse argumendid ei liiguta vaimset anumat; vaid südames läbielatud tõeline puudus tõmbab Valgust ligi." },
    { f: "Kuidas toimib MAN vaimsete maailmade astmete kaudu?", b: "Madalam aste tõstab oma puuduse kõrgemale, mis viib selle Allikani ja toob vastuse alla." },
    { f: "Miks nimetatakse palvet ainsaks relvaks saamissoovi vastu?", b: "Inimene ei suuda oma loodud loomust ise muuta; ta saab vaid hüüda Looja poole, et saada uus andmise loomus." },
    { f: "Miks on palve pidev protsess, mitte ühekordne akt?", b: "Pingutuste ja langemiste ahel lihvib ja küpsetab puudust, kuni see saavutab absoluutse siiruse." },
    { f: "Kuidas avaldub usk vabanemisse kõige pimedamates seisundites?", b: "Isegi kui keha ei näe mingit väljapääsu, on punkt südames kindel, et Looja suudab päästa silmapilkselt." },
    { f: "Mida tähendab, et 'Looja igatseb õigete palvet'?", b: "Looja ootab ettevalmistatud Kli-d, mis suudab anda, kuna Tema armastuse olemus on täitumuse jagamine." },
    { f: "Milline on seos patukahetsuse (Tshuva) ja kabalistliku palve vahel?", b: "Patukahetsus on egoistliku loomuse valus äratundmine ja palve on anumine sellest vabanemiseks." },
    { f: "Kuidas kaitseb palve inimest vaimse uhkuse eest?", b: "See kinnistab teadmist, et iga saavutatud vaimne tase on üksnes teenimatu kingitus ja arm Ülevalt." },
    { f: "Miks tundub palve vahel vastuseta jäävat?", b: "Puudus pole veel saavutanud vajalikku sügavust või puhtust; anum pole veel valmis Valgust hoidma." },
    { f: "Mida tähendab 'oma südame väljavalamine Looja ees'?", b: "Kõigi varjatud soovide, hirmude ja abituse tingimusteta loovutamist Looja juhtimise alla." },
    { f: "Kuidas aitab palveraamat (Siddur) kabalisti sisemist tööd?", b: "See toimib tarkade koostatud täpse vaimse kaardina sisemistest seisunditest ja parandusprotsessidest." },
    { f: "Miks peetakse Lishmale üleminekut imeks?", b: "Sest loodud loomuse (enesearmastuse) pööramine puhtaks altruismiks on võimalik vaid Valguse muundava jõu abil." },
    { f: "Kuidas muutub palve elavaks dialoogiks Loojaga?", b: "Kui südame liikumised peegeldavad täpselt igatsust Tema külge klammerduda, avaneb vahetu sisemine side." },
    { f: "Mida tähendab vanasõna 'Sa pole vaba tööst loobuma'?", b: "Kuigi eesmärk on kingitus Ülevalt, lasub soovi ja puuduse ehitamise vaev täielikult inimesel." },
    { f: "Milline on seos palve ja sõprade armastamise vahel?", b: "Püüd anda sõpradele paljastab täieliku võimetuse omakasupüüdmatuks armastuseks, sünnitades ehtsa appihüüde." },
    { f: "Kuidas puhastab enesevaatlus enne palvet kavatsust?", b: "See rebib maskid isekatelt motiividelt, eemaldab valed sihid ja koondab hüüde ühte tõepunkti." },
    { f: "Mis vahe on passiivsel ootamisel ja vaimsel palvel?", b: "Passiivsus annab alla võitluseta, samas kui palve on viimse piirini võitleva sõdalase äärmuslik hüüe." },
    { f: "Kuidas peegeldub Toora Valgus palves?", b: "Õppimisel ligitõmmatud Parandav Valgus valgustab südame pimedust, äratades sügava palve paranduse järele." },
    { f: "Mida tähendab, et tõeline palve 'hüüab sügavustest'?", b: "Hüüet, mis purskab saamissoovi põhjast, ego vangla kõige pimedamast kuristikust." },
    { f: "Kuidas viib palve Dvekutini (kinnitumiseni) Loojaga?", b: "Omandades andmise omaduse, saavutab inimene vormi samasuse Loojaga, mis on täielik ühtsus." },
    { f: "Mis on 18. õppetunni tähtsaim praktiline õppetund palvest?", b: "Ära rahuldu sõnade kordamisega; ehita ehtne Hisaron oma südamesse, sest Looja kuuleb vaid südame tõde." }
  ],
  lv: [
    { f: "Kāda ir lūgšanas kabalistiskā definīcija?", b: "'Darbs sirdī' (Avoda shebaLev) — vēlmju, nodomu un trūkumu dziļa iekšēja noskaidrošana Radītāja priekšā." },
    { f: "Ko kabalā nozīmē garīgā 'sirds'?", b: "Sirds pārstāv cilvēka visu saņemšanas vēlmju kopumu un viņa emocionālo un gribas tieksmju veselumu." },
    { f: "Kā mutes vārdi attiecas pret sirds vēlmi?", b: "Radītājs atbild vienīgi uz patieso trūkumu (Hisaron) sirds dziļumos, nekad uz mehāniskiem lūpu vārdiem." },
    { f: "Kas ir 'Hisaron' jēdziens lūgšanā?", b: "Patiess iekšējs trūkums, tilpnes (Kli) tukšums, kas kaislīgi ilgojas pēc piepildījuma un garīgās labošanās." },
    { f: "Kāpēc mehāniska vārdu atkārtošana netiek uzskatīta par īstu lūgšanu?", b: "Tāpēc, ka ja sirds neilgojas pēc tā, ko pauž lūpas, vārdi paliek nedzīvas formas bez garīga spēka." },
    { f: "Kāds ir pirmais nosacījums lūgšanas uzklausīšanai?", b: "Nelokāma ticība tam, ka Radītājs patiesi spēj atbrīvot cilvēku no egoisma cietuma." },
    { f: "Kāds ir otrais nosacījums lūgšanas uzklausīšanai?", b: "Apziņa, ka citas izvēles nav: visi cilvēciskie spēki ir izsmelti un palīdzēt var vienīgi Radītājs." },
    { f: "Kāds ir trešais nosacījums lūgšanas uzklausīšanai?", b: "Ka lūgums patiesi ir dzīvības un nāves jautājums, bez kura dvēsele iet bojā saņemšanas vēlmē." },
    { f: "Kā lūgšana darbojas kā 'medijs' garīgajā attīstībā?", b: "Tā nemēģina mainīt Radītāju, bet pārveido pašu cilvēku, sagatavojot Kli atdeves gaismas saņemšanai." },
    { f: "Ko kabalists lūdz patiesā lūgšanā kā medijā?", b: "Vienīgi atdeves trūkumu (vēlmi atdot) un formas vienādību ar Radītāju." },
    { f: "Kāds ir Šamati 20. raksta galvenais vēstījums par Lišma sasniegšanu?", b: "Lišma (Viņas Vārdā / nesavtīga atdeve) ir dāvana un apgaismība no Augšienes, ko cilvēka prāts nespēj sasniegt viens pats." },
    { f: "Ja Lišma ir dāvana no Augšienes, kāpēc vajadzīgas cilvēka pūles?", b: "Tāpēc, ka pūles un līdzekļi cilvēkā veido izlabotās tilpnes (Kelim), kas patiesi ilgojas saņemt Lišma." },
    { f: "Kāda loma saskaņā ar Šamati 20 ir neveiksmei un bezpalīdzībai lūgšanā?", b: "Kad cilvēks redz visu savu darbību veltīgumu, viņš nonāk pilnīgā bezpalīdzībā un tikai tad spēj saukt no sirds dziļumiem." },
    { f: "Kad cilvēks kļūst spējīgs raidīt patiesu lūgšanu no visas sirds?", b: "Tikai pēc tam, kad izmēģinājis visus cilvēciskos līdzekļus un atzinis, ka pats bez Radītāja nespēj sasniegt neko." },
    { f: "Ko nozīmē jēdziens 'MAN' (Mayin Nukvin)?", b: "Sievietes ūdeņi; trūkums, lūgšana un atmošanās, kas paceļas no zemākās tilpnes un piesaista pārpilnību un Gaismu no Augšienes." },
    { f: "Kāda loma garīgajā sistēmā ir 'atmodai no apakšas'?", b: "Atmoda no apakšas (radības lūgšana) ierosina Augstāko Gaišumu (MAD – Mayin Dehrin) plūsmu." },
    { f: "Ko nozīmē princips 'Tam, kurš nāk attīrīties, palīdz'?", b: "Tam, kurš patiesi tiecas pēc atdeves un tīrības, Radītājs no Augšienes sniedz spēku, labošanos un pacelšanos pāri viņa dabai." },
    { f: "Kā tieši Radītājs palīdz tam, kurš nāk attīrīties?", b: "Dāvājot viņam Lišma pakāpi, modinot viņa sirdi un piešķirot pārdabisku spēku, kas pārspēj viņa egoismu." },
    { f: "Kas ir 'darbs sirdī' ikdienas iekšējās noskaidrošanas laikā?", b: "Egoistisko vēlmju atšķiršana no vēlmes atdot, nemitīgi lūdzot par savas dabas pārveidošanu." },
    { f: "Kāpēc Radītājs nemainās lūgšanas ietekmē?", b: "Tāpēc, ka Radītājs ir Absolūti Labs un Nemainīgs; lūgšana maina saņemošo tilpni, padarot to spējīgu saturēt Gaismu." },
    { f: "Kāda ir atšķirība starp parasto reliģisko un kabalistisko lūgšanu?", b: "Parastā lūgšana prasa materiālus labumus vai atvieglojumu ego, kamēr kabalistiskā lūgšana lūdz glābiņu no paša egoisma." },
    { f: "Kā garīgajā ceļā dzimst patiess Hisaron?", b: "Caur neatlaidīgu darbu grupā un avotu pētīšanu, kad trūkums tiek apzināts kā atdeves gaismas trūkums." },
    { f: "Ko nozīmē tas, ka ķermenis 'nepiekrīt Debesu Valstības jūgam'?", b: "Iedzimtā saņemšanas vēlme instinktīvi pretojas darbam tikai Radītāja priekam bez personīga labuma." },
    { f: "Kas cilvēkam jādara, redzot, ka visi viņa orgāni pretojas atdevei?", b: "Viņam nav citas izejas kā vien lūgšana: izliet savu sirdi Radītāja priekšā, lai Viņš piespiestu ķermeni pakļauties atdevei." },
    { f: "Kā Lišma sasniegšana iznīcina ļauno tieksmi?", b: "Tā atceļ patmīlību; saņemšanas tilpnes zaudē savu egoistisko funkciju un garīgi tiek uzskatītas par 'mirušām'." },
    { f: "Kāpēc ir būtiski zināt, ka bez lūgšanas Lišma nav sasniedzama?", b: "Tāpēc, ka šī apziņa padara lūgšanu par absolūtu un neatliekamu nepieciešamību, izkliedējot pašapmierinātības ilūziju." },
    { f: "Kāda ir saikne starp MAN pacelšanu un dvēseles tilpni?", b: "MAN ir pats Kli trūkums; jo tīrāks un dziļāks ir šis trūkums, jo lielāku Gaismu tilpne spēj saņemt." },
    { f: "Kādā ziņā lūgšana ir egoisma bezspēcības atzīšana?", b: "Sirds atklāj savu pilnīgo atkarību, atzīstot savu ego par cietumu, no kura nevar izkļūt bez Radītāja." },
    { f: "Kā grupas darbs savienojas ar personīgo lūgšanu?", b: "Pūles mīlēt draugus atsedz pilnīgu nespēju nesavtīgi atdot, dzemdējot patiesu saucienu pēc palīdzības." },
    { f: "Kāpēc lūgšana tiek uzskatīta par pašas garīgās tilpnes radīšanu?", b: "Tāpēc, ka piepildījums var ienākt tikai tur, kur ir atbilstošs trūkums; lūgšana definē un paplašina šo garīgo vakuumu." },
    { f: "Ko nozīmē teiciens 'Radītājs dzird lūgšanu'?", b: "Lūgums nonāk pilnīgā rezonansē ar augstāko atdeves likumu, un Gaisma nekavējoties piepilda atvērto Kli." },
    { f: "Kāda loma garīgajam izmisumam ir lūgšanas dzimšanā?", b: "Tas iezīmē pilnīgu egoistisko spēku izsīkumu, kas tieši ir priekšvēstnesis palīdzības saņemšanai no Augšienes." },
    { f: "Kas ir 'atmoda no Augšienes' (Itaruta de-Leila)?", b: "Augstākās Gaismas parādīšanās, kas nolaižas kā tieša atbilde uz nobriedušu un attīrītu trūkumu no apakšas (MAN)." },
    { f: "Kāpēc Šamati 20 saņemšanas vēlme tiek salīdzināta ar 'zagli'?", b: "Tāpēc, ka tā cenšas nozagt un piesavināties katru enerģijas un prieka drusku vienīgi savam egoistiskajam baudījumam." },
    { f: "Kāpēc cilvēks sākumā nejūt nekādu prieku darbā atdeves labā?", b: "Lai saņemšanas vēlme tajā neatrastu garšu; ja tā sajustu baudu, cilvēks nekad nepaceltos līdz tīram Lišma." },
    { f: "Kad garīgais darbs kļūst par prieku pats par sevi?", b: "Kad cilvēks pierod atdot, un prieka sniegšana Radītājam kļūst par pašu pūļu lielāko atalgojumu." },
    { f: "Kad kurnēšana garīgajā darbā ir pamatota vai nepamatota?", b: "Sūdzēties var tikai tam kungam, kura labā reāli strādā; kalpojot ego, nav tiesību prasīt spēkus no Radītāja." },
    { f: "Kas ir iekšējā noskaidrošana (Berur) lūgšanā?", b: "Nodomu šķirošana: atdalīšana tā, kas kalpo personīgajam ego, no tā, kas vērsts uz prieka sagādāšanu Radītājam." },
    { f: "Kas ir 'pilnīga pilnība' Debesu Valstības jūga pieņemšanā?", b: "Vēlēties vienīgi atdot un pilnībā atteikties no saņemšanas personīgā labuma dēļ." },
    { f: "Kāpēc intelektuāla izpratne nav pietiekama sirds lūgšanai?", b: "Prāta argumenti nekustina garīgo tilpni; tikai reāls trūkums, kas izdzīvots sirdī, piesaista Gaismu." },
    { f: "Kā MAN darbojas caur garīgo pasauļu pakāpēm?", b: "Zemākā pakāpe paceļ savu trūkumu uz augstāko, kas aiznes to līdz Avotam un nolaiž atbildi lejup." },
    { f: "Kāpēc lūgšana tiek saukta par vienīgo ieroci pret saņemšanas vēlmi?", b: "Cilvēks pats nespēj mainīt savu radīto dabu; viņš var tikai saukt uz Radītāju pēc jaunas atdeves dabas piešķiršanas." },
    { f: "Kāpēc lūgšana ir nepārtraukts process, nevis vienreizēja darbība?", b: "Pūļu un kritienu virkne slīpē un nobriedina iekšējo trūkumu, līdz tas sasniedz absolūtu sirsnību." },
    { f: "Kā izpaužas ticība atbrīvošanai visdrūmākajos stāvokļos?", b: "Pat tad, kad ķermenis neredz nekādu izeju, punkts sirdī ir pārliecināts, ka Radītājs spēj izglābt acu mirklī." },
    { f: "Ko nozīmē tas, ka 'Radītājs ilgojas pēc taisno lūgšanas'?", b: "Radītājs gaida sagatavotu Kli, kas spēj atdot, jo Viņa mīlestības daba ir dāvāt piepildījumu." },
    { f: "Kāda ir saikne starp nožēlu (Tshuva) un kabalistisko lūgšanu?", b: "Nožēla ir egoistiskās dabas sāpīga apzināšanās, un lūgšana ir lūgums pēc atbrīvošanas no tās." },
    { f: "Kā lūgšana pasargā cilvēku no garīgā lepnuma?", b: "Tā nostiprina apziņu, ka jebkurš sasniegtais garīgais līmenis ir vienīgi nenopelnīta dāvana un žēlastība no Augšienes." },
    { f: "Kāpēc dažreiz šķiet, ka lūgšana paliek neatbildēta?", b: "Trūkums vēl nav sasniedzis nepieciešamo dziļumu vai tīrību; tilpne vēl nav gatava noturēt Gaismu." },
    { f: "Ko nozīmē 'izliet savu sirdi Radītāja priekšā'?", b: "Visu apslēpto vēlmju, baiļu un bezpalīdzības beznosacījumu nodošana Radītāja vadībā." },
    { f: "Kā lūgšanu grāmata (Sidurs) palīdz kabalista iekšējam darbam?", b: "Tā kalpo kā precīza gudro sastādīta garīgā karte iekšējiem stāvokļiem un labošanās procesiem." },
    { f: "Kāpēc pāreja uz Lišma tiek uzskatīta par brīnumu?", b: "Tāpēc, ka radītās dabas (patmīlības) pārvēršana tīrā altruismā ir iespējama vienīgi ar Gaismas pārveidojošo spēku." },
    { f: "Kā lūgšana pārtop dzīvā dialogā ar Radītāju?", b: "Kad sirds kustības precīzi atspoguļo ilgas pieķerties Viņam, atveras tieša iekšēja saziņa." },
    { f: "Ko nozīmē teiciens 'Tev nav pienākuma pabeigt darbu, bet tu neesi brīvs no tā atteikties'?", b: "Lai gan mērķis ir dāvana no Augšienes, viss darbs vēlmes un trūkuma veidošanā gulstas vienīgi uz cilvēku." },
    { f: "Kāda ir saikne starp lūgšanu un draugu mīlestību?", b: "Pūlēs dot draugiem atklājas pilnīga nespēja nesavtīgi mīlēt, dzemdējot autentisku saucienu pēc palīdzības." },
    { f: "Kā pašpārbaude pirms lūgšanas attīra nodomu?", b: "Tā atmasko slēptos egoistiskos motīvus, noņem viltus mērķus un fokusē saucienu vienā patiesības punktā." },
    { f: "Kāda ir atšķirība starp pasīvu gaidīšanu un garīgu lūgšanu?", b: "Pasivitāte padodas bez cīņas, kamēr lūgšana ir karotāja galējais sauciens, kurš cīnās līdz spēku galējai robežai." },
    { f: "Kā Toras Gaisma atspoguļojas lūgšanā?", b: "Mācībās piesaistītā Reformējošā Gaisma apgaismo sirds tumsu, modinot dziļu lūgumu pēc labošanās." },
    { f: "Ko nozīmē tas, ka patiesa lūgšana 'sauc no dziļumiem'?", b: "Sauciens, kas izlaužas no pašas saņemšanas vēlmes apakšas, no ego cietuma vistumšākās bezdibeņa." },
    { f: "Kā lūgšana ved pie Dvekut (saplūsmes) ar Radītāju?", b: "Iegūstot atdeves īpašību, cilvēks sasniedz formas vienādību ar Radītāju, kas ir pilnīga vienotība." },
    { f: "Kāda ir 18. nodarbības svarīgākā praktiskā mācība par lūgšanu?", b: "Nenomierinies ar vārdu atkārtošanu; izveido patiesu Hisaron savā sirdī, jo Radītājs dzird tikai sirds patiesību." }
  ],
  lt: [
    { f: "Koks yra kabalistinis maldos apibrėžimas?", b: "'Darbas širdyje' (Avoda shebaLev) — gilus vidinis troškimų, ketinimų ir trūkumų išsiaiškinimas Kūrėjo akivaizdoje." },
    { f: "Ką Kabaloje reprezentuoja dvasinė 'širdis'?", b: "Širdis reprezentuoja visų žmogaus norų gauti sumą bei jo emocinių ir valios siekių visumą." },
    { f: "Kaip burnos žodžiai santykiauja su širdies troškimu?", b: "Kūrėjas atsako išskirtinai į tikrąjį trūkumą (Chisaron) širdies gelmėse, o ne į mechaninius lūpų žodžius." },
    { f: "Kas yra 'Chisaron' sąvoka maldoje?", b: "Tikras vidinis trūkumas, indo (Kli) tuštuma, aistringai trokštanti išsipildymo ir dvasinio išsitaisymo." },
    { f: "Kodėl mechaninis žodžių kartojimas nelaikomas tikra malda?", b: "Nes jei širdis netrokšta to, ką taria lūpos, žodžiai lieka negyvomis formomis be dvasinės gyvybės." },
    { f: "Kokia yra pirmoji maldos išklausymo sąlyga?", b: "Užtikrintas tikėjimas, kad Kūrėjas iš tiesų pajėgus išlaisvinti žmogų iš egoizmo kalėjimo." },
    { f: "Kokia yra antroji maldos išklausymo sąlyga?", b: "Suvokimas, kad kito pasirinkimo nėra: visos žmogiškosios jėgos žlugo ir tik Kūrėjas gali padėti." },
    { f: "Kokia yra trečioji maldos išklausymo sąlyga?", b: "Kad prašymas iš tiesų būtų gyvybės ir mirties klausimas, be kurio siela pražūva gavimo noro spąstuose." },
    { f: "Kaip malda veikia kaip 'mediumas' (priemonė) dvasiniame vystymesi?", b: "Ji nesiekia pakeisti Kūrėjo, bet transformuoja žmogų, paruošdama Kli atidavimo šviesos priėmimui." },
    { f: "Ko kabalistas prašo tikroje maldoje kaip priemonėje?", b: "Išimtinai atidavimo trūkumo (noro atiduoti) ir formos sutapimo su Kūrėju." },
    { f: "Kokia yra Shamati 20 straipsnio pagrindinė žinia apie Lišma pasiekimą?", b: "Lišma (dėl Jos Vardo / nesavanaudiškas atidavimas) yra dovana ir nušvitimas iš Aukščiau, kurio žmogaus protas nepajėgus pasiekti vienas." },
    { f: "Jei Lišma yra dovana iš Aukščiau, kodėl būtinos žmogaus pastangos?", b: "Nes pastangos ir taisymo priemonės kuria žmoguje ištaisytus indus (Kelim), kurie nuoširdžiai trokšta gauti Lišma." },
    { f: "Koks yra nesėkmės ir bejėgiškumo vaidmuo maldoje pagal Shamati 20?", b: "Kai žmogus pamato visų savo veiksmų bergždumą, jis pasiekia visišką bejėgiškumą ir tik tada gali sušukti iš širdies gelmių." },
    { f: "Kada žmogus tampa pajėgus išreikšti nuoširdžią maldą iš širdies gelmių?", b: "Tik išbandęs visas žmogiškąsias priemones ir pripažinęs, kad pats be Kūrėjo negali pasiekti nieko." },
    { f: "Ką reiškia sąvoka 'MAN' (Mayin Nukvin)?", b: "Moteriškieji vandenys; trūkumas, malda ir prabudimas, kylantys iš žemesniojo indo ir pritraukiantys gausą bei Šviesą iš Aukščiau." },
    { f: "Koks yra 'prabudimo iš apačios' vaidmuo dvasinėje sistemoje?", b: "Prabudimas iš apačios (kūrinio malda) sužadina Aukštesniųjų Šviesų (MAD – Mayin Dehrin) tekėjimą." },
    { f: "Ką reiškia principas 'Tam, kuris ateina apsivalyti, padedama'?", b: "Tam, kuris nuoširdžiai siekia atidavimo ir tyrumo, Kūrėjas iš Aukščiau suteikia jėgų, ištaisymą ir pakylėjimą virš jo prigimties." },
    { f: "Kaip būtent Kūrėjas padeda tam, kuris ateina apsivalyti?", b: "Dovanodamas jam Lišma pakopą, pažadindamas jo širdį ir suteikdamas antgamtinę jėgą, pranokstančią jo egoizmą." },
    { f: "Kas yra 'darbas širdyje' kasdienio vidinio aiškinimosi metu?", b: "Egoistinių norų atskyrimas nuo noro atiduoti, nuolat meldžiant savo prigimties transformacijos." },
    { f: "Kodėl Kūrėjas nesikeičia per maldą?", b: "Nes Kūrėjas yra Absoliutus Gėris ir Nekintamas; malda keičia priimantįjį indą, padarydama jį tinkamą Šviesai." },
    { f: "Kuo skiriasi įprastinė religinė malda nuo kabalistinės maldos?", b: "Paprasta malda prašo materialių gėrybių ar palengvinimo ego, o kabalistinė malda meldžia išvadavimo iš paties egoizmo." },
    { f: "Kaip dvasiniame kelyje gimsta tikrasis Chisaron?", b: "Per atkaklų darbą grupėje ir šaltinių studijavimą, kuomet trūkumas išsigrynina kaip atidavimo šviesos nebuvimas." },
    { f: "Ką reiškia, kad kūnas 'nesutinka su Dangaus Karalystės jungu'?", b: "Įgimtas noras gauti instinktyviai priešinasi darbui vien Kūrėjo džiaugsmui be asmeninio atlygio." },
    { f: "Ką turi daryti žmogus, matydamas, kad visi jo organai priešinasi atidavimui?", b: "Jis neturi kitos išeities, kaip tik maldą: išlieti širdį prieš Kūrėją, kad Jis priverstų kūną paklusti atidavimui." },
    { f: "Kaip Lišma pasiekimas numarina blogąjį pradą?", b: "Panaikina savimeilę; gavimo indai praranda savo egoistinę funkciją ir dvasiškai laikomi 'mirusiais'." },
    { f: "Kodėl svarbu žinoti, kad be maldos Lišma yra nepasiekiama?", b: "Nes šis žinojimas paverčia maldą absoliučia ir neatidėliotina būtinybe, išsklaidydamas savikliovos iliuziją." },
    { f: "Koks yra ryšys tarp MAN pakėlimo ir sielos indo?", b: "MAN yra pats Kli trūkumas; kuo švaresnis ir gilesnis trūkumas, tuo didesnę Šviesą indas gali priimti." },
    { f: "Kokia prasme malda yra egoizmo bejėgiškumo pripažinimas?", b: "Širdis atskleidžia visišką priklausomybę, pripažindama savo ego kalėjimu, iš kurio neįmanoma ištrūkti be Kūrėjo." },
    { f: "Kaip darbas grupėje susilieja su asmenine malda?", b: "Pastanga mylėti draugus atveria visišką negebėjimą nesavanaudiškai mylėti, pagimdydama tikrą pagalbos šauksmą." },
    { f: "Kodėl malda laikoma paties dvasinio indo sukūrimu?", b: "Nes pripildymas gali ateiti tik ten, kur yra atitinkama tuštuma; malda apibrėžia ir praplečia šį dvasinį vakuumą." },
    { f: "Ką reiškia posakis 'Kūrėjas girdi maldą'?", b: "Prašymas pasiekia tobulą rezonansą su aukštesniuoju atidavimo dėsniu, ir Šviesa akimirksniu užpildo atvertą Kli." },
    { f: "Koks yra dvasinės vilties praradimo vaidmuo maldos gimimui?", b: "Jis žymi visišką egoistinių jėgų išsekimą, kas betarpiškai veda į pagalbos iš Aukščiau atėjimą." },
    { f: "Kas yra 'prabudimas iš Aukščiau' (Itaruta de-Leila)?", b: "Aukštesniosios Šviesos pasireiškimas, kuris nusileidžia kaip tiesioginis atsakas į subrendusį ir apvalytą trūkumą iš apačios (MAN)." },
    { f: "Kodėl noras gauti Shamati 20 lyginamas su 'vagimi'?", b: "Nes jis bando pavogti ir pasisavinti kiekvieną energijos ir džiaugsmo trupinį išimtinai savo egoistiniam malonumui." },
    { f: "Kodėl žmogus iš pradžių nejaučia jokio džiaugsmo darbe dėl atidavimo?", b: "Kad noras gauti nepatirtų jame skonio; jei patirtų pasitenkinimą, žmogus niekada nepakiltų į tyrą Lišma." },
    { f: "Kada dvasinis darbas tampa džiaugsmu pats savaime?", b: "Kai žmogus pripranta atiduoti, ir džiaugsmo teikimas Kūrėjui tampa didžiausiu pastangų atlygiu." },
    { f: "Kada priekaištas dvasiniame darbe yra pagrįstas ar nepagrįstas?", b: "Skųstis galima tik tam šeimininkui, kuriam realiai dirbama; dirbant ego, negalima reikalauti jėgų iš Kūrėjo." },
    { f: "Kas yra vidinis aiškinimasis (Berur) maldoje?", b: "Kėslų atskyrimas: to, kas daroma savo ego labui, atskyrimas nuo to, kas skirta Kūrėjo džiaugsmui." },
    { f: "Kas yra 'tobulas tobulumas' priimant Dangaus Karalystės jungą?", b: "Norėti vien tik atiduoti ir visiškai atsisakyti gavimo dėl asmeninės naudos." },
    { f: "Kodėl intelektualaus supratimo nepakanka širdies maldai?", b: "Proto argumentai nejudina dvasinio indo; tik realus trūkumas, išgyventas širdyje, pritraukia Šviesą." },
    { f: "Kaip MAN veikia per dvasinių pasaulių pakopas?", b: "Žemesnioji pakopa pakelia savo trūkumą aukštesniajai, o ši iškelia jį iki Šaltinio ir nuleidžia atsakymą žemyn." },
    { f: "Kodėl malda vadinama vieninteliu ginklu prieš norą gauti?", b: "Žmogus pats negali pakeisti savo prigimties; jis gali tik šauktis Kūrėjo, kad suteiktų naują atidavimo prigimtį." },
    { f: "Kodėl malda yra nuolatinis procesas, o ne vienkartinis veiksmas?", b: "Pastangų ir kritimų grandinė šlifuoja ir brandina vidinį trūkumą, kol jis pasiekia visišką nuoširdumą." },
    { f: "Kaip pasireiškia tikėjimas išlaisvinimu tamsiausiose būsenose?", b: "Net kai kūnas nemato jokios išeities, taškas širdyje yra tikras, kad Kūrėjas gali išgelbėti per akimirksnį." },
    { f: "Ką reiškia, kad 'Kūrėjas ilgisi teisiųjų maldos'?", b: "Kūrėjas laukia paruošto Kli, gebančio atiduoti, nes Jo meilės prigimtis yra suteikti pripildymą." },
    { f: "Koks yra ryšys tarp atgailos (Tshuva) ir kabalistinės maldos?", b: "Atgaila yra skausmingas egoistinės prigimties suvokimas, o malda yra prašymas išvaduoti iš jos." },
    { f: "Kaip malda apsaugo žmogų nuo dvasinės puikybės?", b: "Ji įtvirtina suvokimą, kad bet koks pasiektas dvasinis lygis yra išimtinai nepelnyta dovana ir malonė iš Aukščiau." },
    { f: "Kodėl kartais atrodo, kad malda lieka be atsako?", b: "Trūkumas dar nepasiekė reikiamo gylio ar tyrumo; indas dar nėra pasirengęs išlaikyti Šviesą." },
    { f: "Ką reiškia 'išlieti širdį prieš Kūrėją'?", b: "Besąlygiškas visų slaptų norų, baimių ir bejėgiškumo atidavimas Kūrėjo valdymui." },
    { f: "Kaip maldaknygė (Sidūras) padeda kabalisto vidiniam darbui?", b: "Ji tarnauja kaip tikslus išminčių sudarytas vidinių būsenų ir taisymo procesų dvasinis žemėlapis." },
    { f: "Kodėl perėjimas į Lišma laikomas stebuklu?", b: "Nes prigimties (savimeilės) apvertimas į tyrą altruizmą įmanomas tik per transformuojančią Šviesos galią." },
    { f: "Kaip malda virsta gyvu dialogu su Kūrėju?", b: "Kai širdies judesiai tiksliai atspindi troškimą susilieti su Juo, atsiveria tiesioginis vidinis ryšys." },
    { f: "Ką reiškia posakis 'Nesi laisvas atsisakyti darbo'?", b: "Nors tikslas yra dovana iš Aukščiau, visas triūsas kuriant norą ir trūkumą tenka išimtinai žmogui." },
    { f: "Koks yra ryšys tarp maldos ir meilės draugams?", b: "Pastangose duoti draugams atsiskleidžia visiškas negebėjimas nesavanaudiškai mylėti, pagimdydamas autentišką pagalbos šauksmą." },
    { f: "Kaip savianalizė prieš maldą apvalo ketinimą?", b: "Ji nuplėšia kaukes nuo egoistinių motyvų, pašalina klaidingus tikslus ir sutelkia šauksmą į vieną tiesos tašką." },
    { f: "Kuo skiriasi pasyvus laukimas nuo dvasinės maldos?", b: "Pasyvumas pasiduoda be kovos, o malda yra kario, kovojančio iki paskutinių jėgų, kraštutinis šauksmas." },
    { f: "Kaip Toros Šviesa atsispindi maldoje?", b: "Studijų metu pritraukta Grąžinanti į Gėrį Šviesa apšviečia širdies tamsą, sukeldama gilų taisymosi prašymą." },
    { f: "Ką reiškia, kad tikra malda 'šaukiasi iš gelmių'?", b: "Šauksmas, besiveržiantis iš pačio noro gauti dugno, iš tamsiausios ego kalėjimo bedugnės." },
    { f: "Kaip malda veda į Dvekut (susiliejimą) su Kūrėju?", b: "Įgydamas atidavimo savybę žmogus pasiekia formos sutapimą su Kūrėju, kas yra visiška vienybė." },
    { f: "Kokia yra svarbiausia praktinė 18 pamokos pamoka apie maldą?", b: "Nesitenkink žodžių kartojimu; sukurk tikrą Chisaron savo širdyje, nes Kūrėjas girdi tik širdies tiesą." }
  ],
  ar: [
    { f: "ما هو التعريف الكابالي للصلاة؟", b: "'العمل في القلب' (عبودا شيباليف)، وهو توضيح داخلي عميق للرغبات والنوايا والافتقار أمام الخالق." },
    { f: "ماذا يمثل 'القلب' الروحي في حكمة الكابالا؟", b: "يمثل القلب مجموع رغبات الإنسان في التلقي وكافة ميوله العاطفية ونزعاته الإرادية." },
    { f: "كيف ترتبط كلمات الفم برغبة القلب؟", b: "يستجيب الخالق حصرياً للنقص الحقيقي (الحيسارون) في أعماق القلب، ولا يستجيب للكلمات الميكانيكية التي تنطق بها الشفاه." },
    { f: "ما هو مفهوم 'الحيسارون' في الصلاة؟", b: "افتقار داخلي حقيقي، وفراغ الوعاء (الكلي) الذي يتوق بشدة إلى الامتلاء والتصحيح الروحي." },
    { f: "لماذا لا يُعتبر الترديد الميكانيكي للكلمات صلاة حقيقية؟", b: "لأنه إذا لم يكن القلب يتوق إلى ما تنطق به الشفاه، تظل الكلمات قوالب ميتة مجردة من القوة والحيوية الروحية." },
    { f: "ما هو الشرط الأول لاستجابة الصلاة؟", b: "إيمان راسخ لا يتزعزع بأن الخالق قادر تماماً على خلاص الإنسان من سجن الأنانية." },
    { f: "ما هو الشرط الثاني لاستجابة الصلاة؟", b: "إدراك عدم وجود أي خيار آخر: لقد استُنفدت وفشلت كل القوى البشرية، والخالق وحده القادر على المساعدة." },
    { f: "ما هو الشرط الثالث لاستجابة الصلاة؟", b: "أن يكون الطلب مسألة حياة أو موت، وبدونه تهلك الروح وتضيع في رغبة التلقي الأنانية." },
    { f: "كيف تعمل الصلاة كـ 'وسيط' (ميديوم) في التطور الروحي؟", b: "إنها لا تغير الخالق، بل تُحدث تحولاً جذرياً في الإنسان وتُعد الكلي لاستقبال نور العطاء والمنح." },
    { f: "عما يبحث ويسأل الكابالي في الصلاة الحقيقية كوسيط؟", b: "حصرياً عن النقص للعطاء (الرغبة الصادقة في المنح) وعن تطابق الشكل والصفات مع الخالق." },
    { f: "ما هي الرسالة المحورية للمقالة 20 من كتاب 'شمعتي' حول بلوغ درجة 'ليشما'؟", b: "درجة 'ليشما' (من أجل اسمها / العطاء المتجرد) هي هبة واستنارة من الأعلى يعجز العقل البشري عن بلوغها بمفرده." },
    { f: "إذا كانت ليشما هبة من الأعلى، فلماذا يُعد الجهد الإنساني ضرورياً؟", b: "لأن الجهود والوسائل تبني في الإنسان الأوعية المصححة (الكليم) التي ترغب بصدق في نيل هبة ليشما." },
    { f: "ما هو دور الفشل والعجز في الصلاة وفقاً لمقالة شمعتي 20؟", b: "عندما يرى الإنسان عقم وبطلان كل أفعاله الذاتية، يبلغ مرحلة العجز التام، وحينها فقط يمكنه الصراخ من أعماق قلبه." },
    { f: "متى يصبح الإنسان قادراً على صلاة حقيقية وصادقة من سويداء قلبه؟", b: "فقط بعد استنفاد كافة الوسائل البشرية وإدراكه أنه بمفرده عاجز تماماً عن تحقيق أي شيء بدون الخالق." },
    { f: "ماذا يعني مصطلح 'مان' (مايين نوكفين)؟", b: "المياه المؤنثة؛ وهي النقص والصلاة واليقظة الصاعدة من الكلي الأسفل لجذب النور والفيض الإلهي من الأعلى." },
    { f: "ما هو دور 'اليقظة من الأسفل' في النظام الروحي؟", b: "اليقظة من الأسفل (صلاة وتضرع المخلوق) هي التي تُطلق تدفق الأنوار العليا (ماد - مايين ديخرين)." },
    { f: "ما معنى المبدأ القائل: 'من أتى ليتطهر يُعان'؟", b: "من يسعى بصدق نحو العطاء والنقاء، يمنحه الخالق من الأعلى قوة وتصحيحاً ورفعة تسمو فوق طبيعته الأنانية." },
    { f: "كيف يعين الخالق بالتحديد من أتى ليتطهر؟", b: "يمنحه مرتبة ليشما، ويوقظ قلبه، ويزوده بقوة خارقة تعلو وتتجاوز طبيعته الأنانية المجبولة على التلقي." },
    { f: "ما هو 'العمل في القلب' أثناء التوضيح الداخلي اليومي؟", b: "الفرز والتمييز الدائم بين الرغبات الأنانية والرغبة في العطاء، مع الصلاة الدائمة لتحويل طبيعة النفس." },
    { f: "لماذا لا يتغير الخالق بفعل الصلاة؟", b: "لأن الخالق هو الخير المطلق وثابت لا يتغير؛ الصلاة تُغير الوعاء القابل وتجعله مؤهلاً لاحتواء النور." },
    { f: "ما هو الفارق بين الصلاة الدينية التقليدية والصلاة الكابالية؟", b: "الصلاة التقليدية تطلب مكاسب مادية أو راحة للأنا، بينما الصلاة الكابالية تتضرع للخلاص والتحرر من الأنانية ذاتها." },
    { f: "كيف يولد الحيسارون الحقيقي في المسار الروحي؟", b: "من خلال العمل الدؤوب في المجموعة ودراسة المصادر الأصيلة، حيث يتضح النقص بوصفه غياباً لنور العطاء." },
    { f: "ما معنى أن الجسد 'لا يوافق على نير ملكوت السماوات'؟", b: "الرغبة الفطرية في التلقي تنفر وتقاوم غريزياً العمل الصرف لإسعاد الخالق دون مقابل أو منفعة شخصية." },
    { f: "ماذا ينبغي للإنسان أن يفعل حين يرى جوارحه تقاوم العطاء؟", b: "لا ملجأ له سوى الصلاة: أن يسكب قلبه أمام الخالق لكي يُخضع جسده ويجعله قابلاً لنير العطاء." },
    { f: "كيف يقضي بلوغ مرتبة ليشما على الميل إلى الشر (الأنانية)؟", b: "يُبطل ويلغي حب الذات؛ تفقد أوعية التلقي وظيفتها الأنانية وتُعتبر في المفهوم الروحي 'ميتة'." },
    { f: "لماذا من الجوهري معرفة أنه يستحيل بلوغ ليشما دون الصلاة؟", b: "لأن هذا الإدراك يحول الصلاة إلى حاجة مطلقة وملحة، مبدداً كل أوهام الاكتفاء الذاتي والغرور." },
    { f: "ما الرابط بين رفع المان ووعاء الروح؟", b: "المان هو جوهر النقص في الكلي؛ كلما كان النقص أنقى وأعمق، كان النور الذي يستطيع الوعاء استيعابه أعظم." },
    { f: "بأي معنى تُعتبر الصلاة اعترافاً بعجز الأنانية؟", b: "يكشف القلب عن اعتماده الكلي على ربه، معترفاً بأن الأنا سجن حصين يستحيل الهروب منه دون معونة الخالق." },
    { f: "كيف يتكامل العمل في المجموعة مع الصلاة الفردية؟", b: "الجهد المبذول لمحبة الأصدقاء يعري ويكشف العجز التام عن العطاء المتجرد، مما يولد صرخة استغاثة حقيقية." },
    { f: "لماذا تُعتبر الصلاة بمثابة الخلق الفعلي للوعاء الروحي؟", b: "لأن الامتلاء لا يدخل إلا حيث يوجد فراغ ونقص موازٍ؛ الصلاة تحدد وتوسع هذا الفراغ الروحي." },
    { f: "ما معنى العبارة القائلة بأن 'الخالق يسمع الصلاة'؟", b: "يدخل الطلب في رنين وتناغم تام مع قانون العطاء الأعلى، فيملأ النور فوراً الكلي المفتوح." },
    { f: "ما هو دور اليأس الروحي في ولادة الصلاة؟", b: "يؤذن بالنفاد والإنهاك التام للقوى الأنانية، وهو ما يسبق مباشرة تدفق العون الإلهي من الأعلى." },
    { f: "ما هي 'اليقظة من الأعلى' (إيتاروتا ديلعيلا)؟", b: "تجلي النور الأعلى الذي يفيض كاستجابة مباشرة لنقص ناضج ومطهر صاعد من الأسفل (مان)." },
    { f: "لماذا شُبهت رغبة التلقي بـ 'اللص' في مقالة شمعتي 20؟", b: "لأنها تسعى لسرقة واختلاس كل ومضة طاقة وفرح لتحويلها حصرياً للذة الأنانية الخاصة." },
    { f: "لماذا لا يشعر الإنسان في بداية عمله في العطاء بأي نشوة أو فرح؟", b: "لكي لا تجد رغبة التلقي مذاقاً فيه؛ فلو تلذذت به أنانياً، لما استطاع الإنسان الارتقاء أبداً إلى نقاء ليشما." },
    { f: "متى يتحول العمل الروحي إلى بهجة وغبطة بحد ذاته؟", b: "عندما يعتاد الإنسان العطاء، ويصبح إدخال السرور على الخالق هو الجائزة الكبرى والغاية من الجهد." },
    { f: "متى تكون الشكوى في العمل الروحي مبررة أو غير مبررة؟", b: "يحق للمرء الشكوى فقط للسيد الذي يعمل لأجله حقاً؛ أما الكدح في خدمة الأنا فلا يعطي حقاً لطلب القوة من الخالق." },
    { f: "ما هو التوضيح والفرز الداخلي (بيرور) في الصلاة؟", b: "فرز وتمييز النوايا: عزل ما يُفعل لأجل مصلحة الأنا عما هو موجه حقاً لإسعاد الخالق وإرضائه." },
    { f: "ما هو 'الكمال التام' عند قبول نير ملكوت السماوات؟", b: "الرغبة في العطاء الحصري، والتخلي الجذري عن التلقي والانتفاع الذاتي." },
    { f: "لماذا لا يكفي الفهم الفكري المجرد لصلاة القلب؟", b: "حجج العقل والمنطق لا تحرك الكلي الروحي؛ النقص الحقيقي المعاش في شغاف القلب هو وحده القادر على جذب النور." },
    { f: "كيف يعمل المان عبر درجات العوالم الروحية؟", b: "ترفع الدرجة السفلى نقصها إلى الدرجة العليا، والتي ترفعه بدورها إلى المصدر فتستنزل الجواب إلى الأسفل." },
    { f: "لماذا سُميت الصلاة بالسلاح الوحيد ضد رغبة التلقي؟", b: "لأن الإنسان عاجز عن تغيير طبيعته المخلوقة؛ ولا يملك إلا الصراخ للخالق كي يمنحه طبيعة جديدة هي العطاء." },
    { f: "لماذا تُعتبر الصلاة مساراً متواصلاً وليست مجرد فعل عابر؟", b: "لأن سلسلة المحاولات والكبوات تصقل وتنضج النقص الداخلي حتى يبلغ درجة الصدق والوفاء المطلق." },
    { f: "كيف يتجلى الإيمان بالخلاص في أحلك الحالات الروحية ظلمة؟", b: "حتى عندما لا يرى الجسد أي بارقة أمل، تظل النقطة في القلب على يقين تام بأن الخالق قادر على الإنقاذ بلمح البصر." },
    { f: "ما معنى القول بأن 'الخالق يشتاق لصلاة الصديقين'؟", b: "ينتظر الخالق وعاءً معداً وقادراً على العطاء، إذ إن جوهر محبته يكمن في الإفاضة وبث الامتلاء." },
    { f: "ما هي العلاقة بين التوبة (تشوفا) والصلاة الكابالية؟", b: "التوبة هي الإدراك الأليم لشر الطبيعة الأنانية، والصلاة هي التوسل والالتماس للتحرر والانعتاق منها." },
    { f: "كيف تحمي الصلاة الإنسان من الغرور والصلف الروحي؟", b: "ترسخ الوعي واليقين بأن كل درجة روحية محققة هي محض نعمة وهبة مجانية غير مستحقة من الأعلى." },
    { f: "لماذا تبدو الصلاة أحياناً وكأنها بقيت دون إجابة؟", b: "لأن النقص لم يبلغ بعد العمق أو النقاء المطلوب؛ فالكلي لم ينضج بعد ليحتوي النور ويصونه." },
    { f: "ما معنى 'سكب القلب أمام الخالق'؟", b: "التسليم المطلق والتنازل غير المشروط عن سائر الرغبات الخفية والمخاوف ومشاعر العجز لقيادة الخالق." },
    { f: "كيف يساند كتاب الصلوات (السيدور) العمل الباطني للكابالي؟", b: "يعد بمثابة خريطة روحية دقيقة للمقامات الداخلية ومسارات التصحيح صاغها حكماء بلغوا الغاية." },
    { f: "لماذا يُعد التحول إلى ليشما معجزة كبرى؟", b: "لأن قلب الطبيعة المجبولة (حب الذات) وتحويلها إلى إيثار مطلق لا يتأتى إلا بالقدرة القاهرة لنور الخالق." },
    { f: "كيف تصبح الصلاة حواراً حياً مع الخالق؟", b: "حين تعكس نبضات القلب بأمانة تامة التوق للالتصاق به، ينفتح حوار ومناجاة باطنية مباشرة." },
    { f: "ما معنى الحكمة: 'ليس عليك إتمام العمل، ولكنك لست حراً في التخلي عنه'؟", b: "مع أن الغاية هبة من الأعلى، إلا أن عناء بناء الرغبة واكتساب النقص يقع كلياً على عاتق الإنسان." },
    { f: "ما الرابط الوثيق بين الصلاة ومحبة الأصدقاء؟", b: "في مكابدة العطاء للأصدقاء تتكشف العنة التامة عن المحبة الصادقة، مما يلد صرخة استغاثة مشتركة." },
    { f: "كيف تُصفي المحاسبة الذاتية قبل الصلاة النية وتطهرها؟", b: "تكشف المآرب الأنانية المتخفية، وتغربل الأهداف الزائفة، وتركز الصرخة في نقطة حق واحدة." },
    { f: "ما الفارق بين الانتظار السلبي والصلاة الروحية الحية؟", b: "السلبية تستسلم وتلقي السلاح دون نضال، في حين أن الصلاة هي صيحة المقاتل الذي يكافح حتى الرمق الأخير." },
    { f: "كيف يتجلى نور التوراة وينعكس في الصلاة؟", b: "النور المصلح المجتذب خلال التعلم يبدد حلكة القلب، موقظاً ابتهالاً عميقاً لطلب التصحيح." },
    { f: "ما معنى أن الصلاة الحقة 'تصرخ من الأعماق'؟", b: "صرخة تنبثق وتتفجر من قاع رغبة التلقي، من أحلك هوة في معتقل الأنا المظلم." },
    { f: "كيف تفضي الصلاة إلى الالتصاق والاتحاد (ديفكوت) بالخالق؟", b: "باكتساب سمة العطاء يبلغ الإنسان تطابق الشكل مع الخالق، وهو عين الوحدة والاندماج الأسمى." },
    { f: "ما هي العبرة العملية الجوهرية للدرس 18 حول الصلاة؟", b: "لا تكتفِ بترديد الألفاظ؛ ابنِ نقصاً وحيسارون حقيقياً في قلبك، فالخالق لا يسمع إلا صدق القلوب." }
  ],
  fa: [
    { f: "تعریف کبالایی دعا و نیایش چیست؟", b: "'کار در قلب' (آوودا شِبالِو)، تبیین و روشن‌سازی عمیق درونی تمایلات، نیت‌ها و کمبودها در پیشگاه آفریدگار." },
    { f: "مفهوم 'قلب' معنوی در حکمت کبالا نشان‌دهنده چیست؟", b: "قلب نشان‌دهنده مجموع تمام تمایلات انسان برای دریافت و تمامی گرایش‌های احساسی و خواست‌های اوست." },
    { f: "کلمات زبان با تمنا و اشتیاق قلب چگونه ارتباط دارند؟", b: "آفریدگار منحصراً به کمبود راستین (خیسارون) در اعماق قلب پاسخ می‌دهد، نه به کلمات طوطی‌وار و مکانیکی زبان." },
    { f: "مفهوم 'خیسارون' در دعا به چه معناست؟", b: "کمبود حقیقی درونی، تهی بودن و خلأ ظرف (کلی) که مشتاقانه خواهان پُر شدن و تصحیح معنوی است." },
    { f: "چرا تکرار مکانیکی واژه‌ها دعایی اصیل به شمار نمی‌آید؟", b: "زیرا اگر دل در طلب آنچه زبان می‌گوید نتپد، کلمات کالبدهایی مرده و فاقد پویایی و نیروی معنوی باقی می‌مانند." },
    { f: "نخستین شرط اجابت و شنیده شدن دعا چیست؟", b: "ایمانی استوار و صخره‌وار به اینکه آفریدگار براستی قادر است انسان را از سیاه‌چال خودخواهی نجات بخشد." },
    { f: "دومین شرط اجابت و شنیده شدن دعا چیست؟", b: "درک اینکه هیچ چاره دیگری نیست: تمامی توان‌های بشری بی‌ثمر مانده و تنها آفریدگار می‌تواند یاری رساند." },
    { f: "سومین شرط اجابت و شنیده شدن دعا چیست؟", b: "اینکه تقاضا حقیقتاً مسئله مرگ و زندگی باشد که بدون تحقق آن روح در چنگال میل به دریافت هلاک می‌گردد." },
    { f: "دعا چگونه در نقش یک 'واسطه' (مدیوم) در تکامل معنوی عمل می‌کند؟", b: "هدفش دگرگونی آفریدگار نیست، بلکه خودِ انسان را متحول می‌سازد و کلی را برای دریافت نور بخشش مهیا می‌نماید." },
    { f: "کبالیست در دعای حقیقی به عنوان یک واسطه چه تمنایی دارد؟", b: "منحصراً کمبود برای بخشش (میل به ایثار و عطا) و تشابه فرم و صفات با آفریدگار را طلب می‌کند." },
    { f: "پیام بنیادین مقاله ۲۰ کتاب 'شماتی' درباره نیل به مقام 'لیشما' چیست؟", b: "لیشما (به خاطر نام او / ایثار بی‌چشمداشت) موهبت و نوری از بالاست که خرد انسان به تنهایی یارای فهم و کسب آن را ندارد." },
    { f: "اگر لیشما هدیه‌ای از بالاست، چرا تلاش و رنج انسان ضروری است؟", b: "چرا که کوشش‌ها و وسایل در درون انسان ظروف اصلاح‌شده‌ای (کلیم) می‌سازند که قلباً مشتاق دریافت لیشما هستند." },
    { f: "نقش شکست و ناتوانی در دعا بر اساس شماتی ۲۰ چیست؟", b: "وقتی انسان بیهودگی افعال خود را مشاهده می‌کند، به درماندگی تام می‌رسد و تازه در آن دم می‌تواند از بن دندان فریاد برآورد." },
    { f: "چه وقت انسان قادر به ادای دعایی مخلصانه از اعماق قلب خویش است؟", b: "تنها پس از آزمودن همه چاره‌های انسانی و اذعان به اینکه به تنهایی و بدون آفریدگار از عهده هیچ کاری برنمی‌آید." },
    { f: "مفهوم 'مان' (مایین نوکوین) بیانگر چیست؟", b: "آب‌های مؤنث؛ کمبود، دعا و بیداری صعودکننده از ظرف فرودین که فراوانی و نور را از بالا فرومی‌کشد." },
    { f: "نقش 'بیداری از پایین' در نظام معنوی چیست؟", b: "بیداری از پایین (دعای آفریده) موجب به جریان افتادن و ریزش انوار علیا (ماد - مایین دخارین) می‌گردد." },
    { f: "اصل 'آن‌که برای پاک شدن می‌آید یاری‌اش می‌کنند' به چه معناست؟", b: "هر که از سر صدق خواهان ایثار و پاکی باشد، آفریدگار از بالا قدرت، تصحیح و تعالی بر طبیعتش را بدو می‌بخشد." },
    { f: "آفریدگار دقیقاً چگونه کسی را که برای پاک شدن آمده یاری می‌بخشد؟", b: "با اهدای مرتبه لیشما، بیدار ساختن قلبش و بخشیدن نیرویی فوق‌طبیعی که فراتر از طبیعت خودخواهانه اوست." },
    { f: "'کار در قلب' در جریان تبیین‌های درونی روزانه چیست؟", b: "جداسازی امیال نفسانی از خواست بخشش، همراه با دعای پیوسته برای دگرگون گشتن سرشت خویش." },
    { f: "چرا آفریدگار به واسطه دعا دستخوش هیچ دگرگونی نمی‌شود؟", b: "زیرا آفریدگار خیر مطلق و تغییرناپذیر است؛ دعا ظرف گیرنده را متحول و آن را پذیرای تابش نور می‌سازد." },
    { f: "تفاوت میان دعای مرسوم دینی و دعای کبالایی چیست؟", b: "دعای عامیانه در پی مواهب مادی یا آسودگی نفس است، حال آنکه دعای کبالایی رهایی از چنگال خودخواهی را التماس می‌کند." },
    { f: "یک خیسارون اصیل چگونه در مسیر معنوی زاده می‌شود؟", b: "از طریق کار پیگیر در گروه و مطالعه منابع اصیل، زمانی که کمبود به عنوان فقدان نور بخشش ادراک می‌گردد." },
    { f: "اینکه تن 'با یوغ پادشاهی آسمان سر سازگاری ندارد' یعنی چه؟", b: "میل طبیعی به دریافت، غریزتاً از کار کردن صرفاً به نیت خشنودی آفریدگار و بدون پاداش شخصی ابا دارد." },
    { f: "چاره آدمی هنگامی که می‌بیند تمام اندام‌هایش در برابر بخشش مقاومت می‌کنند چیست؟", b: "چاره‌ای جز دعا ندارد: دلش را پیشگاه آفریدگار بگشاید تا او تن را به زیر فرمان بخشش درآورد." },
    { f: "دستیابی به لیشما چگونه گرایش به بدی (نفس اماره) را از پای درمی‌آورد؟", b: "خوددوستی را باطل می‌کند؛ ظروف دریافت کارکرد خودخواهانه را باخته و در معنای روحانی 'مرده' تلقی می‌شوند." },
    { f: "چرا آگاهی از اینکه بدون دعا رسیدن به لیشما محال است، حیاتی است؟", b: "زیرا این آگاهی دعا را به نیازی قطعی و مبرم بدل می‌سازد و توهم خودبسندگی را تارومار می‌کند." },
    { f: "پیوند میان بالا بردن مان و ظرف روح در چیست؟", b: "مان خودِ همان کمبود در کلی است؛ هر اندازه این فقر و نقص زلال‌تر و عمیق‌تر باشد، نوری که ظرف پذیرای آن است فزون‌تر است." },
    { f: "دعا از چه حیث اعتراف به ناتوانی و شکست نفس است؟", b: "قلب وابستگی مطلقش را آشکار ساخته و تصدیق می‌کند که خودخواهی‌اش بدون یاری الهی حصاری تسخیرناپذیر است." },
    { f: "کار در گروه چگونه با دعای فردی درهم می‌آمیزد؟", b: "تلاش برای مهرورزی به یاران، ناتوانی مطلق در ایثار خالصانه را برملا کرده و فریاد استمدادی راستین می‌آفریند." },
    { f: "چرا دعا به منزله آفرینشِ خودِ ظرف معنوی شمرده می‌شود؟", b: "زیرا لبریز شدن تنها در جایی رخ می‌دهد که کمبودی متناظر باشد؛ دعا این خلأ روحی را هویدا و فراخ می‌سازد." },
    { f: "تعبیر 'آفریدگار دعا را می‌شنود' متضمن چه معنایی است؟", b: "تمنا در طنین و رزونانس کامل با قانون برتر بخشش قرار می‌گیرد و نور بی درنگ کلیِ گشوده را سرشار می‌سازد." },
    { f: "نقش یأس معنوی در شکل‌گیری و زایش دعا چیست؟", b: "بیانگر فرسودگی کامل قوای نفسانی است، که طلیعه بی‌واسطه فرود آمدن نصرت و دستگیری از بالاست." },
    { f: "'بیداری از بالا' (ایتاروتا دلعیلا) چیست؟", b: "تجلی و تابش نور برین که در پاسخی مستقیم به کمبودی بالیده و تصفیه‌شده از فرودست (مان) نازل می‌شود." },
    { f: "چرا در شماتی ۲۰ میل به دریافت به 'دزد' تشبیه شده است؟", b: "زیرا سعی دارد هر ذره نیرو و شادمانی را صرفاً برای عیاشی و لذت‌جویی نفسانی خویش غارت کند." },
    { f: "چرا آدمی در آغاز گام نهادن در مسیر ایثار هیچ حظ و حیاتی حس نمی‌کند؟", b: "تا میل به دریافت طعمی در آن نیابد؛ اگر لذت می‌برد، انسان هرگز نمی‌توانست به لیشمای ناب اوج گیرد." },
    { f: "چه هنگام عمل معنوی فی‌نفسه تبدیل به ابتهاج و شادمانی می‌گردد؟", b: "زمانی که انسان به بخشش خو کند و شادمان ساختن آفریدگار، پاداشِ اصیلِ خودِ این مجاهدت شود." },
    { f: "چه وقت گله‌گزاری در کار معنوی روا یا نارواست؟", b: "انسان تنها نزد صاحبی می‌تواند گلایه کند که حقیقتاً برای او کار کرده؛ کار برای خودخواهی حقی برای مطالبه نیرو ایجاد نمی‌کند." },
    { f: "تبیین درونی (برور) در دعا شامل چه مراحلی است؟", b: "غربال نیت‌ها: تفکیک آنچه برای التذاذ نفس انجام می‌پذیرد از آنچه حقیقتاً غرضش خشنودی آفریدگار است." },
    { f: "'کمال محض' در پذیرش یوغ پادشاهی آسمان چیست؟", b: "منحصراً طالب بخشش بودن و دست شستن سراسری از دریافت کردن به سود خویشتن." },
    { f: "چرا درک صرفاً عقلی برای دعای برآمده از دل کفایت نمی‌کند؟", b: "براهین فکری ظرف معنوی را تکان نمی‌دهند؛ تنها کمبودی راستین که در جان تجربه شود نور را جذب می‌کند." },
    { f: "مان چگونه از میان مراتب جهان‌های معنوی عبور کرده و عمل می‌کند؟", b: "مرتبه فرودین کمبودش را به مرتبه فرادست می‌سپارد و آن مرتبه آن را به سرچشمه برده و پاسخ را به زیر می‌آورد." },
    { f: "چرا دعا یگانه سلاح در پیکار علیه میل به دریافت خوانده شده است؟", b: "چون انسان قادر به تبدیل طبیعت آفریده‌شده خویش نیست؛ تنها می‌تواند به درگاه باری‌تعالی برای طبعی نوین بنالد." },
    { f: "چرا دعا فرآیندی پویا و مداوم است نه کاری آنی و زودگذر؟", b: "زیرا زنجیره‌ای از تقلاها و لغزش‌ها نقص درونی را صیقل داده و پخته می‌سازد تا به صداقت مطلق برسد." },
    { f: "ایمان به رستگاری در تاریک‌ترین احوال چگونه متجلی می‌گردد؟", b: "حتی وقتی تن هیچ گریزگاهی نمی‌بیند، نقطه در قلب یقین دارد که آفریدگار در چشم برهم‌زدنی می‌تواند برهاند." },
    { f: "اینکه 'آفریدگار در حسرت دعای صدیقان است' چه مفهومی دارد؟", b: "آفریدگار در انتظار کلی مهیا و آماده بخشش است، چه آنکه سرشت عشق او ریزش فیض و لبریز کردن است." },
    { f: "پیوند میان توبه (تشووا) و دعای کبالایی در چیست؟", b: "توبه وقوف دردناک بر شرارت طبع نفسانی است، و دعا استغاثه برای خلاصی و آزادی از چنگال آن است." },
    { f: "دعا چگونه سالک را از گزند کبر و غرور معنوی ایمن می‌دارد؟", b: "این آگاهی را ریشه‌دار می‌سازد که هر فتح معنوی، منحصراً لطفی رایگان و مرحمتی نامستحق از بالاست." },
    { f: "علت اینکه گاه دعایی بی‌پاسخ به نظر می‌رسد چیست؟", b: "کمبود هنوز به ژرفا یا خلوص لازم نرسیده است؛ ظرف هنوز گنجایش نگهداری نور را پیدا نکرده است." },
    { f: "'فرو ریختن دل در پیشگاه آفریدگار' به چه معناست؟", b: "سپردن بی قید و شرط تمامی آرزوهای پنهان، هراس‌ها و درماندگی‌ها به کف هدایت و ربوبیت آفریدگار." },
    { f: "کتاب ادعیه (سیدور) چگونه یاور کار باطنی کبالیست است؟", b: "همچون نقشه‌ای معنوی و دقیق از احوال درونی و مراتب اصلاح است که توسط واصلان نگاشته شده است." },
    { f: "چرا گذر به ساحت لیشما معجزه‌ای سترگ به شمار می‌آید؟", b: "زیرا دگرگون ساختن سرشت مخلوق (خودپرستی) به ایثار تام، تنها با قدرت دگرگون‌ساز نور امکان‌پذیر است." },
    { f: "دعا چگونه به گفت‌وگویی زنده و پویا با آفریدگار بدل می‌گردد؟", b: "زمانی که تپش‌های دل بازتابنده اشتیاق وصال باشند، پیوندی باطنی و کلامی بی‌واسطه برقرار می‌گردد." },
    { f: "حکمت 'پایان بردن کار بر تو واجب نیست، اما رها کردنش نیز روا نیست' چیست؟", b: "گرچه مقصود موهبتی از بالاست، اما محنت بنیاد نهادن طلب و کمبود تماماً بر دوش انسان نهاده شده است." },
    { f: "پیوند میان نیایش و محبت به یاران و دوستان چیست؟", b: "در رنج ایثار به دوستان است که ناتوانی از عشق راستین پرده برمی‌افکند و استغاثه‌ای جمعی می‌زاید." },
    { f: "محاسبه نفس پیش از دعا چگونه نیت را جلا داده و پالایش می‌کند؟", b: "انگیزه‌های خودخواهانه را رسوا، اهداف پوشالی را حذف و خروش جان را در یک نقطه حقیقت متمرکز می‌کند." },
    { f: "تفاوت میان انتظار منفعلانه با دعای حقیقی معنوی چیست؟", b: "انفعال بدون نبرد سپر می‌اندازد، حال آنکه دعا خروش جنگاوری است که تا واپسین رمق دست از ستیز نمی‌کشد." },
    { f: "نور تورات چگونه در بطن دعا بازتاب می‌یابد؟", b: "نور اصلاح‌گری که در حین مطالعه جذب می‌شود، ظلمت قلب را می‌شکافد و طلب استغفاری عمیق برای تصحیح برمی‌انگیزد." },
    { f: "اینکه دعای حقیقی 'از ژرفاها فریاد می‌کشد' به چه معناست؟", b: "فریادی که از قعر مغاکِ میل به دریافت و از تاریک‌ترین کنج زندان خودخواهی سر برمی‌آورد." },
    { f: "دعا چگونه رهنمون به دوکوت (چسبیدن و پیوستگی) با آفریدگار می‌شود؟", b: "با تحصیل خصلت بخشش، انسان به تشابه فرم با آفریدگار دست می‌یابد که همان یگانگی غایی است." },
    { f: "والاترین درس کاربردی درس ۱۸ درباره دعا و نیایش چیست؟", b: "به لقلقه زبان بسنده مکن؛ خیسارونی راستین در دلت بساز، چرا که آفریدگار تنها بر صدق دل پاسخ می‌دهد." }
  ],
  hy: [
    { f: "Ո՞րն է աղոթքի կաբալիստական սահմանումը:", b: "«Աշխատանք սրտում» (Ավոդա շեբաԼև)՝ Արարչի առջև ցանկությունների, մտադրությունների և պակասի խորը ներքին պարզաբանում:" },
    { f: "Ի՞նչ է ներկայացնում հոգևոր «սիրտը» Կաբալայում:", b: "Սիրտը ներկայացնում է մարդու ստանալու բոլոր ցանկությունների գումարը և նրա զգացմունքային ու կամային հակումների ամբողջությունը:" },
    { f: "Ինչպե՞ս են բերանի խոսքերը հարաբերվում սրտի ցանկության հետ:", b: "Արարիչը պատասխանում է բացառապես սրտի խորքում եղած ճշմարիտ պակասին (Հիսարոն), այլ ոչ թե շուրթերի մեխանիկական բառերին:" },
    { f: "Ի՞նչ է «Հիսարոն» հասկացությունը աղոթքում:", b: "Իսկական ներքին պակաս, անոթի (Կլի) դատարկություն, որը բուռն կերպով տենչում է լցման և հոգևոր ուղղման:" },
    { f: "Ինչո՞ւ բառերի մեխանիկական կրկնությունը չի համարվում իսկական աղոթք:", b: "Քանի որ եթե սիրտը չի տենչում այն, ինչ արտասանում են շուրթերը, բառերը մնում են մեռած ձևեր՝ զուրկ հոգևոր կենսունակությունից:" },
    { f: "Ո՞րն է աղոթքի լսելի լինելու առաջին պայմանը:", b: "Անսասան հավատ առ այն, որ Արարիչն իսկապես ի զորու է ազատել մարդուն եսասիրության բանտից:" },
    { f: "Ո՞րն է աղոթքի լսելի լինելու երկրորդ պայմանը:", b: "Այն գիտակցումը, որ այլ ելք չկա. մարդկային բոլոր ուժերը ձախողվել են, և միայն Արարիչը կարող է օգնել:" },
    { f: "Ո՞րն է աղոթքի լսելի լինելու երրորդ պայմանը:", b: "Որ խնդրանքն իսկապես լինի կյանքի ու մահվան հարց, առանց որի լուծման հոգին կործանվում է ստանալու ցանկության մեջ:" },
    { f: "Ինչպե՞ս է աղոթքը գործում որպես «մեդիում» (միջնորդ) հոգևոր զարգացման մեջ:", b: "Այն չի ձգտում փոխել Արարչին, այլ վերափոխում է մարդուն՝ նախապատրաստելով Կլին պարգևման լույսն ընդունելու համար:" },
    { f: "Ի՞նչ է խնդրում կաբալիստը ճշմարիտ աղոթքում որպես մեդիում:", b: "Բացառապես պարգևման պակասը (տալու ցանկությունը) և Արարչի հետ ձևի նույնականությունը:" },
    { f: "Ո՞րն է Շամատի 20-րդ հոդվածի գլխավոր ուղերձը Լիշմային հասնելու վերաբերյալ:", b: "Լիշման (Հանուն Նրա Անվան / անշահախնդիր պարգևում) Վերևից եկող պարգև և լուսավորություն է, որը մարդկային միտքը միայնակ չի կարող նվաճել:" },
    { f: "Եթե Լիշման պարգև է Վերևից, ինչո՞ւ է անհրաժեշտ մարդկային ջանքը:", b: "Քանի որ ջանքերն ու միջոցները մարդու մեջ կառուցում են ուղղված անոթները (Կելիմ), որոնք իսկապես ցանկանում են ստանալ Լիշման:" },
    { f: "Ի՞նչ դեր ունեն ձախողումն ու անզորությունը աղոթքում ըստ Շամատի 20-ի:", b: "Երբ մարդ տեսնում է իր բոլոր գործողությունների ապարդյուն լինելը, նա հասնում է կատարյալ անզորության, և միայն այդ ժամանակ կարող է աղաղակել սրտի խորքից:" },
    { f: "Ե՞րբ է մարդն ընդունակ անկեղծ աղոթք առաքել իր սրտի խորքից:", b: "Միայն այն բանից հետո, երբ փորձել է բոլոր մարդկային միջոցները և գիտակցել, որ ինքնուրույն՝ առանց Արարչի, ոչնչի չի կարող հասնել:" },
    { f: "Ի՞նչ է նշանակում «ՄԱՆ» (Մայիմ Նուկվին) հասկացությունը:", b: "Իգական ջրեր. պակասը, աղոթքը և զարթոնքը, որոնք բարձրանում են ստորին անոթից և ներքև են ձգում առատությունն ու Լույսը Վերևից:" },
    { f: "Ո՞րն է «ներքևից եկող զարթոնքի» դերը հոգևոր համակարգում:", b: "Ներքևից եկող զարթոնքը (արարածի աղոթքը) գործարկում է Վերին Լույսերի (ՄԱԴ – Մայիմ Դեխրին) հոսքը:" },
    { f: "Ի՞նչ է նշանակում «Նրան, ով գալիս է մաքրվելու, օգնում են» սկզբունքը:", b: "Նրան, ով անկեղծորեն ձգտում է պարգևման և մաքրության, Արարիչը Վերևից ուժ, ուղղում և իր բնությունից վեր բարձրացում է պարգևում:" },
    { f: "Ինչպե՞ս է Արարիչն օգնում նրան, ով գալիս է մաքրվելու:", b: "Շնորհելով նրան Լիշմայի աստիճանը, արթնացնելով նրա սիրտը և տալով գերբնական ուժ, որը գերազանցում է նրա եսասիրական բնությունը:" },
    { f: "Ի՞նչ է «աշխատանքը սրտում» ամենօրյա ներքին պարզաբանման ժամանակ:", b: "Եսասիրական ցանկությունների զատումը տալու ցանկությունից՝ սեփական բնության վերափոխման համար անդադար աղոթքով:" },
    { f: "Ինչո՞ւ Արարիչը չի փոխվում աղոթքի միջոցով:", b: "Քանի որ Արարիչը Բացարձակ Բարի է և Անփոփոխ. աղոթքը փոխում է ընդունող անոթը՝ դարձնելով այն Լույսն ընդունելու ունակ:" },
    { f: "Ո՞րն է տարբերությունը սովորական կրոնական և կաբալիստական աղոթքի միջև:", b: "Սովորական աղոթքը հայցում է նյութական բարիքներ կամ սփոփանք եսի համար, մինչդեռ կաբալիստական աղոթքն աղերսում է ազատագրում հենց եսասիրությունից:" },
    { f: "Ինչպե՞ս է հոգևոր ճանապարհին ծնվում ճշմարիտ Հիսարոնը:", b: "Խմբում տքնաջան աշխատանքի և աղբյուրների ուսումնասիրության միջոցով, երբ պակասը հստակեցվում է որպես պարգևման լույսի բացակայություն:" },
    { f: "Ի՞նչ է նշանակում, որ մարմինը «համաձայն չէ Երկնային Թագավորության լծի հետ»:", b: "Ստանալու բնածին ցանկությունը բնազդաբար դիմադրում է բացառապես Արարչին հաճույք պատճառելու աշխատանքին՝ առանց անձնական հատուցման:" },
    { f: "Ի՞նչ պետք է անի մարդը, երբ տեսնում է, որ իր բոլոր օրգանները դիմադրում են պարգևմանը:", b: "Նա չունի այլ ելք, քան աղոթքը. դատարկել իր սիրտը Արարչի առջև, որպեսզի Նա ստիպի մարմնին խոնարհվել պարգևմանը:" },
    { f: "Ինչպե՞ս է Լիշմային հասնելը սպանում չար նախատրամադրվածությունը:", b: "Այն չեղարկում է եսասիրությունը. ստանալու անոթները կորցնում են իրենց եսասիրական գործառույթը և հոգևոր առումով համարվում են «մեռած»:" },
    { f: "Ինչո՞ւ է կարևոր իմանալ, որ առանց աղոթքի Լիշմային հասնելն անհնար է:", b: "Քանի որ այս գիտակցումը աղոթքը դարձնում է բացարձակ և հրատապ անհրաժեշտություն՝ ցրելով ինքնաբավարարվածության պատրանքը:" },
    { f: "Ո՞րն է կապը ՄԱՆ-ի բարձրացման և հոգու անոթի միջև:", b: "ՄԱՆ-ը հենց Կլիի պակասն է. որքան մաքուր և խորն է այդ պակասը, այնքան ավելի մեծ Լույս կարող է ընդունել անոթը:" },
    { f: "Ի՞նչ իմաստով է աղոթքը եսասիրության անզորության խոստովանություն:", b: "Սիրտը բացահայտում է իր լիակատար կախվածությունը՝ խոստովանելով, որ սեփական եսը անանցանելի բանտ է առանց աստվածային օգնության:" },
    { f: "Ինչպե՞ս է խմբային աշխատանքը միահյուսվում անձնական աղոթքի հետ:", b: "Ընկերներին սիրելու ջանքը մերկացնում է անշահախնդիր պարգևելու կատարյալ անկարողությունը՝ ծնելով օգնության ճշմարիտ ճիչ:" },
    { f: "Ինչո՞ւ է աղոթքը համարվում բուն հոգևոր անոթի ստեղծումը:", b: "Քանի որ լցվելը կարող է մուտք գործել միայն այնտեղ, որտեղ կա համապատասխան դատարկություն. աղոթքը սահմանում և ընդլայնում է այս հոգևոր վակուումը:" },
    { f: "Ի՞նչ է նշանակում «Արարիչը լսում է աղոթքը» արտահայտությունը:", b: "Խնդրանքը մտնում է կատարյալ ռեզոնանսի մեջ պարգևման վերին օրենքի հետ, և Լույսն ակնթարթորեն լցնում է բացված Կլին:" },
    { f: "Ի՞նչ դեր ունի հոգևոր հուսահատությունը աղոթքի ծննդյան մեջ:", b: "Այն նշանավորում է եսասիրական ուժերի լիակատար սպառումը, ինչն անմիջապես նախորդում է Վերևից եկող փրկությանը:" },
    { f: "Ի՞նչ է «զարթոնքը Վերևից» (Իտարութա դե-Լեյլա):", b: "Վերին Լույսի հայտնությունը, որն իջնում է որպես ուղիղ պատասխան ներքևից բարձրացած հասուն և մաքրված պակասին (ՄԱՆ):" },
    { f: "Ինչո՞ւ է ստանալու ցանկությունը Շամատի 20-ում համեմատվում «գողի» հետ:", b: "Որովհետև այն փորձում է գողանալ և յուրացնել էներգիայի ու ուրախության յուրաքանչյուր հատիկ բացառապես իր եսասիրական հաճույքի համար:" },
    { f: "Ինչո՞ւ մարդը սկզբում ոչ մի ուրախություն չի զգում պարգևման աշխատանքում:", b: "Որպեսզի ստանալու ցանկությունը դրանում համ չգտնի. եթե նա եսասիրական հաճույք զգար, մարդը երբեք չէր բարձրանա դեպի մաքուր Լիշմա:" },
    { f: "Ե՞րբ է հոգևոր աշխատանքն ինքնին դառնում ուրախություն:", b: "Երբ մարդը սովորում է պարգևել, և Արարչին հաճույք պատճառելը դառնում է տքնանքի բուն վարձատրությունը:" },
    { f: "Ե՞րբ է հոգևոր աշխատանքում տրտնջալն արդարացված կամ անհիմն:", b: "Մարդը կարող է գանգատվել միայն այն տիրոջից, ում համար իրականում աշխատում է. աշխատելով եսի համար՝ նա իրավունք չունի ուժ պահանջել Արարչից:" },
    { f: "Ի՞նչ է ներքին պարզաբանումը (Բերուր) աղոթքում:", b: "Մտադրությունների զտում. տարանջատել այն, ինչ արվում է սեփական եսի համար, նրանից, ինչն ուղղված է Արարչին ուրախացնելուն:" },
    { f: "Ի՞նչ է «կատարյալ ամբողջականությունը» Երկնային Թագավորության լուծն ընդունելիս:", b: "Ցանկանալ բացառապես պարգևել և ամբողջությամբ հրաժարվել սեփական շահի համար ընդունելուց:" },
    { f: "Ինչո՞ւ ինտելեկտուալ ըմբռնումը բավարար չէ սրտի աղոթքի համար:", b: "Մտքի փաստարկները չեն շարժում հոգևոր անոթը. միայն սրտում ապրված իրական պակասն է ձգում Լույսը:" },
    { f: "Ինչպե՞ս է գործում ՄԱՆ-ը հոգևոր աշխարհների աստիճանների միջով:", b: "Ստորին աստիճանն իր պակասը բարձրացնում է վերինին, իսկ վերջինս այն հասցնում է Ակունքին՝ պատասխանն իջեցնելով ներքև:" },
    { f: "Ինչո՞ւ է աղոթքը կոչվում միակ զենքն ընդդեմ ստանալու ցանկության:", b: "Մարդը չի կարող ինքնուրույն փոխել իր արարված բնությունը. նա կարող է միայն աղաղակել առ Արարիչ՝ պարգևման նոր բնություն ստանալու համար:" },
    { f: "Ինչո՞ւ է աղոթքը շարունակական գործընթաց, այլ ոչ թե ակնթարթային գործողություն:", b: "Ջանքերի և վայրէջքների շղթան հղկում և հասունացնում է ներքին պակասը, մինչև այն հասնի բացարձակ անկեղծության:" },
    { f: "Ինչպե՞ս է դրսևորվում փրկության հանդեպ հավատն ամենախավար վիճակներում:", b: "Նույնիսկ երբ մարմինը ոչ մի ելք չի տեսնում, սրտի կետը վստահ է, որ Արարիչը կարող է փրկել աչքի թարթելու ընթացքում:" },
    { f: "Ի՞նչ է նշանակում «Արարիչը տենչում է արդարների աղոթքին»:", b: "Արարիչը սպասում է պատրաստված Կլիի, որն ընդունակ է պարգևելու, քանի որ Նրա սիրո բնույթն է լիություն շնորհել:" },
    { f: "Ո՞րն է կապը ապաշխարության (Թշուվա) և կաբալիստական աղոթքի միջև:", b: "Ապաշխարությունը եսասիրական բնության ցավալի գիտակցումն է, իսկ աղոթքը՝ դրանից ազատագրվելու աղերսանքը:" },
    { f: "Ինչպե՞ս է աղոթքը պաշտպանում մարդուն հոգևոր հպարտությունից:", b: "Այն ամրապնդում է այն գիտակցությունը, որ ցանկացած նվաճված հոգևոր աստիճան բացառապես անարժան նվեր և ողորմություն է Վերևից:" },
    { f: "Ինչո՞ւ է երբեմն թվում, թե աղոթքն անպատասխան է մնում:", b: "Պակասը դեռ չի հասել պահանջվող խորությանը կամ մաքրությանը. անոթը դեռ պատրաստ չէ Լույսը պահելու համար:" },
    { f: "Ի՞նչ է նշանակում «սիրտը դատարկել Արարչի առջև»:", b: "Բոլոր թաքուն ցանկությունների, վախերի և անզորության անվերապահ հանձնումը Արարչի կառավարմանը:" },
    { f: "Ինչպե՞ս է աղոթագիրքը (Սիդուր) օգնում կաբալիստի ներքին աշխատանքին:", b: "Այն ծառայում է որպես իմաստունների կողմից կազմված ներքին վիճակների և ուղղման գործընթացների ճշգրիտ հոգևոր քարտեզ:" },
    { f: "Ինչո՞ւ է Լիշմային անցումը համարվում գերագույն հրաշք:", b: "Որովհետև արարված բնությունը (եսասիրությունը) մաքուր ալտրուիզմի վերածելը հնարավոր է միայն Լույսի վերափոխող զորությամբ:" },
    { f: "Ինչպե՞ս է աղոթքը վերածվում կենդանի երկխոսության Արարչի հետ:", b: "Երբ սրտի թրթիռները ճշգրտորեն արտացոլում են Նրան կապվելու տենչը, բացվում է ուղիղ ներքին հաղորդակցություն:" },
    { f: "Ի՞նչ է նշանակում «Դու ազատ չես գործից հրաժարվելու» ասացվածքը:", b: "Թեև նպատակը պարգև է Վերևից, ցանկությունը և պակասը կառուցելու ծանր աշխատանքն ամբողջությամբ ընկած է մարդու վրա:" },
    { f: "Ո՞րն է կապը աղոթքի և ընկերների հանդեպ սիրո միջև:", b: "Ընկերներին պարգևելու ջանքերում ի հայտ է գալիս անշահախնդիր սիրելու կատարյալ անկարողությունը՝ ծնելով օգնության ճշմարիտ աղաղակ:" },
    { f: "Ինչպե՞ս է աղոթքից առաջ ինքնաքննությունը մաքրում մտադրությունը:", b: "Այն բացահայտում է թաքնված եսասիրական դրդապատճառները, հեռացնում կեղծ նպատակները և կենտրոնացնում ճիչը ճշմարտության մեկ կետում:" },
    { f: "Ո՞րն է տարբերությունը պասիվ սպասման և հոգևոր աղոթքի միջև:", b: "Պասիվությունը հանձնվում է առանց կռվի, մինչդեռ աղոթքը մինչև ուժերի վերջին սահմանը պայքարող ռազմիկի ծայրահեղ ճիչն է:" },
    { f: "Ինչպե՞ս է Թորայի Լույսն արտացոլվում աղոթքում:", b: "Ուսման ընթացքում ներգրավված Բարեփոխող Լույսը լուսավորում է սրտի խավարը՝ արթնացնելով ուղղման խորին աղերսանք:" },
    { f: "Ի՞նչ է նշանակում, որ ճշմարիտ աղոթքը «աղաղակում է խորքերից»:", b: "Մի ճիչ, որը բխում է ստանալու ցանկության հենց հատակից, եսի բանտի ամենախավար անդունդից:" },
    { f: "Ինչպե՞ս է աղոթքը տանում դեպի Դվեկուտ (միաձուլում) Արարչի հետ:", b: "Ձեռք բերելով պարգևման հատկությունը՝ մարդը հասնում է Արարչի հետ ձևի նույնականության, ինչը կատարյալ միասնություն է:" },
    { f: "Ո՞րն է 18-րդ դասի գլխավոր գործնական դասը աղոթքի մասին:", b: "Մի՛ բավարարվիր բառերի կրկնությամբ. կառուցի՛ր իսկական Հիսարոն քո սրտում, քանի որ Արարիչը լսում է միայն սրտի ճշմարտությունը:" }
  ],
  az: [
    { f: "Duanın kabbalistik tərifi nədir?", b: "'Ürəkdəki iş' (Avoda shebaLev) — Yaradanın hüzurunda arzuların, niyyətlərin və çatışmazlıqların dərindən daxili aydınlaşdırılmasıdır." },
    { f: "Qabbalada mənəvi 'ürək' nəyi təmsil edir?", b: "Ürək insanın bütün almaq arzularının cəmini və onun emosional və iradi meyllərinin məcmusunu təmsil edir." },
    { f: "Ağzın sözləri ilə ürəyin arzusu necə əlaqələnir?", b: "Yaradan dodaqların mexaniki sözlərinə deyil, yalnız və yalnız ürəyin dərinliyindəki həqiqi çatışmazlığa (Hisaron) cavab verir." },
    { f: "Duada 'Hisaron' anlayışı nədir?", b: "Həqiqi daxili çatışmazlıq, dolmağa və mənəvi islahata ehtirasla can atan qabın (Kli) daxili boşluğudur." },
    { f: "Sözlərin mexaniki təkrarı niyə əsl dua sayılmır?", b: "Çünki əgər ürək dodaqların dediyini arzulamırsa, sözlər mənəvi həyatverici qüvvədən məhrum cansız formalar olaraq qalır." },
    { f: "Duanın qəbul olunmasının birinci şərti nədir?", b: "Yaradanın insanı eqoizmin zindanından xilas etməyə həqiqətən qadir olduğuna dair sarsılmaz inam." },
    { f: "Duanın qəbul olunmasının ikinci şərti nədir?", b: "Başqa heç bir seçimin olmadığının dərk edilməsi: bütün insani qüvvələr tükənmişdir və yalnız Yaradan kömək edə bilər." },
    { f: "Duanın qəbul olunmasının üçüncü şərti nədir?", b: "Tələbin həqiqətən ölüm-dirim məsələsi olması, onsuz ruhun almaq arzusunun əlində həlak olmasıdır." },
    { f: "Dua mənəvi inkişafda necə bir 'vasitəçi' (medium) kimi fəaliyyət göstərir?", b: "O, Yaradanı dəyişdirməyə çalışmır, əksinə insanı dəyişdirir və Klini bəxşetmə nurunu qəbul etməyə hazırlayır." },
    { f: "Qabbalist bir vasitəçi olan həqiqi duada nə diləyir?", b: "Yalnız bəxşetmə çatışmazlığını (bəxş etmək arzusunu) və Yaradan ilə forma bərabərliyini diləyir." },
    { f: "Lişmaya çatmaq barədə Şamati 20-ci məqaləsinin əsas mesajı nədir?", b: "Lişma (Onun Adı naminə / təmənnasız bəxşetmə) insan ağlının təkbaşına fəth edə bilməyəcəyi, Yuxarıdan gələn bir hədiyyə və işıqlanmadır." },
    { f: "Əgər Lişma Yuxarıdan gələn hədiyyədirsə, insanın zəhməti nə üçün zəruridir?", b: "Çünki səylər və islah vasitələri insanda Lişmanı qəbul etməyi həqiqətən arzulayan düzəlmiş qabları (Kelim) inşa edir." },
    { f: "Şamati 20-yə görə uğursuzluq və acizlik duada hansı rolu oynayır?", b: "İnsan bütün əməllərinin puçluğunu gördükdə tam çarəsizliyə çatır və yalnız bundan sonra ürəyinin dərinliyindən fəryad edə bilir." },
    { f: "İnsan nə vaxt ürəyinin dərinliyindən səmimi bir dua etməyə qadir olur?", b: "Yalnız bütün insani vasitələri tükəndirdikdən və Yaradan olmadan təkbaşına heç bir şeyə nail ola bilməyəcəyini anladıqdan sonra." },
    { f: "'MAN' (Mayin Nukvin) anlayışı nə deməkdir?", b: "Qadın suları; aşağı qabdan yüksələn və Yuxarıdan bərəkət və Nur cəlb edən çatışmazlıq, dua və oyanışdır." },
    { f: "Mənəvi sistemdə 'aşağıdan gələn oyanışın' rolu nədir?", b: "Aşağıdan gələn oyanış (yaradılmışın duası) Yuxarı Nurların (MAD – Mayin Dehrin) axınını işə salır." },
    { f: "'Təmizlənməyə gələnə kömək edilər' prinsipi nə deməkdir?", b: "Bəxşetməyə və saflığa səmimi qəlbdən can atan kəsə Yaradan Yuxarıdan güc, islahat və təbiətindən ucalma bəxş edir." },
    { f: "Yaradan təmizlənməyə gələnə konkret olaraq necə kömək edir?", b: "Ona Lişma dərəcəsini bəxş edir, qəlbini oyadır və eqoist təbiətini aşan fövqəltəbii bir güc verir." },
    { f: "Gündəlik daxili aydınlaşma zamanı 'ürəkdəki iş' nədir?", b: "Eqoist arzuları bəxşetmə arzusundan fərqləndirmək və öz təbiətinin transformasiyası üçün fasiləsiz dua etməkdir." },
    { f: "Yaradan dua vasitəsilə niyə dəyişmir?", b: "Çünki Yaradan Mütləq Xeyirdir və Dəyişməzdir; dua alıcı qabı dəyişdirərək onu Nuru saxlamağa qadir edir." },
    { f: "Ənənəvi dini dua ilə kabbalistik dua arasındakı fərq nədir?", b: "Adi dua maddi nemətlər və ya eqo üçün yüngüllük istəyir, kabbalistik dua isə eqoizmin özündən qurtuluş üçün yalvarır." },
    { f: "Mənəvi yolda həqiqi Hisaron necə yaranır?", b: "Qrupda davamlı iş və mənbələri öyrənmək vasitəsilə; bu zaman çatışmazlıq bəxşetmə nurunun yoxluğu kimi aydınlaşır." },
    { f: "Bədənin 'Səma Padşahlığının boyunduruğu ilə razılaşmaması' nə deməkdir?", b: "Anadangəlmə almaq arzusu şəxsi qazanc olmadan sırf Yaradanın sevinci üçün çalışmağa instinktiv olaraq müqavimət göstərir." },
    { f: "Bütün üzvlərinin bəxşetməyə müqavimət göstərdiyini görən insan nə etməlidir?", b: "Duadan başqa heç bir çarəsi yoxdur: bədənini bəxşetməyə tabe etməsi üçün ürəyini Yaradanın önünə tökməlidir." },
    { f: "Lişmaya çatmaq şər meyli necə məhv edir?", b: "Özünü sevməyi ləğv edir; almaq qabları bencil funksiyasını itirir və mənəvi mənada 'ölü' sayılır." },
    { f: "Dua olmadan Lişmaya çatmağın qeyri-mümkün olduğunu bilmək nə üçün vacibdir?", b: "Çünki bu dərketmə duanı mütləq və təxirəsalınmaz bir zərurətə çevirərək arxayınlıq illüziyasını dağıdır." },
    { f: "MAN-ın qaldırılması ilə ruhun qabı arasında hansı əlaqə var?", b: "MAN Kli-nin çatışmazlığının özüdür; bu çatışmazlıq nə qədər təmiz və dərin olarsa, qab o qədər böyük Nuru qəbul edə bilər." },
    { f: "Dua hansı mənada eqoizmin acizliyinin etirafıdır?", b: "Qəlb özünün mütləq asılılığını açır və ilahi kömək olmadan öz eqosunun alınmaz bir zindan olduğunu etiraf edir." },
    { f: "Qrupdakı iş şəxsi dua ilə necə birləşir?", b: "Dostları sevmək cəhdi təmənnasız sevməkdəki tam acizliyi üzə çıxarır və həqiqi bir kömək fəryadı doğurur." },
    { f: "Dua nə üçün mənəvi qabın bilavasitə yaradılması hesab olunur?", b: "Çünki dolma yalnız müvafiq boşluğun olduğu yerə daxil ola bilər; dua bu mənəvi vakuumu müəyyənləşdirir və genişləndirir." },
    { f: "'Yaradan duanı eşidir' ifadəsi nə deməkdir?", b: "Tələb üst bəxşetmə qanunu ilə tam rezonansa girir və Nur açılmış Klini dərhal doldurur." },
    { f: "Mənəvi ümidsizlik duanın yaranmasında hansı rolu oynayır?", b: "Eqoist qüvvələrin tam tükənməsini bildirir ki, bu da bilavasitə Yuxarıdan köməyin gəlməsindən əvvəl baş verir." },
    { f: "'Yuxarıdan oyanış' (İtaruta de-Leila) nədir?", b: "Aşağıdan yüksələn yetkin və təmizlənmiş çatışmazlığa (MAN) birbaşa cavab olaraq enən Ali Nurun zühurudur." },
    { f: "Şamati 20-də almaq arzusu nə üçün 'oğruya' bənzədilir?", b: "Çünki hər bir enerji və sevinc qığılcımını yalnız öz eqoist həzzi üçün oğurlamağa və mənimsəməyə çalışır." },
    { f: "İnsan bəxşetmək naminə işdə əvvəlcə niyə heç bir sevinc hiss etmir?", b: "Almaq arzusu onda ləzzət tapmasın deyə; əgər eqoist zövq alsaydı, insan heç vaxt təmiz Lişmaya yüksələ bilməzdi." },
    { f: "Mənəvi iş nə vaxt özlüyündə bir sevinclə çevrilir?", b: "İnsan bəxş etməyə alışdıqda və Yaradana sevinc bəxş etmək zəhmətin ən böyük mükafatı olduqda." },
    { f: "Mənəvi işdə gileylənmək nə vaxt əsaslı və ya əsassızdır?", b: "İnsan yalnız həqiqətən işlədiyi ağaya şikayət edə bilər; eqo üçün çalışaraq Yaradandan güc tələb etmək haqqı yoxdur." },
    { f: "Duada daxili aydınlaşma (Berur) nədir?", b: "Niyyətlərin seçilməsi: öz eqosuna xidmət edənləri Yaradanı sevindirməyə yönəlmiş olanlardan ayırmaqdır." },
    { f: "Səma Padşahlığının boyunduruğunu qəbul edərkən 'tam kamillik' nədir?", b: "Yalnız bəxş etməyi istəmək və öz mənfəəti üçün almaqdan tamamilə imtina etməkdir." },
    { f: "Nə üçün intellektual anlama qəlbin duası üçün kifayət deyil?", b: "Ağlın arqumentləri mənəvi qabı hərəkətə gətirmir; yalnız ürəkdə yaşanan real çatışmazlıq Nuru cəlb edir." },
    { f: "MAN mənəvi dünyaların dərəcələri boyunca necə fəaliyyət göstərir?", b: "Aşağı dərəcə öz çatışmazlığını yuxarı dərəcəyə qaldırır, o da bunu Mənbəyə çatdıraraq cavabı aşağı endirir." },
    { f: "Dua nə üçün almaq arzusuna qarşı yeganə silah adlanır?", b: "İnsan öz yaradılmış təbiətini təkbaşına dəyişə bilməz; o, yalnız yeni bəxşetmə təbiəti əldə etmək üçün Yaradana yalvara bilər." },
    { f: "Dua nə üçün anlıq bir hərəkət deyil, davamlı bir prosesdir?", b: "Zəhmətlər və enişlər silsiləsi daxili çatışmazlığı cilalayır və mütləq səmimiyyətə çatana qədər yetişdirir." },
    { f: "Ən qaranlıq hallarda qurtuluşa inam necə təzahür edir?", b: "Bədən heç bir çıxış yolu görmədikdə belə, qəlbdəki nöqtə Yaradanın bir göz qırpımında xilas edə biləcəyinə əmindir." },
    { f: "'Yaradan salehlərin duasını arzulayır' kəlamı nə deməkdir?", b: "Yaradan bəxş etməyə qadir olan hazır bir Kli gözləyir, çünki Onun məhəbbətinin təbiəti dolğunluq bəxş etməkdir." },
    { f: "Tövbə (Tşuva) ilə kabbalistik dua arasında hansı əlaqə var?", b: "Tövbə eqoist təbiətin ağrılı şəkildə dərk edilməsidir, dua isə ondan xilas olmaq üçün yalvarışdır." },
    { f: "Dua insanı mənəvi təkəbbürdən necə qoruyur?", b: "Hər bir əldə edilmiş mənəvi səviyyənin yalnız layiq olunmayan bir hədiyyə və Yuxarıdan gələn mərhəmət olduğu şüurunu möhkəmləndirir." },
    { f: "Bəzən duanın cavabsız qaldığı təəssüratı niyə yaranır?", b: "Çatışmazlıq hələ lazımi dərinliyə və ya saflığa çatmayıb; qab hələ Nuru saxlamağa hazır deyil." },
    { f: "'Qəlbi Yaradanın önünə tökmək' nə deməkdir?", b: "Bütün gizli arzuların, qorxuların və çarəsizliyin qeyd-şərtsiz Yaradanın idarəsinə təslim edilməsidir." },
    { f: "Dua kitabı (Siddur) kabbalistin daxili işinə necə kömək edir?", b: "Müdriklər tərəfindən tərtib edilmiş daxili halların və islahat proseslərinin dəqiq mənəvi xəritəsi kimi xidmət edir." },
    { f: "Lişmaya keçid nə üçün möcüzə hesab olunur?", b: "Çünki yaradılmış təbiəti (özünü sevməyi) saf altruizmə çevirmək yalnız Nurun dəyişdirici gücü ilə mümkündür." },
    { f: "Dua Yaradanla canlı bir dialoqa necə çevrilir?", b: "Qəlbin döyüntüləri Ona qovuşmaq arzusunu dəqiqliklə əks etdirdikdə, birbaşa daxili ünsiyyət açılır." },
    { f: "'İşi başa çatdırmaq sənin borcun deyil, lakin ondan boyun qaçırmağa da ixtiyarın yoxdur' nə deməkdir?", b: "Məqsəd Yuxarıdan verilsə də, arzunu və çatışmazlığı inşa etmək zəhməti tamamilə insanın üzərinə düşür." },
    { f: "Dua ilə dost sevgisi arasında hansı bağ var?", b: "Dostlara bəxş etmək səyində təmənnasız sevməkdəki tam acizlik üzə çıxır və bu da həqiqi bir kömək harayı doğurur." },
    { f: "Duadan əvvəlki daxili hesabat niyyəti necə təmizləyir?", b: "Gizli eqoist motivləri ifşa edir, saxta hədəfləri kənarlaşdırır və harayı həqiqətin tək bir nöqtəsinə cəmləyir." },
    { f: "Passiv gözləmə ilə mənəvi dua arasındakı fərq nədir?", b: "Passivlik döyüşsüz təslim olur, dua isə son həddə qədər vuruşan döyüşçünün son fəryadıdır." },
    { f: "Tövratın Nuru duada necə əks olunur?", b: "Təhsil zamanı cəlb olunan İslah Edən Nur qəlbin qaranlığını işıqlandırır və islahat üçün dərin bir yalvarış oyadır." },
    { f: "Həqiqi duanın 'dərinliklərdən fəryad etməsi' nə deməkdir?", b: "Almaq arzusunun ən dibindən, eqo zindanının ən qaranlıq uçurumundan qopan bir haraydır." },
    { f: "Dua Yaradanla Dvekuta (qovuşmağa) necə aparır?", b: "Bəxşetmə xüsusiyyətini əldə etməklə insan Yaradanla forma bərabərliyinə çatır ki, bu da mütləq birlikdir." },
    { f: "18-ci dərsin dua haqqında ən mühüm praktiki dərsi nədir?", b: "Sözləri təkrarlamaqla kifayətlənmə; qəlbində həqiqi bir Hisaron qur, çünki Yaradan yalnız qəlbin həqiqətini eşidir." }
  ],
  ka: [
    { f: "რა არის ლოცვის კაბალისტური განსაზღვრება?", b: "«შრომა გულში» (ავოდა შებალევ) — სურვილების, განზრახვებისა და ნაკლებობის ღრმა შინაგანი გარკვევა შემოქმედის წინაშე." },
    { f: "რას წარმოადგენს სულიერი «გული» კაბალაში?", b: "გული განასახიერებს ადამიანის მიღების ყველა სურვილის ჯამსა და მისი ემოციური და ნებითი სწრაფვების ერთობლიობას." },
    { f: "როგორ ეთანადება პირის სიტყვები გულის სურვილს?", b: "შემოქმედი პასუხობს მხოლოდ და მხოლოდ გულის სიღრმეში არსებულ ჭეშმარიტ ნაკლებობას (ხისარონს) და არა ბაგეთა მექანიკურ სიტყვებს." },
    { f: "რა არის «ხისარონის» ცნება ლოცვაში?", b: "ჭეშმარიტი შინაგანი ნაკლებობა, ჭურჭლის (კლის) სიცარიელე, რომელიც ვნებიანად ესწრაფვის აღვსებასა და სულიერ შესწორებას." },
    { f: "რატომ არ მიიჩნევა სიტყვების მექანიკური გამეორება ჭეშმარიტ ლოცვად?", b: "იმიტომ, რომ თუ გული არ ესწრაფვის იმას, რასაც ბაგეები წარმოთქვამენ, სიტყვები რჩება მკვდარ ფორმებად სულიერი ძალის გარეშე." },
    { f: "რა არის ლოცვის შესმენის პირველი პირობა?", b: "ურყევი რწმენა იმისა, რომ შემოქმედს ნამდვილად შესწევს ძალა, დაიხსნას ადამიანი ეგოიზმის საპყრობილიდან." },
    { f: "რა არის ლოცვის შესმენის მეორე პირობა?", b: "იმის გაცნობიერება, რომ სხვა არჩევანი არ არსებობს: ყველა ადამიანურმა ძალამ მარცხი განიცადა და მხოლოდ შემოქმედს შეუძლია დახმარება." },
    { f: "რა არის ლოცვის შესმენის მესამე პირობა?", b: "რომ თხოვნა ნამდვილად იყოს სიცოცხლისა და სიკვდილის საკითხი, რომლის გარეშეც სული იღუპება მიღების სურვილში." },
    { f: "როგორ მოქმედებს ლოცვა, როგორც «მედიუმი» (შუამავალი) სულიერ ევოლუციაში?", b: "ის არ ცდილობს შემოქმედის შეცვლას, არამედ გარდაქმნის ადამიანს და ამზადებს კლის გაცემის ნათელის მისაღებად." },
    { f: "რას ითხოვს კაბალისტი ჭეშმარიტ ლოცვაში, როგორც მედიუმში?", b: "მხოლოდ და მხოლოდ გაცემის ნაკლებობას (გაცემის სურვილს) და შემოქმედთან ფორმის მსგავსებას." },
    { f: "რა არის შამათის მე-20 სტატიის მთავარი გზავნილი ლიშმას მიღწევის შესახებ?", b: "ლიშმა (მისი სახელისთვის / უანგარო გაცემა) არის საჩუქარი და ნათება ზემოდან, რომელსაც ადამიანის გონება დამოუკიდებლად ვერ მიაღწევს." },
    { f: "თუ ლიშმა საჩუქარია ზემოდან, რატომ არის აუცილებელი ადამიანის ძალისხმევა?", b: "იმიტომ, რომ ძალისხმევა და საშუალებები ადამიანში აშენებენ შესწორებულ ჭურჭლებს (კელიმ), რომლებსაც გულწრფელად სურთ მიიღონ ლიშმა." },
    { f: "რა როლს თამაშობს წარუმატებლობა და უმწეობა ლოცვაში შამათი 20-ის მიხედვით?", b: "როდესაც ადამიანი ხედავს თავისი ქმედებების ამაოებას, ის აღწევს სრულ უმწეობას და მხოლოდ მაშინ შეუძლია შეჰღაღადოს გულის სიღრმიდან." },
    { f: "როდის ძალუძს ადამიანს აღავლინოს გულწრფელი ლოცვა გულის სიღრმიდან?", b: "მხოლოდ მას შემდეგ, რაც მოსინჯა ყველა ადამიანური საშუალება და აღიარა, რომ შემოქმედის გარეშე დამოუკიდებლად არაფრის მიღწევა არ შეუძლია." },
    { f: "რას ნიშნავს ცნება «მან» (მაიინ ნუკვინ)?", b: "ქალური წყლები; ნაკლებობა, ლოცვა და გამოღვიძება, რომლებიც აღმოდის ქვედა ჭურჭლიდან და იზიდავს სიუხვესა და ნათელს ზემოდან." },
    { f: "რა როლი აქვს «ქვემოდან გამოღვიძებას» სულიერ სისტემაში?", b: "ქვემოდან გამოღვიძება (ქმნილების ლოცვა) იწვევს ზედა ნათელთა (მად – მაიინ დეხრინ) გადმოდინებას." },
    { f: "რას ნიშნავს პრინციპი «ვინც განსაწმენდად მოდის, მას ეხმარებიან»?", b: "მას, ვინც გულწრფელად ესწრაფვის გაცემასა და სიწმინდეს, შემოქმედი ზემოდან აძლევს ძალას, შესწორებასა და ამაღლებას საკუთარ ბუნებაზე." },
    { f: "კონკრეტულად როგორ ეხმარება შემოქმედი მას, ვინც განსაწმენდად მოდის?", b: "ჩუქნის მას ლიშმას საფეხურს, უღვიძებს გულს და ანიჭებს ზებუნებრივ ძალას, რომელიც აღემატება მის ეგოისტურ ბუნებას." },
    { f: "რა არის «შრომა გულში» ყოველდღიური შინაგანი გარკვევის დროს?", b: "ეგოისტური სურვილების გარჩევა გაცემის სურვილისგან საკუთარი ბუნების გარდაქმნისთვის განუწყვეტელი ლოცვით." },
    { f: "რატომ არ იცვლება შემოქმედი ლოცვით?", b: "იმიტომ, რომ შემოქმედი არის აბსოლუტური სიკეთე და უცვლელი; ლოცვა ცვლის მიმღებ ჭურჭელს, რათა მან შეძლოს ნათელის დატევა." },
    { f: "რა განსხვავებაა ჩვეულებრივ რელიგიურ და კაბალისტურ ლოცვას შორის?", b: "ჩვეულებრივი ლოცვა ითხოვს მატერიალურ სიკეთეებს ან შვებას ეგოსთვის, მაშინ როცა კაბალისტური ლოცვა ევედრება ეგოიზმისგან დახსნას." },
    { f: "როგორ იბადება ჭეშმარიტი ხისარონი სულიერ გზაზე?", b: "ჯგუფში დაუღალავი შრომითა და წყაროების შესწავლით, რა დროსაც ნაკლებობა ცხადდება, როგორც გაცემის ნათელის არარსებობა." },
    { f: "რას ნიშნავს, რომ სხეული «არ ეთანხმება ცათა სასუფევლის უღელს»?", b: "მიღების თანდაყოლილი სურვილი ინსტინქტურად ეწინააღმდეგება შრომას მხოლოდ შემოქმედის სასიამოვნოდ, პირადი სარგებლის გარეშე." },
    { f: "რა უნდა გააკეთოს ადამიანმა, როცა ხედავს, რომ მისი ყველა ორგანო ეწინააღმდეგება გაცემას?", b: "მას არ აქვს სხვა გამოსავალი, გარდა ლოცვისა: გული გადმოუღვაროს შემოქმედს, რათა მან აიძულოს სხეული, დაემორჩილოს გაცემას." },
    { f: "როგორ კლავს ლიშმას მიღწევა ბოროტ საწყისს?", b: "ის აუქმებს თვითსიყვარულს; მიღების ჭურჭლები კარგავენ ეგოისტურ ფუნქციას და სულიერად «მკვდრად» ითვლებიან." },
    { f: "რატომ არის სასიცოცხლოდ მნიშვნელოვანი იმის ცოდნა, რომ ლოცვის გარეშე ლიშმა მიუღწეველია?", b: "იმიტომ, რომ ეს გაცნობიერება ლოცვას აქცევს აბსოლუტურ და გადაუდებელ აუცილებლობად, რაც ფანტავს თვითკმაყოფილების ილუზიას." },
    { f: "რა კავშირია მან-ის აღმართვასა და სულის ჭურჭელს შორის?", b: "მან-ი თავად არის კლის ნაკლებობა; რაც უფრო სუფთა და ღრმაა ეს ნაკლებობა, მით უფრო დიდ ნათელს იტევს ჭურჭელი." },
    { f: "რა გაგებით არის ლოცვა ეგოიზმის უმწეობის აღიარება?", b: "გული ავლენს თავის სრულ დამოკიდებულებას და აღიარებს, რომ საკუთარი ეგო არის საპყრობილე, საიდანაც ღვთაებრივი შეწევნის გარეშე თავის დაღწევა შეუძლებელია." },
    { f: "როგორ ერწყმის ჯგუფური მუშაობა პირად ლოცვას?", b: "მეგობრების სიყვარულის მცდელობა ამხელს უანგარო გაცემის სრულ უუნარობას, რაც ბადებს ჭეშმარიტ შეძახილს დახმარებისთვის." },
    { f: "რატომ მიიჩნევა ლოცვა თავად სულიერი ჭურჭლის შექმნად?", b: "იმიტომ, რომ აღვსება შეიძლება შევიდეს მხოლოდ იქ, სადაც არის შესაბამისი სიცარიელე; ლოცვა განსაზღვრავს და აფართოებს ამ სულიერ ვაკუუმს." },
    { f: "რას ნიშნავს გამოთქმა «შემოქმედს ესმის ლოცვა»?", b: "თხოვნა სრულ რეზონანსში შედის გაცემის უმაღლეს კანონთან და ნათელი მყისიერად ავსებს გახსნილ კლის." },
    { f: "რა როლს თამაშობს სულიერი სასოწარკვეთა ლოცვის დაბადებაში?", b: "ის მიანიშნებს ეგოისტური ძალების სრულ ამოწურვაზე, რაც უშუალოდ უსწრებს წინ ზემოდან შეწევნის გარდმომოსვლას." },
    { f: "რა არის «გამოღვიძება ზემოდან» (ითარუთა დე-ლეილა)?", b: "უმაღლესი ნათელის გამოვლენა, რომელიც ეშვება ქვემოდან აღვლენილი მომწიფებული და განწმენდილი ნაკლებობის (მან) პირდაპირ პასუხად." },
    { f: "რატომ არის შედარებული მიღების სურვილი «ქურდთან» შამათი 20-ში?", b: "იმიტომ, რომ ის ცდილობს მოიპაროს და მიითვისოს ენერგიისა და სიხარულის ყოველი ნაწილაკი მხოლოდ საკუთარი ეგოისტური სიამოვნებისთვის." },
    { f: "რატომ არ გრძნობს ადამიანი თავდაპირველად სიხარულს გაცემისთვის შრომაში?", b: "რათა მიღების სურვილმა მასში გემო ვერ იპოვოს; ეგოისტური სიამოვნება რომ ეგრძნო, ადამიანი ვერასოდეს ამაღლდებოდა წმინდა ლიშმამდე." },
    { f: "როდის ხდება სულიერი შრომა თავისთავად სიხარული?", b: "როდესაც ადამიანი ეჩვევა გაცემას და შემოქმედისთვის სიამოვნების მინიჭება თავად ხდება გარჯის უდიდესი ჯილდო." },
    { f: "როდის არის დრტვინვა სულიერ შრომაში გამართლებული ან გაუმართლებელი?", b: "ადამიანს შეუძლია იჩივლოს მხოლოდ იმ ბატონთან, ვისთვისაც რეალურად მუშაობს; ეგოსთვის მუშაობისას შემოქმედისგან ძალების მოთხოვნის უფლება არ აქვს." },
    { f: "რა არის შინაგანი გარკვევა (ბერური) ლოცვაში?", b: "განზრახვების გადარჩევა: იმის გამიჯვნა, რაც კეთდება საკუთარი ეგოსთვის, იმისგან, რაც მიმართულია შემოქმედის სიხარულისკენ." },
    { f: "რა არის «სრული სრულყოფილება» ცათა სასუფევლის უღლის მიღებისას?", b: "გსურდეს მხოლოდ გაცემა და სრულად თქვა უარი საკუთარი სარგებლისთვის მიღებაზე." },
    { f: "რატომ არ არის საკმარისი ინტელექტუალური გაგება გულის ლოცვისთვის?", b: "გონების არგუმენტები არ ამოძრავებს სულიერ ჭურჭელს; მხოლოდ გულში განცდილი რეალური ნაკლებობა იზიდავს ნათელს." },
    { f: "როგორ მოქმედებს მან-ი სულიერი სამყაროების საფეხურებზე?", b: "ქვედა საფეხური თავის ნაკლებობას აღამაღლებს ზედასთან, რომელიც მას მიიტანს სათავემდე და პასუხს ჩამოუშვებს ქვემოთ." },
    { f: "რატომ ეწოდება ლოცვას ერთადერთი იარაღი მიღების სურვილის წინააღმდეგ?", b: "ადამიანს არ შეუძლია თავად შეცვალოს თავისი შექმნილი ბუნება; მას მხოლოდ ის ძალუძს, რომ შეჰღაღადოს შემოქმედს გაცემის ახალი ბუნების მისაღებად." },
    { f: "რატომ არის ლოცვა უწყვეტი პროცესი და არა წამიერი მოქმედება?", b: "ძალისხმევისა და დაცემის ჯაჭვი ხვეწს და ამწიფებს შინაგან ნაკლებობას, სანამ ის არ მიაღწევს აბსოლუტურ გულწრფელობას." },
    { f: "როგორ ვლინდება ხსნის რწმენა ყველაზე ბნელ მდგომარეობებში?", b: "მაშინაც კი, როდესაც სხეული ვერ ხედავს გამოსავალს, გულში არსებული წერტილი დარწმუნებულია, რომ შემოქმედს თვალის დახამხამებაში შეუძლია გადარჩენა." },
    { f: "რას ნიშნავს, რომ «შემოქმედს სწყურია მართალთა ლოცვა»?", b: "შემოქმედი ელოდება გაცემისთვის მომზადებულ კლის, რადგან მისი სიყვარულის ბუნებაა აღვსების ბოძება." },
    { f: "რა კავშირია სინანულსა (თშუვა) და კაბალისტურ ლოცვას შორის?", b: "სინანული არის ეგოისტური ბუნების მტკივნეული გაცნობიერება, ხოლო ლოცვა არის მისგან გათავისუფლების ვედრება." },
    { f: "როგორ იცავს ლოცვა ადამიანს სულიერი ქედმაღლობისგან?", b: "ის ამკვიდრებს შეგნებას, რომ ნებისმიერი მიღწეული სულიერი საფეხური არის მხოლოდ დაუმსახურებელი საჩუქარი და წყალობა ზემოდან." },
    { f: "რატომ ჩანს ზოგჯერ, რომ ლოცვა უპასუხოდ რჩება?", b: "ნაკლებობას ჯერ არ მიუღწევია საჭირო სიღრმისა თუ სიწმინდისთვის; ჭურჭელი ჯერ არ არის მზად ნათელის შესაკავებლად." },
    { f: "რას ნიშნავს «გულის გადმოღვრა შემოქმედის წინაშე»?", b: "ყველა ფარული სურვილის, შიშისა და უმწეობის უპირობო გადაცემა შემოქმედის მმართველობის ქვეშ." },
    { f: "როგორ ეხმარება ლოცვანი (სიდური) კაბალისტის შინაგან მუშაობას?", b: "ის ემსახურება როგორც ბრძენთა მიერ შედგენილი შინაგანი მდგომარეობებისა და შესწორების პროცესების ზუსტი სულიერი რუკა." },
    { f: "რატომ მიიჩნევა ლიშმაზე გადასვლა უმაღლეს სასწაულად?", b: "იმიტომ, რომ შექმნილი ბუნების (თვითსიყვარულის) წმინდა ალტრუიზმად გარდაქმნა შესაძლებელია მხოლოდ ნათელის გარდამქმნელი ძალით." },
    { f: "როგორ გადაიქცევა ლოცვა ცოცხალ დიალოგად შემოქმედთან?", b: "როდესაც გულის ძგერა ზუსტად ასახავს მასთან მიწებების ლტოლვას, იხსნება პირდაპირი შინაგანი კავშირი." },
    { f: "რას ნიშნავს გამონათქვამი «შენ არ გევალება საქმის დასრულება, მაგრამ არც იმის უფლება გაქვს, რომ თავი აარიდო მას»?", b: "თუმცა მიზანი საჩუქარია ზემოდან, სურვილისა და ნაკლებობის აგების მძიმე შრომა სრულად ადამიანზეა დაკისრებული." },
    { f: "რა კავშირია ლოცვასა და მეგობრების სიყვარულს შორის?", b: "მეგობრებისთვის გაცემის მცდელობაში ვლინდება უანგარო სიყვარულის სრული უუნარობა, რაც ბადებს ჭეშმარიტ შეძახილს შეწევნისთვის." },
    { f: "როგორ ასუფთავებს განზრახვას თვითჩაღრმავება ლოცვის წინ?", b: "ის ამხელს ფარულ ეგოისტურ მოტივებს, განდევნის ცრუ მიზნებს და ყურადღებას ამახვილებს სიმართლის ერთ წერტილზე." },
    { f: "რა განსხვავებაა პასიურ ლოდინსა და სულიერ ლოცვას შორის?", b: "პასიურობა ბრძოლის გარეშე ნებდება, მაშინ როდესაც ლოცვა არის უკიდურესი ღაღადი მეომრისა, რომელიც იბრძვის ძალების უკანასკნელ ზღვრამდე." },
    { f: "როგორ აისახება თორის ნათელი ლოცვაში?", b: "სწავლის დროს მოზიდული გარდამქმნელი ნათელი ანათებს გულის სიბნელეს, რაც აღვიძებს შესწორების ღრმა ვედრებას." },
    { f: "რას ნიშნავს, რომ ჭეშმარიტი ლოცვა «სიღრმიდან ღაღადებს»?", b: "შეძახილი, რომელიც ამოიფრქვევა მიღების სურვილის ფსკერიდან, ეგოს საპყრობილის ყველაზე ბნელი უფსკრულიდან." },
    { f: "როგორ მიჰყავს ლოცვას შემოქმედთან დვეკუთამდე (მიწებებამდე)?", b: "გაცემის თვისების შეძენით ადამიანი აღწევს ფორმის მსგავსებას შემოქმედთან, რაც სრული ერთიანობაა." },
    { f: "რა არის მე-18 გაკვეთილის მთავარი პრაქტიკული გაკვეთილი ლოცვის შესახებ?", b: "ნუ დაკმაყოფილდები სიტყვების გამეორებით; ააგე ნამდვილი ხისარონი შენს გულში, რადგან შემოქმედს მხოლოდ გულის სიმართლე ესმის." }
  ],
  "zh-cn": [
    { f: "卡巴拉对祈祷的定义是什么？", b: "“心中的工作”（Avoda shebaLev），即在创造者面前对自己内心的愿望、意图与匮乏进行深刻的澄清。" },
    { f: "在卡巴拉中，精神层面的“心”代表什么？", b: "心代表人类所有接受欲望的总和，以及其全部情感与意志倾向的集合。" },
    { f: "口中的言语与心中的渴望有何关联？", b: "创造者只回应心灵深处真实的匮乏（Hisaron），绝不回应嘴唇机械念诵的言词。" },
    { f: "祈祷中的“Hisaron”概念是什么？", b: "一种真实的内在缺失感，即器皿（Kli）渴望获得灵性充实与修正的空虚状态。" },
    { f: "为什么机械地重复词句不算真正的祈祷？", b: "因为若内心不渴求双唇所念之物，言语便只是没有灵性活力的枯死形式。" },
    { f: "祈祷蒙应允的第一个条件是什么？", b: "坚信创造者确实有能力将人从利己主义的牢笼中彻底拯救出来。" },
    { f: "祈祷蒙应允的第二个条件是什么？", b: "认识到别无选择：人类自身的一切力量皆已告罄，唯有创造者能施以援手。" },
    { f: "祈祷蒙应允的第三个条件是什么？", b: "这一请求必须切实关乎生死，若得不到解决，灵魂便会在接受欲望中毁灭。" },
    { f: "祈祷在灵性进化中如何作为“媒介”发挥作用？", b: "它并非试图改变创造者，而是转化人本身，使Kli准备好接纳给予之光。" },
    { f: "卡巴拉学者在作为媒介的真正祈祷中祈求什么？", b: "唯独祈求对给予的匮乏（给予的意愿）以及与创造者达成形式上的对等。" },
    { f: "《沙玛蒂》第20篇关于达成Lishma的核心要义是什么？", b: "Lishma（为了祂的名 / 无私的给予）是来自上方的恩赐与启迪，仅凭人类理性无法独自获得。" },
    { f: "既然Lishma是来自上方的恩赐，为何人的努力不可或缺？", b: "因为自身的努力与修正手段能够在人心中构建起真正渴望获得Lishma的修正之器（Kelim）。" },
    { f: "根据《沙玛蒂》第20篇，失败与无力感在祈祷中扮演何种角色？", b: "当人看清自己一切作为皆属徒劳时，便陷入彻底的无能为力，唯有此时方能发自肺腑地呼求。" },
    { f: "人何时才能发自内心深处发出诚挚的祈祷？", b: "唯有用尽人间一切手段并承认没有创造者自己便一事无成之后。" },
    { f: "“MAN”（Mayin Nukvin）这一概念意味着什么？", b: "女性之水；即从下方器皿升起的匮乏、祈祷与觉醒，负责引下上方的丰盛与光明。" },
    { f: "“下方的觉醒”在灵性体系中起什么作用？", b: "下方的觉醒（受造物的祈祷）触发了上方光芒（MAD - Mayin Dehrin）的倾泻。" },
    { f: "“凡前来净化者必得帮助”的法则意味着什么？", b: "凡真诚追求给予与纯洁者，创造者必从上方赋予力量、修正以及超越其本性的提升。" },
    { f: "创造者究竟如何帮助前来净化之人？", b: "赐予他Lishma的阶位，唤醒他的心灵，并赋予他超越自身利己本性的超自然力量。" },
    { f: "每日内在澄清中的“心中的工作”是什么？", b: "将自私的欲望与给予的渴望区分开来，并不断祈求转化自身的本性。" },
    { f: "为何创造者不会因祈祷而改变？", b: "因为创造者是绝对至善且恒常不变的；祈祷改变的是接收之器，使其具备容纳光的能力。" },
    { f: "世俗宗教祈祷与卡巴拉祈祷有何区别？", b: "世俗祈祷求的是物质利益或自我的慰藉，而卡巴拉祈祷祈求的是从利己主义中得到救赎。" },
    { f: "真正的Hisaron如何在灵性道路上诞生？", b: "通过在团队中的坚韧工作与对原典的研读，当匮乏被明确为缺少给予之光时而产生。" },
    { f: "身体“不同意天国之轭”意味着什么？", b: "生来的接受欲望本能地抗拒在没有个人报酬的情况下，纯粹为了创造者的喜悦而工作。" },
    { f: "当人看到自己的所有感官都抗拒给予时，该怎么做？", b: "除了祈祷别无他法：在创造者面前倾心吐意，求祂使身体屈服于给予。" },
    { f: "达成Lishma如何消灭恶的倾向？", b: "它消解了自爱；接受之器失去了利己的功能，在灵性意义上被视为“死亡”。" },
    { f: "为何认识到“没有祈祷就不可能达到Lishma”至关重要？", b: "因为这种认识使祈祷成为绝对而迫切的需求，打破了自鸣得意的虚妄幻想。" },
    { f: "提升MAN与灵魂器皿之间有何联系？", b: "MAN即是Kli自身的匮乏；这种匮乏越纯粹、越深沉，器皿所能容纳的光就越大。" },
    { f: "在何种意义上，祈祷是对利己主义无能为力的承认？", b: "心灵袒露了其绝对的依赖，承认没有神圣的相助，自身的自我便是一座无法逃脱的牢笼。" },
    { f: "团队工作如何与个人祈祷相结合？", b: "去爱同伴的努力暴露了自身在无私给予上的彻底无能，从而催生出真正的求救呼声。" },
    { f: "为什么祈祷被视为灵性器皿本身的创造？", b: "因为唯有在存在相应空白之处，充盈才能进入；祈祷定义并拓宽了这一灵性真空。" },
    { f: "“创造者倾听祈祷”这句话意味着什么？", b: "祈求与上方给予的法则达成了完美的共鸣，光便瞬间注满了敞开的Kli。" },
    { f: "灵性的绝望在祈祷的诞生中扮演什么角色？", b: "它标志着利己力量的彻底耗尽，是上方救助降临的直接前奏。" },
    { f: "什么是“上方的觉醒”（Itaruta de-Leila）？", b: "上方光芒的显现，它是对下方升起的成熟纯净的匮乏（MAN）所作出的直接回应。" },
    { f: "在《沙玛蒂》第20篇中，为何将接受欲望比作“小偷”？", b: "因为它企图偷窃并侵吞每一丝能量与喜悦，完全用于自身的利己享受。" },
    { f: "为何人最初在为给予而工作时感受不到喜悦？", b: "为了不让接受欲望在其中尝到甜头；若尝到甜头，人便永远无法升入纯粹的Lishma。" },
    { f: "灵性工作何时能成为其本身的喜悦？", b: "当人习惯了给予，而为创造者带来喜悦成为了努力本身的最大奖赏之时。" },
    { f: "灵性工作中的抱怨何时合理，何时不合理？", b: "人只能向自己真正为其效劳的主人抱怨；若为自我效劳，便无权向创造者索求力量。" },
    { f: "祈祷中的内在澄清（Berur）是什么？", b: "梳理意图：将为自身私利所做的事，与旨在取悦创造者的意图彻底区分开来。" },
    { f: "在承受天国之轭时的“完全圆满”是什么？", b: "唯独想要给予，完全放弃出于一己私利的索取。" },
    { f: "为何智力上的理解不足以构成心灵的祈祷？", b: "理性的论据无法打动灵性器皿；唯有在心灵中切身体验到的真实匮乏才能吸引光明。" },
    { f: "MAN如何在灵性世界的各个阶梯阶位中发挥作用？", b: "较低的阶位将其匮乏提升至较高的阶位，后者再将其升至源头，并将回应带引而下。" },
    { f: "为何祈祷被称为对抗接受欲望的唯一武器？", b: "因为人无法靠自己改变被造的本性；他只能向创造者呼求，以赐予其给予的新本性。" },
    { f: "为什么祈祷是一个持续的过程，而非短暂的举动？", b: "一系列的努力与跌倒不断磨砺并成熟内心的匮乏，直至其达到绝对的真诚。" },
    { f: "在最黑暗的境地中，对救赎的信心如何体现？", b: "纵使肉体看不到出路，心中的点依然确信创造者能在转瞬之间施以拯救。" },
    { f: "“创造者渴望义人的祈祷”意味着什么？", b: "创造者等待着具备给予能力的就绪Kli，因为祂爱的本质便是施予充盈。" },
    { f: "悔改（Tshuva）与卡巴拉祈祷之间有何关联？", b: "悔改是对利己本性之恶的痛苦体认，而祈祷则是祈求从中解脱的呼吁。" },
    { f: "祈祷如何保护人免于灵性傲慢？", b: "它让人牢记：所达到的任何灵性阶位，完全是来自上方不配得的礼物与慈悲。" },
    { f: "为何有时祈祷看起来未得到回应？", b: "因为匮乏尚未达到所需的深度或纯度；器皿尚未准备好保持住光。" },
    { f: "“在创造者面前倾心吐意”意味着什么？", b: "毫无保留地将一切隐秘的愿望、恐惧与无力感交由创造者掌管。" },
    { f: "祈祷书（Siddur）如何协助卡巴拉学者的内在工作？", b: "它是已达觉悟的智者所绘制的内在状态与修正过程的精准灵性地图。" },
    { f: "为何向Lishma的转变被视为至高的奇迹？", b: "因为将被造的本性（自爱）彻底翻转为纯粹的利他，唯有依靠光的转化力量方能达成。" },
    { f: "祈祷如何转化为与创造者活生生的对话？", b: "当心灵的律动准确反映出与祂结合的渴望时，直接的内在交流便开启了。" },
    { f: "“你无须完成工作，但亦无权放弃”这句格言意味着什么？", b: "尽管目标是来自上方的恩赐，但建立愿望与匮乏的辛劳完全落在人身上。" },
    { f: "祈祷与爱同伴之间有何联系？", b: "在向同伴给予的努力中，暴露了自身完全缺乏无私之爱的能力，从而催生了真正的求救呼声。" },
    { f: "祈祷前的反省如何净化意图？", b: "它揭开隐秘的自私动机，剔除虚假的目标，将呼求聚焦于真理的单一点上。" },
    { f: "被动等待与灵性祈祷之间有何区别？", b: "被动是未战先降，而祈祷是战斗至最后一刻的勇士发出的极限呼救。" },
    { f: "托拉之光如何在祈祷中彰显？", b: "在研习中引来的修正之光照亮心灵的黑暗，唤醒寻求修正的深沉祈求。" },
    { f: "真正的祈祷“从深处呼求”意味着什么？", b: "那是从接受欲望的最底层、从自我牢笼最幽暗的深渊中迸发而出的呐喊。" },
    { f: "祈祷如何引向与创造者的结合（Dvekut）？", b: "通过获得给予的属性，人达成了与创造者形式上的对等，这便是全然的一体。" },
    { f: "第18课关于祈祷的最重要实践教训是什么？", b: "切勿满足于重复言语；要在心中建立起真正的Hisaron，因为创造者只倾听心灵的真理。" }
  ],
  "zh-hant": [
    { f: "卡巴拉對祈禱的定義是什麼？", b: "「心中的工作」（Avoda shebaLev），即在創造者面前對自己內心的願望、意圖與匱乏進行深刻的澄清。" },
    { f: "在卡巴拉中，精神層面的「心」代表什麼？", b: "心代表人類所有接受欲望的總和，以及其全部情感與意志傾向的集合。" },
    { f: "口中的言語與心中的渴望有何關聯？", b: "創造者只回應心靈深處真實的匱乏（Hisaron），絕不回應嘴唇機械唸誦的言詞。" },
    { f: "祈禱中的「Hisaron」概念是什麼？", b: "一種真實的內在缺失感，即器皿（Kli）渴望獲得靈性充實與修正的空虛狀態。" },
    { f: "為什麼機械地重複詞句不算真正的祈禱？", b: "因為若內心不渴求雙唇所唸之物，言語便只是沒有靈性活力的枯死形式。" },
    { f: "祈禱蒙應允的第一個條件是什麼？", b: "堅信創造者確實有能力將人從利己主義的牢籠中徹底拯救出來。" },
    { f: "祈禱蒙應允的第二個條件是什麼？", b: "認識到別無選擇：人類自身的一切力量皆已告罄，唯有創造者能施以援手。" },
    { f: "祈禱蒙應允的第三個條件是什麼？", b: "這一請求必須切實關乎生死，若得不到解決，靈魂便會在接受欲望中毀滅。" },
    { f: "祈禱在靈性進化中如何作為「媒介」發揮作用？", b: "它並非試圖改變創造者，而是轉化人本身，使Kli準備好接納給予之光。" },
    { f: "卡巴拉學者在作為媒介的真正祈禱中祈求什麼？", b: "唯獨祈求對給予的匱乏（給予的意願）以及與創造者達成形式上的對等。" },
    { f: "《沙瑪蒂》第20篇關於達成Lishma的核心要義是什麼？", b: "Lishma（為了祂的名 / 無私的給予）是來自上方的恩賜與啟迪，僅憑人類理性無法獨自獲得。" },
    { f: "既然Lishma是來自上方的恩賜，為何人的努力不可或缺？", b: "因為自身的努力與修正手段能夠在人心深處構建起真正渴望獲得Lishma的修正之器（Kelim）。" },
    { f: "根據《沙瑪蒂》第20篇，失敗與無力感在祈禱中扮演何種角色？", b: "當人看清自己一切作為皆屬徒勞時，便陷入徹底的無能為力，唯有此時方能發自肺腑地呼求。" },
    { f: "人何時才能發自內心深處發出誠摯的祈禱？", b: "唯有用盡人間一切手段並承認沒有創造者自己便一事無成之後。" },
    { f: "「MAN」（Mayin Nukvin）這一概念意味著什麼？", b: "女性之水；即從下方器皿升起的匱乏、祈禱與覺醒，負責引下上方的豐盛與光明。" },
    { f: "「下方的覺醒」在靈性體系中起什麼作用？", b: "下方的覺醒（受造物的祈禱）觸發了上方光芒（MAD - Mayin Dehrin）的傾瀉。" },
    { f: "「凡前來淨化者必得幫助」的法則意味著什麼？", b: "凡真誠追求給予與純潔者，創造者必從上方賦予力量、修正以及超越其本性的提升。" },
    { f: "創造者究竟如何幫助前來淨化之人？", b: "賜予他Lishma的階位，喚醒他的心靈，並賦予他超越自身利己本性的超自然力量。" },
    { f: "每日內在澄清中的「心中的工作」是什麼？", b: "將自私的欲望與給予的渴望區分開來，並不斷祈求轉化自身的本性。" },
    { f: "為何創造者不會因祈禱而改變？", b: "因為創造者是絕對至善且恆常不變的；祈禱改變的是接收之器，使其具備容納光的能力。" },
    { f: "世俗宗教祈禱與卡巴拉祈禱有何區別？", b: "世俗祈禱求的是物質利益或自我的慰藉，而卡巴拉祈禱祈求的是從利己主義中得到救贖。" },
    { f: "真正的Hisaron如何在靈性道路上誕生？", b: "透過在團隊中的堅韌工作與對原典的研讀，當匱乏被明確為缺少給予之光時而產生。" },
    { f: "身體「不同意天國之軛」意味著什麼？", b: "生來的接受欲望本能地抗拒在沒有個人報酬的情況下，純粹為了創造者的喜悅而工作。" },
    { f: "當人看到自己的所有感官都抗拒給予時，該怎麼做？", b: "除了祈禱別無他法：在創造者面前傾心吐意，求祂使身體屈服於給予。" },
    { f: "達成Lishma如何消滅惡的傾向？", b: "它消解了自愛；接受之器失去了利己的功能，在靈性意義上被視為「死亡」。" },
    { f: "為何認識到「沒有祈禱就不可能達到Lishma」至關重要？", b: "因為這種認識使祈禱成為絕對而迫切的需求，打破了自鳴得意的虛妄幻想。" },
    { f: "提升MAN與靈魂器皿之間有何聯繫？", b: "MAN即是Kli自身的匱乏；這種匱乏越純粹、越深沉，器皿所能容納的光就越大。" },
    { f: "在何種意義上，祈禱是對利己主義無能為力的承認？", b: "心靈袒露了其絕對的依賴，承認沒有神聖的相助，自身的自我便是一座無法逃脫的牢籠。" },
    { f: "團隊工作如何與個人祈禱相結合？", b: "去愛同伴的努力暴露了自身在無私給予上的徹底無能，從而催生出真正的求救呼聲。" },
    { f: "為什麼祈禱被視為靈性器皿本身的創造？", b: "因為唯有在存在相應空白之處，充盈才能進入；祈禱定義並拓寬了這一靈性真空。" },
    { f: "「創造者傾聽祈禱」這句話意味著什麼？", b: "祈求與上方給予的法則達成了完美的共鳴，光便瞬間注滿了敞開的Kli。" },
    { f: "靈性的絕望在祈禱的誕生中扮演什麼角色？", b: "它標誌著利己力量的徹底耗盡，是上方救助降臨的直接前奏。" },
    { f: "什麼是「上方的覺醒」（Itaruta de-Leila）？", b: "上方光芒的顯現，它是對下方升起的成熟純淨的匱乏（MAN）所作出的直接回應。" },
    { f: "在《沙瑪蒂》第20篇中，為何將接受欲望比作「小偷」？", b: "因為它企圖偷竊並侵吞每一絲能量與喜悅，完全用於自身的利己享受。" },
    { f: "為何人最初在為給予而工作時感受不到喜悅？", b: "為了不讓接受欲望在其中嚐到甜頭；若嚐到甜頭，人便永遠無法升入純粹的Lishma。" },
    { f: "靈性工作何時能成為其本身的喜悅？", b: "當人習慣了給予，而為創造者帶來喜悅成為了努力本身的最大獎賞之時。" },
    { f: "靈性工作中的抱怨何時合理，何時不合理？", b: "人只能向自己真正為其效勞的主人抱怨；若為自我效勞，便無權向創造者索求力量。" },
    { f: "祈禱中的內在澄清（Berur）是什麼？", b: "梳理意圖：將為自身私利所做的事，與旨在取悅創造者的意圖徹底區分開來。" },
    { f: "在承受天國之軛時的「完全圓滿」是什麼？", b: "唯獨想要給予，完全放棄出於一己私利的索取。" },
    { f: "為何智力上的理解不足以構成心靈的祈禱？", b: "理性的論據無法打動靈性器皿；唯有在心靈中切身體驗到的真實匱乏才能吸引光明。" },
    { f: "MAN如何在靈性世界的各個階梯階位中發揮作用？", b: "較低的階位將其匱乏提升至較高的階位，後者再將其升至源頭，並將回應帶引而下。" },
    { f: "為何祈禱被稱為對抗接受欲望的唯一武器？", b: "因為人無法靠自己改變被造的本性；他只能向創造者呼求，以賜予其給予的新本性。" },
    { f: "為什麼祈禱是一個持續的過程，而非短暫的舉動？", b: "一系列的努力與跌倒不斷磨礪並成熟內心的匱乏，直至其達到絕對的真誠。" },
    { f: "在最黑暗的境地中，對救贖的信心如何體現？", b: "縱使肉體看不到出路，心中的點依然確信創造者能在轉瞬之間施以拯救。" },
    { f: "「創造者渴望義人的祈禱」意味著什麼？", b: "創造者等待著具備給予能力就緒的Kli，因為祂愛的本質便是施予充盈。" },
    { f: "悔改（Tshuva）與卡巴拉祈禱之間有何關聯？", b: "悔改是對利己本性之惡的痛苦體認，而祈禱則是祈求從中解脫的呼籲。" },
    { f: "祈禱如何保護人免於靈性傲慢？", b: "它讓人牢記：所達到的任何靈性階位，完全是來自上方不配得的禮物與慈悲。" },
    { f: "為何有時祈禱看起來未得到回應？", b: "因為匱乏尚未達到所需的深度或純度；器皿尚未準備好保持住光。" },
    { f: "「在創造者面前傾心吐意」意味著什麼？", b: "毫無保留地將一切隱秘的願望、恐懼與無力感交由創造者掌管。" },
    { f: "祈禱書（Siddur）如何協助卡巴拉學者的內在工作？", b: "它是已達覺悟的智者所繪製的內在狀態與修正過程的精準靈性地圖。" },
    { f: "為何向Lishma的轉變被視為至高的奇蹟？", b: "因為將被造的本性（自愛）徹底翻轉為純粹的利他，唯有依靠光的轉化力量方能達成。" },
    { f: "祈禱如何轉化為與創造者活生生的對話？", b: "當心靈的律動準確反映出與祂結合的渴望時，直接的內在交流便開啟了。" },
    { f: "「你無須完成工作，但亦無權放棄」這句格言意味著什麼？", b: "儘管目標是來自上方的恩賜，但建立願望與匱乏的辛勞完全落在人身上。" },
    { f: "祈禱與愛同伴之間有何聯繫？", b: "在向同伴給予的努力中，暴露了自身完全缺乏無私之愛的能力，從而催生了真正的求救呼聲。" },
    { f: "祈禱前的反省如何淨化意圖？", b: "它揭開隱秘的自私動機，剔除虛假的目標，將呼求聚焦於真理的單一點上。" },
    { f: "被動等待與靈性祈禱之間有何區別？", b: "被動是未戰先降，而祈禱是戰鬥至最後一刻的勇士發出的極限呼救。" },
    { f: "托拉之光如何在祈禱中彰顯？", b: "在研習中引來的修正之光照亮心靈的黑暗，喚醒尋求修正的深沉祈求。" },
    { f: "真正的祈禱「從深處呼求」意味著什麼？", b: "那是從接受欲望的最底層、從自我牢籠最幽暗的深淵中迸發而出的吶喊。" },
    { f: "祈禱如何引向與創造者的結合（Dvekut）？", b: "透過獲得給予的屬性，人達成了與創造者形式上的對等，這便是全然的一體。" },
    { f: "第18課關於祈禱的最重要實踐教訓是什麼？", b: "切勿滿足於重複言語；要在心中建立起真正的Hisaron，因為創造者只傾聽心靈的真理。" }
  ],
  ja: [
    { f: "カバラにおける祈りの定義とは何ですか？", b: "「心における作業」（アヴォダ・シェバ・レヴ）、すなわち創造主の御前で自身の欲望、意図、欠乏を深く内省し明らかにすることです。" },
    { f: "カバラにおいて霊的な「心」は何を表していますか？", b: "心は人間の受け取る欲望の総体、および感情的・意志的な傾向の全体を表しています。" },
    { f: "口の言葉と心の欲望はどのように関連していますか？", b: "創造主は唇が機械的に発する言葉ではなく、心の深淵にある真の欠乏（ヒサロン）にのみ応えられます。" },
    { f: "祈りにおける「ヒサロン」の概念とは何ですか？", b: "真の内的欠乏であり、霊的な充足と矯正を切望する器（クリ）の空虚な状態です。" },
    { f: "なぜ言葉の機械的な反復は真の祈りと見なされないのですか？", b: "唇が発するものを心が渇望していなければ、言葉は霊的な生命力を欠いた死んだ形式に過ぎないからです。" },
    { f: "祈りが聞き届けられるための第一の条件は何ですか？", b: "創造主が人間を利己主義の牢獄から真に解放する力を持っておられるという揺るぎない信仰です。" },
    { f: "祈りが聞き届けられるための第二の条件は何ですか？", b: "他に選択肢がないという認識です。人間のあらゆる力は尽き果て、創造主だけが助けを与えることができます。" },
    { f: "祈りが聞き届けられるための第三の条件は何ですか？", b: "その願いが真に死活問題であり、それが解決されなければ魂が受け取る欲望の中で滅びてしまうということです。" },
    { f: "祈りは霊的進化においてどのように「媒体」（メディウム）として機能しますか？", b: "創造主を変えるのではなく人間自身を変容させ、授与の光を受け取れるようにクリを準備します。" },
    { f: "カバリストは媒体としての真の祈りにおいて何を求めますか？", b: "もっぱら授与の欠乏（与えたいという欲求）と、創造主との形態の同等性のみを求めます。" },
    { f: "リシュマー達成に関する『シャマティ』第20編の核心的なメッセージは何ですか？", b: "リシュマー（主の御名のために／私心なき授与）は上層からの贈り物であり啓発であって、人間の知性だけでは到達できません。" },
    { f: "リシュマーが上層からの贈り物であるなら、なぜ人間の努力が必要なのですか？", b: "努力と修復手段こそが、リシュマーを受け取ることを真に望む矯正された器（ケリム）を人の内に築くからです。" },
    { f: "『シャマティ』第20編によれば、失敗と無力感は祈りにおいてどのような役割を果たしますか？", b: "自らの行いがすべて無駄であったと知った時、人は完全な無力感に至り、その時初めて心の底から叫ぶことができるのです。" },
    { f: "人はいつ、心の底から発する真摯な祈りを捧げることができるようになりますか？", b: "人間的な手段をすべて尽くし、創造主なしには自力で何も達成できないと認めた後でのみ可能です。" },
    { f: "「MAN」（メイ・ヌクヴィン）の概念は何を意味しますか？", b: "女性的な水。下層の器から上昇する欠乏、祈り、目覚めであり、上層から豊かさと光を引き下ろします。" },
    { f: "霊的システムにおいて「下層からの目覚め」はどのような役割を果たしますか？", b: "下層からの目覚め（被造物の祈り）が、上層の光（MAD - メイ・デフリン）の流出を引き起こします。" },
    { f: "「清めを求めて来る者は助けられる」という原則は何を意味しますか？", b: "授与と純粋さを真摯に求める者には、創造主が上層からその本性を超える力、矯正、高揚を与えてくださいます。" },
    { f: "創造主は清めを求めて来る者を具体的にどのように助けられますか？", b: "リシュマーの階梯を授け、その心を目覚めさせ、利己的な本性を克服する超自然的な力を与えることによってです。" },
    { f: "日々の内省における「心における作業」とは何ですか？", b: "利己的な欲望と授与の欲求とを識別し、自らの本性の変容を絶えず祈ることです。" },
    { f: "なぜ創造主は祈りによって変化しないのですか？", b: "創造主は絶対的な善であり不変だからです。祈りは受け取る器を変化させ、光を保持できるように整えます。" },
    { f: "通常の宗教的祈りとカバラの祈りの違いは何ですか？", b: "通常の祈りは物質的な利益やエゴの安寧を求めますが、カバラの祈りは利己主義そのものからの救済を懇願します。" },
    { f: "霊的な道において真のヒサロンはどのようにして生まれますか？", b: "グループでの粘り強い作業と原典の学習を通じ、欠乏が授与の光の欠如として明確に認識されることによって生まれます。" },
    { f: "身体が「天の王国の軛に同意しない」とはどういう意味ですか？", b: "生まれながらの受け取る欲望は、見返りなしに純粋に創造主の歓びのために働くことに本能的に抵抗します。" },
    { f: "全身の諸器官が授与に抵抗しているのを見た時、人は何をすべきですか？", b: "祈るより他に道はありません。身体を授与に従わせるよう、創造主の御前に心を注ぎ出すべきです。" },
    { f: "リシュマーの達成はどのようにして悪の傾向を滅ぼしますか？", b: "自己愛を無効化します。受け取る器はその利己的な機能を失い、霊的な意味で「死んだ」ものと見なされます。" },
    { f: "祈りなしにはリシュマーに到達できないと知ることがなぜ不可欠なのですか？", b: "この認識こそが祈りを絶対的かつ切実な必要事へと変え、自己満足の錯覚を打ち砕くからです。" },
    { f: "MANの上昇と魂の器にはどのような関連がありますか？", b: "MANはクリ自身の欠乏そのものです。その欠乏が純粋で深いほど、器が受け取ることのできる光は大きくなります。" },
    { f: "祈りはどのような意味において利己主義の無力の告白なのですか？", b: "心が絶対的な依存を露わにし、自らのエゴが神聖な助けなしには脱出不能な牢獄であると認めるからです。" },
    { f: "グループでの作業は個人の祈りとどのように結びついていますか？", b: "仲間を愛そうとする努力が無私の授与に対する完全な無力さを露呈させ、真の助けを求める叫びを生み出します。" },
    { f: "なぜ祈りは霊的な器そのものの創造と見なされるのですか？", b: "充足は対応する欠乏が存在する場所にしか入ることができないからです。祈りはその霊的空白を定義し拡大します。" },
    { f: "「創造主は祈りを聞かれる」という表現は何を意味しますか？", b: "願いが上層の授与の法則と完全に共鳴し、開かれたクリへと光が即座に満ちることを意味します。" },
    { f: "霊的な絶望は祈りの誕生においてどのような役割を果たしますか？", b: "利己的な力の完全な枯渇を示し、上層からの救済が流れ込む直前の兆候となります。" },
    { f: "「上層からの目覚め」（イタルタ・デ・レイラ）とは何ですか？", b: "下層から上昇した成熟し浄化された欠乏（MAN）に対する直接的な応答として下る上層の光の顕現です。" },
    { f: "『シャマティ』第20編で受け取る欲望が「泥棒」に例えられているのはなぜですか？", b: "あらゆるエネルギーや喜びの破片を、自分自身の利己的な快楽のためだけに盗み私物化しようとするからです。" },
    { f: "なぜ人は当初、授与のための作業に喜びを感じられないのですか？", b: "受け取る欲望がそこに味を見出さないようにするためです。もし快楽を感じれば、純粋なリシュマーへ昇華できません。" },
    { f: "霊的作業はいつそれ自体が歓びとなるのですか？", b: "人が授与に慣れ親しみ、創造主を歓ばせることが努力自体の最大の報酬となった時です。" },
    { f: "霊的作業における不平不満は、いつ正当であり、いつ不当なのですか？", b: "実際に仕えている主人に対してのみ不満を述べることができます。エゴのために働きながら創造主に力を要求する権利はありません。" },
    { f: "祈りにおける内省・弁別（ベルール）とは何ですか？", b: "意図の選別です。自分のエゴのために行われることと、純粋に創造主の歓びを目指すこととを峻別することです。" },
    { f: "天の王国の軛を受け入れる際の「完全な円満」とは何ですか？", b: "もっぱら授与のみを望み、私利私欲のための受容を完全に断念することです。" },
    { f: "知的な理解が心の祈りにとって不十分なのはなぜですか？", b: "理性の論理は霊的な器を動かせないからです。心で体験された真の欠乏のみが光を引き寄せます。" },
    { f: "MANは霊的世界の諸階梯を通じてどのように働きますか？", b: "下位の階梯がその欠乏を上位の階梯へと引き上げ、上位がそれを源泉へと運び、応答を下層へともたらします。" },
    { f: "なぜ祈りは受け取る欲望に対する唯一の武器と呼ばれるのですか？", b: "人間は創造された自らの本性を自力で変えることができないからです。新たな授与の本性を授けてくださるよう叫ぶことしかできません。" },
    { f: "なぜ祈りは瞬間的な行為ではなく継続的なプロセスなのですか？", b: "努力と挫折の連鎖が内なる欠乏を研磨し成熟させ、絶対的な誠実さに達するまで鍛え上げるからです。" },
    { f: "最も暗い状態において、救済への信仰はどのように現れますか？", b: "肉体が出口を見出せない時でさえ、心の中の点は創造主が一瞬にして救うことができると確信しています。" },
    { f: "「創造主は義人の祈りを切望される」とはどういう意味ですか？", b: "創造主は授与を行う用意のできたクリを待っておられます。なぜなら、神の愛の本質は満たすことにあるからです。" },
    { f: "悔い改め（テシューヴァ）とカバラの祈りにはどのような関連がありますか？", b: "悔い改めは利己的な本性の悪を痛切に認識することであり、祈りはそこからの解放を求める嘆願です。" },
    { f: "祈りはどのようにして人を霊的な傲慢から守りますか？", b: "達成されたいかなる霊的階梯も、上層からの不相応な賜物であり慈悲に過ぎないという自覚を根付かせます。" },
    { f: "祈りが時に答えられていないように見えるのはなぜですか？", b: "欠乏がまだ必要な深さや純度に達していないためです。器はまだ光を保持する準備ができていません。" },
    { f: "「創造主の御前に心を注ぎ出す」とは何を意味しますか？", b: "隠されたあらゆる欲望、恐れ、無力感を、何一つ留保することなく創造主の統御に委ねることです。" },
    { f: "祈祷書（シドゥール）はカバリストの内的な作業をどのように助けますか？", b: "到達した賢者たちによって記された、内的状態と矯正プロセスの精緻な霊的地図として機能します。" },
    { f: "なぜリシュマーへの移行は至高の奇跡と見なされるのですか？", b: "被造物の本性（自己愛）を純粋な利他主義へと逆転させることは、光の変容力によってのみ可能だからです。" },
    { f: "祈りはどのようにして創造主との生きた対話へと発展しますか？", b: "心の鼓動が主と結びつきたいという渇望を精確に反映する時、直接的な内なる対話が開かれます。" },
    { f: "「作業を完了することは汝の義務ではないが、そこから退く自由もない」とは何を意味しますか？", b: "目標は上層からの賜物であるとしても、欲望と欠乏を構築する労苦は全面的に人間に課せられているということです。" },
    { f: "祈りと仲間への愛にはどのような関連がありますか？", b: "仲間に授与しようとする努力の中で無条件に愛することの完全な無力さが暴かれ、真の助けを求める叫びが生まれます。" },
    { f: "祈りの前の自己反省はどのように意図を浄化しますか？", b: "隠れた利己的動機を白日の下に晒し、偽りの目標を削ぎ落とし、叫びを真理の一点へと集中させます。" },
    { f: "受動的な待ちの姿勢と霊的な祈りとの違いは何ですか？", b: "受動性は戦うことなく降伏しますが、祈りは力の限界まで戦い抜く戦士の極限の叫びです。" },
    { f: "トーラーの光は祈りの中にどのように反映されますか？", b: "学習中に引き寄せられた矯正の光が心の闇を照らし出し、矯正を求める深切な嘆願を目覚めさせます。" },
    { f: "真の祈りが「深き淵より叫ぶ」とは何を意味しますか？", b: "受け取る欲望の最底流から、エゴの牢獄の最も暗い奈落から噴出する叫びのことです。" },
    { f: "祈りはどのようにして創造主との合一（ドヴェクート）へと導きますか？", b: "授与の属性を獲得することによって、人は創造主との形態の同等性を達成し、これが完全な一体化となります。" },
    { f: "祈りに関する第18課の最も重要な実践的教訓は何ですか？", b: "言葉を反復するだけで満足してはなりません。心の中に真のヒサロンを築きなさい。創造主は心の真実にのみ応えられるからです。" }
  ],
  ko: [
    { f: "카발라에서 기도의 정의는 무엇인가?", b: "'마음의 작업'(Avoda shebaLev)으로, 창조주 앞에서 자신의 욕망, 의도 및 결핍을 깊이 내적으로 명확히 밝히는 것이다." },
    { f: "카발라에서 영적인 '마음'은 무엇을 나타내는가?", b: "마음은 인간이 가진 모든 받으려는 욕망의 총합이자 감정적·의지적 성향의 전체를 의미한다." },
    { f: "입의 말과 마음의 욕망은 어떤 관계인가?", b: "창조주는 입술이 기계적으로 읊조리는 말이 아니라 오직 마음 깊은 곳의 진정한 결핍(Hisaron)에만 응답하신다." },
    { f: "기도에서 '히사론'(Hisaron)의 개념은 무엇인가?", b: "충만과 영적 교정을 갈망하는 영적 그릇(Kli)의 공허함, 진실한 내적 결핍감이다." },
    { f: "말을 기계적으로 반복하는 것이 왜 진정한 기도로 간주되지 않는가?", b: "입술이 말하는 바를 마음이 갈망하지 않는다면, 그 말은 영적 생명력이 결여된 죽은 형태에 불과하기 때문이다." },
    { f: "기도가 응답받기 위한 첫 번째 조건은 무엇인가?", b: "창조주께서 인간을 이기주의의 감옥에서 능히 구원하실 수 있다는 확고한 믿음이다." },
    { f: "기도가 응답받기 위한 두 번째 조건은 무엇인가?", b: "다른 선택지가 없음을 깨닫는 것이다. 인간의 모든 힘은 실패했으며 오직 창조주만이 도우실 수 있다." },
    { f: "기도가 응답받기 위한 세 번째 조건은 무엇인가?", b: "그 간구가 해결되지 않으면 영혼이 받으려는 욕망 안에서 멸망하고 마는, 진정한 생사의 문제여야 한다." },
    { f: "기도는 영적 진화에서 어떻게 '매개체'(medium)로 작용하는가?", b: "창조주를 변화시키는 것이 아니라 인간 자신을 변형시켜 클리가 베풂의 빛을 받을 준비를 갖추게 한다." },
    { f: "카발리스트는 매개체로서의 참된 기도에서 무엇을 구하는가?", b: "오직 베풂에 대한 결핍(베풀고자 하는 욕망)과 창조주와의 형태의 동등성만을 구한다." },
    { f: "리슈마 달성에 관한 샤마티 20장의 핵심 메시지는 무엇인가?", b: "리슈마(그분의 이름을 위해 / 이타적 베풂)는 인간의 이성만으로는 도달할 수 없는, 위로부터 오는 선물이며 깨달음이다." },
    { f: "리슈마가 위로부터 오는 선물이라면 왜 인간의 노력이 필요한가?", b: "노력과 교정의 수단들이 인간 안에 리슈마를 진정으로 받기 원하는 교정된 영적 그릇(Kelim)을 형성하기 때문이다." },
    { f: "샤마티 20장에 따르면 실패와 무력감은 기도에서 어떤 역할을 하는가?", b: "자신의 모든 행위가 헛됨을 볼 때 사람은 완전한 무력감에 도달하며, 비로소 그때 마음 깊은 곳에서 부르짖을 수 있다." },
    { f: "인간은 언제 마음 깊은 곳에서 우러나오는 진솔한 기도를 드릴 수 있는가?", b: "모든 인간적인 수단을 다 써보고 창조주 없이는 스스로 아무것도 이룰 수 없음을 인정한 뒤에야 가능하다." },
    { f: "'MAN'(Mayin Nukvin) 개념은 무엇을 뜻하는가?", b: "여성적 물로, 아래의 그릇에서 솟아올라 위로부터 빛과 풍요를 끌어당기는 결핍, 기도, 깨어남을 의미한다." },
    { f: "영적 체계에서 '아래로부터의 깨어남'은 어떤 역할을 하는가?", b: "아래로부터의 깨어남(피조물의 기도)은 상위 빛들(MAD - Mayin Dehrin)의 흘러넘침을 촉발한다." },
    { f: "'스스로 정결해지고자 오는 자는 도움을 받는다'는 원리는 무엇을 뜻하는가?", b: "베풂과 순결을 진심으로 갈망하는 자에게 창조주께서는 위로부터 힘과 교정, 타고난 본성을 넘어서는 영적 상승을 베푸신다." },
    { f: "창조주는 정결해지고자 오는 자를 구체적으로 어떻게 도우시는가?", b: "리슈마의 단계를 선물하고, 마음을 일깨우며, 이기적 본성을 초월하는 초자연적인 힘을 주신다." },
    { f: "일상적인 내적 명료화에서 '마음의 작업'이란 무엇인가?", b: "자신의 본성을 변화시켜 달라는 끊임없는 기도와 함께 이기적인 욕망과 베풀려는 욕망을 분별하는 것이다." },
    { f: "창조주는 왜 기도로 인해 변하지 않으시는가?", b: "창조주는 절대선이며 변함이 없으시기 때문이다. 기도는 빛을 담을 수 있도록 받아들이는 그릇을 변화시킨다." },
    { f: "통상적인 종교적 기도와 카발라 기도의 차이점은 무엇인가?", b: "통상적인 기도는 물질적 유익이나 에고의 안녕을 구하지만, 카발라 기도는 이기주의 자체로부터의 구원을 간구한다." },
    { f: "영적 경로에서 진정한 히사론은 어떻게 태어나는가?", b: "그룹 안에서의 끈기 있는 헌신과 원전 공부를 통해, 결핍이 베풂의 빛의 부재로 명확해질 때 생겨난다." },
    { f: "육체가 '하늘나라의 멍에에 동의하지 않는다'는 것은 무슨 뜻인가?", b: "타고난 받으려는 욕망은 개인적 보상 없이 오직 창조주의 기쁨만을 위해 일하는 것을 본능적으로 거부한다." },
    { f: "모든 지체가 베풂에 저항하는 것을 볼 때 사람은 무엇을 해야 하는가?", b: "기도 외에는 길이 없다. 육체가 베풂에 굴복하도록 창조주 앞에 마음을 온전히 쏟아내야 한다." },
    { f: "리슈마에 도달하면 어떻게 악한 성향이 죽음에 이르는가?", b: "자기애가 무효화된다. 받으려는 그릇들은 이기적 기능을 상실하고 영적인 의미에서 '죽은' 것으로 간주된다." },
    { f: "기도 없이는 리슈마에 도달할 수 없음을 아는 것이 왜 결정적인가?", b: "이 깨달음이 기도를 절대적이고 시급한 필수품으로 만들어 자기만족이라는 헛된 환상을 무너뜨리기 때문이다." },
    { f: "MAN을 올리는 것과 영혼의 그릇 사이에는 어떤 연결이 있는가?", b: "MAN은 클리의 결핍 그 자체다. 결핍이 더 순수하고 깊을수록 그릇은 더 큰 빛을 받을 수 있다." },
    { f: "어떤 의미에서 기도는 이기주의의 무력함을 인정하는 고백인가?", b: "마음은 창조주의 도우심 없이는 자신의 에고가 탈출할 수 없는 감옥임을 인정하며 전적인 의존성을 드러낸다." },
    { f: "그룹 작업은 개인의 기도와 어떻게 융합되는가?", b: "친구들을 사랑하려는 노력은 사심 없이 베풀 수 없는 완전한 무능력을 드러내어 참된 구원의 외침을 낳는다." },
    { f: "기도가 왜 영적 그릇 자체의 창조로 간주되는가?", b: "충만은 상응하는 결핍이 있는 곳에만 들어올 수 있기 때문이다. 기도는 이 영적 진공을 규정하고 확장한다." },
    { f: "'창조주께서 기도를 들으신다'는 표현은 무엇을 뜻하는가?", b: "간구가 상위의 베풂의 법칙과 완벽한 공명을 이루어 빛이 열린 클리를 즉시 채움을 의미한다." },
    { f: "영적 절망은 기도가 태어나는 데 어떤 역할을 하는가?", b: "이기적인 힘의 완전한 소진을 의미하며, 이는 위로부터 오는 구원이 흘러드는 바로 직전 단계다." },
    { f: "'위로부터의 깨어남'(Itaruta de-Leila)이란 무엇인가?", b: "아래에서 올라온 성숙하고 정화된 결핍(MAN)에 대한 직접적인 응답으로 내려오는 상위 빛의 현현이다." },
    { f: "샤마티 20장에서 받으려는 욕망이 왜 '도둑'에 비유되는가?", b: "모든 에너지와 기쁨의 파편을 오직 자신의 이기적인 즐거움만을 위해 훔치고 가로채려 하기 때문이다." },
    { f: "사람은 왜 베풂을 위한 작업의 초기에는 아무런 기쁨도 느끼지 못하는가?", b: "받으려는 욕망이 그 안에서 맛을 느끼지 못하게 하기 위함이다. 쾌락을 느낀다면 사람은 결코 순수한 리슈마로 상승할 수 없다." },
    { f: "영적 작업은 언제 그 자체로 기쁨이 되는가?", b: "사람이 베풂에 익숙해져서 창조주께 기쁨을 드리는 것 자체가 수고의 가장 큰 보상이 될 때이다." },
    { f: "영적 작업에서 불평은 언제 정당하고 언제 부당한가?", b: "실제로 일해 준 주인에게만 불평할 수 있다. 에고를 위해 일하면서 창조주께 힘을 요구할 권리는 없다." },
    { f: "기도 안에서의 내적 명료화(Berur)란 무엇인가?", b: "의도의 선별이다. 자신의 에고를 위한 것과 창조주를 기쁘시게 하기 위한 것을 분리하는 작업이다." },
    { f: "하늘나라의 멍에를 질 때의 '완전한 온전함'이란 무엇인가?", b: "오직 베풀기만을 원하며, 자신의 이익을 위해 받으려는 것을 완전히 포기하는 것이다." },
    { f: "지적인 이해가 마음의 기도에 충분하지 않은 이유는 무엇인가?", b: "이성의 논리는 영적 그릇을 움직이지 못한다. 마음으로 경험한 실제적 결핍만이 빛을 끌어당긴다." },
    { f: "MAN은 영적 세계의 단계들을 통해 어떻게 작용하는가?", b: "하위 단계가 자신의 결핍을 상위 단계로 올리면, 상위 단계는 그것을 근원으로 가져가 응답을 아래로 내린다." },
    { f: "기도가 받으려는 욕망에 대항하는 유일한 무기라 불리는 이유는 무엇인가?", b: "사람은 피조된 본성을 스스로 바꿀 수 없다. 새로운 베풂의 본성을 주시도록 창조주께 부르짖을 수 있을 뿐이다." },
    { f: "기도가 일회적 행위가 아니라 지속적인 과정인 이유는 무엇인가?", b: "노력과 추락의 연속이 내면의 결핍을 연마하고 성숙시켜 완전한 진실함에 이르게 하기 때문이다." },
    { f: "가장 어두운 상태에서 구원에 대한 믿음은 어떻게 나타나는가?", b: "육체는 아무런 출구를 보지 못할지라도 마음속의 점은 창조주께서 눈 깜짝할 사이에 구원하실 수 있음을 확신한다." },
    { f: "'창조주께서는 의인의 기도를 갈망하신다'는 말은 무엇을 뜻하는가?", b: "창조주께서는 베풀 수 있는 준비된 클리를 기다리신다. 그분의 사랑의 본질은 충만을 베푸는 데 있기 때문이다." },
    { f: "회개(Tshuva)와 카발라 기도의 관계는 무엇인가?", b: "회개는 이기적 본성의 악함을 고통스럽게 자각하는 것이며, 기도는 그로부터의 해방을 구하는 간청이다." },
    { f: "기도는 사람을 영적 오만으로부터 어떻게 지켜주는가?", b: "달성된 모든 영적 수준이 전적으로 값없이 주어지는 선물이자 위로부터의 자비임을 깊이 각인시킨다." },
    { f: "기도가 때때로 응답받지 못하는 것처럼 보이는 이유는 무엇인가?", b: "결핍이 아직 필요한 깊이나 순도에 도달하지 않았기 때문이다. 그릇이 아직 빛을 간직할 준비가 되지 않았다." },
    { f: "'창조주 앞에 마음을 쏟아붓는다'는 것은 무슨 뜻인가?", b: "모든 은밀한 욕망, 두려움, 무력감을 아무런 조건 없이 창조주의 통치에 맡기는 것이다." },
    { f: "기도서(Siddur)는 카발리스트의 내적 작업에 어떻게 도움이 되는가?", b: "깨달음을 얻은 지혜자들이 작성한 내적 상태와 교정 과정에 대한 정확한 영적 지도로 기능한다." },
    { f: "리슈마로의 전환이 왜 궁극의 기적으로 여겨지는가?", b: "피조된 본성(자기애)을 순수한 이타주의로 뒤집는 것은 오직 빛의 변형시키는 힘으로만 가능하기 때문이다." },
    { f: "기도는 어떻게 창조주와의 살아있는 대화로 변모하는가?", b: "마음의 움직임이 그분께 밀착하려는 갈망을 정확히 반영할 때 직접적인 내적 소통이 열린다." },
    { f: "'그 일의 완성을 마칠 의무는 네게 없으나, 손을 뗄 자유도 없다'는 말은 무엇을 뜻하는가?", b: "목표는 위로부터 오는 선물이지만, 욕망과 결핍을 짓는 수고는 온전히 사람의 몫이다." },
    { f: "기도와 친구에 대한 사랑 사이에는 어떤 연관성이 있는가?", b: "친구들에게 베풀려는 노력 속에서 사심 없이 사랑할 수 없는 완전한 무능력이 폭로되며, 이는 참된 구원의 부르짖음을 낳는다." },
    { f: "기도 전의 내적 결산은 의도를 어떻게 정화하는가?", b: "숨겨진 이기적 동기를 폭로하고 거짓된 목표를 쳐내어 부르짖음을 진리의 한 점으로 집중시킨다." },
    { f: "수동적인 기다림과 영적 기도의 차이는 무엇인가?", b: "수동성은 싸우지도 않고 굴복하지만, 기도는 한계에 맞서 싸우는 전사의 마지막 외침이다." },
    { f: "토라의 빛은 기도 안에 어떻게 반영되는가?", b: "공부 중에 끌어당겨진 개혁의 빛이 마음의 어둠을 밝혀주어 교정을 구하는 깊은 기도를 깨운다." },
    { f: "참된 기도가 '깊은 곳에서 부르짖는다'는 것은 무슨 뜻인가?", b: "받으려는 욕망의 맨 밑바닥, 에고의 감옥의 가장 어두운 심연에서 터져 나오는 외침이다." },
    { f: "기도는 어떻게 창조주와의 드베쿠트(Dvekut, 결합)로 이끄는가?", b: "베풂의 속성을 획득함으로써 인간은 창조주와의 형태의 동등성을 달성하며, 이것이 온전한 합일이다." },
    { f: "기도에 관한 18과의 가장 중요한 실천적 교훈은 무엇인가?", b: "말을 반복하는 것에 만족하지 말라. 마음에 진정한 히사론을 세워라. 창조주는 마음의 진실에만 응답하시기 때문이다." }
  ],
  hi: [
    { f: "कब्बाला के अनुसार प्रार्थना की परिभाषा क्या है?", b: "'हृदय का कार्य' (Avoda shebaLev), सृष्टिकर्ता के समक्ष अपनी इच्छाओं, इरादों और कमियों का गहरा आंतरिक स्पष्टीकरण।" },
    { f: "कब्बाला में आध्यात्मिक 'हृदय' किसका प्रतीक है?", b: "हृदय मनुष्य की पाने की सभी इच्छाओं के कुल योग और उसकी भावनात्मक तथा संकल्पनात्मक प्रवृत्तियों की समग्रता का प्रतिनिधित्व करता है।" },
    { f: "मुख के शब्दों का संबंध हृदय की इच्छा से कैसे है?", b: "सृष्टिकर्ता केवल हृदय की गहराइयों में स्थित सच्ची कमी (Hisaron) का उत्तर देते हैं, होठों के यांत्रिक शब्दों का कभी नहीं।" },
    { f: "प्रार्थना में 'हिसारोन' (Hisaron) की अवधारणा क्या है?", b: "एक वास्तविक आंतरिक कमी, पात्र (Kli) का वह खालीपन जो तृप्ति और आध्यात्मिक सुधार के लिए तीव्रता से तड़पता है।" },
    { f: "शब्दों के यांत्रिक दोहराव को सच्ची प्रार्थना क्यों नहीं माना जाता?", b: "क्योंकि यदि हृदय उस बात की इच्छा नहीं करता जो होंठ कहते हैं, तो शब्द आध्यात्मिक प्राणशक्ति से रहित निर्जीव रूप बने रहते हैं।" },
    { f: "प्रार्थना स्वीकार होने की पहली शर्त क्या है?", b: "यह अटूट विश्वास कि सृष्टिकर्ता वास्तव में मनुष्य को अहंकार के कारागार से मुक्त कराने में सक्षम हैं।" },
    { f: "प्रार्थना स्वीकार होने की दूसरी शर्त क्या है?", b: "यह अहसास कि कोई अन्य विकल्प नहीं है: सभी मानवीय प्रयास विफल हो चुके हैं और केवल सृष्टिकर्ता ही सहायता कर सकते हैं।" },
    { f: "प्रार्थना स्वीकार होने की तीसरी शर्त क्या है?", b: "यह कि विनती वास्तव में जीवन और मृत्यु का प्रश्न हो, जिसके बिना आत्मा पाने की इच्छा में नष्ट हो जाती है।" },
    { f: "आध्यात्मिक विकास में प्रार्थना 'माध्यम' (medium) के रूप में कैसे कार्य करती है?", b: "यह सृष्टिकर्ता को बदलने का प्रयास नहीं करती, बल्कि मनुष्य को रूपांतरित करती है और क्ली को दान के प्रकाश को प्राप्त करने के लिए तैयार करती है।" },
    { f: "एक कबाली माध्यम के रूप में सच्ची प्रार्थना में क्या मांगता है?", b: "विशेष रूप से दान की कमी (देने की इच्छा) और सृष्टिकर्ता के साथ स्वरूप की समानता मांगता है।" },
    { f: "लिश्मा प्राप्त करने के संबंध में शमाती के 20वें लेख का केंद्रीय संदेश क्या है?", b: "लिश्मा (उनके नाम के लिए / निस्वार्थ समर्पण) ऊपर से मिलने वाला एक उपहार और प्रकाश है जिसे मानवीय बुद्धि अकेले प्राप्त नहीं कर सकती।" },
    { f: "यदि लिश्मा ऊपर से मिलने वाला उपहार है, तो मानवीय प्रयास क्यों आवश्यक है?", b: "क्योंकि प्रयास और सुधार के साधन मनुष्य के भीतर सुधारे हुए पात्रों (Kelim) का निर्माण करते हैं जो वास्तव में लिश्मा प्राप्त करने की इच्छा रखते हैं।" },
    { f: "शमाती 20 के अनुसार प्रार्थना में असफलता और लाचारी की क्या भूमिका है?", b: "जब मनुष्य अपने सभी कर्मों की व्यर्थता को देखता है, तो वह पूर्ण असहायता की स्थिति में पहुंच जाता है, और तभी वह हृदय की गहराइयों से पुकार सकता है।" },
    { f: "मनुष्य अपने हृदय के अंतस्तल से सच्ची प्रार्थना करने में कब सक्षम होता है?", b: "सारे मानवीय उपाय समाप्त करने और यह स्वीकार करने के बाद ही कि वह सृष्टिकर्ता के बिना अपने दम पर कुछ भी हासिल नहीं कर सकता।" },
    { f: "'MAN' (Mayin Nukvin) की अवधारणा का क्या अर्थ है?", b: "स्त्री जल; निचले पात्र से उठने वाली कमी, प्रार्थना और जागरण जो ऊपर से प्रचुरता और प्रकाश को आकर्षित करता है।" },
    { f: "आध्यात्मिक प्रणाली में 'नीचे से जागरण' की क्या भूमिका है?", b: "नीचे से जागरण (सृष्टि की प्रार्थना) उच्च प्रकाशों (MAD - Mayin Dehrin) के प्रवाह को सक्रिय करता है।" },
    { f: "'जो शुद्ध होने आता है, उसकी सहायता की जाती है' सिद्धांत का क्या अर्थ है?", b: "जो ईमानदारी से दान और पवित्रता का प्रयास करता है, सृष्टिकर्ता ऊपर से उसे शक्ति, सुधार और उसके स्वभाव से ऊपर उठने की क्षमता प्रदान करते हैं।" },
    { f: "सृष्टिकर्ता शुद्ध होने आने वाले की विशेष रूप से कैसे सहायता करते हैं?", b: "उसे लिश्मा का स्तर प्रदान करके, उसके हृदय को जाग्रत करके और उसे उसके अहंकारी स्वभाव से परे अलौकिक शक्ति देकर।" },
    { f: "दैनिक आंतरिक स्पष्टीकरण के दौरान 'हृदय का कार्य' क्या है?", b: "अपने स्वभाव को रूपांतरित करने की निरंतर प्रार्थना के साथ अहंकारी इच्छाओं को देने की इच्छा से अलग करना।" },
    { f: "प्रार्थना से सृष्टिकर्ता क्यों नहीं बदलते?", b: "क्योंकि सृष्टिकर्ता परम कल्याणकारी और अपरिवर्तनीय हैं; प्रार्थना प्राप्त करने वाले पात्र को बदलती है ताकि वह प्रकाश को धारण करने के योग्य बन सके।" },
    { f: "पारंपरिक धार्मिक प्रार्थना और कबालिस्टिक प्रार्थना में क्या अंतर है?", b: "पारंपरिक प्रार्थना भौतिक लाभ या अहंकार के लिए राहत मांगती है, जबकि कबालिस्टिक प्रार्थना अहंकार से मुक्ति की गुहार लगाती है। " },
    { f: "आध्यात्मिक मार्ग पर एक सच्चा हिसारोन कैसे जन्म लेता है?", b: "समूह में निरंतर कार्य और स्रोतों के अध्ययन के माध्यम से, जहाँ कमी दान के प्रकाश की अनुपस्थिति के रूप में स्पष्ट हो जाती है।" },
    { f: "शरीर का 'स्वर्ग के राज्य के जुए से सहमत न होना' क्या दर्शाता है?", b: "पाने की जन्मजात इच्छा व्यक्तिगत पुरस्कार के बिना विशुद्ध रूप से सृष्टिकर्ता की प्रसन्नता के लिए कार्य करने का सहज रूप से विरोध करती है।" },
    { f: "जब मनुष्य देखता है कि उसके सारे अंग दान का विरोध करते हैं, तो उसे क्या करना चाहिए?", b: "प्रार्थना के अलावा कोई उपाय नहीं है: सृष्टिकर्ता के सामने अपना हृदय उड़ेल देना ताकि वे शरीर को दान के अधीन कर दें।" },
    { f: "लिश्मा की प्राप्ति बुरी प्रवृत्ति को कैसे समाप्त करती है?", b: "यह आत्म-प्रेम को निष्प्रभावी कर देती है; प्राप्ति के पात्र अपना स्वार्थी कार्य खो देते हैं और आध्यात्मिक रूप से 'मृत' माने जाते हैं।" },
    { f: "यह जानना क्यों महत्वपूर्ण है कि प्रार्थना के बिना लिश्मा प्राप्त नहीं किया जा सकता?", b: "क्योंकि यह समझ प्रार्थना को एक पूर्ण और अपरिहार्य आवश्यकता बना देती है, जिससे आत्म-संतुष्टि का भ्रम दूर हो जाता है।" },
    { f: "MAN को ऊपर उठाने और आत्मा के पात्र के बीच क्या संबंध है?", b: "MAN स्वयं क्ली की कमी है; कमी जितनी अधिक शुद्ध और गहरी होगी, पात्र उतना ही बड़ा प्रकाश ग्रहण कर सकेगा।" },
    { f: "किस अर्थ में प्रार्थना अहंकार की लाचारी की स्वीकारोक्ति है?", b: "हृदय अपनी पूर्ण निर्भरता को उजागर करता है, यह स्वीकार करते हुए कि उसका अपना अहंकार ईश्वरीय सहायता के बिना एक अभेद्य कारागार है।" },
    { f: "समूह कार्य व्यक्तिगत प्रार्थना के साथ कैसे एकीकृत होता है?", b: "मित्रों से प्रेम करने का प्रयास निस्वार्थ भाव से देने की पूर्ण अक्षमता को उजागर करता है, जिससे सहायता के लिए एक सच्ची पुकार जन्म लेती है।" },
    { f: "प्रार्थना को आध्यात्मिक पात्र का वास्तविक निर्माण क्यों माना जाता है?", b: "क्योंकि तृप्ति केवल वहीं प्रवेश कर सकती है जहाँ अनुरूप शून्यता हो; प्रार्थना इस आध्यात्मिक शून्यता को परिभाषित और विस्तारित करती है।" },
    { f: "'सृष्टिकर्ता प्रार्थना सुनते हैं' इस कथन का क्या अर्थ है?", b: "याचना देने के उच्च नियम के साथ पूर्ण सामंजस्य में आ जाती है और प्रकाश तुरंत खुले क्ली को भर देता है।" },
    { f: "प्रार्थना के जन्म में आध्यात्मिक निराशा की क्या भूमिका है?", b: "यह अहंकारी शक्तियों की पूर्ण थकावट का संकेत देती है, जो ऊपर से आने वाली सहायता के ठीक पहले की अवस्था है।" },
    { f: "'ऊपर से जागरण' (Itaruta de-Leila) क्या है?", b: "उच्च प्रकाश का प्रकटीकरण जो नीचे से उठी परिपक्व और शुद्ध कमी (MAN) के प्रत्यक्ष उत्तर के रूप में उतरता है।" },
    { f: "शमाती 20 में पाने की इच्छा की तुलना 'चोर' से क्यों की गई है?", b: "क्योंकि यह ऊर्जा और आनंद के हर अंश को केवल अपने स्वार्थी सुख के लिए चुराने और हथियाने का प्रयास करती है।" },
    { f: "शुरुआत में मनुष्य को दान के कार्य में कोई आनंद क्यों महसूस नहीं होता?", b: "ताकि पाने की इच्छा इसमें कोई स्वाद न पा सके; यदि उसे सुख मिलता, तो मनुष्य कभी भी शुद्ध लिश्मा तक नहीं उठ पाता।" },
    { f: "आध्यात्मिक कार्य अपने आप में कब एक आनंद बन जाता है?", b: "जब मनुष्य देने का आदी हो जाता है, और सृष्टिकर्ता को प्रसन्न करना ही प्रयास का सबसे बड़ा पुरस्कार बन जाता है।" },
    { f: "आध्यात्मिक कार्य में शिकायत कब उचित या अनुचित होती है?", b: "कोई केवल उसी स्वामी से शिकायत कर सकता है जिसके लिए वह वास्तव में कार्य करता है; अहंकार के लिए काम करते हुए सृष्टिकर्ता से शक्ति मांगने का कोई अधिकार नहीं है।" },
    { f: "प्रार्थना में आंतरिक स्पष्टीकरण (Berur) क्या है?", b: "इरादों की छँटाई: अपने अहंकार के लिए किए जाने वाले कार्यों को सृष्टिकर्ता की प्रसन्नता के लिए किए जाने वाले कार्यों से अलग करना।" },
    { f: "स्वर्ग के राज्य के जुए को स्वीकार करने में 'पूर्ण परिपूर्णता' क्या है?", b: "केवल देना चाहना और अपने स्वार्थ के लिए प्राप्ति का पूर्ण त्याग करना।" },
    { f: "हृदय की प्रार्थना के लिए बौद्धिक समझ पर्याप्त क्यों नहीं है?", b: "बुद्धि के तर्क आध्यात्मिक पात्र को हिला नहीं सकते; केवल हृदय में अनुभव की गई वास्तविक कमी ही प्रकाश को आकर्षित करती है।" },
    { f: "MAN आध्यात्मिक संसारों के स्तरों के माध्यम से कैसे कार्य करता है?", b: "निचला स्तर अपनी कमी को उच्च स्तर तक उठाता है, जो इसे स्रोत तक ले जाता है और उत्तर को नीचे लाता है।" },
    { f: "प्रार्थना को पाने की इच्छा के विरुद्ध एकमात्र हथियार क्यों कहा जाता है?", b: "मनुष्य अपने रचे गए स्वभाव को स्वयं नहीं बदल सकता; वह केवल दान का एक नया स्वभाव पाने के लिए सृष्टिकर्ता को पुकार सकता है।" },
    { f: "प्रार्थना एक क्षणिक कार्य न होकर एक सतत प्रक्रिया क्यों है?", b: "प्रयासों और गिरावटों की एक श्रृंखला आंतरिक कमी को तब तक तराशती और परिपक्व करती है जब तक कि वह पूर्ण निष्कपटता तक न पहुँच जाए।" },
    { f: "घोर अंधकारमय अवस्थाओं में उद्धार का विश्वास कैसे प्रकट होता है?", b: "भले ही शरीर को कोई रास्ता न दिखे, हृदय का बिंदु आश्वस्त रहता है कि सृष्टिकर्ता पलक झपकते ही उद्धार कर सकते हैं।" },
    { f: "'सृष्टिकर्ता धर्मियों की प्रार्थना की लालसा रखते हैं' का क्या अर्थ है?", b: "सृष्टिकर्ता दान करने में सक्षम एक तैयार क्ली की प्रतीक्षा करते हैं, क्योंकि उनके प्रेम का स्वभाव ही परिपूर्णता प्रदान करना है।" },
    { f: "पश्चाताप (Tshuva) और कबालिस्टिक प्रार्थना के बीच क्या संबंध है?", b: "पश्चाताप अहंकारी स्वभाव की पीड़ादायक पहचान है, और प्रार्थना उससे मुक्ति की याचना है।" },
    { f: "प्रार्थना मनुष्य को आध्यात्मिक अहंकार से कैसे बचाती है?", b: "यह इस जागरूकता को सुदृढ़ करती है कि प्राप्त किया गया प्रत्येक आध्यात्मिक स्तर केवल ऊपर से मिला अवांछित उपहार और अनुग्रह है।" },
    { f: "कभी-कभी ऐसा क्यों प्रतीत होता है कि प्रार्थना अनुत्तरित रह गई है?", b: "कमी अभी तक आवश्यक गहराई या शुद्धता तक नहीं पहुँची है; पात्र अभी प्रकाश को धारण करने के लिए तैयार नहीं है।" },
    { f: "'सृष्टिकर्ता के सामने अपना हृदय उड़ेलने' का क्या अर्थ है?", b: "अपनी सभी गुप्त इच्छाओं, भयों और लाचारी को बिना किसी शर्त के सृष्टिकर्ता के मार्गदर्शन में सौंप देना।" },
    { f: "प्रार्थना पुस्तक (Siddur) कबाली के आंतरिक कार्य में कैसे सहायता करती है?", b: "यह आत्मज्ञानी ऋषियों द्वारा तैयार किए गए आंतरिक अवस्थाओं और सुधार प्रक्रियाओं के एक सटीक आध्यात्मिक मानचित्र के रूप में कार्य करती है।" },
    { f: "लिश्मा में परिवर्तन को एक परम चमत्कार क्यों माना जाता है?", b: "क्योंकि रचे गए स्वभाव (आत्म-प्रेम) को शुद्ध परोपकार में बदलना केवल प्रकाश की रूपांतरणकारी शक्ति से ही संभव है।" },
    { f: "प्रार्थना सृष्टिकर्ता के साथ एक जीवंत संवाद में कैसे बदल जाती है?", b: "जब हृदय का स्पंदन उनके साथ जुड़ने की लालसा को सटीक रूप से दर्शाता है, तो एक सीधा आंतरिक संवाद खुल जाता है।" },
    { f: "'कार्य को पूरा करना तुम्हारा दायित्व नहीं है, पर तुम इससे विमुख होने के लिए भी स्वतंत्र नहीं हो' का क्या अर्थ है?", b: "यद्यपि लक्ष्य ऊपर से एक उपहार है, इच्छा और कमी के निर्माण का पूरा श्रम पूरी तरह से मनुष्य पर निर्भर करता है।" },
    { f: "प्रार्थना और मित्रों के प्रति प्रेम के बीच क्या संबंध है?", b: "मित्रों को दान करने के प्रयास में निस्वार्थ प्रेम करने की पूर्ण अक्षमता उजागर होती है, जिससे सहायता के लिए एक सच्ची पुकार जन्म लेती है।" },
    { f: "प्रार्थना से पहले आत्म-निरीक्षण इरादे को कैसे शुद्ध करता है?", b: "यह छिपे हुए स्वार्थी इरादों को उजागर करता है, झूठे लक्ष्यों को हटाता है और पुकार को सत्य के एक ही बिंदु पर केंद्रित करता है।" },
    { f: "निष्क्रिय प्रतीक्षा और आध्यात्मिक प्रार्थना में क्या अंतर है?", b: "निष्क्रियता बिना लड़े आत्मसमर्पण कर देती है, जबकि प्रार्थना अपनी शक्ति की अंतिम सीमा तक लड़ने वाले योद्धा की अंतिम पुकार है।" },
    { f: "तोराह का प्रकाश प्रार्थना में कैसे प्रतिबिंबित होता है?", b: "अध्ययन के दौरान आकर्षित होने वाला सुधारक प्रकाश हृदय के अंधकार को दूर करता है, सुधार के लिए एक गहरी विनती को जगाता है।" },
    { f: "सच्ची प्रार्थना का 'गहराइयों से पुकारना' क्या दर्शाता है?", b: "वह पुकार जो पाने की इच्छा के सबसे निचले तल से, अहंकार के कारागार के सबसे अंधकारमय गर्त से फूटती है।" },
    { f: "प्रार्थना सृष्टिकर्ता के साथ द्वेकूत (Dvekut, जुड़ाव) की ओर कैसे ले जाती है?", b: "दान के गुण को प्राप्त करके मनुष्य सृष्टिकर्ता के साथ स्वरूप की समानता प्राप्त करता है, जो कि पूर्ण एकता है।" },
    { f: "प्रार्थना के बारे में पाठ 18 का सबसे महत्वपूर्ण व्यावहारिक सबक क्या है?", b: "केवल शब्दों को दोहराने से संतुष्ट न हों; अपने हृदय में एक सच्चा हिसारोन बनाएं, क्योंकि सृष्टिकर्ता केवल हृदय के सत्य को सुनते हैं।" }
  ],
  id: [
    { f: "Apa definisi kabalistik tentang doa?", b: "'Kerja di dalam hati' (Avoda shebaLev), sebuah klarifikasi batin yang mendalam tentang keinginan, niat, dan kekurangan di hadapan Sang Pencipta." },
    { f: "Apa yang dilambangkan oleh 'hati' spiritual dalam Kabbalah?", b: "Hati melambangkan jumlah total dari semua keinginan menerima pada manusia serta seluruh kecenderungan emosional dan kehendaknya." },
    { f: "Bagaimana hubungan antara kata-kata di mulut dan keinginan di hati?", b: "Sang Pencipta secara eksklusif hanya menjawab kekurangan yang sejati (Hisaron) di kedalaman hati, bukan kata-kata mekanis di bibir." },
    { f: "Apa konsep 'Hisaron' dalam doa?", b: "Kekurangan batiniah yang sejati, kehampaan bejana (Kli) yang sangat mendambakan kepenuhan dan perbaikan spiritual." },
    { f: "Mengapa pengulangan kata-kata secara mekanis tidak dianggap sebagai doa sejati?", b: "Karena jika hati tidak mendambakan apa yang diucapkan bibir, kata-kata itu tetap menjadi bentuk mati tanpa daya vitalitas spiritual." },
    { f: "Apa syarat pertama agar doa dikabulkan?", b: "Iman yang tak tergoyahkan bahwa Sang Pencipta benar-benar sanggup membebaskan manusia dari penjara egoisme." },
    { f: "Apa syarat kedua agar doa dikabulkan?", b: "Kesadaran bahwa tidak ada pilihan lain: semua kekuatan manusia telah gagal dan hanya Sang Pencipta yang dapat menolong." },
    { f: "Apa syarat ketiga agar doa dikabulkan?", b: "Bahwa permohonan itu benar-benar merupakan masalah hidup dan mati, yang tanpanya jiwa akan binasa di dalam keinginan menerima." },
    { f: "Bagaimana doa bertindak sebagai 'medium' dalam evolusi spiritual?", b: "Doa tidak berupaya mengubah Sang Pencipta, melainkan mentransformasi manusia dan mempersiapkan Kli untuk menerima cahaya penganugerahan." },
    { f: "Apa yang diminta seorang kabalis dalam doa sejati sebagai medium?", b: "Semata-mata kekurangan untuk menganugerahkan (keinginan untuk memberi) dan kesetaraan bentuk dengan Sang Pencipta." },
    { f: "Apa pesan utama dari artikel Shamati 20 tentang pencapaian Lishma?", b: "Lishma (demi Nama-Nya / penganugerahan tanpa pamrih) adalah anugerah dan pencerahan dari Atas yang tidak dapat diraih oleh akal manusia sendirian." },
    { f: "Jika Lishma adalah anugerah dari Atas, mengapa usaha manusia tetap diperlukan?", b: "Karena usaha dan sarana perbaikan membangun bejana-bejana yang telah diperbaiki (Kelim) di dalam diri manusia yang sungguh-sungguh ingin menerima Lishma." },
    { f: "Apa peran kegagalan dan ketidakberdayaan dalam doa menurut Shamati 20?", b: "Ketika manusia melihat kesia-siaan dari semua tindakannya, ia mencapai ketidakberdayaan total, dan baru saat itulah ia dapat berseru dari lubuk hatinya." },
    { f: "Kapan seseorang mampu memanjatkan doa yang tulus dari lubuk hatinya?", b: "Hanya setelah mencoba semua sarana manusiawi dan mengakui bahwa ia sendiri tidak dapat mencapai apa pun tanpa Sang Pencipta." },
    { f: "Apa arti konsep 'MAN' (Mayin Nukvin)?", b: "Air feminin; kekurangan, doa, dan kebangkitan yang naik dari bejana yang lebih rendah yang menarik kelimpahan dan Cahaya dari Atas." },
    { f: "Apa peran 'kebangkitan dari bawah' dalam sistem spiritual?", b: "Kebangkitan dari bawah (doa makhluk ciptaan) memicu pancaran Cahaya-Cahaya Tingkat Tinggi (MAD - Mayin Dehrin)." },
    { f: "Apa arti prinsip 'Barang siapa datang untuk menyucikan diri, ia akan ditolong'?", b: "Kepada siapa pun yang bersungguh-sungguh berikhtiar menuju penganugerahan dan kemurnian, Sang Pencipta memberi kekuatan, perbaikan, dan pengangkatan melampaui kodrat egoisnya dari Atas." },
    { f: "Bagaimana Sang Pencipta secara khusus menolong orang yang datang untuk menyucikan diri?", b: "Dengan menganugerahinya derajat Lishma, membangkitkan hatinya, dan memberinya kekuatan adikodrati yang melampaui kodrat egoisnya." },
    { f: "Apa itu 'kerja di dalam hati' selama klarifikasi batin harian?", b: "Membedakan keinginan egois dari keinginan untuk memberi, disertai doa terus-menerus demi transformasi kodrat diri." },
    { f: "Mengapa Sang Pencipta tidak berubah melalui doa?", b: "Karena Sang Pencipta adalah Kebaikan Mutlak dan Tak Berubah; doa mengubah bejana penerima sehingga mampu menampung Cahaya." },
    { f: "Apa perbedaan antara doa religius konvensional dan doa kabalistik?", b: "Doa biasa meminta keuntungan materi atau kelegaan bagi ego, sedangkan doa kabalistik memohon penebusan dari egoisme itu sendiri." },
    { f: "Bagaimana Hisaron yang sejati lahir di jalur spiritual?", b: "Melalui kerja gigih di dalam kelompok dan penelaahan sumber-sumber otentik, di mana kekurangan diperjelas sebagai ketiadaan cahaya penganugerahan." },
    { f: "Apa artinya bahwa tubuh 'tidak menyetujui kuk Kerajaan Surga'?", b: "Keinginan bawaan untuk menerima secara naluriah menolak bekerja murni demi kesenangan Sang Pencipta tanpa imbalan pribadi." },
    { f: "Apa yang harus dilakukan manusia ketika melihat semua organ tubuhnya menentang penganugerahan?", b: "Ia tidak memiliki jalan lain selain berdoa: mencurahkan isi hatinya di hadapan Sang Pencipta agar Dia menundukkan tubuh kepada penganugerahan." },
    { f: "Bagaimana pencapaian Lishma mematikan kecenderungan jahat?", b: "Itu meniadakan cinta diri; bejana-bejana penerimaan kehilangan fungsi egoisnya dan secara spiritual dianggap 'mati'." },
    { f: "Mengapa sangat penting untuk mengetahui bahwa tanpa doa Lishma mustahil dicapai?", b: "Karena pemahaman ini menjadikan doa sebagai kebutuhan mutlak dan mendesak, melenyapkan ilusi kepuasan diri palsu." },
    { f: "Apa hubungan antara menaikkan MAN dan bejana jiwa?", b: "MAN adalah kekurangan dari Kli itu sendiri; semakin murni dan dalam kekurangan tersebut, semakin besar Cahaya yang dapat ditampung bejana." },
    { f: "Dalam arti apa doa merupakan pengakuan atas ketidakberdayaan egoisme?", b: "Hati menyingkapkan ketergantungan mutlaknya, mengakui bahwa egonya sendiri adalah penjara yang tak tertembus tanpa pertolongan ilahi." },
    { f: "Bagaimana kerja kelompok berpadu dengan doa pribadi?", b: "Upaya untuk mengasihi teman-teman menyingkapkan ketidakmampuan total untuk memberi tanpa pamrih, melahirkan jeritan pertolongan yang sejati." },
    { f: "Mengapa doa dianggap sebagai penciptaan bejana spiritual itu sendiri?", b: "Karena pemenuhan hanya dapat masuk ke tempat di mana ada kehampaan yang sepadan; doa menegaskan dan memperluas ruang hampa spiritual ini." },
    { f: "Apa arti ungkapan 'Sang Pencipta mendengar doa'?", b: "Permohonan itu beresonansi sempurna dengan hukum penganugerahan yang lebih tinggi, dan Cahaya seketika mengisi Kli yang terbuka." },
    { f: "Apa peran keputusasaan spiritual dalam kelahiran doa?", b: "Hal itu menandai habisnya kekuatan egois secara tuntas, yang secara langsung mendahului turunnya pertolongan dari Atas." },
    { f: "Apa itu 'kebangkitan dari Atas' (Itaruta de-Leila)?", b: "Pengejawantahan Cahaya Tingkat Tinggi yang turun sebagai respons langsung terhadap kekurangan yang matang dan dimurnikan dari bawah (MAN)." },
    { f: "Mengapa keinginan menerima diibaratkan sebagai 'pencuri' dalam Shamati 20?", b: "Karena ia mencoba mencuri dan merampas setiap serpihan energi dan sukacita semata-mata untuk kenikmatan egoisnya sendiri." },
    { f: "Mengapa manusia pada awalnya tidak merasakan sukacita dalam bekerja demi memberi?", b: "Agar keinginan menerima tidak mengecap kenikmatan di dalamnya; jika ia merasakan kepuasan egois, manusia tidak akan pernah bisa naik ke Lishma yang murni." },
    { f: "Kapan kerja spiritual menjadi sukacita dalam dirinya sendiri?", b: "Ketika manusia terbiasa memberi, dan memberikan kesenangan kepada Sang Pencipta menjadi upah terbesar dari usaha itu sendiri." },
    { f: "Kapan keluhan dalam kerja spiritual dibenarkan atau tidak dibenarkan?", b: "Seseorang hanya dapat mengeluh kepada tuan yang benar-benar ia layani; bekerja untuk ego tidak memberi hak menuntut kekuatan dari Sang Pencipta." },
    { f: "Apa itu klarifikasi batin (Berur) dalam doa?", b: "Pemilahan niat: memisahkan apa yang dilakukan demi ego sendiri dari apa yang murni ditujukan untuk kesenangan Sang Pencipta." },
    { f: "Apa itu 'kesempurnaan mutlak' dalam memikul kuk Kerajaan Surga?", b: "Hanya ingin memberi, dan melepaskan sepenuhnya penerimaan demi keuntungan diri sendiri." },
    { f: "Mengapa pemahaman intelektual tidak mencukupi untuk doa di hati?", b: "Argumen akal tidak menggerakkan bejana spiritual; hanya kekurangan nyata yang dialami di dalam hatilah yang menarik Cahaya." },
    { f: "Bagaimana MAN bekerja melalui tingkatan dunia spiritual?", b: "Tingkatan yang lebih rendah menaikkan kekurangannya ke tingkatan yang lebih tinggi, yang kemudian membawanya ke Sumber dan menurunkan jawabannya." },
    { f: "Mengapa doa disebut sebagai satu-satunya senjata melawan keinginan menerima?", b: "Manusia tidak dapat mengubah kodrat ciptaannya sendiri; ia hanya dapat berseru kepada Sang Pencipta agar dianugerahi kodrat memberi yang baru." },
    { f: "Mengapa doa merupakan proses berkelanjutan dan bukan tindakan sesaat?", b: "Rangkaian upaya dan kejatuhan mengasah dan mematangkan kekurangan batin hingga mencapai ketulusan mutlak." },
    { f: "Bagaimana iman akan keselamatan terwujud dalam keadaan yang paling gelap?", b: "Bahkan ketika tubuh tidak melihat jalan keluar, titik di dalam hati yakin bahwa Sang Pencipta dapat menyelamatkan dalam sekejap mata." },
    { f: "Apa artinya bahwa 'Sang Pencipta mendambakan doa orang-orang benar'?", b: "Sang Pencipta menantikan Kli yang siap dan mampu memberi, karena hakikat kasih-Nya adalah melimpahkan kepenuhan." },
    { f: "Apa hubungan antara pertobatan (Tshuva) dan doa kabalistik?", b: "Pertobatan adalah kesadaran menyakitkan akan kodrat egois, dan doa adalah permohonan untuk dibebaskan darinya." },
    { f: "Bagaimana doa melindungi manusia dari kesombongan spiritual?", b: "Doa menanamkan kesadaran bahwa setiap tingkat spiritual yang dicapai semata-mata adalah anugerah dan belas kasihan yang tak layak diterima dari Atas." },
    { f: "Mengapa terkadang sebuah doa tampak tidak terjawab?", b: "Kekurangan tersebut belum mencapai kedalaman atau kemurnian yang dibutuhkan; bejana belum siap menahan Cahaya." },
    { f: "Apa arti 'mencurahkan isi hati di hadapan Sang Pencipta'?", b: "Penyerahan tanpa syarat atas semua keinginan tersembunyi, ketakutan, dan ketidakberdayaan di bawah bimbingan Sang Pencipta." },
    { f: "Bagaimana buku doa (Siddur) membantu kerja batin seorang kabalis?", b: "Buku itu berfungsi sebagai peta spiritual yang tepat tentang keadaan batin dan proses perbaikan yang disusun oleh para bijak yang telah mencapainya." },
    { f: "Mengapa peralihan ke Lishma dianggap sebagai mukjizat tertinggi?", b: "Karena mengubah kodrat ciptaan (cinta diri) menjadi altruisme murni hanya mungkin dilakukan melalui kekuatan Cahaya yang mentransformasi." },
    { f: "Bagaimana doa berubah menjadi dialog hidup dengan Sang Pencipta?", b: "Ketika getaran hati mencerminkan kerinduan untuk melekat pada-Nya secara tepat, terbukalah komunikasi batin yang langsung." },
    { f: "Apa arti pepatah 'Bukan tugasmu menyelesaikan pekerjaan itu, tetapi kamu tidak bebas menghindarinya'?", b: "Meskipun tujuan adalah anugerah dari Atas, jerih payah membangun keinginan dan kekurangan sepenuhnya berada di pundak manusia." },
    { f: "Apa hubungan antara doa dan kasih kepada teman-teman?", b: "Dalam upaya memberi kepada teman-teman, ketidakmampuan total untuk mengasihi tanpa pamrih tersingkap, melahirkan seruan pertolongan yang sejati." },
    { f: "Bagaimana introspeksi sebelum doa memurnikan niat?", b: "Introspeksi menyingkap motif-motif egois tersembunyi, menyingkirkan tujuan palsu, dan memusatkan seruan pada satu titik kebenaran." },
    { f: "Apa perbedaan antara menunggu pasif dan doa spiritual?", b: "Kepasifan menyerah tanpa perlawanan, sedangkan doa adalah jeritan puncak dari seorang pejuang yang bertarung hingga batas kekuatannya." },
    { f: "Bagaimana Cahaya Taurat terpancar di dalam doa?", b: "Cahaya Pembaruan yang ditarik saat belajar menerangi kegelapan hati, membangkitkan permohonan mendalam untuk perbaikan." },
    { f: "Apa artinya bahwa doa yang sejati 'berseru dari kedalaman'?", b: "Jeritan yang membuncah dari dasar keinginan menerima yang paling dalam, dari jurang paling kelam di penjara ego." },
    { f: "Bagaimana doa menuntun pada Dvekut (pelekatan) dengan Sang Pencipta?", b: "Dengan memperoleh sifat memberi, manusia mencapai kesetaraan bentuk dengan Sang Pencipta, yang merupakan kesatuan sempurna." },
    { f: "Apa pelajaran praktis terpenting dari Pelajaran 18 tentang doa?", b: "Jangan puas hanya dengan mengulang kata-kata; bangunlah Hisaron sejati di dalam hatimu, karena Sang Pencipta hanya mendengar kebenaran hati." }
  ],
  tl: [
    { f: "Ano ang kabalistang depinisyon ng panalangin?", b: "'Gawa sa puso' (Avoda shebaLev), isang malalim na panloob na paglilinaw ng mga hangarin, intensiyon, at kakulangan sa harap ng Maylalang." },
    { f: "Ano ang kinakatawan ng espirituwal na 'puso' sa Kabbalah?", b: "Kinakatawan ng puso ang kabuuan ng lahat ng pagnanais na tumanggap ng tao at ang kalahatan ng kanyang emosyonal at kusang hilig." },
    { f: "Paano nauugnay ang mga salita ng bibig sa hangarin ng puso?", b: "Eksklusibong sumasagot ang Maylalang sa tunay na kakulangan (Hisaron) sa kaibuturan ng puso, hindi kailanman sa mekanikal na mga salita ng mga labi." },
    { f: "Ano ang konsepto ng 'Hisaron' sa panalangin?", b: "Isang tunay na panloob na kakulangan, ang kahungkagan ng sisidlan (Kli) na marubdob na nananabik sa kapuspusan at espirituwal na pagwawasto." },
    { f: "Bakit hindi itinuturing na tunay na panalangin ang mekanikal na pag-uulit ng mga salita?", b: "Dahil kung hindi ninanais ng puso ang binibigkas ng mga labi, ang mga salita ay nananatiling patay na anyo na walang espirituwal na sigla." },
    { f: "Ano ang unang kondisyon para marinig ang panalangin?", b: "Matibay na pananampalataya na ang Maylalang ay tunay na may kakayahang palayain ang tao mula sa bilangguan ng egoismo." },
    { f: "Ano ang ikalawang kondisyon para marinig ang panalangin?", b: "Ang pagkaunawa na walang ibang pagpipilian: ang lahat ng lakas ng tao ay nabigo at ang Maylalang lamang ang makatutulong." },
    { f: "Ano ang ikatlong kondisyon para marinig ang panalangin?", b: "Na ang kahilingan ay tunay na usapin ng buhay at kamatayan, na kung wala ito ay mapapahamak ang kaluluwa sa pagnanais na tumanggap." },
    { f: "Paano gumagana ang panalangin bilang isang 'medium' sa espirituwal na ebolusyon?", b: "Hindi nito hinahangad na baguhin ang Maylalang, kundi binabago nito ang tao at inihahanda ang Kli na tanggapin ang liwanag ng pagkakaloob." },
    { f: "Ano ang hinihiling ng kabalista sa tunay na panalangin bilang medium?", b: "Tanging ang kakulangan sa pagkakaloob (ang hangaring magkaloob) at ang pagkakapantay ng anyo sa Maylalang." },
    { f: "Ano ang pangunahing mensahe ng artikulo 20 ng Shamati tungkol sa pagkamit ng Lishma?", b: "Ang Lishma (para sa Kanyang Pangalan / walang pag-iimbot na pagkakaloob) ay isang regalo at kaliwanagan mula sa Itaas na hindi kayang abutin ng isip ng tao nang mag-isa." },
    { f: "Kung ang Lishma ay regalo mula sa Itaas, bakit kailangan ang pagsisikap ng tao?", b: "Dahil ang mga pagsisikap at remedyo ang nagtatayo sa tao ng mga naitamang sisidlan (Kelim) na tunay na nagnanais na tumanggap ng Lishma." },
    { f: "Ano ang papel ng kabiguan at kawalan ng kapangyarihan sa panalangin ayon sa Shamati 20?", b: "Kapag nakita ng tao ang kawalang-saysay ng lahat ng kanyang gawa, nararating niya ang lubos na kawalan ng magagawa, at doon lamang siya makatitili mula sa kaibuturan ng kanyang puso." },
    { f: "Kailan nagiging may kakayahan ang tao na mag-alay ng taimtim na panalangin mula sa kaibuturan ng puso?", b: "Pagkatapos lamang subukan ang lahat ng pamamaraan ng tao at kilalanin na wala siyang magagawa sa sarili nang walang Maylalang." },
    { f: "Ano ang kahulugan ng konseptong 'MAN' (Mayin Nukvin)?", b: "Pambabaeng tubig; ang kakulangan, panalangin, at paggising na umaakyat mula sa mas mababang sisidlan na humihila ng kasaganaan at Liwanag mula sa Itaas." },
    { f: "Ano ang papel ng 'paggising mula sa ibaba' sa espirituwal na sistema?", b: "Ang paggising mula sa ibaba (ang panalangin ng nilikha) ang nagpapasimula ng pagbuhos ng Mas Mataas na Liwanag (MAD - Mayin Dehrin)." },
    { f: "Ano ang ibig sabihin ng alituntuning 'Ang lumalapit upang maglinis ay tinutulungan'?", b: "Sa sinumang taimtim na nagsisikap tungo sa pagkakaloob at kadalisayan, ang Maylalang ay nagbibigay mula sa Itaas ng lakas, pagwawasto, at pag-angat higit sa kanyang egoistikong kalikasan." },
    { f: "Paano partikular na tinutulungan ng Maylalang ang lumalapit upang maglinis?", b: "Sa pamamagitan ng paggawad sa kanya ng antas ng Lishma, paggising sa kanyang puso, at pagbibigay ng higit-sa-natural na lakas na lumalampas sa kanyang kalikasan." },
    { f: "Ano ang 'gawa sa puso' sa panahon ng pang-araw-araw na panloob na paglilinaw?", b: "Ang paghihiwalay ng mga makasariling hangarin mula sa hangaring magkaloob, kalakip ang patuloy na panalangin para sa pagbabago ng sariling kalikasan." },
    { f: "Bakit hindi nababago ang Maylalang sa pamamagitan ng panalangin?", b: "Dahil ang Maylalang ay Ganap na Mabuti at Hindi Nagbabago; binabago ng panalangin ang tumatanggap na sisidlan upang maging karapat-dapat itong maglaman ng Liwanag." },
    { f: "Ano ang pagkakaiba ng karaniwang panrelihiyong panalangin sa kabalistang panalangin?", b: "Ang karaniwang panalangin ay humihingi ng materyal na kapakinabangan o kaginhawahan para sa ego, habang ang kabalistang panalangin ay sumasamo para sa kaligtasan mula sa mismong egoismo." },
    { f: "Paano isinisilang ang isang tunay na Hisaron sa espirituwal na landas?", b: "Sa pamamagitan ng matiyagang paggawa sa pangkat at pag-aaral ng mga pinagmulan, kung saan ang kakulangan ay nililinaw bilang kawalan ng liwanag ng pagkakaloob." },
    { f: "Ano ang ibig sabihin na ang katawan ay 'hindi sumasang-ayon sa pamatok ng Kaharian ng Langit'?", b: "Ang likas na hangaring tumanggap ay likas na tumatanggi na magtrabaho para lamang sa kasiyahan ng Maylalang nang walang personal na gantimpala." },
    { f: "Ano ang dapat gawin ng tao kapag nakita niyang ang lahat ng kanyang organo ay lumalaban sa pagkakaloob?", b: "Wala siyang ibang paraan kundi manalangin: ibuhos ang kanyang puso sa harap ng Maylalang upang pasukuin Niya ang katawan sa pagkakaloob." },
    { f: "Paano pinapatay ng pagkamit sa Lishma ang masamang hilig?", b: "Pinawawalang-bisa nito ang pagmamahal sa sarili; nawawala ang makasariling gamit ng mga sisidlan ng pagtanggap at espirituwal na itinuturing na 'patay'." },
    { f: "Bakit napakahalagang malaman na kung walang panalangin ay imposibleng maabot ang Lishma?", b: "Dahil ginagawa ng kabatirang ito ang panalangin na isang ganap at kagyat na pangangailangan, na nagpapawi sa ilusyon ng huwad na pagtitiwala sa sarili." },
    { f: "Ano ang kaugnayan ng pagtataas ng MAN at ng sisidlan ng kaluluwa?", b: "Ang MAN ay ang mismong kakulangan ng Kli; habang mas dalisay at malalim ang kakulangang iyon, mas malaking Liwanag ang kayang tanggapin ng sisidlan." },
    { f: "Sa anong diwa ang panalangin ay pag-amin sa kawalan ng kapangyarihan ng egoismo?", b: "Inilalantad ng puso ang lubos na pag-asa nito, na kinikilalang ang sariling ego ay isang bilangguang hindi matatakasan kung walang banal na tulong." },
    { f: "Paano nakikipag-ugnayan ang gawa sa pangkat sa personal na panalangin?", b: "Ang pagsisikap na ibigin ang mga kaibigan ay naglalantad ng ganap na kawalan ng kakayahang magkaloob nang walang pag-iimbot, na nagsisilang ng tunay na daing para sa tulong." },
    { f: "Bakit itinuturing ang panalangin bilang mismong paglikha ng espirituwal na sisidlan?", b: "Dahil ang kapuspusan ay maaari lamang pumasok kung saan may katumbas na kawalan; tinutukoy at pinalalawak ng panalangin ang espirituwal na hungkag na puwang na ito." },
    { f: "Ano ang ibig sabihin ng pariralang 'dinirinig ng Maylalang ang panalangin'?", b: "Ang pagsamo ay pumapasok sa ganap na tugma sa mas mataas na batas ng pagkakaloob, at agad na pinupuno ng Liwanag ang bukas na Kli." },
    { f: "Ano ang papel ng espirituwal na kawalang-pag-asa sa pagsilang ng panalangin?", b: "Ipinapahiwatig nito ang ganap na pagkaubos ng mga egoistikong lakas, na direktang nauuna sa pagdating ng tulong mula sa Itaas." },
    { f: "Ano ang 'paggising mula sa Itaas' (Itaruta de-Leila)?", b: "Ang pagpapakita ng Mas Mataas na Liwanag na bumababa bilang direktang tugon sa isang hinog at dinalisay na kakulangan mula sa ibaba (MAN)." },
    { f: "Bakit inihahalintulad ang pagnanais na tumanggap sa isang 'magnanakaw' sa Shamati 20?", b: "Dahil sinusubukan nitong nakawin at kamkamin ang bawat piraso ng lakas at kagalakan para lamang sa sarili nitong makasariling kasiyahan." },
    { f: "Bakit sa simula ay hindi nakadarama ng kagalakan ang tao sa paggawa para sa pagkakaloob?", b: "Upang ang pagnanais na tumanggap ay hindi makatagpo ng lasa rito; kung nakadama ito ng kasiyahan, hindi kailanman aangat ang tao sa dalisay na Lishma." },
    { f: "Kailan nagiging kagalakan sa kanyang sarili ang espirituwal na gawa?", b: "Kapag nasanay na ang tao na magkaloob, at ang pagbibigay ng kasiyahan sa Maylalang ay naging pinakadakilang gantimpala ng mismong pagsisikap." },
    { f: "Kailan makatwiran o hindi makatwiran ang pagdaing sa espirituwal na gawa?", b: "Maaari lamang dumaing ang tao sa panginoon na tunay niyang pinaglilingkuran; ang pagtatrabaho para sa ego ay hindi nagbibigay ng karapatang humingi ng lakas sa Maylalang." },
    { f: "Ano ang panloob na paglilinaw (Berur) sa panalangin?", b: "Ang pagbubukod ng mga intensiyon: paghihiwalay sa ginagawa para sa sariling ego mula sa tunay na nakatuon sa kasiyahan ng Maylalang." },
    { f: "Ano ang 'ganap na kasakdalan' sa pagtanggap sa pamatok ng Kaharian ng Langit?", b: "Ang tanging magnais na magkaloob, at ganap na talikuran ang pagtanggap para sa sariling kapakinabangan." },
    { f: "Bakit hindi sapat ang intelektuwal na pagkaunawa para sa panalangin ng puso?", b: "Hindi pinakikilos ng mga argumento ng isip ang espirituwal na sisidlan; tanging ang tunay na kakulangang naranasan sa puso ang humihila sa Liwanag." },
    { f: "Paano gumagana ang MAN sa pamamagitan ng mga antas ng mga espirituwal na daigdig?", b: "Itinataas ng mas mababang antas ang kakulangan nito sa mas mataas, na nagdadala nito sa Pinagmulan at nagbababa ng sagot." },
    { f: "Bakit tinawag ang panalangin na tanging sandata laban sa pagnanais na tumanggap?", b: "Hindi kayang baguhin ng tao ang kanyang nilikhang kalikasan sa kanyang sarili; maaari lamang siyang sumigaw sa Maylalang upang pagkalooban ng bagong kalikasan ng pagkakaloob." },
    { f: "Bakit ang panalangin ay isang tuloy-tuloy na proseso at hindi minsang kilos?", b: "Ang sunod-sunod na pagsisikap at pagbagsak ay nagpapakinis at nagpapahinog sa panloob na kakulangan hanggang sa maabot nito ang ganap na katapatan." },
    { f: "Paano nahahayag ang pananampalataya sa kaligtasan sa pinakamadilim na kalagayan?", b: "Kahit na walang nakikitang labasan ang katawan, ang tuldok sa puso ay tiyak na kayang magligtas ng Maylalang sa isang kisapmata." },
    { f: "Ano ang ibig sabihin na 'kinasasabikan ng Maylalang ang panalangin ng mga matuwid'?", b: "Naghihintay ang Maylalang ng isang handang Kli na may kakayahang magkaloob, sapagkat ang kalikasan ng Kanyang pag-ibig ay magbuhos ng kapuspusan." },
    { f: "Ano ang kaugnayan ng pagsisisi (Tshuva) at kabalistang panalangin?", b: "Ang pagsisisi ay ang masakit na pagkilala sa egoistikong kalikasan, at ang panalangin ay ang pagsamo para mapalaya mula rito." },
    { f: "Paano pinoprotektahan ng panalangin ang tao mula sa espirituwal na kapalaluan?", b: "Ipinapasok nito ang kamalayan na ang bawat naabot na espirituwal na antas ay tanging isang hindi karapat-dapat na regalo at habag mula sa Itaas." },
    { f: "Bakit minsan ay tila hindi sinasagot ang isang panalangin?", b: "Hindi pa naabot ng kakulangan ang kinakailangang lalim o kadalisayan; hindi pa handa ang sisidlan na hawakan ang Liwanag." },
    { f: "Ano ang ibig sabihin ng 'pagbuhos ng puso sa harap ng Maylalang'?", b: "Ang walang pasubaling pagsuko ng lahat ng lihim na hangarin, takot, at kawalan ng magagawa sa ilalim ng pamamahala ng Maylalang." },
    { f: "Paano tumutulong ang aklat ng panalangin (Siddur) sa panloob na gawa ng kabalista?", b: "Nagsisilbi ito bilang isang tumpak na espirituwal na mapa ng mga panloob na kalagayan at proseso ng pagwawasto na binalangkas ng mga naliwanagang pantas." },
    { f: "Bakit itinuturing na pinakadakilang himala ang paglipat sa Lishma?", b: "Dahil ang pagbaligtad sa nilikhang kalikasan (pagmamahal sa sarili) tungo sa dalisay na altruismo ay posible lamang sa pamamagitan ng nagbabagong kapangyarihan ng Liwanag." },
    { f: "Paano nagiging isang buháy na diyalogo sa Maylalang ang panalangin?", b: "Kapag ang mga pintig ng puso ay tumpak na sumasalamin sa pananabik na kumapit sa Kanya, nagbubukas ang isang direktang panloob na pakikipag-usap." },
    { f: "Ano ang ibig sabihin ng kasabihang 'Hindi mo tungkuling tapusin ang gawain, ngunit hindi ka malayang umiwas dito'?", b: "Kahit na ang layunin ay regalo mula sa Itaas, ang hirap sa pagbuo ng hangarin at kakulangan ay ganap na nakasalalay sa tao." },
    { f: "Ano ang kaugnayan ng panalangin at pag-ibig sa mga kaibigan?", b: "Sa pagsisikap na magkaloob sa mga kaibigan, ang ganap na kawalan ng kakayahang umibig nang walang pag-iimbot ay nahahayag, na nagsisilang ng tunay na daing para sa tulong." },
    { f: "Paano dinadalisay ng pagsusuri sa sarili bago manalangin ang intensiyon?", b: "Inilalantad nito ang mga nakatagong makasariling motibo, inaalis ang mga maling layunin, at itinutuon ang daing sa iisang punto ng katotohanan." },
    { f: "Ano ang pagkakaiba ng pasibong paghihintay at espirituwal na panalangin?", b: "Ang pasibidad ay sumusuko nang walang laban, samantalang ang panalangin ay ang sukdulang sigaw ng isang mandirigma na lumalaban hanggang sa dulo ng kanyang lakas." },
    { f: "Paano nasasalamin ang Liwanag ng Torah sa panalangin?", b: "Ang Nagpapanumbalik na Liwanag na nahihila habang nag-aaral ay nagbibigay-liwanag sa kadiliman ng puso, na gumigising sa malalim na pagsamo para sa pagwawasto." },
    { f: "Ano ang ibig sabihin na ang tunay na panalangin ay 'sumisigaw mula sa kailaliman'?", b: "Isang sigaw na pumuputok mula sa pinakailalim ng pagnanais na tumanggap, mula sa pinakamadilim na bangin ng bilangguan ng ego." },
    { f: "Paano umaakay ang panalangin sa Dvekut (pagkapit) sa Maylalang?", b: "Sa pamamagitan ng pagtatamo ng katangian ng pagkakaloob, nakakamit ng tao ang pagkakapantay ng anyo sa Maylalang, na siyang ganap na pagkakaisa." },
    { f: "Ano ang pinakamahalagang praktikal na aral ng Aralin 18 tungkol sa panalangin?", b: "Huwag masiyahan sa pag-uulit lamang ng mga salita; bumuo ng isang tunay na Hisaron sa iyong puso, sapagkat ang Maylalang ay nakikinig lamang sa katotohanan ng puso." }
  ],
  am: [
    { f: "የጸሎት የካባላዊ ትርጉም ምንድነው?", b: "'በልብ ውስጥ የሚደረግ ሥራ' (Avoda shebaLev)፤ በፈጣሪ ፊት ምኞቶችን፣ ዓላማዎችን እና ጉድለቶችን በጥልቀት ውስጣዊ ግልጽ ማድረግ ነው።" },
    { f: "መንፈሳዊ 'ልብ' በካባላ ውስጥ ምንን ይወክላል?", b: "ልብ የሰውን የመቀበል ፍላጎቶች ድምር እና የስሜታዊና የፈቃደኝነት ዝንባሌዎቹን ሙሉ ገጽታ ይወክላል።" },
    { f: "የአፍ ቃላት ከልብ ምኞት ጋር እንዴት ይዛመዳሉ?", b: "ፈጣሪ ምላሽ የሚሰጠው በከንፈሮች ለሚነገሩ ሜካኒካዊ ቃላት ሳይሆን በልብ ጥልቀት ውስጥ ላለው እውነተኛ ጉድለት (ሂሳሮን) ብቻ ነው።" },
    { f: "በጸሎት ውስጥ የ'ሂሳሮን' (Hisaron) ጽንሰ-ሀሳብ ምንድነው?", b: "እውነተኛ ውስጣዊ ጉድለት፤ ሙላትን እና መንፈሳዊ እርማትን አጥብቆ የሚናፍቅ የዕቃው (ክሊ) ባዶነት ነው።" },
    { f: "ቃላትን በሜካኒካዊ መንገድ መድገም ለምን እንደ እውነተኛ ጸሎት አይቆጠርም?", b: "ምክንያቱም ከንፈሮች የሚናገሩትን ልብ ካልናፈቀው፣ ቃላቱ መንፈሳዊ ህያውነት የሌላቸው የሞቱ ቅርጾች ሆነው ስለሚቀሩ ነው።" },
    { f: "ጸሎት ተቀባይነት እንዲያገኝ የመጀመሪያው ቅድመ ሁኔታ ምንድነው?", b: "ፈጣሪ ሰውን ከራስ ወዳድነት እስር ቤት በእውነት ነፃ ማውጣት እንደሚችል የማይናወጥ እምነት መኖር ነው።" },
    { f: "ጸሎት ተቀባይነት እንዲያገኝ ሁለተኛው ቅድመ ሁኔታ ምንድነው?", b: "ሌላ ምርጫ እንደሌለ መገንዘብ፤ የሰው ኃይል ሁሉ እንደከሸፈ እና ፈጣሪ ብቻ ሊረዳ እንደሚችል ማወቅ ነው።" },
    { f: "ጸሎት ተቀባይነት እንዲያገኝ ሦስተኛው ቅድመ ሁኔታ ምንድነው?", b: "ልመናው በእውነት የሕይወትና የሞት ጥያቄ መሆን አለበት፣ ያለዚያ ነፍስ በመቀበል ፍላጎት ውስጥ ትጠፋለች።" },
    { f: "ጸሎት በመንፈሳዊ እድገት ውስጥ እንደ 'አገናኝ' (medium) እንዴት ይሠራል?", b: "ፈጣሪን ለመለወጥ አይፈልግም፣ ይልቁንም ሰውን ይለውጣል እና ክሊ የመስጠት ብርሃንን ለመቀበል ያዘጋጃል።" },
    { f: "አንድ ካባሊስት እንደ አገናኝ በሆነ እውነተኛ ጸሎት ውስጥ ምን ይጠይቃል?", b: "የመስጠትን ጉድለት (የመስጠት ፍላጎትን) እና ከፈጣሪ ጋር የቅርጽ እኩልነትን ብቻ ይጠይቃል።" },
    { f: "ሊሽማን ስለማግኘት የሻማቲ አንቀጽ 20 ዋና መልእክት ምንድነው?", b: "ሊሽማ (ስለ ስሟ / ከራስ ወዳድነት ነፃ የሆነ ስጦታ) የሰው አእምሮ ብቻውን ሊደርስበት የማይችል ከላይ የሚመጣ ስጦታ እና መገለጥ ነው።" },
    { f: "ሊሽማ ከላይ የሚመጣ ስጦታ ከሆነ፣ የሰው ጥረት ለምን አስፈለገ?", b: "ምክንያቱም ጥረቶች እና የሕክምና ዘዴዎች በሰው ውስጥ ሊሽማን ለመቀበል በእውነት የሚሹትን የተስተካከሉ ዕቃዎችን (ኬሊም) ስለሚገነቡ ነው።" },
    { f: "በሻማቲ 20 መሠረት በጸሎት ውስጥ የውድቀት እና አቅም ማጣት ሚና ምንድነው?", b: "ሰው የድርጊቶቹን ሁሉ ከንቱነት ሲመለከት ፍጹም አቅም ማጣት ላይ ይደርሳል፣ እናም ከዚያ በኋላ ብቻ ከልቡ ጥልቀት መጮኽ ይችላል።" },
    { f: "አንድ ሰው ከልቡ ጥልቀት እውነተኛ ጸሎት ማቅረብ የሚችለው መቼ ነው?", b: "ሁሉንም ሰዋዊ መንገዶች ከሞከረ እና ያለ ፈጣሪ ብቻውን ምንም ነገር ማከናወን እንደማይችል ካመነ በኋላ ብቻ ነው።" },
    { f: "የ'MAN' (ማዪን ኑክቪን) ጽንሰ-ሀሳብ ምን ማለት ነው?", b: "ሴታዊ ውኃዎች፤ ከታችኛው ዕቃ የሚወጣ ጉድለት፣ ጸሎት እና መነቃቃት ሲሆን ይህም ከላይ የተትረፈረፈ በረከትንና ብርሃንን ይስባል።" },
    { f: "በመንፈሳዊው ሥርዓት ውስጥ 'ከታች የመነቃቃት' ሚና ምንድነው?", b: "ከታች የሚመጣው መነቃቃት (የፍጡር ጸሎት) የላይኛውን ብርሃናት (MAD - Mayin Dehrin) ፍሰት ያስጀምራል።" },
    { f: "'ሊነጻ የሚመጣ ይረዳዋል' የሚለው መርህ ምን ማለት ነው?", b: "ለመስጠት እና ለንጽሕና በእውነት ለሚጥር ሰው፣ ፈጣሪ ከራስ ወዳድነት ተፈጥሮው በላይ የሚያደርገውን ኃይል፣ እርማት እና ከፍታ ከላይ ይሰጠዋል።" },
    { f: "ፈጣሪ ራሱን ሊያነጻ የሚመጣውን በተለይ እንዴት ይረዳዋል?", b: "የሊሽማን ደረጃ በመስጠት፣ ልቡን በማንቃት እና ከራስ ወዳድ ተፈጥሮው በላይ የሆነ ከተፈጥሮ በላይ ኃይል በመስጠት ነው።" },
    { f: "በዕለታዊ ውስጣዊ ግልጽነት ወቅት 'በልብ ውስጥ የሚደረግ ሥራ' ምንድነው?", b: "የገዛ ተፈጥሮን ለመለወጥ ከማያቋርጥ ጸሎት ጋር ራስ ወዳድ ምኞቶችን ከመስጠት ፍላጎት መለየት ነው።" },
    { f: "ፈጣሪ በጸሎት ለምን አይለወጥም?", b: "ምክንያቱም ፈጣሪ ፍጹም በጎ እና የማይለወጥ ነው፤ ጸሎት ተቀባዩን ዕቃ ይለውጠዋል፣ ይህም ብርሃኑን ለመያዝ ብቁ ያደርገዋል።" },
    { f: "በተለመደው ሃይማኖታዊ ጸሎት እና በካባላዊ ጸሎት መካከል ያለው ልዩነት ምንድነው?", b: "ተራ ጸሎት ቁሳዊ ጥቅሞችን ወይም ለራስ እፎይታን ይጠይቃል፣ የካባላዊ ጸሎት ግን ከራስ ወዳድነት ለመዳን ይማጸናል።" },
    { f: "በመንፈሳዊው መንገድ ላይ እውነተኛ ሂሳሮን እንዴት ይወለዳል?", b: "በቡድኑ ውስጥ ባለው ጽኑ ሥራ እና የመጻሕፍት ጥናት አማካኝነት ጉድለቱ የመስጠት ብርሃን አለመኖር ሆኖ ሲገለጽ ነው።" },
    { f: "አካል 'ከመንግሥተ ሰማያት ቀንበር ጋር አይስማማም' ማለት ምን ማለት ነው?", b: "የተፈጠረው የመቀበል ፍላጎት ያለ ግል ጥቅም ለፈጣሪ ደስታ ብቻ መሥራትን በተፈጥሮው ይቃወማል።" },
    { f: "አንድ ሰው ብልቶቹ ሁሉ መስጠትን ሲቃወሙ ሲያይ ምን ማድረግ አለበት?", b: "ከጸሎት በቀር ሌላ መውጫ የለውም፤ ፈጣሪ አካሉን ለመስጠት እንዲያስገዛው ልቡን በፊቱ ማፍሰስ አለበት።" },
    { f: "ሊሽማን ማግኘት ክፉውን ዝንባሌ እንዴት ይገድለዋል?", b: "ራስን መውደድን ውድቅ ያደርገዋል፤ የመቀበያ ዕቃዎች ራስ ወዳድነታቸውን ያጣሉ እና በመንፈሳዊ ሁኔታ 'የሞቱ' እንደሆኑ ይቆጠራሉ።" },
    { f: "ያለ ጸሎት ሊሽማን ማግኘት እንደማይቻል ማወቅ ለምን ወሳኝ ሆነ?", b: "ምክንያቱም ይህ ግንዛቤ ጸሎትን ፍጹም እና አስቸኳይ ፍላጎት ያደርገዋል፣ የውሸት በራስ የመተማመን ቅዠትን ያስወግዳል።" },
    { f: "MANን የማንሳት እና የነፍስ ዕቃ ግንኙነት ምንድነው?", b: "MAN የክሊ ራሱ ጉድለት ነው፤ ጉድለቱ ይበልጥ ንጹሕ እና ጥልቅ በሆነ መጠን፣ ዕቃው ሊቀበለው የሚችለው ብርሃን ይበልጣል" },
    { f: "ጸሎት የራስ ወዳድነትን አቅም ማጣት ማመን የሆነው በምን መልኩ ነው?", b: "ልብ ፍጹም ጥገኝነቱን ያሳያል፣ የራሱ ኢጎ ያለ መለኮታዊ እርዳታ የማይታለፍ እስር ቤት መሆኑን ያምናል።" },
    { f: "የቡድን ሥራ ከግል ጸሎት ጋር እንዴት ይዋሃዳል?", b: "ጓደኞችን ለመውደድ የሚደረገው ጥረት ከራስ ወዳድነት ነፃ የመሆን ፍጹም አቅም ማጣትን ያጋልጣል፣ ይህም የእውነተኛ የእርዳታ ጩኸት ይወልዳል።" },
    { f: "ጸሎት እንደ ራሱ የመንፈሳዊ ዕቃ ፈጠራ ተደርጎ የሚወሰደው ለምንድነው?", b: "ምክንያቱም ሙላት ሊገባ የሚችለው ተጓዳኝ ጉድለት ባለበት ቦታ ብቻ ነው፤ ጸሎት ይህንን መንፈሳዊ ክፍተት ይገልጻል እና ያሰፋዋል።" },
    { f: "'ፈጣሪ ጸሎትን ይሰማል' የሚለው አገላለጽ ምን ማለት ነው?", b: "ልመናው ከከፍተኛው የመስጠት ሕግ ጋር ፍጹም ስምምነት ውስጥ ይገባል፣ እናም ብርሃኑ የተከፈተውን ክሊ ወዲያውኑ ይሞላል።" },
    { f: "መንፈሳዊ ተስፋ መቁረጥ በጸሎት መወለድ ውስጥ ምን ሚና ይጫወታል?", b: "የራስ ወዳድነት ኃይሎች ፍጹም ድካምን ያመለክታል፣ ይህም ከላይ የሚመጣው እርዳታ ከመውረዱ በፊት ወዲያውኑ የሚከሰት ነው።" },
    { f: "'ከላይ መነቃቃት' (Itaruta de-Leila) ምንድነው?", b: "ከታች ከተነሳ የበሰለ እና የነጻ ጉድለት (MAN) ቀጥተኛ ምላሽ ሆኖ የሚወርደው የላቀ ብርሃን መገለጥ ነው።" },
    { f: "በሻማቲ 20 ውስጥ የመቀበል ፍላጎት ከ'ሌባ' ጋር የተነጻጸረው ለምንድነው?", b: "ምክንያቱም እያንዳንዱን የኃይል እና የደስታ ፍንጣቂ ለራሱ ራስ ወዳድነት ደስታ ብቻ ለመስረቅ እና ለመውሰድ ስለሚሞክር ነው።" },
    { f: "ሰው በመጀመሪያ ለመስጠት በሚደረገው ሥራ ውስጥ ምንም ዓይነት ደስታ የማይሰማው ለምንድነው?", b: "የመቀበል ፍላጎት በውስጡ ጣዕም እንዳያገኝ ነው፤ ደስታ ካገኘበት ሰውዬው ወደ ንጹሕ ሊሽማ ፈጽሞ ሊነሳ አይችልም ነበር።" },
    { f: "መንፈሳዊ ሥራ በራሱ ደስታ የሚሆነው መቼ ነው?", b: "ሰው መስጠትን ሲለምድ እና ፈጣሪን ማስደሰት የጥረት ትልቁ ሽልማት ሲሆን ነው።" },
    { f: "በመንፈሳዊ ሥራ ውስጥ ማጉረምረም ትክክል ወይም ስህተት የሚሆነው መቼ ነው?", b: "ሰው ማጉረምረም የሚችለው በእውነት ለሚሠራለት ጌታ ብቻ ነው፤ ለኢጎ እየሠሩ ከፈጣሪ ኃይል የመጠየቅ መብት የለም።" },
    { f: "በጸሎት ውስጥ ውስጣዊ ግልጽነት (Berur) ምንድነው?", b: "ዓላማዎችን መለየት፡ ለራስ ኢጎ የሚደረገውን ፈጣሪን ለማስደሰት በእውነት ከታለመው ነገር መለየት ነው።" },
    { f: "የመንግሥተ ሰማያትን ቀንበር በመቀበል ረገድ 'ፍጹም ምልዓት' ምንድነው?", b: "ለመስጠት ብቻ መፈለግ እና ለግል ጥቅም ከመቀበል ሙሉ በሙሉ መተው ነው።" },
    { f: "ለልብ ጸሎት አእምሯዊ ግንዛቤ ለምን በቂ አይሆንም?", b: "የአእምሮ ክርክሮች መንፈሳዊውን ዕቃ አያንቀሳቅሱትም፤ በልብ ውስጥ የተለማመደው እውነተኛ ጉድለት ብቻ ብርሃኑን ይስባል።" },
    { f: "MAN በመንፈሳዊ ዓለማት ደረጃዎች ውስጥ እንዴት ይሠራል?", b: "ዝቅተኛው ደረጃ ጉድለቱን ወደ ከፍተኛው ያነሳል፣ እሱም ወደ ምንጩ ያደርሰዋል እና መልሱን ወደ ታች ያወርዳል።" },
    { f: "ጸሎት የመቀበል ፍላጎትን ለመዋጋት ብቸኛው መሣሪያ የተባለው ለምንድነው?", b: "ሰው የተፈጠረውን ተፈጥሮውን ራሱ መለወጥ አይችልም፤ አዲስ የመስጠት ተፈጥሮ እንዲሰጠው ወደ ፈጣሪ መጮኽ ብቻ ነው የሚችለው።" },
    { f: "ጸሎት የአንድ ጊዜ ድርጊት ሳይሆን ቀጣይነት ያለው ሂደት የሆነው ለምንድነው?", b: "የጥረቶች እና የመውደቅ ሰንሰለት ውስጣዊ ጉድለቱን ፍጹም ቅንነት ላይ እስኪደርስ ድረስ ስለሚቀርጸው እና ስለሚያበስለው ነው።" },
    { f: "በጣም ጨለማ በሆኑ ሁኔታዎች ውስጥ በመዳን ላይ ያለው እምነት እንዴት ይገለጻል?", b: "አካሉ ምንም ዓይነት መውጫ ባያይም እንኳ፣ በልብ ውስጥ ያለው ነጥብ ፈጣሪ በቅጽበት ማዳን እንደሚችል እርግጠኛ ነው።" },
    { f: "'ፈጣሪ የጻድቃንን ጸሎት ይናፍቃል' ማለት ምን ማለት ነው?", b: "ፈጣሪ የመስጠት ችሎታ ያለው የተዘጋጀ ክሊ ይጠብቃል፣ ምክንያቱም የፍቅሩ ባሕርይ ሙላትን መስጠት ነው።" },
    { f: "በንስሐ (Tshuva) እና በካባላዊ ጸሎት መካከል ያለው ግንኙነት ምንድነው?", b: "ንስሐ የራስ ወዳድ ተፈጥሮን ህመም ማወቅ ነው፣ ጸሎት ደግሞ ከእርሱ ለመዳን የሚደረግ ልመና ነው።" },
    { f: "ጸሎት ሰውን ከመንፈሳዊ ትዕቢት እንዴት ይጠብቃል?", b: "የተገኘ ማንኛውም መንፈሳዊ ደረጃ ከላይ የተሰጠ የማይገባ ስጦታ እና ምሕረት ብቻ መሆኑን ግንዛቤን ያሰርጻል።" },
    { f: "አንዳንድ ጊዜ ጸሎት ያልተመለሰ የሚመስለው ለምንድነው?", b: "ጉድለቱ ገና ወደ ሚፈለገው ጥልቀት ወይም ንጽሕና አልደረሰም፤ ዕቃው ብርሃኑን ለመያዝ ገና ዝግጁ አይደለም።" },
    { f: "'በፈጣሪ ፊት ልብን ማፍሰስ' ማለት ምን ማለት ነው?", b: "ሁሉንም የተደበቁ ምኞቶችን፣ ፍርሃቶችን እና አቅም ማጣትን ያለ ምንም ቅድመ ሁኔታ በፈጣሪ አመራር ሥር መስጠት ነው።" },
    { f: "የጸሎት መጽሐፍ (ሲዱር) የካባሊስትን ውስጣዊ ሥራ እንዴት ይረዳል?", b: "በጥበበኞች የተዘጋጀ የውስጣዊ ሁኔታዎች እና የእርማት ሂደቶች ትክክለኛ መንፈሳዊ ካርታ ሆኖ ያገለግላል።" },
    { f: "ወደ ሊሽማ መሸጋገር እንደ ታላቅ ተአምር የሚቆጠረው ለምንድነው?", b: "ምክንያቱም የተፈጠረውን ተፈጥሮ (ራስን መውደድ) ወደ ንጹሕ አልትሩይዝም መለወጥ የሚቻለው በብርሃኑ ለዋጭ ኃይል ብቻ ነው።" },
    { f: "ጸሎት ከፈጣሪ ጋር ወደ ሕያው ውይይት የሚለወጠው እንዴት ነው?", b: "የልብ ምት ከእርሱ ጋር የመጣበቅን ናፍቆት በትክክል ሲያንጸባርቅ፣ ቀጥተኛ ውስጣዊ ግንኙነት ይከፈታል።" },
    { f: "'ሥራውን መጨረስ የአንተ ግዴታ አይደለም፣ ነገር ግን ከእርሱ የመተው ነፃነት የለህም' የሚለው አባባል ምን ማለት ነው?", b: "ምንም እንኳ ግቡ ከላይ የተሰጠ ስጦታ ቢሆንም፣ ምኞትን እና ጉድለትን የመገንባት ድካም ሙሉ በሙሉ በሰውየው ላይ ነው።" },
    { f: "በጸሎት እና ለጓደኞች ባለው ፍቅር መካከል ያለው ግንኙነት ምንድነው?", b: "ለጓደኞች ለመስጠት በሚደረገው ጥረት፣ ያለ አንዳች ጥቅም የመውደድ ፍጹም አቅም ማጣት ይገለጣል፣ ይህም እውነተኛ የእርዳታ ጩኸት ይወልዳል።" },
    { f: "ከጸሎት በፊት ራስን መመርመር ዓላማን እንዴት ያነጻል?", b: "የተደበቁ ራስ ወዳድ ዓላማዎችን ያጋልጣል፣ የውሸት ግቦችን ያስወግዳል፣ እናም ጩኸቱን በአንድ የእውነት ነጥብ ላይ ያተኩራል።" },
    { f: "ዝም ብሎ በመጠበቅ እና በመንፈሳዊ ጸሎት መካከል ያለው ልዩነት ምንድነው?", b: "ተገብሮ መሆን ያለ ትግል እጅ ይሰጣል፣ ጸሎት ግን እስከ መጨረሻው የኃይል ገደብ ድረስ የሚታገል ተዋጊ ከፍተኛ ጩኸት ነው።" },
    { f: "የቶራ ብርሃን በጸሎት ውስጥ እንዴት ይንጸባረቃል?", b: "በጥናት ወቅት የሚሳበው አዳሽ ብርሃን የልብን ጨለማ ያበራል፣ ይህም ለእርማት ጥልቅ ልመናን ያነቃቃል።" },
    { f: "እውነተኛ ጸሎት 'ከጥልቅ ይጮኻል' ማለት ምን ማለት ነው?", b: "ከመቀበል ፍላጎት የታችኛው ክፍል፣ ከኢጎ እስር ቤት እጅግ በጣም ጨለማ ከሆነው ጥልቁ የሚወጣ ጩኸት ነው።" },
    { f: "ጸሎት ከፈጣሪ ጋር ወደ ድቬኩት (መጣበቅ) እንዴት ይመራል?", b: "የመስጠትን ባሕርይ በማግኘት ሰው ከፈጣሪ ጋር የቅርጽ እኩልነትን ያገኛል፣ ይህም ፍጹም አንድነት ነው።" },
    { f: "ስለ ጸሎት የትምህርት 18 በጣም አስፈላጊው ተግባራዊ ትምህርት ምንድነው?", b: "ቃላትን በመድገም ብቻ አትወሰኑ፤ በልባችሁ ውስጥ እውነተኛ ሂሳሮን ገንቡ፣ ምክንያቱም ፈጣሪ የልብን እውነት ብቻ ነው የሚሰማው።" }
  ]
};

Object.values(window.lessonDB[18].quiz).forEach(questions => {
  const questionList = Array.isArray(questions) ? questions : questions.questions;
  questionList.forEach(question => {
    const options = question.options.map((text, index) => ({
      text,
      isCorrect: index === question.correct
    }));

    for (let i = options.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [options[i], options[j]] = [options[j], options[i]];
    }

    question.options = options.map(option => option.text);
    question.correct = options.findIndex(option => option.isCorrect);
  });
});